  return q(`INSERT INTO cars(title,brand,model,year,price,dealer_id,vin,registration_number) VALUES('t${carSeq}','Toyota','Prado',2018,3500000,${owner ? `'${owner}'` : "NULL"},'${v}','${r}') RETURNING id;`).split("\n")[0];
