    for (const p of probes) {
      const { table, idColumn = 'id', aId, bId, label = table } = p || {};
      if (!table || !aId || !bId || !/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(table) || !/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(idColumn)) {
