    const { data, error } = await query;
    if (error) throw error;
    return (data || []).map((r) => r[slugCol]).filter(Boolean);
  } catch (err) {
    console.warn(`  Warning: could not fetch ${table}: ${err.message}`);
    return [];
  }
}

