const exists = (file) => fs.existsSync(path.join(root, file));

const workflowPath = '.github/workflows/ci.yml';
if (!exists(workflowPath)) failures.push('Missing .github/workflows/ci.yml');
else {
  const workflow = read(workflowPath);
  const required = [
    'actions/checkout@v4',
