import { useState } from 'react';
import { Calendar, Gauge, Fuel, MapPin, Shield, Gavel, ChevronRight, Heart, BarChart3 } from 'lucide-react';
import LazyImage from './LazyImage';
import { formatKES } from '../utils/helpers';

export interface Car {
  id: number;
  make: string;
  model: string;
  price: number;
  year: number;
  mileage: string;
  fuel: string;
  city: string;
  type: 'SUV' | 'Pickup' | 'Sedan' | 'Wagon';
  badges: ('escrow' | 'auction' | 'verified' | 'sponsored' | 'financing' | 'negotiable')[];
  image: string;
  transmission?: string;
  engine?: string;
  dealerName?: string;
  isVerified?: boolean;
  isBankOwned?: boolean;
  isNegotiable?: boolean;
  hasFinancing?: boolean;
  views?: number;
  createdAt?: string;
  currentBid?: number;
  auctionEnd?: string;
}

interface CarCardProps {
  car: Car;
  onClick?: () => void;
  onToggleCompare?: () => void;
  isComparing?: boolean;
  compareCount?: number;
  onFavorite?: (carId: number) => void;
  isFavorited?: boolean;
  showCompare?: boolean;
  listView?: boolean;
}

export default function CarCard({
  car,
  onClick,
  onToggleCompare,
  isComparing = false,
  compareCount = 0,
  onFavorite,
  isFavorited = false,
  showCompare = true,
  listView = false,
}: CarCardProps) {
  const [imgLoaded, setImgLoaded] = useState(false);

  // Auction status
  const now = Date.now();
  const auctionEnd = car.auctionEnd ? new Date(car.auctionEnd).getTime() : 0;
  const isOnAuction = (car.badges ?? []).includes('auction') && auctionEnd > now;
  const currentPrice = isOnAuction && car.currentBid && car.currentBid > 0 ? car.currentBid : car.price;

  if (listView) {
    return (
      <div
        onClick={onClick}
        className="group flex flex-col sm:flex-row bg-white rounded-2xl overflow-hidden shadow-sm hover:shadow-xl transition-all duration-300 cursor-pointer border border-[#D7E7E4] hover:border-[#5AAFA4]/50"
      >
        {/* Image */}
        <div className="relative w-full sm:w-72 h-48 sm:h-auto flex-shrink-0 overflow-hidden bg-[#EEF7F5]">
          <LazyImage
            src={car.image}
            alt={`${car.make} ${car.model}`}
            width={400}
            height={300}
            className="w-full h-full"
            onLoad={() => setImgLoaded(true)}
            style={{ opacity: imgLoaded ? 1 : 0 }}
          />
          {!imgLoaded && (
            <div className="absolute inset-0 bg-[#DDF4F0] animate-pulse" />
          )}
          <div className="absolute inset-0 bg-gradient-to-r from-transparent to-[#0A3340]/20 opacity-0 group-hover:opacity-100 transition-opacity" />

          {/* Badges */}
          <div className="absolute top-3 left-3 flex flex-col gap-1.5">
            {isOnAuction && (
              <span className="card-badge bg-red-500/90 text-white backdrop-blur-sm">
                <span className="w-1.5 h-1.5 bg-white rounded-full animate-pulse" />
                LIVE
              </span>
            )}
            {(car.badges ?? []).includes('escrow') && (
              <span className="card-badge bg-[#0A3340]/90 text-white backdrop-blur-sm">
                <Shield size={10} />
                ESCROW
              </span>
            )}
            {car.isVerified && (
              <span className="card-badge bg-emerald-500/90 text-white backdrop-blur-sm">
                ✓ VERIFIED
              </span>
            )}
          </div>

          {/* Compare button */}
          {showCompare && onToggleCompare && (
            <button
              onClick={(e) => { e.stopPropagation(); onToggleCompare(); }}
              className={`absolute top-3 right-3 p-2 rounded-full backdrop-blur-md transition-all hover:scale-110 border ${
                isComparing
                  ? 'bg-[#13B8A6] text-white border-[#5AAFA4] opacity-100'
                  : 'bg-[#0A3340]/60 text-white border-white/20 hover:border-[#5AAFA4] opacity-0 group-hover:opacity-100'
              }`}
              title={isComparing ? 'Remove from compare' : 'Add to compare'}
            >
              <BarChart3 size={15} />
            </button>
          )}
        </div>

        {/* Content */}
        <div className="flex-1 p-5 flex flex-col">
          <div className="flex justify-between items-start gap-4">
            <div className="flex-1 min-w-0">
              <p className="section-label mb-1">{car.make}</p>
              <h3 className="font-serif text-xl text-[#0A3340] font-semibold mb-2 group-hover:text-[#176B87] transition-colors">
                {car.model}
              </h3>

              {/* Specs */}
              <div className="flex flex-wrap gap-3 text-sm text-warm-500">
                {car.year && <span>{car.year}</span>}
                {car.mileage && <span>· {car.mileage}</span>}
                {car.fuel && <span>· {car.fuel}</span>}
                {car.transmission && <span>· {car.transmission}</span>}
                {car.engine && <span>· {car.engine}</span>}
              </div>

              {/* Location */}
              <div className="flex items-center gap-1.5 text-sm text-warm-400 mt-2">
                <MapPin size={14} />
                <span>{car.city}</span>
              </div>
            </div>

            <div className="text-right flex-shrink-0">
              <p className="text-[10px] font-sans font-semibold tracking-widest text-warm-400 uppercase mb-1">
                {isOnAuction ? (car.currentBid ? 'Current Bid' : 'Starting Bid') : 'Price'}
              </p>
              <p className="font-serif text-2xl text-[#0A3340] font-semibold">
                {formatKES(currentPrice)}
              </p>
              {car.isNegotiable && (
                <span className="text-xs text-warm-400">Negotiable</span>
              )}
            </div>
          </div>

          {/* Footer */}
          <div className="mt-auto pt-4 border-t border-[#D7E7E4] flex items-center justify-between">
            <div className="flex items-center gap-3">
              {car.dealerName && (
                <span className="text-sm text-warm-400">
                  {car.isBankOwned ? '🏦 ' : ''}{car.dealerName}
                </span>
              )}
              {car.views && (
                <span className="text-xs text-warm-300">{car.views} views</span>
              )}
            </div>

            <div className="flex items-center gap-2">
              {onFavorite && (
                <button
                  onClick={(e) => { e.stopPropagation(); onFavorite(car.id); }}
                  className="p-2 rounded-full hover:bg-[#EEF7F5] transition-colors"
                >
                  <Heart
                    size={18}
                    className={isFavorited ? 'fill-red-500 text-red-500' : 'text-warm-400'}
                  />
                </button>
              )}
              <span className="text-[#176B87] text-sm font-medium group-hover:translate-x-1 transition-transform">
                View →
              </span>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // Grid View
  return (
    <div
      onClick={onClick}
      className="group relative bg-white rounded-2xl overflow-hidden shadow-sm hover:shadow-xl transition-all duration-300 cursor-pointer border border-[#D7E7E4] hover:border-[#5AAFA4]/50 hover:-translate-y-1"
    >
      {/* Image */}
      <div className="relative overflow-hidden aspect-[4/3]">
        <LazyImage
          src={car.image}
          alt={`${car.make} ${car.model}`}
          width={400}
          height={300}
          className="w-full h-full"
          onLoad={() => setImgLoaded(true)}
          style={{ opacity: imgLoaded ? 1 : 0 }}
        />
        {!imgLoaded && (
          <div className="absolute inset-0 bg-[#DDF4F0] animate-pulse" />
        )}

        {/* Gradient Overlay */}
        <div className="absolute inset-x-0 bottom-0 h-1/3 bg-gradient-to-t from-[#0A3340]/60 to-transparent" />

        {/* Badges - Top Left */}
        <div className="absolute top-3 left-3 flex flex-col gap-1.5">
          {isOnAuction && (
            <span className="card-badge bg-red-500/90 text-white backdrop-blur-sm">
              <span className="w-1.5 h-1.5 bg-white rounded-full animate-pulse" />
              LIVE
            </span>
          )}
          {(car.badges ?? []).includes('escrow') && (
            <span className="card-badge bg-[#0A3340]/90 text-white backdrop-blur-sm">
              <Shield size={10} />
              ESCROW
            </span>
          )}
          {car.isVerified && (
            <span className="card-badge bg-emerald-500/90 text-white backdrop-blur-sm">
              ✓
            </span>
          )}
        </div>

        {/* Badges - Top Right */}
        <div className="absolute top-3 right-3 flex flex-col gap-1.5">
          {onFavorite && (
            <button
              onClick={(e) => { e.stopPropagation(); onFavorite(car.id); }}
              className="p-2 bg-[#0A3340]/60 hover:bg-[#0A3340]/80 backdrop-blur-sm rounded-full transition-all hover:scale-110"
            >
              <Heart
                size={18}
                className={isFavorited ? 'fill-red-500 text-red-500' : 'text-white'}
              />
            </button>
          )}
        </div>

        {/* Compare button */}
        {showCompare && onToggleCompare && (
          <button
            onClick={(e) => { e.stopPropagation(); onToggleCompare(); }}
            className={`absolute top-3 right-14 p-2 rounded-full backdrop-blur-md transition-all hover:scale-110 border ${
              isComparing
                ? 'bg-[#13B8A6] text-white border-[#5AAFA4]'
                : 'bg-[#0A3340]/60 text-white border-white/20 hover:border-[#5AAFA4] opacity-0 group-hover:opacity-100'
            }`}
            title={isComparing ? 'Remove from compare' : 'Add to compare'}
          >
            <BarChart3 size={15} />
          </button>
        )}

        {/* Type pill */}
        <div className="absolute bottom-3 right-3">
          <span className="bg-white/90 backdrop-blur-sm text-warm-600 text-xs font-sans font-semibold px-3 py-1 rounded-full">
            {car.type}
          </span>
        </div>

        {/* Year badge */}
        {car.year && (
          <div className="absolute bottom-3 left-3">
            <span className="bg-[#0A3340]/60 backdrop-blur-sm text-white text-xs font-semibold px-2.5 py-1 rounded-lg">
              {car.year}
            </span>
          </div>
        )}
      </div>

      {/* Details */}
      <div className="p-5">
        <p className="section-label mb-1">{car.make}</p>
        <h3 className="font-serif text-xl text-[#0A3340] font-semibold mb-2 line-clamp-1 group-hover:text-[#176B87] transition-colors duration-200">
          {car.model}
        </h3>

        {/* Quick Specs */}
        <div className="flex flex-wrap gap-2 mb-3">
          <span className="text-xs px-2.5 py-1 bg-[#EEF7F5] rounded-md text-warm-500">
            {car.mileage}
          </span>
          <span className="text-xs px-2.5 py-1 bg-[#EEF7F5] rounded-md text-warm-500">
            {car.fuel}
          </span>
          {car.transmission && (
            <span className="text-xs px-2.5 py-1 bg-[#EEF7F5] rounded-md text-warm-500">
              {car.transmission}
            </span>
          )}
        </div>

        {/* Location */}
        <div className="flex items-center gap-1.5 text-sm text-warm-400 mb-3">
          <MapPin size={14} />
          <span>{car.city}</span>
        </div>

        {/* Dealer */}
        {car.dealerName && (
          <div className="flex items-center gap-1.5 text-xs text-warm-400 mb-3">
            {car.isBankOwned && <span>🏦</span>}
            <span>{car.dealerName}</span>
            {car.isVerified && <span className="text-emerald-500">✓</span>}
          </div>
        )}

        {/* Divider */}
        <div className="h-px bg-[#13B8A6]/20 my-3" />

        {/* Price */}
        <div className="flex items-end justify-between">
          <div>
            <p className="text-[10px] font-sans font-semibold tracking-widest text-warm-400 uppercase">
              {isOnAuction ? (car.currentBid ? 'Current Bid' : 'Starting Bid') : 'Price'}
            </p>
            <p className="font-serif text-2xl text-[#0A3340] font-semibold tracking-wide">
              {formatKES(currentPrice)}
            </p>
            {car.isNegotiable && (
              <span className="text-xs text-warm-400">Negotiable</span>
            )}
          </div>

          <span className="text-[#176B87] text-sm font-medium group-hover:translate-x-1 transition-transform">
            View →
          </span>
        </div>
      </div>
    </div>
  );
}

import { useState, memo } from 'react';
import { Link } from 'react-router-dom';
import { Gauge, MapPin, ArrowRight } from 'lucide-react';
import LazyImage from './LazyImage';

const FALLBACK = 'https://images.unsplash.com/photo-1503376780353-7e8f0e4b39f4?q=80&w=1200&auto=format&fit=crop';

interface CarImage { url?: string; }
interface CarLocation { city?: string; }

interface Car {
  _id: string;
  title: string;
  image?: string;
  images?: (string | CarImage)[];
  coverImage?: number;
  auctionStartTime?: string;
  auctionEnd?: string;
  currentBid?: number;
  price?: number;
  location?: string | CarLocation;
  year?: number;
  fuel?: string;
  transmission?: string;
  mileage?: number;
  ntsaVerified?: boolean;
  isPromoted?: boolean;
  escrowEnabled?: boolean;
  status?: string;
  paymentStatus?: string;
  createdAt?: string;
  dealer?: { name?: string; businessName?: string; logo?: string; _id?: string; role?: string; verified?: boolean };
  seller?: { name?: string; avatar?: string; _id?: string };
}

function firstImage(car: Car): string | undefined {
  if (car.image) return car.image;
  const imgs = car.images || [];
  if (!imgs.length) return undefined;
  const idx = typeof car.coverImage === 'number' ? car.coverImage : 0;
  const img = imgs[idx] || imgs[0];
  if (typeof img === 'string' && img) return img;
  if (typeof img === 'object' && img?.url) return img.url;
  return undefined;
}

interface CarGridItemProps {
  car: Car;
  listView?: boolean;
  isMobile?: boolean;
}

const CarGridItem = memo(function CarGridItem({ car, listView = false, isMobile = false }: CarGridItemProps) {
  const [hovered, setHovered] = useState(false);

  if (!car) return null;

  const now = Date.now();
  const SEVEN_DAYS = 7 * 24 * 60 * 60 * 1000;
  const auctionStartTime = car.auctionStartTime ? new Date(car.auctionStartTime).getTime() : 0;
  const auctionEnd = car.auctionEnd ? new Date(car.auctionEnd).getTime() : 0;
  const isLiveNow = auctionStartTime > 0 && auctionEnd > 0 && auctionStartTime <= now && auctionEnd > now;
  const isUpcomingAuction = auctionStartTime > 0 && auctionStartTime > now;
  const isOnAuction = isLiveNow || isUpcomingAuction;
  const isSold = car.status === 'sold' || car.paymentStatus === 'released';
  const isNewListing = car.createdAt && (now - new Date(car.createdAt).getTime()) < SEVEN_DAYS;

  const detailTo = `/cars/${car._id}`;
  const img = firstImage(car) || undefined;
  const city = typeof car.location === 'string' ? car.location : (car.location?.city || 'Nairobi');
  const price = Number(car.currentBid || car.price || 0);
  const sellerName = car.dealer?.businessName || car.dealer?.name || car.seller?.name || 'Private Seller';
  const isPrivateSeller = !car.dealer || car.dealer?.role === 'individual_seller' || car.dealer?.role === 'user';
  const showEscrowBadge = car.escrowEnabled || isPrivateSeller;
  const formatMileage = (km) => km ? `${Math.round(Number(km) / 1000)}k` : null;

  if (listView) {
    return (
      <Link to={detailTo} className="block group">
        <div
          className="transition-colors duration-200 hover:bg-[#0a3340]"
          style={{
            display: 'flex', flexDirection: isMobile ? 'column' : 'row',
            background: '#0a3340', borderRadius: 14,
            border: '1px solid rgba(255,255,255,0.06)',
            overflow: 'hidden',
          }}
          onMouseEnter={() => setHovered(true)}
          onMouseLeave={() => setHovered(false)}
        >
          <div style={{
            width: isMobile ? '100%' : 300, height: isMobile ? 200 : 200,
            flexShrink: 0, position: 'relative', overflow: 'hidden', background: '#0a3340',
          }}>
            <LazyImage src={img} fallback={FALLBACK} alt={car.title} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
            <div style={{ position: 'absolute', inset: 0, background: 'linear-gradient(to right, rgba(10, 51, 64, 0.5), transparent)', opacity: hovered ? 0 : 1 }} />
            <div style={{ position: 'absolute', bottom: 0, left: 0, right: 0, height: '40%', background: 'linear-gradient(transparent, rgba(10, 51, 64, 0.6))' }} />
            {isLiveNow && (
              <div style={{ position: 'absolute', top: 10, left: 10, padding: '3px 9px', borderRadius: 20, fontSize: 9, fontWeight: 700, background: 'rgba(239,68,68,0.92)', color: '#fff', letterSpacing: '0.06em' }}>
                <span style={{ width: 4, height: 4, borderRadius: '50%', background: '#fff', display: 'inline-block', animation: 'pulse 1.5s infinite', marginRight: 4 }} />
                LIVE
              </div>
            )}
          </div>
          <div style={{ flex: 1, padding: '16px 20px', display: 'flex', flexDirection: 'column', minWidth: 0 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', gap: 16 }}>
              <div style={{ flex: 1, minWidth: 0 }}>
                <h3 style={{ fontSize: 17, fontWeight: 600, lineHeight: 1.3, margin: 0, fontFamily: 'var(--font-display)', fontStyle: 'italic' }}>
                  {car.year && <span style={{ color: 'rgba(255,255,255,0.4)', fontWeight: 400 }}>{car.year} </span>}
                  {car.title}
                </h3>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: '12px 20px', marginTop: 10, fontSize: 12, color: 'rgba(255,255,255,0.45)' }}>
                  {car.mileage && <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}><Gauge size={12} /> {formatMileage(car.mileage)}</span>}
                  {car.transmission && <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}>⚙️ {car.transmission}</span>}
                  <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}><MapPin size={12} /> {city}</span>
                </div>
              </div>
              <div style={{ textAlign: 'right', flexShrink: 0 }}>
                <div style={{ fontSize: 9, color: 'rgba(255,255,255,0.35)', fontWeight: 700, letterSpacing: '0.12em', textTransform: 'uppercase' }}>
                  {isOnAuction ? (car.currentBid && car.currentBid > 0 ? 'Current Bid' : 'Starting Bid') : 'Price'}
                </div>
                <div style={{ fontSize: 18, fontWeight: 700, color: 'var(--brand-light)', lineHeight: 1.2, fontFamily: 'var(--font-display)', fontStyle: 'italic' }}>
                  KES {price.toLocaleString()}
                </div>
              </div>
            </div>
          </div>
        </div>
      </Link>
    );
  }

  return (
    <div
      className="group transition-transform duration-300 hover:-translate-y-1"
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
    >
      <Link to={detailTo} className="block no-underline">
        <div className="overflow-hidden rounded-xl" style={{ background: 'var(--card)', border: '1px solid var(--border)' }}>
          <div className="relative overflow-hidden" style={{ aspectRatio: '16/9', background: '#0a3340' }}>
            <LazyImage src={img} fallback={FALLBACK} alt={car.title} className="w-full h-full object-cover" />
            <div className="absolute inset-0" style={{ background: 'linear-gradient(to top, rgba(10, 51, 64, 0.4), transparent)' }} />
            {isSold && (
              <div style={{ position: 'absolute', inset: 0, background: 'rgba(10, 51, 64, 0.5)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 2 }}>
                <span style={{ fontSize: 13, fontWeight: 900, color: '#fff', letterSpacing: '0.15em', textTransform: 'uppercase', background: 'rgba(239,68,68,0.85)', padding: '6px 18px', borderRadius: 6 }}>Sold</span>
              </div>
            )}
            {showEscrowBadge && !isSold && (
              <div style={{ position: 'absolute', top: 10, left: 10, padding: '3px 10px', borderRadius: 9999, fontSize: 9, fontWeight: 700, background: 'rgba(34,197,94,0.92)', color: '#fff', letterSpacing: '0.06em', backdropFilter: 'blur(4px)' }}>
                Escrow Protected
              </div>
            )}
            {isLiveNow && !isSold && (
              <div style={{ position: 'absolute', top: 10, right: 10, display: 'flex', alignItems: 'center', gap: 4, padding: '3px 10px', borderRadius: 9999, fontSize: 9, fontWeight: 700, background: 'rgba(239,68,68,0.92)', color: '#fff', letterSpacing: '0.06em', backdropFilter: 'blur(4px)' }}>
                <span style={{ width: 4, height: 4, borderRadius: '50%', background: '#fff', animation: 'pulse 1.5s infinite' }} />
                LIVE
              </div>
            )}
            {isUpcomingAuction && !isSold && (
              <div style={{ position: 'absolute', top: 10, right: 10, padding: '3px 10px', borderRadius: 9999, fontSize: 9, fontWeight: 700, background: 'rgba(23, 107, 135, 0.92)', color: '#1a1200', letterSpacing: '0.06em', backdropFilter: 'blur(4px)' }}>
                Upcoming
              </div>
            )}
            {isNewListing && !isSold && (
              <div style={{ position: 'absolute', top: isLiveNow || isUpcomingAuction ? 36 : 10, right: 10, padding: '2px 8px', borderRadius: 9999, fontSize: 8, fontWeight: 700, background: 'rgba(23, 107, 135, 0.85)', color: '#fff', letterSpacing: '0.06em' }}>
                New
              </div>
            )}
            {car.isPromoted && !isSold && (
              <div style={{ position: 'absolute', bottom: 10, left: 10, padding: '2px 8px', borderRadius: 9999, fontSize: 8, fontWeight: 700, background: 'rgba(23, 107, 135, 0.9)', color: '#0a3340', letterSpacing: '0.08em' }}>
                Featured
              </div>
            )}
          </div>

          <div style={{ padding: '14px 16px 16px' }}>
            <div style={{ marginBottom: 8 }}>
              <h3 style={{ fontSize: 15, fontWeight: 600, color: '#fff', margin: '0 0 2px', fontFamily: 'var(--font-display)', fontStyle: 'italic', lineHeight: 1.3, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                {car.year && <span>{car.year} </span>}
                <span>{car.title}</span>
              </h3>
              <div style={{ fontSize: 11, color: 'rgba(255,255,255,0.5)' }}>{sellerName}</div>
            </div>

            <div style={{ marginBottom: 10 }}>
              <div style={{ fontSize: 9, color: 'rgba(255,255,255,0.35)', fontWeight: 700, letterSpacing: '0.12em', textTransform: 'uppercase' }}>Price</div>
              <div style={{ fontSize: 20, fontWeight: 700, color: 'var(--brand)', fontFamily: 'var(--font-display)', fontStyle: 'italic' }}>
                KES {price.toLocaleString()}
              </div>
            </div>

            <div style={{ display: 'flex', alignItems: 'center', gap: 14, fontSize: 11, color: 'rgba(255,255,255,0.45)', marginBottom: 12 }}>
              {car.mileage && <span style={{ display: 'flex', alignItems: 'center', gap: 3 }}><Gauge size={11} /> {formatMileage(car.mileage)}</span>}
              {car.fuel && <span>{car.fuel}</span>}
              {car.transmission && <span>⚙️{car.transmission}</span>}
              <span style={{ display: 'flex', alignItems: 'center', gap: 3, marginLeft: 'auto' }}><MapPin size={11} /> {city}</span>
            </div>

            <div style={{ display: 'flex', alignItems: 'center', gap: 6, fontSize: 11, color: 'var(--brand)', fontWeight: 600 }}>
              View Details <ArrowRight size={12} />
            </div>
          </div>
        </div>
      </Link>
    </div>
  );
});

export default CarGridItem;

import React, { useState } from 'react';
import { Vehicle } from '../types';
import { isEscrowApplicable, getEscrowBadgeLabel } from '../utils/escrow';
import { X, Lock, ArrowRightLeft, Sparkles, CheckCircle2, ShieldCheck, Tag } from 'lucide-react';
import { Modal, Table, TableHeader, TableBody, TableRow, TableHead, TableCell, Button, Badge, LazyImage } from './ui';

interface CompareModalProps {
  vehicles: Vehicle[];
  onClose: () => void;
  onRemove: (id: string) => void;
  onStartEscrow: (vehicle: Vehicle) => void;
  onQuickViewVehicle?: (vehicle: Vehicle) => void;
}

export const CompareModal: React.FC<CompareModalProps> = ({
  vehicles,
  onClose,
  onRemove,
  onStartEscrow,
  onQuickViewVehicle
}) => {
  const [highlightDifferences, setHighlightDifferences] = useState<boolean>(false);

  if (vehicles.length === 0) return null;

  // Calculate lowest price for best value tag
  const lowestPrice = Math.min(...vehicles.map((v) => v.price));

  // Helper function to check if values differ across columns
  const areValuesDifferent = (extractor: (v: Vehicle) => any) => {
    if (vehicles.length < 2) return false;
    const firstVal = extractor(vehicles[0]);
    return vehicles.some((v) => extractor(v) !== firstVal);
  };

  const title = (
    <div className="flex items-center justify-between w-full pr-8">
      <div className="flex items-center gap-2">
        <ArrowRightLeft className="w-5 h-5 text-[#176B87]" />
        <span>Vehicle Comparison Matrix ({vehicles.length} Selected)</span>
      </div>

      <button
        onClick={() => vehicles.forEach((v) => onRemove(v.id))}
        className="text-xs font-bold text-rose-600 hover:underline flex items-center gap-1"
      >
        <X className="w-3.5 h-3.5" /> Clear All
      </button>
    </div>
  );

  return (
    <Modal isOpen={vehicles.length > 0} onClose={onClose} title={title} maxWidth="5xl">
      <div className="space-y-4">
        {/* Toggle Highlight Differences Bar */}
        <div className="flex items-center justify-between bg-[#F6FAF9] p-3 rounded-xl border border-[#D7E7E4] text-xs">
          <span className="text-[#64748B] font-medium">
            Comparing specifications side-by-side across East Africa certified inventory
          </span>

          <label className="flex items-center gap-2 font-bold text-[#176B87] cursor-pointer select-none">
            <input
              type="checkbox"
              checked={highlightDifferences}
              onChange={(e) => setHighlightDifferences(e.target.checked)}
              className="accent-[#176B87] w-4 h-4 rounded"
            />
            <Sparkles className="w-3.5 h-3.5 text-[#176B87]" />
            <span>Highlight Differences</span>
          </label>
        </div>

        {/* Comparison Matrix Table */}
        <div className="overflow-x-auto border border-[#D7E7E4] rounded-xl">
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="w-44 bg-[#EEF7F5] font-bold text-[#12576D]">Specification</TableHead>
                {vehicles.map((v) => (
                  <TableHead key={v.id} className="min-w-[220px] bg-[#F6FAF9]">
                    <div className="space-y-2 relative pt-2">
                      <button
                        onClick={() => onRemove(v.id)}
                        className="absolute top-0 right-0 p-1 bg-[#DDF4F0] hover:bg-rose-500 hover:text-white text-[#64748B] rounded-full transition-colors"
                        title="Remove vehicle from compare"
                      >
                        <X className="w-3.5 h-3.5" />
                      </button>

                      <div
                        className="h-32 rounded-lg overflow-hidden border border-[#D7E7E4] relative group cursor-pointer"
                        onClick={() => onQuickViewVehicle?.(v)}
                        title="View vehicle details"
                      >
                        <LazyImage src={v.image} alt={v.title} wrapperClassName="h-full w-full" className="h-full w-full object-cover group-hover:scale-105 transition-transform" />
                        {v.price === lowestPrice && vehicles.length > 1 && (
                          <span className="absolute top-2 left-2 bg-emerald-600 text-white text-[10px] font-extrabold px-2 py-0.5 rounded shadow">
                            Lowest Price
                          </span>
                        )}
                      </div>

                      <div
                        className="cursor-pointer group"
                        onClick={() => onQuickViewVehicle?.(v)}
                      >
                        <p className="font-extrabold text-[#176B87] line-clamp-1 text-xs font-display group-hover:text-[#176B87] transition-colors">{v.title}</p>
                        <p className="text-[10px] text-[#64748B] font-medium">{v.location} ({v.county})</p>
                      </div>
                    </div>
                  </TableHead>
                ))}
              </TableRow>
            </TableHeader>

            <TableBody>
              {/* Row: Price */}
              <TableRow className={highlightDifferences && areValuesDifferent((v) => v.price) ? 'bg-[#F3FAF9]/70' : ''}>
                <TableCell className="font-bold text-[#64748B] bg-[#F6FAF9]/50">Price (Ksh)</TableCell>
                {vehicles.map((v) => (
                  <TableCell key={v.id} className="font-black text-base text-[#176B87] font-display">
                    Ksh {v.price.toLocaleString()}
                    {v.marketPriceAvg && (
                      <span className="block text-[10px] text-[#94A3B8] font-normal line-through">
                        Avg: Ksh {v.marketPriceAvg.toLocaleString()}
                      </span>
                    )}
                  </TableCell>
                ))}
              </TableRow>

              {/* Row: Year & Mileage */}
              <TableRow className={highlightDifferences && areValuesDifferent((v) => `${v.year}-${v.mileage}`) ? 'bg-[#F3FAF9]/70' : ''}>
                <TableCell className="font-bold text-[#64748B] bg-[#F6FAF9]/50">Year / Mileage</TableCell>
                {vehicles.map((v) => (
                  <TableCell key={v.id} className="font-bold text-[#0A3340]">
                    {v.year} • {v.mileage.toLocaleString()} km
                  </TableCell>
                ))}
              </TableRow>

              {/* Row: Fuel & Transmission */}
              <TableRow className={highlightDifferences && areValuesDifferent((v) => `${v.fuelType}-${v.transmission}`) ? 'bg-[#F3FAF9]/70' : ''}>
                <TableCell className="font-bold text-[#64748B] bg-[#F6FAF9]/50">Fuel & Transmission</TableCell>
                {vehicles.map((v) => (
                  <TableCell key={v.id} className="font-medium text-[#12576D]">
                    {v.fuelType} ({v.transmission})
                  </TableCell>
                ))}
              </TableRow>

              {/* Row: Engine & Drive */}
              <TableRow className={highlightDifferences && areValuesDifferent((v) => `${v.engineSize}-${v.driveType}`) ? 'bg-[#F3FAF9]/70' : ''}>
                <TableCell className="font-bold text-[#64748B] bg-[#F6FAF9]/50">Engine / Drive</TableCell>
                {vehicles.map((v) => (
                  <TableCell key={v.id} className="font-medium text-[#12576D]">
                    {v.engineSize || 'N/A'} • {v.driveType || '2WD'}
                  </TableCell>
                ))}
              </TableRow>

              {/* Row: Body Style & Condition */}
              <TableRow className={highlightDifferences && areValuesDifferent((v) => `${v.bodyStyle}-${v.condition}`) ? 'bg-[#F3FAF9]/70' : ''}>
                <TableCell className="font-bold text-[#64748B] bg-[#F6FAF9]/50">Body & Condition</TableCell>
                {vehicles.map((v) => (
                  <TableCell key={v.id} className="font-medium text-[#12576D]">
                    {v.bodyStyle || 'N/A'} ({v.condition || 'Used'})
                  </TableCell>
                ))}
              </TableRow>

              {/* Row: Seller & Rating */}
              <TableRow className={highlightDifferences && areValuesDifferent((v) => v.sellerName) ? 'bg-[#F3FAF9]/70' : ''}>
                <TableCell className="font-bold text-[#64748B] bg-[#F6FAF9]/50">Seller & Rating</TableCell>
                {vehicles.map((v) => (
                  <TableCell key={v.id} className="font-semibold text-[#0A3340]">
                    <p>{v.sellerName}</p>
                    <p className="text-[#176B87] font-bold text-[11px] flex items-center gap-1 mt-0.5">
                      ★ {v.sellerRating} <span className="text-[#94A3B8] font-normal">({v.sellerType})</span>
                    </p>
                  </TableCell>
                ))}
              </TableRow>

              {/* Row: 150-Point Inspection */}
              <TableRow className={highlightDifferences && areValuesDifferent((v) => v.inspectionPassed) ? 'bg-[#F3FAF9]/70' : ''}>
                <TableCell className="font-bold text-[#64748B] bg-[#F6FAF9]/50">Pre-purchase inspection</TableCell>
                {vehicles.map((v) => (
                  <TableCell key={v.id}>
                    <Badge variant={v.inspectionPassed ? 'success' : 'neutral'}>
                      {v.inspectionPassed ? '✓ Certified Passed' : 'Pending'}
                    </Badge>
                  </TableCell>
                ))}
              </TableRow>

              {/* Row: Escrow Protection */}
              <TableRow className={highlightDifferences && areValuesDifferent((v) => isEscrowApplicable(v)) ? 'bg-[#F3FAF9]/70' : ''}>
                <TableCell className="font-bold text-[#64748B] bg-[#F6FAF9]/50">Escrow Protection</TableCell>
                {vehicles.map((v) => {
                  const escrowActive = isEscrowApplicable(v);
                  return (
                    <TableCell key={v.id}>
                      <Badge variant={escrowActive ? 'escrow' : 'neutral'}>
                        {escrowActive ? `✓ ${getEscrowBadgeLabel(v)}` : 'Standard Deal'}
                      </Badge>
                    </TableCell>
                  );
                })}
              </TableRow>

              {/* Row: Financing Availability */}
              <TableRow className={highlightDifferences && areValuesDifferent((v) => v.financeAvailable) ? 'bg-[#F3FAF9]/70' : ''}>
                <TableCell className="font-bold text-[#64748B] bg-[#F6FAF9]/50">Financing</TableCell>
                {vehicles.map((v) => (
                  <TableCell key={v.id}>
                    <Badge variant={v.financeAvailable ? 'success' : 'neutral'}>
                      {v.financeAvailable ? '✓ Asset Finance Ready' : 'Cash Deal'}
                    </Badge>
                  </TableCell>
                ))}
              </TableRow>

              {/* Row: Response Time & Freshness */}
              <TableRow className={highlightDifferences && areValuesDifferent((v) => `${v.responseTime}-${v.listingFreshness}`) ? 'bg-[#F3FAF9]/70' : ''}>
                <TableCell className="font-bold text-[#64748B] bg-[#F6FAF9]/50">Response & Freshness</TableCell>
                {vehicles.map((v) => (
                  <TableCell key={v.id} className="text-[11px] font-medium text-[#12576D]">
                    <p className="font-bold text-[#12576D]">{v.responseTime || '< 15 mins'}</p>
                    <p className="text-[#94A3B8]">{v.listingFreshness}</p>
                  </TableCell>
                ))}
              </TableRow>

              {/* Row: CTA Actions */}
              <TableRow>
                <TableCell className="font-bold text-[#64748B] bg-[#F6FAF9]/50">Purchase Option</TableCell>
                {vehicles.map((v) => (
                  <TableCell key={v.id}>
                    <Button
                      variant="primary"
                      size="sm"
                      fullWidth
                      onClick={() => {
                        onClose();
                        onStartEscrow(v);
                      }}
                    >
                      <Lock className="w-3.5 h-3.5 text-[#13B8A6]" />
                      Buy with Escrow
                    </Button>
                  </TableCell>
                ))}
              </TableRow>
            </TableBody>
          </Table>
        </div>
      </div>
    </Modal>
  );
};

export default CompareModal;

import React, { useEffect, useMemo, useState } from 'react';
import { Activity, BarChart3, Bell, Car, CreditCard, ChevronRight, ClipboardCheck, LayoutDashboard, RefreshCw, Settings2, ShieldCheck, ShoppingBag, Users, Wrench } from 'lucide-react';
import { getOwnershipDashboard } from '../services/ownershipApi';
import * as dealerApi from '../services/dealerPlatformApi';
import { getControlPlaneSnapshot } from '../services/commandCenterApi';
import { inspectionAPI } from '../api/api';
import { AuctionExperienceRail, BidderIdentityCard } from './auction/AuctionExperienceRail';
import { isStaffRole } from '../utils/staffRoles';
import { usePrivateSellerCapability } from '../hooks/usePrivateSellerCapability';
import SellerCapabilityPanel from './SellerCapabilityPanel';

type Props = { user: any; vehicles?: any[]; onNavigate: (nav: string) => void };

type RoleConfig = { title: string; subtitle: string; accent: string; actions: Array<{ label: string; nav: string; icon: React.ElementType }> };

const configs: Record<string, RoleConfig> = {
  user: { title: 'Buyer Dashboard', subtitle: 'Your saved vehicles, active transactions and next actions.', accent: '#176B87', actions: [{label:'Browse vehicles',nav:'marketplace',icon:Car},{label:'Saved vehicles',nav:'saved',icon:ShoppingBag},{label:'Vehicle financing',nav:'buyer-platform',icon:CreditCard},{label:'Auctions',nav:'auctions',icon:Activity},{label:'My escrow deals',nav:'buyer-platform',icon:ShieldCheck},{label:'Messages',nav:'chat',icon:Bell}] },
  buyer: { title: 'Buyer Dashboard', subtitle: 'Your saved vehicles, active transactions and next actions.', accent: '#176B87', actions: [{label:'Browse vehicles',nav:'marketplace',icon:Car},{label:'Saved vehicles',nav:'saved',icon:ShoppingBag},{label:'Vehicle financing',nav:'buyer-platform',icon:CreditCard},{label:'Auctions',nav:'auctions',icon:Activity},{label:'My escrow deals',nav:'buyer-platform',icon:ShieldCheck},{label:'Messages',nav:'chat',icon:Bell}] },
  individual_seller: { title: 'Private Seller Dashboard', subtitle: 'Manage your listings, buyer interest and verification status.', accent: '#13B8A6', actions: [{label:'Seller workspace',nav:'seller-platform',icon:LayoutDashboard},{label:'Add / manage cars',nav:'seller-platform',icon:Car},{label:'Inspections',nav:'inspections',icon:ClipboardCheck},{label:'Messages',nav:'chat',icon:Bell}] },
  broker: { title: 'Seller Dashboard', subtitle: 'Manage seller inventory and marketplace activity.', accent: '#12576d', actions: [{label:'Seller workspace',nav:'seller-platform',icon:LayoutDashboard},{label:'Marketplace',nav:'marketplace',icon:Car},{label:'Messages',nav:'chat',icon:Bell}] },
  dealer: { title: 'Dealer Dashboard', subtitle: 'Commercial inventory, leads, auctions, subscriptions and payouts.', accent: '#12576d', actions: [{label:'Dealer workspace',nav:'dealer-dashboard',icon:LayoutDashboard},{label:'Inventory',nav:'dealer-dashboard',icon:Car},{label:'Auctions',nav:'auctions',icon:Activity},{label:'Finance',nav:'finance',icon:BarChart3}] },
  ghost_checker: { title: 'Inspector Dashboard', subtitle: 'Assigned inspections, evidence and execution status.', accent: '#5AAFA4', actions: [{label:'Inspection work',nav:'inspections',icon:ClipboardCheck},{label:'Messages',nav:'chat',icon:Bell}] },
};

const staffActions = [{label:'Control plane',nav:'admin',icon:LayoutDashboard},{label:'Vehicle moderation',nav:'admin',icon:Car},{label:'Inspections',nav:'inspections',icon:ClipboardCheck},{label:'Support',nav:'support',icon:Users}];

export default function DashboardHub({ user, vehicles = [], onNavigate }: Props) {
  const role = user?.role || 'user';
  // Phase 13E: a private seller is still a buyer. individual_seller no longer gets a seller-only view; it gets the buyer dashboard
  // plus the seller workspace entry. The seller section itself is driven by the real capability state (SellerCapabilityPanel).
  const isPersonal = role === 'user' || role === 'buyer' || role === 'individual_seller';
  const { capability, loading: capLoading, error: capError, reload: reloadCap } = usePrivateSellerCapability(isPersonal);
  const sellerApproved = capability ? capability.status === 'approved' : role === 'individual_seller';
  const baseConfig = configs[role === 'individual_seller' ? 'user' : role];
  // Phase 13F: a legacy individual_seller whose real capability is suspended/revoked/rejected is not offered the seller workspace entry (the backend refuses their seller writes).
  const sellerBlocked = !!capability && ['suspended', 'revoked', 'rejected'].includes(capability.status);
  const personalConfig = role === 'individual_seller' ? { ...baseConfig, title: 'My Dashboard', subtitle: 'Buy and sell from one account: your saved vehicles, active transactions and private-seller tools.', actions: sellerBlocked ? baseConfig.actions : [...baseConfig.actions, {label:'Seller workspace',nav:'seller-platform',icon:LayoutDashboard}] } : (isPersonal && capability?.status === 'approved' ? { ...baseConfig, actions: [...baseConfig.actions, {label:'Seller workspace',nav:'seller-platform',icon:LayoutDashboard}] } : baseConfig);
  const config = (isPersonal ? personalConfig : undefined) || configs[role] || (['admin','superadmin','marketing','technical_support','hr','accounts','escrow_officer','ad_manager','moderator'].includes(role) ? { title: 'Platform Operations Dashboard', subtitle: 'Role-scoped control, queues and platform health.', accent: '#5AAFA4', actions: staffActions } : configs.user);
  const [density, setDensity] = useState<'comfortable'|'compact'>('comfortable');
  const [hidden, setHidden] = useState<string[]>([]);
  const [snapshot, setSnapshot] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [sourceError, setSourceError] = useState('');

  const cards = useMemo(() => {
    const owned = vehicles.filter((v) => v?.sellerId && v.sellerId === (user?.id || user?._id));
    if (role === 'dealer' || role === 'broker') return [{id:'inventory',label:'Your inventory',value:owned.length,icon:Car},{id:'saved',label:'Saved vehicles',value:0,icon:ShoppingBag},{id:'activity',label:'Marketplace activity',value:vehicles.length,icon:Activity}];
    if (['admin','superadmin','marketing','technical_support','hr','accounts','escrow_officer','ad_manager','moderator'].includes(role)) return [{id:'users',label:'Users',value:snapshot?.counts?.users ?? '—',icon:Users},{id:'cars',label:'Vehicles',value:snapshot?.counts?.cars ?? '—',icon:Car},{id:'incidents',label:'Incidents',value:snapshot?.counts?.incidents ?? '—',icon:Activity},{id:'alerts',label:'Alerts',value:snapshot?.counts?.alerts ?? '—',icon:Bell}];
    if (role === 'ghost_checker') return [{id:'assigned',label:'Assigned inspections',value:Array.isArray(snapshot?.orders) ? snapshot.orders.length : '—',icon:ClipboardCheck},{id:'messages',label:'Messages',value:'—',icon:Bell},{id:'market',label:'Marketplace',value:vehicles.length,icon:Car}];
    const buyerCards = [{id:'saved',label:'Saved vehicles',value:'—',icon:ShoppingBag},{id:'vehicles',label:'Marketplace inventory',value:vehicles.length,icon:Car},{id:'alerts',label:'Action alerts',value:'—',icon:Bell}];
    return sellerApproved ? [{id:'inventory',label:'Your inventory',value:owned.length,icon:Car}, ...buyerCards] : buyerCards;
  }, [vehicles, user, role, snapshot, sellerApproved]);

  const refresh = async () => {
    setLoading(true); setSourceError('');
    try {
      if (['admin','superadmin','marketing','technical_support','hr','accounts','escrow_officer','ad_manager','moderator'].includes(role)) {
        const result = await getControlPlaneSnapshot(); setSnapshot(result?.data || result);
      } else if (role === 'dealer') {
        const result = await dealerApi.getDealerDashboard(); setSnapshot(result?.data || result);
      } else if (role === 'user' || role === 'buyer' || role === 'individual_seller') {
        const result = await getOwnershipDashboard(); setSnapshot(result);
      } else if (role === 'ghost_checker') {
        const result = await inspectionAPI.myAssigned(); setSnapshot(result?.data || result);
      }
    } catch (e) { setSourceError('Live dashboard data could not be refreshed. Existing values were not replaced with mock data.'); }
    finally { setLoading(false); }
  };

  useEffect(() => { refresh(); }, [role]);

  const toggle = (id: string) => setHidden((prev) => prev.includes(id) ? prev.filter(x=>x!==id) : [...prev,id]);

  return <section className={`space-y-6 pb-10 auction-dashboard-experience kayad-portal kayad-portal--${role}`} data-kayad-portal={role} data-dashboard-role={role}>
    {!isStaffRole(role) && <>
      <AuctionExperienceRail current="wallet" />
      <BidderIdentityCard user={user} savedCount={null} onPayments={() => onNavigate('payments')} />
    </>}
    <div className="rounded-3xl p-6 text-white shadow-lg" style={{background:`linear-gradient(135deg, ${config.accent}, #0A3340)`}}>
      <div className="flex flex-col gap-5 md:flex-row md:items-center md:justify-between">
        <div><p className="text-[10px] font-black uppercase tracking-[0.2em] text-white/60">KAYAD workspace</p><h1 className="mt-1 text-2xl font-black">{config.title}</h1><p className="mt-1 max-w-2xl text-sm text-white/70">{config.subtitle}</p></div>
        <div className="flex flex-wrap gap-2"><button onClick={refresh} disabled={loading} className="inline-flex items-center gap-2 rounded-xl border border-white/20 bg-white/10 px-3 py-2 text-xs font-bold hover:bg-white/15"><RefreshCw size={14} className={loading?'animate-spin':''}/> Refresh</button><button onClick={()=>setDensity(density==='comfortable'?'compact':'comfortable')} className="inline-flex items-center gap-2 rounded-xl border border-white/20 bg-white/10 px-3 py-2 text-xs font-bold"><Settings2 size={14}/> {density==='comfortable'?'Compact':'Comfortable'}</button></div>
      </div>
    </div>

    {isPersonal && <SellerCapabilityPanel capability={capability} loading={capLoading} error={capError} onReload={reloadCap} onOpenWorkspace={() => onNavigate('seller-platform')} />}

    {sourceError && <div className="rounded-xl border border-[#BDE5DE] bg-[#F3FAF9] p-3 text-xs font-bold text-[#0A3340]">{sourceError}</div>}

    <div className={`grid gap-3 ${density==='compact'?'sm:grid-cols-4':'sm:grid-cols-2 lg:grid-cols-4'}`}>
      {cards.filter(c=>!hidden.includes(c.id)).map((card)=>{const Icon=card.icon;return <div key={card.id} className="group rounded-2xl border border-[#D7E7E4] bg-white p-4 shadow-sm"><div className="flex items-start justify-between"><div><p className="text-[10px] font-black uppercase tracking-wider text-[#5B6B7D]">{card.label}</p><p className="mt-1 text-2xl font-black text-[#0A3340]">{card.value}</p></div><Icon size={20} style={{color:config.accent}}/></div><button onClick={()=>toggle(card.id)} className="mt-3 text-[10px] font-bold text-[#5B6B7D] opacity-0 group-hover:opacity-100">Hide card</button></div>})}
    </div>

    <div className="grid gap-5 lg:grid-cols-[1.3fr_.7fr]">
