import { useState, useEffect } from 'react';
import { TrendingUp, TrendingDown, Minus, BarChart3, Clock, Target } from 'lucide-react';
import { marketAPI } from '../api/api';

const fmtKES = (n) => 'KES ' + Number(n || 0).toLocaleString('en-KE');

const TREND_CONFIG = {
  undervalued: { icon: TrendingUp, color: '#22c55e', label: 'Undervalued', desc: 'Priced below market — good buying opportunity' },
  stable: { icon: Minus, color: '#176B87', label: 'Fair Value', desc: 'Priced in line with market' },
  overvalued: { icon: TrendingDown, color: '#ef4444', label: 'Overvalued', desc: 'Priced above typical market range' },
};

function ScoreRing({ score, size = 56 }) {
  const r = (size - 8) / 2;
  const circ = 2 * Math.PI * r;
  const offset = circ - (score / 100) * circ;
  const color = score >= 75 ? '#22c55e' : score >= 50 ? 'var(--brand)' : '#ef4444';
  return (
    <svg width={size} height={size} style={{ flexShrink: 0 }}>
      <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth={4} />
      <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke={color} strokeWidth={4}
        strokeDasharray={circ} strokeDashoffset={offset} strokeLinecap="round"
        transform={`rotate(-90 ${size / 2} ${size / 2})`}
        style={{ transition: 'stroke-dashoffset 1s ease' }} />
      <text x={size / 2} y={size / 2} textAnchor="middle" dominantBaseline="central"
        fill={color} fontSize={size * 0.28} fontWeight={900} fontFamily="var(--font-display)">
        {score}
      </text>
    </svg>
  );
}

export default function MarketPulse({ carId, carBrand, carYear }) {
  const [pulse, setPulse] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  useEffect(() => {
    if (!carId) { setLoading(false); return; }
    setLoading(true);
    setError(false);
    marketAPI.pulse(carId)
      .then(d => setPulse(d?.data || d))
      .catch(() => setError(true))
      .finally(() => setLoading(false));
  }, [carId]);

  if (loading) return (
    <div style={{ background: 'var(--card)', borderRadius: 'var(--radius-lg)', border: '1px solid var(--border)', padding: 16, marginBottom: 14 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 12 }}>
        <BarChart3 size={14} style={{ color: 'var(--brand)' }} />
        <span style={{ fontSize: 11, fontWeight: 700, color: 'rgba(255,255,255,0.5)', textTransform: 'uppercase', letterSpacing: '0.06em' }}>Market Pulse</span>
      </div>
      <div style={{ height: 14, borderRadius: 4, background: 'rgba(255,255,255,0.05)', width: '60%', marginBottom: 8 }} />
      <div style={{ height: 14, borderRadius: 4, background: 'rgba(255,255,255,0.05)', width: '40%' }} />
    </div>
  );

  if (error || !pulse) return null;

  const trend = TREND_CONFIG[pulse.trend] || TREND_CONFIG.stable;
  const TrendIcon = trend.icon;

  return (
    <div style={{
      background: 'linear-gradient(135deg, var(--card) 0%, rgba(19, 184, 166, 0.04) 100%)',
      borderRadius: 'var(--radius-lg)', border: '1px solid rgba(19, 184, 166, 0.15)',
      padding: 16, marginBottom: 14,
    }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 14 }}>
        <BarChart3 size={14} style={{ color: 'var(--brand)' }} />
        <span style={{ fontSize: 11, fontWeight: 700, color: 'rgba(255,255,255,0.6)', textTransform: 'uppercase', letterSpacing: '0.06em' }}>Market Pulse</span>
        <span style={{ marginLeft: 'auto', fontSize: 10, color: 'rgba(255,255,255,0.25)' }}>{carBrand} · {carYear}</span>
      </div>

      <div style={{ display: 'flex', gap: 16, alignItems: 'center', marginBottom: 14 }}>
        <ScoreRing score={pulse.predictiveScore} />
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 13, fontWeight: 800, color: '#fff', marginBottom: 2 }}>
            {pulse.demandScore >= 80 ? 'High Demand' : pulse.demandScore >= 60 ? 'Moderate Demand' : 'Low Demand'}
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 5, marginBottom: 4 }}>
            <TrendIcon size={12} style={{ color: trend.color }} />
            <span style={{ fontSize: 11, fontWeight: 700, color: trend.color }}>{trend.label}</span>
          </div>
          <div style={{ fontSize: 10, color: 'rgba(255,255,255,0.4)', lineHeight: 1.4 }}>{trend.desc}</div>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginBottom: 12 }}>
        <div style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 8, padding: '10px 12px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 5, marginBottom: 4 }}>
            <Target size={11} style={{ color: 'var(--brand)' }} />
            <span style={{ fontSize: 9, color: 'rgba(255,255,255,0.4)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Fair Price</span>
          </div>
          <div style={{ fontSize: 12, fontWeight: 700, color: '#fff' }}>{fmtKES(pulse.fairPriceRange.avg)}</div>
          <div style={{ fontSize: 10, color: 'rgba(255,255,255,0.3)' }}>
            {fmtKES(pulse.fairPriceRange.min)} – {fmtKES(pulse.fairPriceRange.max)}
          </div>
        </div>
        <div style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 8, padding: '10px 12px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 5, marginBottom: 4 }}>
            <Clock size={11} style={{ color: trend.color }} />
            <span style={{ fontSize: 9, color: 'rgba(255,255,255,0.4)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Est. Sell Time</span>
          </div>
          <div style={{ fontSize: 12, fontWeight: 700, color: '#fff' }}>{pulse.estDaysToSell} days</div>
          <div style={{ fontSize: 10, color: 'rgba(255,255,255,0.3)' }}>
            {pulse.daysOnMarket} days on market
          </div>
        </div>
      </div>

      <div style={{ height: 4, borderRadius: 9999, background: 'rgba(255,255,255,0.06)', overflow: 'hidden', marginBottom: 8 }}>
        <div style={{
          width: `${pulse.demandScore}%`, height: '100%', borderRadius: 9999,
          background: `linear-gradient(90deg, #176B87, ${pulse.demandScore >= 80 ? '#22c55e' : pulse.demandScore >= 50 ? 'var(--brand)' : '#ef4444'})`,
          transition: 'width 1s ease',
        }} />
      </div>
      <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 9, color: 'rgba(255,255,255,0.3)' }}>
        <span>Market Demand Score: {pulse.demandScore}/100</span>
        <span>{pulse.sampleSize} comparable listings</span>
      </div>
    </div>
  );
}

import React from 'react';
import { LucideIcon, ExternalLink } from 'lucide-react';

export interface MarketingCardData {
  id: string;
  /** Shown as a small uppercase label in the corner - always visible,
   * never hidden or minimized. A marketplace's users need to be able
   * to tell a sponsored placement from a real listing at a glance;
   * burying or shrinking this label defeats that. */
  label: 'Sponsored' | 'Partner' | 'Featured Dealer';
  category: string;
  name: string;
  tagline: string;
  ctaLabel: string;
  ctaUrl?: string;
  icon: LucideIcon;
  /** Tailwind color token, e.g. '#176B87' or 'emerald' - used for the
   * icon badge and accent border so different sponsor categories are
   * visually distinguishable from each other, not just from real cars. */
  accentColor: string;
}

interface MarketingCardProps {
  data: MarketingCardData;
}

/**
 * A sponsor/partner/advertisement placement designed to sit inside the
 * same grid as VehicleCard (matches its overall footprint so it doesn't
 * break grid alignment) but is deliberately NOT a visual copy of it -
 * no image-first layout, no price, no "View Details" affordance shaped
 * like a listing. A user should never be able to mistake this for a
 * real vehicle, even glancing quickly while scrolling.
 */
export const MarketingCard: React.FC<MarketingCardProps> = React.memo(({ data }) => {
  const Icon = data.icon;

  const handleClick = () => {
    if (data.ctaUrl) {
      window.open(data.ctaUrl, '_blank', 'noopener,noreferrer');
    }
  };

  return (
    <div
      onClick={handleClick}
      onKeyDown={(e) => {
        if ((e.key === 'Enter' || e.key === ' ') && data.ctaUrl) {
          e.preventDefault();
          handleClick();
        }
      }}
      role={data.ctaUrl ? 'button' : undefined}
      tabIndex={data.ctaUrl ? 0 : undefined}
      aria-label={`${data.label}: ${data.name}`}
      className="relative bg-gradient-to-br from-[#F6FAF9] to-white rounded-2xl overflow-hidden border-2 border-dashed border-[#D7E7E4] hover:border-[#BDE5DE] transition-all flex flex-col justify-between p-4 h-full min-h-[220px] cursor-pointer group focus:outline-none focus:ring-2 focus:ring-[#176B87] focus:ring-offset-2"
    >
      {/* Always-visible disclosure label - top right, high contrast,
          never smaller or lower-contrast than any other badge on a real
          VehicleCard, since this needs to be at least as noticeable. */}
      <span className="absolute top-2.5 right-2.5 px-2 py-0.5 rounded-full text-[9px] font-black uppercase tracking-wider bg-[#12576D] text-white">
        {data.label}
      </span>

      <div className="space-y-3">
        <div
          className="w-11 h-11 rounded-xl flex items-center justify-center shrink-0"
          style={{ backgroundColor: `${data.accentColor}18`, border: `1px solid ${data.accentColor}30` }}
        >
          <Icon className="w-5 h-5" style={{ color: data.accentColor }} />
        </div>

        <div>
          <p className="text-[10px] font-extrabold uppercase tracking-wider text-[#94A3B8] mb-0.5">
            {data.category}
          </p>
          <h3 className="text-sm font-black text-[#176B87] font-display leading-snug">
            {data.name}
          </h3>
          <p className="text-xs text-[#64748B] font-medium mt-1 leading-snug">
            {data.tagline}
          </p>
        </div>
      </div>

      <div
        className="flex items-center justify-between gap-2 mt-3 pt-3 border-t border-[#D7E7E4] text-xs font-extrabold group-hover:gap-3 transition-all"
        style={{ color: data.accentColor }}
      >
        <span>{data.ctaLabel}</span>
        <ExternalLink className="w-3.5 h-3.5 shrink-0" />
      </div>
    </div>
  );
});

MarketingCard.displayName = 'MarketingCard';

export default MarketingCard;

import React, { useEffect, useMemo, useState } from 'react';
import { MapPin, RotateCcw, SlidersHorizontal } from 'lucide-react';
import { getSearchFacets } from '../services/searchApi';

const FIELDS = [
  ['brand','Make'], ['model','Model'], ['location','Region'], ['body','Body'], ['fuel','Fuel'],
  ['transmission','Transmission'], ['color','Colour'], ['condition','Condition'], ['dealerType','Seller'],
];

export default function MarketplaceFilterBar({ filters, onFilterChange, onClear }) {
  const [facets, setFacets] = useState(null);
  const [open, setOpen] = useState(false);
  useEffect(() => { let dead=false; getSearchFacets(filters).then(v=>{if(!dead)setFacets(v)}).catch(()=>{}); return ()=>{dead=true}; }, [JSON.stringify(filters)]);
  const options = useMemo(() => ({
    brand: facets?.brands || [], model: facets?.models || [], location: facets?.locations || [], body: facets?.bodyTypes || [],
    fuel: facets?.fuels || [], transmission: facets?.transmissions || [], color: facets?.colors || [], condition: facets?.conditions || [],
    dealerType: [{value:'dealer',label:'Dealers'},{value:'private',label:'Private sellers'}],
  }), [facets]);
  const active = Object.entries(filters).filter(([k,v]) => k !== 'filter' && v).length + (filters.filter !== 'all' ? 1 : 0);
  return <section className="marketplace-filter-shell" aria-label="Marketplace filters">
    <div className="marketplace-filter-head">
      <div className="marketplace-filter-title"><SlidersHorizontal size={16}/><strong>Filter marketplace</strong>{active>0&&<span>{active}</span>}</div>
      <div className="marketplace-filter-actions"><small>{facets?.total ?? '—'} matching vehicles</small>{active>0&&<button type="button" onClick={onClear}><RotateCcw size={13}/> Reset</button>}<button type="button" className="mobile-filter-toggle" onClick={()=>setOpen(v=>!v)}>{open?'Hide filters':'All filters'}</button></div>
    </div>
    <div className={`marketplace-filter-grid ${open?'marketplace-filter-grid-open':''}`}>
      {FIELDS.map(([key,label]) => <label key={key} className="marketplace-filter-field"><span>{key==='location'?<MapPin size={12}/>:null}{label}</span><select value={filters[key]||''} onChange={e=>onFilterChange(key,e.target.value)}><option value="">Any {label}</option>{(options[key]||[]).map(item=>{const value=typeof item==='string'?item:item.value; const text=typeof item==='string'?item:item.label; return <option key={value} value={value}>{text}</option>})}</select></label>)}
      <label className="marketplace-filter-field"><span>Sale</span><select value={filters.filter==='all'?'':filters.filter} onChange={e=>onFilterChange('category',e.target.value||'all')}><option value="">All listings</option><option value="auction">Auctions</option><option value="fixed">Buy Now</option><option value="sold">Sold</option></select></label>
      <label className="marketplace-filter-field"><span>Min price</span><input inputMode="numeric" value={filters.priceMin||''} placeholder="KES" onChange={e=>onFilterChange('priceMin',e.target.value.replace(/\D/g,''))}/></label>
      <label className="marketplace-filter-field"><span>Max price</span><input inputMode="numeric" value={filters.priceMax||''} placeholder="KES" onChange={e=>onFilterChange('priceMax',e.target.value.replace(/\D/g,''))}/></label>
      <label className="marketplace-filter-field"><span>Year from</span><input inputMode="numeric" value={filters.yearMin||''} placeholder="YYYY" onChange={e=>onFilterChange('yearMin',e.target.value.replace(/\D/g,'').slice(0,4))}/></label>
      <label className="marketplace-filter-field"><span>Year to</span><input inputMode="numeric" value={filters.yearMax||''} placeholder="YYYY" onChange={e=>onFilterChange('yearMax',e.target.value.replace(/\D/g,'').slice(0,4))}/></label>
      <label className="marketplace-filter-field"><span>Mileage to</span><input inputMode="numeric" value={filters.mileageMax||''} placeholder="KM" onChange={e=>onFilterChange('mileageMax',e.target.value.replace(/\D/g,''))}/></label>
      <label className="marketplace-filter-check"><input type="checkbox" checked={filters.verifiedOnly==='true'} onChange={e=>onFilterChange('verifiedOnly',e.target.checked?'true':'')}/><span>Verified dealers</span></label>
      <label className="marketplace-filter-check"><input type="checkbox" checked={filters.inspectedOnly==='true'} onChange={e=>onFilterChange('inspectedOnly',e.target.checked?'true':'')}/><span>Inspected only</span></label>
    </div>
  </section>;
}

