import { useState, useEffect, type ReactNode, useRef } from 'react';
import { loginPathFor } from '../../utils/authIntent';
import AdminSidebar from './AdminSidebar';
import { useAuth, SessionRecovery } from '../../context/AuthContext';
import { useLocation, Navigate } from 'react-router-dom';
import { ChevronRight, Menu } from 'lucide-react';
import { ADMIN_ROLE_LABELS as ROLE_LABELS } from './adminRoleLabels';
import '../../styles/kayad-admin-shell.css';
import '../../styles/kayad-admin-legacy-surface.css';


const ACRONYMS = new Set(['ntsa', 'ai', 'cms', 'seo', 'vxp', 'xos', 'kyc', 'rbac', 'api']);
const crumbLabel = (segment: string) => segment.split('-').map(word => (ACRONYMS.has(word.toLowerCase()) ? word.toUpperCase() : word)).join(' ');

interface AdminLayoutProps {
  children: ReactNode;
}

export default function AdminLayout({ children }: AdminLayoutProps) {
  const { user, isAuth, loading, sessionStatus } = useAuth();
  const location = useLocation();
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const sidebarToggleRef = useRef<HTMLButtonElement>(null);
  const closeSidebar = () => {
    setSidebarOpen(false);
    sidebarToggleRef.current?.focus();
  };

  useEffect(() => {
    document.body.style.overflow = sidebarOpen ? 'hidden' : '';
    return () => { document.body.style.overflow = ''; };
  }, [sidebarOpen]);

  useEffect(() => {
    if (!sidebarOpen) return;
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Escape') return;
      closeSidebar();
    };
    document.addEventListener('keydown', onKeyDown);
    const firstLink = document.querySelector<HTMLElement>('.admin-sidebar a[href]');
    firstLink?.focus();
    return () => document.removeEventListener('keydown', onKeyDown);
  }, [sidebarOpen]);

  useEffect(() => {
    setSidebarOpen(false);
  }, [location.pathname]);

  if (loading) return null;
  if (!isAuth && sessionStatus === 'error') return <SessionRecovery />;
  if (!isAuth) return <Navigate to={loginPathFor(location)} replace />;

  const STAFF_ROLES = ['admin', 'superadmin', 'moderator', 'marketing', 'technical_support', 'hr', 'accounts', 'escrow_officer', 'ad_manager', 'ghost_checker'];
  if (!STAFF_ROLES.includes(user?.role || '')) return <Navigate to="/" replace />;
  const segments = location.pathname.split('/').filter(Boolean);
  const roleLabel = ROLE_LABELS[user?.role || ''] || user?.role || 'Staff';
  const displayName = user?.name?.trim() || 'Administrator';
  const initials = displayName.split(/\s+/).filter(Boolean).slice(0, 2).map(part => part[0]).join('').toUpperCase() || 'A';

  return (
    <div className="kayad-admin-shell">
      <AdminSidebar mobileOpen={sidebarOpen} onToggle={closeSidebar} />
      <div className="kayad-admin-shell__main">
        <header className="kayad-admin-header">
          <nav className="kayad-admin-header__breadcrumb" aria-label="Breadcrumb">
            <button
              ref={sidebarToggleRef}
              type="button"
              className="sidebar-toggle-btn"
              aria-label={sidebarOpen ? 'Close admin navigation' : 'Open admin navigation'}
              aria-expanded={sidebarOpen}
              aria-controls="admin-sidebar-navigation"
              onClick={() => setSidebarOpen(value => !value)}
            >
              <Menu size={19} aria-hidden="true" />
            </button>
            <span className="kayad-admin-header__brand">KAYAD</span>
            {segments.map((segment, index) => (
              <span className="kayad-admin-header__crumb" key={`${segment}-${index}`}>
                <ChevronRight size={13} aria-hidden="true" />
                <span aria-current={index === segments.length - 1 ? 'page' : undefined} className={index === segments.length - 1 ? 'is-current' : ''}>
                  {crumbLabel(segment)}
                </span>
              </span>
            ))}
          </nav>
          <div className="kayad-admin-header__identity" role="group" aria-label={`Signed in as ${displayName}, ${roleLabel}`}>
            <div className="kayad-admin-header__identity-copy">
              <span className="kayad-admin-header__identity-name">{displayName}</span>
              <span className="kayad-admin-header__identity-role">{roleLabel}</span>
            </div>
            <div className="kayad-admin-header__avatar" aria-hidden="true">{initials}</div>
          </div>
        </header>
        <main className="kayad-admin-shell__content">
          {children}
        </main>
      </div>
    </div>
  );
}

import { useState, type FC, type FormEvent } from 'react';
import { ShieldCheck, CheckCircle2, AlertTriangle, Users, Gavel, DollarSign, FileText, Megaphone, Plus, Trash2, Eye, ExternalLink, Sparkles, Image as ImageIcon } from 'lucide-react';
import { useMarketplace } from '../../context/MarketplaceContext';
import { Badge } from '../ui/Badge';
import { Button } from '../ui/Button';

interface AdvertItem {
  id: string;
  title: string;
  subtitle: string;
  badge: string;
  ctaText: string;
  imageUrl: string;
  placement: string;
  isActive: boolean;
  createdAt: string;
}

const PRESET_IMAGES = [
  { label: 'Japanese Luxury SUV', url: 'https://images.unsplash.com/photo-1533473359331-0135ef1b58bf?auto=format&fit=crop&w=1200&q=80' },
  { label: 'Sports Coupe Red', url: 'https://images.unsplash.com/photo-1617814076367-b759c7d7e738?auto=format&fit=crop&w=1200&q=80' },
  { label: 'Executive Sedan', url: 'https://images.unsplash.com/photo-1555215695-3004980ad54e?auto=format&fit=crop&w=1200&q=80' },
  { label: 'Off-Road 4x4', url: 'https://images.unsplash.com/photo-1549399542-7e3f8b79c341?auto=format&fit=crop&w=1200&q=80' },
];

export const AdminPage: FC = () => {
  const { vehicles, escrowContracts, navigateTo } = useMarketplace();

  // Advert Form State
  const [adverts, setAdverts] = useState<AdvertItem[]>([]);

  const [formTitle, setFormTitle] = useState('');
  const [formSubtitle, setFormSubtitle] = useState('');
  const [formBadge, setFormBadge] = useState('FEATURED ADVERT');
  const [formCta, setFormCta] = useState('Explore Offer');
  const [formImage, setFormImage] = useState(PRESET_IMAGES[0].url);
  const [formPlacement, setFormPlacement] = useState('Hero Banner');
  const [successMessage, setSuccessMessage] = useState('');

  const handleCreateAdvert = (e: FormEvent) => {
    e.preventDefault();
    if (!formTitle.trim()) return;

    const newAd: AdvertItem = {
      id: `ad_${Date.now()}`,
      title: formTitle,
      subtitle: formSubtitle || 'Exclusive promotion verified by KAYAD Admin.',
      badge: formBadge || 'FEATURED',
      ctaText: formCta || 'Learn More',
      imageUrl: formImage,
      placement: formPlacement,
      isActive: true,
      createdAt: 'Just now',
    };

    setAdverts([newAd, ...adverts]);
    setSuccessMessage('New advertisement published successfully!');
    setFormTitle('');
    setFormSubtitle('');

    setTimeout(() => setSuccessMessage(''), 4000);
  };

  const toggleAdvertStatus = (id: string) => {
    setAdverts(prev =>
      prev.map(ad => (ad.id === id ? { ...ad, isActive: !ad.isActive } : ad))
    );
  };

  const deleteAdvert = (id: string) => {
    setAdverts(prev => prev.filter(ad => ad.id !== id));
  };

  return (
    <div className="py-10 px-4 sm:px-6 lg:px-8 max-w-7xl mx-auto space-y-8 bg-[#F6FAF9]">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-6 border-b border-[#D7E7E4]">
        <div>
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-[#176B87]/10 text-[#176B87] text-xs font-bold uppercase tracking-wider mb-2 border border-[#176B87]/20">
            <ShieldCheck className="w-4 h-4 text-[#13B8A6]" />
            <span>Admin Control Panel</span>
          </div>
          <h1 className="text-3xl font-extrabold text-[#176B87] font-serif tracking-tight">
            KAYAD Platform Oversight & Marketing
          </h1>
          <p className="text-sm text-[#176b87] mt-1 font-medium">
            Manage active escrow compliance, platform analytics, and live advertisement banners.
          </p>
        </div>
      </div>

      {/* Metrics */}
      <div className="grid grid-cols-1 sm:grid-cols-4 gap-4">
        <div className="p-5 rounded-2xl bg-white border border-[#D7E7E4] shadow-xs">
          <span className="text-xs font-bold text-[#64748b] uppercase block">Total Active Listings</span>
          <span className="text-3xl font-black text-[#176B87] font-serif">{vehicles.length}</span>
        </div>
