import { useState, useEffect } from 'react';
import { Link } from 'wouter';
import { Scale, X, ArrowRight } from 'lucide-react';
import { useProductComparison } from '@/hooks/use-data';

export function ComparisonBar() {
  const { comparison, loading, clearComparison } = useProductComparison();
  const [isVisible, setIsVisible] = useState(false);
  const [productCount, setProductCount] = useState(0);

  useEffect(() => {
    const count = comparison?.product_ids?.length || 0;
    setProductCount(count);
    setIsVisible(count > 0);
  }, [comparison?.product_ids]);

  if (!isVisible || loading) return null;

  return (
    <div className="fixed bottom-0 left-0 right-0 bg-white border-t border-[#D7E7E4] shadow-lg z-40">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-4">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-2 text-navy-900">
              <Scale className="w-5 h-5" />
              <span className="font-semibold">{productCount} product{productCount !== 1 ? 's' : ''} to compare</span>
            </div>
            <p className="text-sm text-[#64748B] hidden sm:block">
              Compare up to 4 products side-by-side
            </p>
          </div>
          <div className="flex items-center gap-3">
            <button
              onClick={() => {
                clearComparison();
              }}
              className="text-sm text-[#64748B] hover:text-[#12576D] transition-colors flex items-center gap-1"
            >
              <X className="w-4 h-4" />
              Clear
            </button>
            <Link
              href="/compare"
              className="btn-primary flex items-center gap-2"
            >
              Compare Now
              <ArrowRight className="w-4 h-4" />
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import {
  Building,
  Car,
  Gavel,
  Banknote,
  ClipboardCheck,
  FileText,
  Users,
  Shield,
  CheckCircle2,
  Circle,
  ChevronDown,
  ChevronRight,
  AlertTriangle,
  Info,
  ExternalLink,
  FileCheck,
  Clock
} from 'lucide-react';
import { Card } from '../ui/Card';
import { Badge } from '../ui/Badge';
import { Button } from '../ui/Button';
import type {
  ComplianceCheck,
  ComplianceCategory,
  ComplianceItem
} from '../../utils/auctionCompliance';
import {
  COMPLIANCE_CATEGORIES,
  getChecksByCategory,
  getComplianceSummary
} from '../../utils/auctionCompliance';

export interface ComplianceChecklistProps {
  checks: ComplianceCheck[];
  onCheckToggle?: (checkId: string, isComplete: boolean) => void;
  onViewPolicy?: (policyId: string) => void;
  onSubmitForReview?: () => void;
  isEditable?: boolean;
}

// Category icons
const CATEGORY_ICONS: Record<string, React.ReactNode> = {
  organization: <Building className="w-5 h-5" />,
  vehicle: <Car className="w-5 h-5" />,
  auction: <Gavel className="w-5 h-5" />,
  financial: <Banknote className="w-5 h-5" />,
  inspection: <ClipboardCheck className="w-5 h-5" />,
  document: <FileText className="w-5 h-5" />,
  marketplace_policy: <Shield className="w-5 h-5" />,
  customer_protection: <Users className="w-5 h-5" />,
};

// Single check item
const ComplianceCheckItem: React.FC<{
  check: ComplianceCheck;
  onToggle?: (id: string, complete: boolean) => void;
  editable?: boolean;
}> = ({ check, onToggle, editable }) => {
  const categoryInfo = COMPLIANCE_CATEGORIES[check.category];

  return (
    <div className={`flex items-start gap-3 p-3 rounded-lg border ${
      check.isComplete
        ? 'bg-emerald-50 border-emerald-200'
        : check.severity === 'required'
          ? 'bg-red-50 border-red-200'
          : 'bg-[#F6FAF9] border-[#D7E7E4]'
    }`}>
      <button
        onClick={() => editable && onToggle?.(check.id, !check.isComplete)}
        disabled={!editable}
        className={`mt-0.5 ${check.isComplete ? 'text-emerald-600' : 'text-[#94A3B8]'} ${
          editable ? 'cursor-pointer hover:text-emerald-600' : 'cursor-default'
        }`}
      >
        {check.isComplete ? (
          <CheckCircle2 className="w-5 h-5" />
        ) : (
          <Circle className="w-5 h-5" />
        )}
      </button>
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2 flex-wrap">
          <span className={`text-sm font-medium ${
            check.isComplete ? 'text-emerald-800' : 'text-[#0A3340]'
          }`}>
            {check.label}
          </span>
          {check.severity === 'required' && !check.isComplete && (
            <Badge variant="danger" size="sm" className="text-[10px] bg-red-100 text-red-700 border-red-200">
              Required
            </Badge>
          )}
          {check.severity === 'recommended' && !check.isComplete && (
            <Badge variant="warning" size="sm" className="text-[10px] bg-[#DDF4F0] text-[#12576D] border-[#BDE5DE]">
              Recommended
            </Badge>
          )}
          {check.isVerified && (
            <Badge variant="success" size="sm" className="text-[10px] bg-emerald-100 text-emerald-700 border-emerald-200">
              <FileCheck className="w-3 h-3 mr-0.5" />
              Verified
            </Badge>
          )}
          {check.expiryDate && (
            <Badge variant="neutral" size="sm" className="text-[10px] bg-[#EEF7F5] text-[#64748B] border-[#D7E7E4]">
              <Clock className="w-3 h-3 mr-0.5" />
              Expires: {new Date(check.expiryDate).toLocaleDateString()}
            </Badge>
          )}
        </div>
        <p className="text-xs text-[#64748B] mt-0.5">{check.description}</p>
        {check.documentUrl && (
          <a
            href={check.documentUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="text-xs text-[#176B87] font-medium mt-1 flex items-center gap-1 hover:underline"
          >
            View Document
            <ExternalLink className="w-3 h-3" />
          </a>
        )}
      </div>
    </div>
  );
};

// Category section accordion
const ComplianceCategorySection: React.FC<{
  category: ComplianceCategory;
  checks: ComplianceCheck[];
  isExpanded: boolean;
  onToggle: () => void;
  onCheckToggle?: (checkId: string, complete: boolean) => void;
  editable?: boolean;
}> = ({ category, checks, isExpanded, onToggle, onCheckToggle, editable }) => {
  const categoryInfo = COMPLIANCE_CATEGORIES[category];
  const completedCount = checks.filter(c => c.isComplete).length;
  const totalCount = checks.length;
  const requiredCount = checks.filter(c => c.severity === 'required').length;
  const requiredComplete = checks.filter(c => c.severity === 'required' && c.isComplete).length;
  const isComplete = completedCount === totalCount;
  const hasIncompleteRequired = requiredComplete < requiredCount;

  return (
    <div className={`border rounded-xl overflow-hidden ${
      isComplete ? 'border-emerald-200' : hasIncompleteRequired ? 'border-red-200' : 'border-[#D7E7E4]'
    }`}>
      <button
        onClick={onToggle}
        className={`w-full flex items-center gap-4 p-4 text-left transition-colors ${
          isComplete ? 'bg-emerald-50 hover:bg-emerald-100' : hasIncompleteRequired ? 'bg-red-50 hover:bg-red-100' : 'bg-[#F6FAF9] hover:bg-[#EEF7F5]'
        }`}
      >
        <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${
          isComplete ? 'bg-emerald-100 text-emerald-600' : hasIncompleteRequired ? 'bg-red-100 text-red-600' : 'bg-white text-[#64748B]'
        }`} style={{ color: categoryInfo.color }}>
          {CATEGORY_ICONS[category]}
        </div>
        <div className="flex-1 min-w-0">
          <h4 className="font-bold text-[#176B87]">{categoryInfo.label}</h4>
          <p className="text-xs text-[#64748B]">{categoryInfo.description}</p>
        </div>
        <div className="text-right">
          <div className="text-lg font-black text-[#176B87]">{completedCount}/{totalCount}</div>
          {requiredCount > 0 && (
            <div className="text-[10px] text-[#64748B]">
              {requiredComplete}/{requiredCount} required
            </div>
          )}
        </div>
        {isExpanded ? (
          <ChevronDown className="w-5 h-5 text-[#94A3B8]" />
        ) : (
          <ChevronRight className="w-5 h-5 text-[#94A3B8]" />
        )}
      </button>

      {isExpanded && (
        <div className="p-4 bg-white space-y-2">
          {checks.map(check => (
            <ComplianceCheckItem
              key={check.id}
              check={check}
              onToggle={onCheckToggle}
              editable={editable}
            />
          ))}
        </div>
      )}
    </div>
  );
};

// Main checklist component
export const ComplianceChecklist: React.FC<ComplianceChecklistProps> = ({
  checks,
  onCheckToggle,
  onViewPolicy,
  onSubmitForReview,
  isEditable = false,
}) => {
  const [expandedCategories, setExpandedCategories] = useState<Set<ComplianceCategory>>(
    new Set(['organization', 'financial'])
  );

  const checksByCategory = getChecksByCategory(checks);
  const summary = getComplianceSummary(checks);

  const toggleCategory = (category: ComplianceCategory) => {
    setExpandedCategories(prev => {
      const next = new Set(prev);
      if (next.has(category)) {
        next.delete(category);
      } else {
        next.add(category);
      }
      return next;
    });
  };

  const handleCheckToggle = (checkId: string, isComplete: boolean) => {
    onCheckToggle?.(checkId, isComplete);
  };

  const canSubmitForReview = summary.requiredCompleted === summary.required;

  return (
    <div className="space-y-6">
      {/* Progress Header */}
      <Card className="p-5 bg-gradient-to-r from-[#0A3340] to-[#12576d] text-white border-none">
        <div className="flex flex-col md:flex-row items-center gap-6">
          {/* Progress Ring */}
          <div className="relative w-24 h-24">
            <svg className="transform -rotate-90" width="96" height="96">
              <circle
                cx="48"
                cy="48"
                r="42"
                fill="none"
                stroke="rgba(255,255,255,0.1)"
                strokeWidth="8"
              />
              <circle
                cx="48"
                cy="48"
                r="42"
                fill="none"
                stroke={summary.requiredCompleted === summary.required ? '#10B981' : '#176b87'}
                strokeWidth="8"
                strokeLinecap="round"
                strokeDasharray={`${2 * Math.PI * 42}`}
                strokeDashoffset={`${2 * Math.PI * 42 * (1 - summary.percentage / 100)}`}
                className="transition-all duration-500"
              />
            </svg>
            <div className="absolute inset-0 flex flex-col items-center justify-center">
              <span className="text-2xl font-black">{summary.percentage}%</span>
              <span className="text-[10px] text-[#94A3B8]">Complete</span>
            </div>
          </div>

          {/* Summary */}
          <div className="flex-1 text-center md:text-left">
            <h3 className="text-xl font-black mb-2">
              Compliance Checklist
            </h3>
            <p className="text-[#BDE5DE] text-sm mb-4">
              {canSubmitForReview
                ? 'All required items are complete. Ready to submit for review.'
                : `${summary.required - summary.requiredCompleted} required items must be completed before submitting.`
              }
            </p>

            <div className="flex flex-wrap justify-center md:justify-start gap-4">
              <div className="flex items-center gap-2">
                <div className={`w-3 h-3 rounded-full ${summary.requiredCompleted === summary.required ? 'bg-emerald-400' : 'bg-red-400'}`} />
                <span className="text-sm text-[#BDE5DE]">
                  {summary.requiredCompleted}/{summary.required} Required
                </span>
              </div>
              <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-full bg-[#13B8A6]" />
                <span className="text-sm text-[#BDE5DE]">
                  {summary.recommendedCompleted}/{summary.recommended} Recommended
                </span>
              </div>
            </div>
          </div>

          {/* Submit Button */}
          <Button
            size="lg"
            disabled={!canSubmitForReview}
            onClick={onSubmitForReview}
            className={`px-6 font-bold ${
              canSubmitForReview
                ? 'bg-emerald-600 hover:bg-emerald-700 text-white'
                : 'bg-[#91CEC5] text-[#64748B] cursor-not-allowed'
            }`}
          >
            {canSubmitForReview ? (
              <>
                <CheckCircle2 className="w-5 h-5 mr-2" />
                Submit for Review
              </>
            ) : (
              <>
                <AlertTriangle className="w-5 h-5 mr-2" />
                Complete Required Items
              </>
            )}
          </Button>
        </div>

        {/* Not Ready Notice */}
        {!canSubmitForReview && (
          <div className="mt-4 p-3 bg-[#13B8A6]/20 border border-[#5AAFA4]/30 rounded-xl flex items-start gap-3">
            <AlertTriangle className="w-5 h-5 text-[#13B8A6] flex-shrink-0 mt-0.5" />
            <div>
              <p className="text-sm font-bold text-[#13B8A6]">Required Items Incomplete</p>
              <p className="text-xs text-[#BDE5DE] mt-1">
                Please complete all required compliance items before submitting your auction for review.
              </p>
            </div>
          </div>
        )}
      </Card>

      {/* Category Sections */}
      <div className="space-y-3">
        {Object.entries(checksByCategory)
          .filter(([_, checks]) => checks.length > 0)
          .sort(([a], [b]) => {
            const order = Object.keys(COMPLIANCE_CATEGORIES);
            return order.indexOf(a) - order.indexOf(b);
          })
          .map(([category, categoryChecks]) => (
            <ComplianceCategorySection
              key={category}
              category={category as ComplianceCategory}
              checks={categoryChecks}
              isExpanded={expandedCategories.has(category as ComplianceCategory)}
              onToggle={() => toggleCategory(category as ComplianceCategory)}
              onCheckToggle={handleCheckToggle}
              editable={isEditable}
            />
          ))
        }
      </div>

      {/* Bottom Action */}
      {canSubmitForReview && onSubmitForReview && (
        <div className="flex justify-center pt-4">
          <Button
            size="lg"
            onClick={onSubmitForReview}
            className="px-8 font-bold bg-emerald-600 hover:bg-emerald-700 text-white"
          >
            <CheckCircle2 className="w-5 h-5 mr-2" />
            Submit for Compliance Review
          </Button>
        </div>
      )}
    </div>
  );
};

export default ComplianceChecklist;

import React, { useState, useMemo } from 'react';
import {
  Shield,
  ShieldCheck,
  ShieldAlert,
  ShieldX,
  Building,
  Car,
  Gavel,
  Banknote,
  ClipboardCheck,
  FileText,
  Users,
  AlertTriangle,
  CheckCircle2,
  Clock,
  XCircle,
  PauseCircle,
  AlertCircle,
  Calendar,
  ChevronRight,
  ChevronDown,
  Search,
  Filter,
  Download,
  Eye,
  Edit,
  Ban,
  CheckCheck,
  RefreshCw,
  ExternalLink,
  Bell,
  Info
} from 'lucide-react';
import { Card } from '../ui/Card';
import { Badge } from '../ui/Badge';
import { Button } from '../ui/Button';
import type { AuctionSession } from '../../types';
import type {
  ComplianceItem,
  ComplianceStatus,
  ComplianceCategory,
  ComplianceCheck,
  ComplianceMetrics,
  ComplianceAuditEntry
} from '../../utils/auctionCompliance';
import {
  COMPLIANCE_CATEGORIES,
  COMPLIANCE_STATUS_STYLES,
  getChecksByCategory,
  getComplianceSummary,
  calculateComplianceMetrics,
  generateExpiryReminders
} from '../../utils/auctionCompliance';

export interface ComplianceDashboardProps {
  complianceItems?: ComplianceItem[];
  sessions?: Partial<AuctionSession>[];
  audits?: ComplianceAuditEntry[];
  onApprove?: (itemId: string) => void;
  onReject?: (itemId: string, reason: string) => void;
  onSuspend?: (itemId: string, reason: string) => void;
  onRequestCorrection?: (itemId: string, corrections: string[]) => void;
  onViewDetails?: (item: ComplianceItem) => void;
  onExportReport?: (format: 'csv' | 'pdf') => void;
  isAdminView?: boolean;
}

// Status icons mapping
const STATUS_ICONS: Record<ComplianceStatus, React.ReactNode> = {
  pending: <Clock className="w-4 h-4" />,
  under_review: <Eye className="w-4 h-4" />,
  approved: <CheckCircle2 className="w-4 h-4" />,
  conditional_approval: <AlertCircle className="w-4 h-4" />,
  suspended: <PauseCircle className="w-4 h-4" />,
  rejected: <XCircle className="w-4 h-4" />,
  expired: <Clock className="w-4 h-4" />,
};

// Category icons mapping
const CATEGORY_ICONS: Record<string, React.ReactNode> = {
  organization: <Building className="w-4 h-4" />,
  vehicle: <Car className="w-4 h-4" />,
  auction: <Gavel className="w-4 h-4" />,
  financial: <Banknote className="w-4 h-4" />,
  inspection: <ClipboardCheck className="w-4 h-4" />,
  document: <FileText className="w-4 h-4" />,
  marketplace_policy: <Shield className="w-4 h-4" />,
  customer_protection: <Users className="w-4 h-4" />,
};

// Status summary card
const StatusSummaryCard: React.FC<{
  status: ComplianceStatus;
  count: number;
  label: string;
}> = ({ status, count, label }) => {
  const style = COMPLIANCE_STATUS_STYLES[status];

  return (
    <Card
      className={`p-4 cursor-pointer hover:shadow-md transition-shadow ${style.bgColor} border ${style.borderColor}`}
    >
      <div className="flex items-center gap-3">
        <div className="w-10 h-10 rounded-lg flex items-center justify-center" style={{ backgroundColor: style.color + '20', color: style.color }}>
          {STATUS_ICONS[status]}
        </div>
        <div>
          <div className="text-2xl font-black" style={{ color: style.color }}>{count}</div>
          <div className="text-xs text-[#64748B] font-medium">{label}</div>
        </div>
      </div>
    </Card>
  );
};

// Compliance item card
const ComplianceItemCard: React.FC<{
  item: ComplianceItem;
  session?: Partial<AuctionSession>;
  onApprove?: () => void;
  onReject?: () => void;
  onSuspend?: () => void;
  onViewDetails?: () => void;
  expanded?: boolean;
  onToggleExpand?: () => void;
  isAdmin?: boolean;
}> = ({ item, session, onApprove, onReject, onSuspend, onViewDetails, expanded, onToggleExpand, isAdmin }) => {
  const statusStyle = COMPLIANCE_STATUS_STYLES[item.status];
  const summary = getComplianceSummary(item.checks);
  const checksByCategory = getChecksByCategory(item.checks);

  return (
    <Card className={`overflow-hidden border ${item.status === 'approved' ? 'border-emerald-200' : item.status === 'suspended' || item.status === 'rejected' ? 'border-red-200' : 'border-[#D7E7E4]'}`}>
      {/* Header */}
      <div
        className="flex items-center gap-4 p-4 cursor-pointer hover:bg-[#F6FAF9]"
        onClick={onToggleExpand}
      >
        <div className="w-10 h-10 rounded-xl flex items-center justify-center" style={{ backgroundColor: statusStyle.color + '20', color: statusStyle.color }}>
          {STATUS_ICONS[item.status]}
        </div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center gap-2">
            <h4 className="font-bold text-[#176B87] truncate">
              {session?.id || item.auctionId}
            </h4>
            <Badge
              size="sm"
              className="text-[10px]"
              style={{ backgroundColor: statusStyle.bgColor, color: statusStyle.color, borderColor: statusStyle.borderColor }}
            >
              {statusStyle.label}
            </Badge>
          </div>
          <p className="text-xs text-[#64748B] truncate">
            {session?.organizer?.name || 'Unknown Organizer'}
          </p>
        </div>
        <div className="text-right">
          <div className="text-lg font-black text-[#176B87]">{summary.percentage}%</div>
          <div className="text-[10px] text-[#64748B]">
            {summary.requiredCompleted}/{summary.required} required
          </div>
        </div>
        {expanded ? (
          <ChevronDown className="w-5 h-5 text-[#94A3B8]" />
        ) : (
          <ChevronRight className="w-5 h-5 text-[#94A3B8]" />
        )}
      </div>

      {/* Expanded Details */}
      {expanded && (
        <div className="border-t border-[#D7E7E4] p-4 bg-[#F6FAF9] space-y-4">
          {/* Progress Bar */}
          <div>
            <div className="flex justify-between text-xs mb-1">
              <span className="text-[#64748B]">Compliance Progress</span>
              <span className="font-bold text-[#176B87]">{summary.percentage}%</span>
            </div>
            <div className="h-2 bg-[#DDF4F0] rounded-full overflow-hidden">
              <div
                className="h-full rounded-full transition-all"
                style={{
                  width: `${summary.percentage}%`,
                  backgroundColor: summary.requiredCompleted === summary.required ? '#10B981' : '#176b87'
                }}
              />
            </div>
          </div>

          {/* Category Breakdown */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
            {Object.entries(checksByCategory)
              .filter(([_, checks]) => checks.length > 0)
              .map(([category, checks]) => {
                const catInfo = COMPLIANCE_CATEGORIES[category as ComplianceCategory];
                const completed = checks.filter(c => c.isComplete).length;
                return (
                  <div
                    key={category}
                    className="p-2 rounded-lg border border-[#D7E7E4] bg-white"
                  >
                    <div className="flex items-center gap-1.5 mb-1" style={{ color: catInfo.color }}>
                      {CATEGORY_ICONS[category]}
                      <span className="text-[10px] font-medium truncate">{catInfo.label}</span>
                    </div>
                    <div className="text-sm font-bold text-[#12576D]">
                      {completed}/{checks.length}
                    </div>
                  </div>
                );
              })}
          </div>

          {/* Missing Required Checks */}
          {summary.required > summary.requiredCompleted && (
            <div className="p-3 bg-red-50 border border-red-200 rounded-lg">
              <div className="flex items-center gap-2 mb-2">
                <AlertTriangle className="w-4 h-4 text-red-600" />
                <span className="text-xs font-bold text-red-800">
                  {summary.required - summary.requiredCompleted} Required Checks Incomplete
                </span>
              </div>
              <div className="space-y-1">
                {item.checks
                  .filter(c => c.severity === 'required' && !c.isComplete)
                  .slice(0, 3)
                  .map(check => (
                    <div key={check.id} className="text-xs text-red-700">
                      • {check.label}
                    </div>
                  ))}
                {(summary.required - summary.requiredCompleted) > 3 && (
                  <div className="text-xs text-red-600 font-medium">
                    +{(summary.required - summary.requiredCompleted) - 3} more...
                  </div>
                )}
              </div>
            </div>
          )}

          {/* Actions */}
          {isAdmin && (
            <div className="flex items-center gap-2 pt-2 border-t border-[#D7E7E4]">
              <Button size="sm" variant="success" onClick={onApprove}>
                <CheckCheck className="w-3.5 h-3.5 mr-1" />
                Approve
              </Button>
              <Button size="sm" variant="outline" onClick={onReject}>
                <XCircle className="w-3.5 h-3.5 mr-1" />
                Reject
              </Button>
              <Button size="sm" variant="outline" onClick={onSuspend}>
                <PauseCircle className="w-3.5 h-3.5 mr-1" />
                Suspend
              </Button>
              <div className="flex-1" />
              <Button size="sm" variant="ghost" onClick={onViewDetails}>
                View Details
                <ExternalLink className="w-3.5 h-3.5 ml-1" />
              </Button>
            </div>
          )}

          {/* Metadata */}
          <div className="flex items-center gap-4 text-xs text-[#64748B] pt-2 border-t border-[#D7E7E4]">
            <span>Created: {new Date(item.createdAt).toLocaleDateString()}</span>
            {item.reviewedAt && (
              <span>Reviewed: {new Date(item.reviewedAt).toLocaleDateString()}</span>
            )}
            {item.reviewedBy && (
              <span>By: {item.reviewedBy}</span>
            )}
          </div>
        </div>
      )}
    </Card>
  );
};

// Main Dashboard Component
export const ComplianceDashboard: React.FC<ComplianceDashboardProps> = ({
  complianceItems = [],
  sessions = [],
  audits = [],
  onApprove,
  onReject,
  onSuspend,
  onRequestCorrection,
  onViewDetails,
  onExportReport,
  isAdminView = false,
}) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState<ComplianceStatus | 'all'>('all');
  const [categoryFilter, setCategoryFilter] = useState<ComplianceCategory | 'all'>('all');
  const [expandedItems, setExpandedItems] = useState<Set<string>>(new Set());

  // Calculate metrics
  const metrics = useMemo(() => calculateComplianceMetrics(complianceItems), [complianceItems]);

  // Generate expiry reminders
  const reminders = useMemo(() => generateExpiryReminders(complianceItems), [complianceItems]);

  // Filter items
  const filteredItems = useMemo(() => {
    let filtered = [...complianceItems];

    // Filter by status
    if (statusFilter !== 'all') {
      filtered = filtered.filter(i => i.status === statusFilter);
    }

    // Filter by category
    if (categoryFilter !== 'all') {
      filtered = filtered.filter(i =>
        i.checks.some(c => c.category === categoryFilter && !c.isComplete)
      );
    }

    // Filter by search
    if (searchQuery) {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter(i =>
        i.auctionId.toLowerCase().includes(query) ||
        i.organizerId.toLowerCase().includes(query)
      );
    }

    // Sort by status priority
    const statusPriority: Record<ComplianceStatus, number> = {
      pending: 0,
      under_review: 1,
      suspended: 2,
      rejected: 3,
      conditional_approval: 4,
      approved: 5,
      expired: 6,
    };
    filtered.sort((a, b) => statusPriority[a.status] - statusPriority[b.status]);

    return filtered;
  }, [complianceItems, statusFilter, categoryFilter, searchQuery]);

  const toggleExpand = (itemId: string) => {
    setExpandedItems(prev => {
      const next = new Set(prev);
      if (next.has(itemId)) {
        next.delete(itemId);
      } else {
        next.add(itemId);
      }
      return next;
    });
  };

  return (
    <div className="space-y-6">
      {/* Confidentiality Notice */}
      <Card className="p-4 bg-[#F3FAF9] border border-[#D7E7E4]">
        <div className="flex items-center gap-3">
          <Shield className="w-5 h-5 text-[#176B87] flex-shrink-0" />
          <div>
            <p className="text-sm font-bold text-[#0E4655]">Internal Compliance Center</p>
            <p className="text-xs text-[#176B87]">
              This information is confidential and visible only to Auction Organizers, KAYAD Administrators, and Compliance Officers.
            </p>
          </div>
        </div>
      </Card>

      {/* Compliance Status Summary */}
      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-7 gap-4">
        <StatusSummaryCard status="pending" count={metrics.pendingReview} label="Pending" />
        <StatusSummaryCard status="under_review" count={complianceItems.filter(i => i.status === 'under_review').length} label="Under Review" />
        <StatusSummaryCard status="approved" count={metrics.approved} label="Approved" />
        <StatusSummaryCard status="conditional_approval" count={complianceItems.filter(i => i.status === 'conditional_approval').length} label="Conditional" />
        <StatusSummaryCard status="suspended" count={metrics.suspended} label="Suspended" />
        <StatusSummaryCard status="rejected" count={metrics.rejected} label="Rejected" />
        <StatusSummaryCard status="expired" count={metrics.expired} label="Expired" />
      </div>

      {/* Quick Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card className="p-4 text-center bg-emerald-50 border-emerald-200">
          <div className="text-2xl font-black text-emerald-600">{metrics.approved}</div>
          <div className="text-xs text-emerald-600">Compliant Auctions</div>
        </Card>
        <Card className="p-4 text-center bg-red-50 border-red-200">
          <div className="text-2xl font-black text-red-600">{metrics.pendingReview}</div>
          <div className="text-xs text-red-600">Awaiting Review</div>
        </Card>
        <Card className="p-4 text-center bg-[#F3FAF9] border-[#BDE5DE]">
          <div className="text-2xl font-black text-[#176B87]">{metrics.expiringWithin7Days}</div>
          <div className="text-xs text-[#176B87]">Expiring Soon (7 days)</div>
        </Card>
        <Card className="p-4 text-center bg-[#F3FAF9] border-[#D7E7E4]">
          <div className="text-2xl font-black text-[#176B87]">{metrics.expiringWithin30Days}</div>
          <div className="text-xs text-[#176B87]">Expiring Soon (30 days)</div>
        </Card>
      </div>

      {/* Expiry Reminders */}
      {reminders.length > 0 && (
        <Card className="p-4 bg-[#F3FAF9] border-[#BDE5DE]">
          <div className="flex items-center gap-2 mb-3">
            <Bell className="w-5 h-5 text-[#176B87]" />
            <h3 className="font-bold text-[#0A3340]">Upcoming Expirations</h3>
          </div>
          <div className="space-y-2">
            {reminders.slice(0, 5).map(reminder => (
              <div
                key={reminder.id}
                className={`flex items-center gap-3 p-2 rounded-lg ${
                  reminder.severity === 'critical' ? 'bg-red-100' : 'bg-[#F3FAF9]'
                }`}
              >
                <AlertTriangle className={`w-4 h-4 ${reminder.severity === 'critical' ? 'text-red-600' : 'text-[#176B87]'}`} />
                <div className="flex-1">
                  <span className="text-sm font-medium text-[#0A3340]">{reminder.documentName}</span>
                  <span className="text-xs text-[#64748B] ml-2">({reminder.documentType})</span>
                </div>
                <Badge
                  size="sm"
                  className={reminder.severity === 'critical' ? 'bg-red-200 text-red-800' : 'bg-[#BDE5DE] text-[#0A3340]'}
                >
                  {reminder.daysUntilExpiry} days
                </Badge>
              </div>
            ))}
          </div>
        </Card>
      )}

      {/* Filters */}
      <Card className="p-4">
        <div className="flex flex-col md:flex-row gap-4">
          {/* Search */}
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#94A3B8]" />
            <input
              type="text"
              placeholder="Search by auction ID or organizer..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2 border border-[#D7E7E4] rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#176B87]/20 focus:border-[#176B87]"
            />
          </div>

          {/* Status Filter */}
          <div className="flex items-center gap-2">
            <Filter className="w-4 h-4 text-[#64748B]" />
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value as ComplianceStatus | 'all')}
              className="px-3 py-2 border border-[#D7E7E4] rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#176B87]/20"
            >
              <option value="all">All Statuses</option>
              <option value="pending">Pending</option>
              <option value="under_review">Under Review</option>
              <option value="approved">Approved</option>
              <option value="conditional_approval">Conditional</option>
              <option value="suspended">Suspended</option>
              <option value="rejected">Rejected</option>
            </select>
          </div>

          {/* Category Filter */}
          <select
            value={categoryFilter}
            onChange={(e) => setCategoryFilter(e.target.value as ComplianceCategory | 'all')}
            className="px-3 py-2 border border-[#D7E7E4] rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-[#176B87]/20"
          >
            <option value="all">All Categories</option>
            {Object.entries(COMPLIANCE_CATEGORIES).map(([key, cat]) => (
              <option key={key} value={key}>{cat.label}</option>
            ))}
          </select>

          {/* Export */}
          {isAdminView && onExportReport && (
            <div className="flex items-center gap-2">
              <Button size="sm" variant="outline" onClick={() => onExportReport('csv')}>
                <Download className="w-3.5 h-3.5 mr-1" />
                CSV
              </Button>
              <Button size="sm" variant="outline" onClick={() => onExportReport('pdf')}>
                <Download className="w-3.5 h-3.5 mr-1" />
                PDF
              </Button>
            </div>
          )}
        </div>
      </Card>

      {/* Compliance Items List */}
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <h3 className="font-bold text-[#176B87]">
            Compliance Items ({filteredItems.length})
          </h3>
        </div>

        {filteredItems.length === 0 ? (
          <Card className="p-12 text-center">
            <ShieldCheck className="w-12 h-12 text-emerald-400 mx-auto mb-4" />
            <h3 className="text-lg font-bold text-[#0A3340] mb-2">
              {statusFilter === 'all' ? 'No Compliance Items' : `No ${COMPLIANCE_STATUS_STYLES[statusFilter].label} Items`}
            </h3>
            <p className="text-sm text-[#64748B]">
              {statusFilter === 'all'
                ? 'Compliance items will appear here as auctions are created.'
                : `There are no auctions with ${COMPLIANCE_STATUS_STYLES[statusFilter].label} status.`
              }
            </p>
          </Card>
        ) : (
          filteredItems.map(item => {
            const session = sessions.find(s => s.id === item.auctionId);
            return (
              <ComplianceItemCard
                key={item.id}
                item={item}
                session={session}
                expanded={expandedItems.has(item.id)}
                onToggleExpand={() => toggleExpand(item.id)}
                onApprove={() => onApprove?.(item.id)}
                onReject={() => onReject?.(item.id, '')}
                onSuspend={() => onSuspend?.(item.id, '')}
                onViewDetails={() => onViewDetails?.(item)}
                isAdmin={isAdminView}
              />
            );
          })
        )}
      </div>
    </div>
  );
};

export default ComplianceDashboard;

