import { Link } from 'react-router-dom';

// ============================================================
// KAYAD UNIFIED DESIGN SYSTEM
// Premium Light Theme for Enterprise Dashboards
// ============================================================

// Design Tokens - Unified across all enterprise components
export const EnterpriseTokens = {
  // Brand Colors (KAYAD Design System)
  navy: '#0A3340',
  navyLight: '#12576D',
  navyDark: '#0f1833',
  beige: '#EEF7F5',
  beigeLight: '#f6faf9',
  white: '#FFFFFF',

  // Semantic Colors
  emerald: '#10B981',
  emeraldLight: '#D1FAE5',
  terracotta: '#5aafa4',
  terracottaLight: '#FDE8E0',
  softBlue: '#5AAFA4',
  softBlueLight: '#DDF4F0',
  mutedOrange: '#13b8a6',
  mutedOrangeLight: '#DDF4F0',
  mutedCrimson: '#EF4444',
  mutedCrimsonLight: '#FEE2E2',
  purple: '#5aafa4',
  purpleLight: '#EDE9FE',

  // Neutrals
  slate: {
    50: '#f6faf9',
    100: '#f6faf9',
    200: '#d7e7e4',
    300: '#d7e7e4',
    400: '#94A3B8',
    500: '#64748B',
    600: '#64748b',
    700: '#12576d',
    800: '#1E293B',
    900: '#0a3340',
  },

  // Semantic Aliases
  success: '#10B981',
  successBg: '#D1FAE5',
  successBorder: '#A7F3D0',
  warning: '#176b87',
  warningBg: '#eef7f5',
  warningBorder: '#ddf4f0',
  danger: '#EF4444',
  dangerBg: '#FEE2E2',
  dangerBorder: '#FECACA',
  info: '#176B87',
  infoBg: '#DDF4F0',
  infoBorder: '#BFDBFE',

  // Text Colors
  textPrimary: '#1E293B',
  textSecondary: '#64748b',
  textMuted: '#64748B',
  textDisabled: '#94A3B8',

  // Backgrounds
  bg: '#EEF7F5',
  bgLight: '#f6faf9',
  card: '#FFFFFF',
  surface: '#f6faf9',
  surfaceHover: '#f6faf9',

  // Borders
  border: 'rgba(10, 51, 64, 0.08)',
  borderLight: 'rgba(10, 51, 64, 0.05)',
  borderMedium: 'rgba(10, 51, 64, 0.12)',
  borderFocus: '#0A3340',

  // Shadows
  shadow: '0 1px 3px rgba(10, 51, 64, 0.05), 0 1px 2px rgba(10, 51, 64, 0.03)',
  shadowSm: '0 1px 2px rgba(10, 51, 64, 0.04)',
  shadowMd: '0 4px 6px -1px rgba(10, 51, 64, 0.05), 0 2px 4px -1px rgba(10, 51, 64, 0.03)',
  shadowLg: '0 10px 15px -3px rgba(10, 51, 64, 0.08), 0 4px 6px -2px rgba(10, 51, 64, 0.04)',
  shadowCard: '0 2px 8px -1px rgba(30, 48, 99, 0.06), 0 1px 4px -1px rgba(30, 48, 99, 0.04)',
  shadowCardHover: '0 12px 24px -4px rgba(30, 48, 99, 0.12), 0 4px 8px -2px rgba(30, 48, 99, 0.06)',
};

// Common Styles
const S = {
  // Card styles
  card: {
    background: EnterpriseTokens.card,
    border: `1px solid ${EnterpriseTokens.border}`,
    borderRadius: 16,
    overflow: 'hidden',
    transition: 'all 0.2s ease',
  },
  cardHover: {
    boxShadow: EnterpriseTokens.shadowCardHover,
    borderColor: EnterpriseTokens.borderMedium,
  },
  header: {
    padding: '16px 20px',
    borderBottom: `1px solid ${EnterpriseTokens.border}`,
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  body: {
    padding: '20px',
  },

  // KPI Card styles
  kpi: {
    background: EnterpriseTokens.card,
    border: `1px solid ${EnterpriseTokens.border}`,
    borderRadius: 14,
    padding: '20px',
    position: 'relative',
    overflow: 'hidden',
    transition: 'all 0.2s ease',
  },
  kpiBg: {
    position: 'absolute',
    right: -20,
    top: -20,
    width: 80,
    height: 80,
    borderRadius: '50%',
    opacity: 0.06,
  },
  kpiIcon: {
    width: 40,
    height: 40,
    borderRadius: 10,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    fontSize: 18,
    marginBottom: 12,
  },
  kpiLabel: {
    fontSize: 11,
    fontWeight: 600,
    color: EnterpriseTokens.textMuted,
    textTransform: 'uppercase',
    letterSpacing: '0.05em',
    marginBottom: 4,
  },
  kpiValue: {
    fontSize: '1.75rem',
    fontFamily: 'Outfit, sans-serif',
    fontWeight: 700,
    color: EnterpriseTokens.textPrimary,
    lineHeight: 1.1,
    marginBottom: 4,
  },
  kpiSub: {
    fontSize: 12,
    color: EnterpriseTokens.textMuted,
    marginTop: 2,
  },

  // Badge styles
  badge: (color, bgColor) => ({
    padding: '4px 10px',
    borderRadius: 9999,
    fontSize: 11,
    fontWeight: 600,
    background: bgColor || `${color}15`,
    color: color,
    display: 'inline-flex',
    alignItems: 'center',
  }),

  // Grid layouts
  grid2: { display: 'grid', gridTemplateColumns: 'minmax(0, 2fr) minmax(0, 1fr)', gap: 24 },
  grid3: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))', gap: 16 },
  grid4: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(240px, 1fr))', gap: 16 },

  // Quick action styles
  actionLink: {
    display: 'flex',
    alignItems: 'center',
    gap: 12,
    padding: '14px 16px',
    borderRadius: 12,
    background: EnterpriseTokens.surface,
    border: `1px solid ${EnterpriseTokens.border}`,
    textDecoration: 'none',
    color: 'inherit',
    transition: 'all 0.2s ease',
    cursor: 'pointer',
  },

  // Activity item styles
  activityItem: {
    display: 'flex',
    gap: 12,
    padding: '12px 0',
    borderBottom: `1px solid ${EnterpriseTokens.borderLight}`,
  },
  timelineDot: (color) => ({
    width: 8,
    height: 8,
    borderRadius: '50%',
    background: color,
    flexShrink: 0,
    marginTop: 6,
  }),

  // Notification styles
  notification: {
    display: 'flex',
    gap: 12,
    padding: '12px 0',
    borderBottom: `1px solid ${EnterpriseTokens.borderLight}`,
    cursor: 'pointer',
  },

  // Table styles
