export function firstImage(car: any, idx = 0): string | null {
  const imgs = car?.images || [];
  const img = imgs[idx];
  if (!img) return null;
  return typeof img === 'string' ? img : img?.url || null;
}

interface GalleryImageProps {
  car: any;
  idx: number;
  onPrev: () => void;
  onNext: () => void;
  total: number;
  onOpenGallery?: () => void;
}

export function GalleryImage({ car, idx, onPrev, onNext, total, onOpenGallery }: GalleryImageProps) {
  const [err, setErr] = useState(false);
  const [loaded, setLoaded] = useState(false);
  const touchX = useRef<number | null>(null);

  const src = (!err && firstImage(car, idx)) ||
    'https://images.unsplash.com/photo-1503376780353-7e8f0e4b39f4?q=80&w=1600&fit=crop';

  const handleTouchStart = useCallback((e: TouchEvent) => {
    touchX.current = e.touches[0].clientX;
  }, []);

  const handleTouchEnd = useCallback((e: TouchEvent) => {
    if (touchX.current === null) return;
    const dx = e.changedTouches[0].clientX - touchX.current;
    if (dx > 50) onPrev();
    else if (dx < -50) onNext();
    touchX.current = null;
  }, [onPrev, onNext]);

  return (
    <div
      className="relative w-full aspect-video bg-[#12576D] rounded-2xl overflow-hidden cursor-pointer"
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
      onClick={onOpenGallery}
    >
      {!loaded && (
        <div className="absolute inset-0 bg-[#12576D] animate-pulse" />
      )}
      <img
        src={src}
        onError={() => setErr(true)}
        onLoad={() => setLoaded(true)}
        alt={car?.title || 'Vehicle'}
        width={800}
        height={450}
        loading="lazy"
        decoding="async"
        className="w-full h-full object-cover transition-opacity duration-500"
        style={{ opacity: loaded ? 1 : 0.3 }}
      />

      {/* Gradient overlay */}
      <div className="absolute inset-0 bg-gradient-to-t from-[#0A3340]/30 via-transparent to-[#0A3340]/20 pointer-events-none" />

      {/* Navigation arrows */}
      {total > 1 && (
        <>
          <button
            onClick={(e) => { e.stopPropagation(); onPrev(); }}
            className="absolute left-4 top-1/2 -translate-y-1/2 w-10 h-10 bg-white/10 hover:bg-white/20 backdrop-blur-sm text-white rounded-full flex items-center justify-center transition-all z-10"
          >
            <ChevronLeft size={18} />
          </button>
          <button
            onClick={(e) => { e.stopPropagation(); onNext(); }}
            className="absolute right-4 top-1/2 -translate-y-1/2 w-10 h-10 bg-white/10 hover:bg-white/20 backdrop-blur-sm text-white rounded-full flex items-center justify-center transition-all z-10"
          >
            <ChevronRight size={18} />
          </button>
          <div className="absolute bottom-4 right-4 px-3 py-1.5 bg-[#0A3340]/60 text-white text-xs font-semibold rounded-full backdrop-blur-sm z-10">
            {idx + 1} / {total}
          </div>
        </>
      )}

      {/* Featured badge */}
      {car?.isPromoted && (
        <div className="absolute top-4 left-4 flex items-center gap-1.5 px-3 py-1.5 bg-[#13B8A6]/90 text-[#0A3340] text-xs font-bold rounded-full z-10">
          <Star size={12} />
          FEATURED
        </div>
      )}

      {/* Demo badge */}

      {/* Live auction badge */}
      {car?.auctionStatus === 'live' && (
        <div className="absolute top-4 left-4 flex items-center gap-2 px-3 py-1.5 bg-red-500/90 text-white text-xs font-bold rounded-full z-10">
          <span className="w-2 h-2 bg-white rounded-full animate-pulse" />
          LIVE AUCTION
        </div>
      )}
    </div>
  );
}

