import { useState, useEffect, type FC } from 'react';
import { bidLogsAPI, formatKES } from '../../../api/api.exports';

interface ActiveBidLogsProps {
  carId: string;
  className?: string;
  maxItems?: number;
  showStats?: boolean;
}

export const ActiveBidLogs: FC<ActiveBidLogsProps> = ({
  carId,
  className = '',
  maxItems = 10,
  showStats = false,
}) => {
  const [logs, setLogs] = useState<any[]>([]);
  const [stats, setStats] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadData();
    // Refresh every 30 seconds
    const interval = setInterval(loadData, 30000);
    return () => clearInterval(interval);
  }, [carId]);

  const loadData = async () => {
    try {
      const [bidLogs, bidStats] = await Promise.all([
        bidLogsAPI.getActive(carId, { limit: maxItems }),
        showStats ? bidLogsAPI.getStats(carId) : Promise.resolve(null),
      ]);
      setLogs(bidLogs.logs || bidLogs || []);
      setStats(bidStats);
    } catch (err: any) {
      setError(err.message || 'Failed to load bid logs');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className={`bg-white dark:bg-[#12576D] rounded-xl p-4 ${className}`}>
        <div className="animate-pulse space-y-3">
          {[...Array(5)].map((_, i) => (
            <div key={i} className="h-12 bg-[#DDF4F0] dark:bg-[#12576D] rounded" />
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className={`bg-white dark:bg-[#12576D] rounded-xl ${className}`}>
      {/* Header */}
      <div className="p-4 border-b border-[#D7E7E4] dark:border-[#12576D]">
        <div className="flex items-center justify-between">
          <h3 className="font-semibold text-[#12576D] dark:text-[#64748B]">
            Live Bid Activity
          </h3>
          <span className="flex items-center gap-1 text-xs text-emerald-600">
            <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
            Live
          </span>
        </div>
      </div>

      {error && (
        <div className="p-4 text-red-600 dark:text-red-400 text-sm">{error}</div>
      )}

      {/* Stats */}
      {showStats && stats && (
        <div className="grid grid-cols-4 gap-2 p-4 bg-[#F6FAF9] dark:bg-[#12576D]/50">
          <div className="text-center">
            <p className="text-lg font-bold text-[#12576D] dark:text-[#64748B]">
              {stats.totalBids}
            </p>
            <p className="text-xs text-[#64748B]">Total Bids</p>
          </div>
          <div className="text-center">
            <p className="text-lg font-bold text-brand-500">
              {stats.uniqueBidders}
            </p>
            <p className="text-xs text-[#64748B]">Bidders</p>
          </div>
          <div className="text-center">
            <p className="text-lg font-bold text-emerald-600">
              {formatKES(stats.highestBid)}
            </p>
            <p className="text-xs text-[#64748B]">Highest</p>
          </div>
          <div className="text-center">
            <p className="text-lg font-bold text-[#176B87] dark:text-[#64748B]">
              {formatKES(stats.averageBid)}
            </p>
            <p className="text-xs text-[#64748B]">Average</p>
          </div>
        </div>
      )}

      {/* Bid List */}
      <div className="divide-y divide-[#EEF7F5] dark:divide-[#12576D]">
        {logs.length === 0 ? (
          <div className="p-8 text-center">
            <p className="text-[#64748B] dark:text-[#5AAFA4]">No bids yet</p>
            <p className="text-sm text-[#0A3340] dark:text-[#176B87]">
              Be the first to place a bid!
            </p>
          </div>
        ) : (
          logs.map((log, index) => (
            <div
              key={log.id || index}
              className={`px-4 py-3 flex items-center justify-between ${
                index === 0 ? 'bg-brand-50/50 dark:bg-brand-900/10' : ''
              }`}
            >
              <div className="flex items-center gap-3">
                {/* Position */}
                <div className={`w-6 h-6 rounded-full flex items-center justify-center text-xs font-bold ${
                  index === 0
                    ? 'bg-brand-500 text-white'
                    : index === 1
                    ? 'bg-[#BDE5DE] text-[#12576D]'
                    : index === 2
                    ? 'bg-[#176B87] text-white'
                    : 'bg-[#DDF4F0] dark:bg-[#176B87] text-[#64748B]'
                }`}>
                  {index + 1}
                </div>

                {/* Bidder Info */}
                <div>
                  <div className="flex items-center gap-2">
                    <p className="font-medium text-[#12576D] dark:text-[#64748B]">
                      {log.pseudonym}
                    </p>
                    {log.isAutoBid && (
                      <span className="px-1.5 py-0.5 rounded text-xs bg-[#DDF4F0] text-[#176B87] dark:bg-[#0A3340]/30 dark:text-[#5AAFA4]">
                        AUTO
                      </span>
                    )}
                    {log.isVerified && index === 0 && (
                      <span className="px-1.5 py-0.5 rounded text-xs bg-emerald-100 text-emerald-600">
                        ✓
                      </span>
                    )}
                  </div>
                  <p className="text-xs text-[#64748B] dark:text-[#5AAFA4]">
                    {new Date(log.createdAt).toLocaleTimeString()}
                  </p>
                </div>
              </div>

              {/* Amount */}
              <div className="text-right">
                <p className={`font-bold ${
                  index === 0
                    ? 'text-brand-600 dark:text-brand-400'
                    : 'text-[#12576D] dark:text-[#64748B]'
                }`}>
                  {formatKES(log.amount)}
                </p>
                <p className={`text-xs ${
                  log.status === 'active' ? 'text-emerald-600' : 'text-[#64748B]'
                }`}>
                  {log.status === 'active' ? 'Leading' : log.status}
                </p>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Source indicator */}
      <div className="p-3 border-t border-[#D7E7E4] dark:border-[#12576D] text-center">
        <span className="text-xs text-[#0A3340] dark:text-[#176B87]">
          Showing {Math.min(logs.length, maxItems)} of {stats?.totalBids || logs.length} bids
        </span>
      </div>
    </div>
  );
};

export default ActiveBidLogs;

import { useState, useEffect } from 'react';

export default function AppInstallPrompt() {
  const [deferredPrompt, setDeferredPrompt] = useState<any>(null);

  useEffect(() => {
    const handler = (e: Event) => {
      e.preventDefault();
      setDeferredPrompt(e);
    };
    window.addEventListener('beforeinstallprompt', handler);
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  const handleInstall = () => {
    if (!deferredPrompt) return;
    deferredPrompt.prompt();
    deferredPrompt.userChoice.then(() => {
      setDeferredPrompt(null);
    });
  };

  if (!deferredPrompt) return null;

  return (
    <div style={{
      position: 'fixed', bottom: 20, right: 20, zIndex: 200,
      display: 'flex', alignItems: 'center', gap: 8,
    }}>
      <div onClick={handleInstall} style={{
        background: 'var(--brand)', padding: '8px 14px', borderRadius: '2rem',
        display: 'flex', alignItems: 'center', gap: 8, cursor: 'pointer',
        boxShadow: '0 4px 20px rgba(10, 51, 64, 0.3)', fontSize: 11,
        fontWeight: 700, color: '#0A3340', textTransform: 'uppercase',
        letterSpacing: '0.04em', whiteSpace: 'nowrap',
      }}>
        <span style={{ fontSize: 14 }}>+</span>
        Install App
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { BarChart3, X, Eye } from 'lucide-react';
import { useCompare } from '../../../context/CompareContext';
import { carsAPI } from '../../../api/api';


export default function CompareDrawer() {
  const { compareIds, compareCount, maxCompare, removeCar, clearAll } = useCompare();
  const [cars, setCars] = useState<any[]>([]);

  useEffect(() => {
    let cancelled = false;
    Promise.all(compareIds.map(id => carsAPI.get(id).catch(() => null)))
      .then(results => { if (!cancelled) setCars(results.map((r: any) => r?.car || r?.data || r).filter(Boolean)); });
    return () => { cancelled = true; };
  }, [compareIds]);

  if (compareIds.length === 0) return null;

  return (
    <div className="fixed bottom-4 left-1/2 -translate-x-1/2 z-[9999] bg-[#0A3340]/95 border border-[#5AAFA4]/25 rounded-full px-3 py-2 flex items-center gap-3 shadow-xl backdrop-blur-md max-w-[calc(100vw-2rem)]">
      {/* Icon and count */}
      <div className="flex items-center gap-1.5 flex-shrink-0">
        <BarChart3 size={14} className="text-[#13B8A6]" />
        <span className="text-xs font-bold text-[#13B8A6]">
          Compare {compareCount}/{maxCompare}
        </span>
      </div>

      {/* Car thumbnails */}
      <div className="flex gap-1.5">
        {cars.slice(0, maxCompare).map(car => (
          <div key={car.id} className="relative w-10 h-7 rounded overflow-hidden border border-[#5AAFA4]/25 bg-[#12576D] flex-shrink-0">
            <img
              src={car.image}
              alt={car.model}
              loading="lazy"
              decoding="async"
              className="w-full h-full object-cover"
              onError={e => { (e.target as HTMLImageElement).style.display = 'none'; }}
            />
            <button
              onClick={() => removeCar(String(car.id))}
              aria-label="Remove"
              className="absolute top-0 right-0 w-3.5 h-3.5 rounded-bl bg-[#0A3340]/75 flex items-center justify-center text-white hover:bg-red-500 transition-colors"
            >
              <X size={8} />
            </button>
          </div>
        ))}
      </div>

      {/* Actions */}
      <div className="flex items-center gap-1.5 flex-shrink-0">
        <button
          onClick={clearAll}
          className="bg-transparent border-none text-white/45 text-xs font-semibold cursor-pointer px-1 hover:text-white transition-colors"
        >
          Clear
        </button>
        <Link
          to="/compare"
          className={`inline-flex items-center gap-1 bg-[#13B8A6] rounded-full px-3 py-1.5 text-[#0A3340] text-xs font-bold no-underline transition-all ${
            compareCount < 2 ? 'opacity-50 pointer-events-none' : ''
          }`}
        >
          <Eye size={12} /> Compare
        </Link>
      </div>
    </div>
  );
}

import { Clock, User, FileText, AlertTriangle } from 'lucide-react';
import { timeAgo } from '../../../utils/helpers';

interface TimelineEvent {
  id: string;
  type: 'upload' | 'note' | 'status_change' | 'escalation';
  description: string;
  user?: string;
  timestamp: string;
  details?: string;
}

interface EvidenceTimelineProps {
  events: TimelineEvent[];
  className?: string;
}

export default function EvidenceTimeline({ events, className = '' }: EvidenceTimelineProps) {
  const getEventIcon = (type: TimelineEvent['type']) => {
    switch (type) {
      case 'upload':
        return <FileText className="h-4 w-4 text-[#2F8F87]" />;
      case 'note':
        return <User className="h-4 w-4 text-[#64748B]" />;
      case 'status_change':
        return <Clock className="h-4 w-4 text-[#176B87]" />;
      case 'escalation':
        return <AlertTriangle className="h-4 w-4 text-red-500" />;
      default:
        return <Clock className="h-4 w-4 text-[#64748B]" />;
    }
  };

  const getEventColor = (type: TimelineEvent['type']) => {
    switch (type) {
      case 'upload':
        return 'border-l-blue-500';
      case 'note':
        return 'border-l-gray-400';
      case 'status_change':
        return 'border-l-[#13B8A6]';
      case 'escalation':
        return 'border-l-red-500';
      default:
        return 'border-l-gray-400';
    }
  };

  if (events.length === 0) {
    return (
      <div className="text-center py-8 text-[#64748B]">
        No activity yet
      </div>
    );
  }

  return (
    <div className={`space-y-4 ${className}`}>
      {events.map((event, index) => (
        <div
          key={event.id}
          className={`relative pl-6 border-l-2 ${getEventColor(event.type)} pb-4 last:pb-0`}
        >
          <div className="absolute -left-3 top-0 bg-white p-1">
            {getEventIcon(event.type)}
          </div>

          <div className="ml-4">
            <p className="text-sm font-medium text-[#0A3340]">{event.description}</p>

            {event.details && (
              <p className="mt-1 text-sm text-[#64748B]">{event.details}</p>
            )}

            <div className="mt-1 flex items-center gap-2 text-xs text-[#64748B]">
              {event.user && <span>by {event.user}</span>}
              <span>{timeAgo(event.timestamp)}</span>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}

import { useState, useEffect, useCallback, useRef, type TouchEvent } from 'react';
import { ChevronLeft, ChevronRight, MapPin, Shield, Star, Eye, Clock } from 'lucide-react';
import { formatKES, timeAgo } from '../../../utils/helpers';
import { carsAPI } from '../../../api/api';

interface FeaturedCar {
  _id: string;
  title: string;
  brand: string;
  model: string;
  price: number;
  currentBid?: number;
  year: number;
  mileage?: number | string;
  fuel?: string;
  location?: { city?: string };
  images?: Array<{ url?: string } | string>;
  isPromoted?: boolean;
  views?: number;
  createdAt?: string;
  escrowEnabled?: boolean;
  auctionStatus?: string;
  auctionEnd?: string;
  ntsaVerified?: boolean;
  dealer?: { name?: string; isBank?: boolean };
}

interface HeroCarouselProps {
  onViewCar: (car: FeaturedCar) => void;
}

export default function HeroCarousel({ onViewCar }: HeroCarouselProps) {
  const [cars, setCars] = useState<FeaturedCar[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [touchStart, setTouchStart] = useState<number | null>(null);
  const autoPlayRef = useRef<NodeJS.Timeout | null>(null);

  // Fetch featured cars (promoted or top-viewed) using API client
  useEffect(() => {
    const fetchFeatured = async () => {
      try {
        const data = await carsAPI.list({ page: 1, limit: 20, status: 'active' });
        const fetchedCars = data?.cars || data?.data || [];
        // Filter for promoted or top viewed
        const featured = fetchedCars.filter((car: FeaturedCar) =>
          car.isPromoted || (car.views && car.views > 100)
        ).slice(0, 5);
        setCars(featured.length > 0 ? featured : fetchedCars.slice(0, 5));
      } catch {
        // API unavailable; keep the featured carousel empty
      } finally {
        setLoading(false);
      }
    };
    fetchFeatured();
  }, []);

  const displayCars = cars;

  const nextSlide = useCallback(() => {
    setCurrentIndex(prev => (prev + 1) % displayCars.length);
  }, [displayCars.length]);

  const prevSlide = useCallback(() => {
    setCurrentIndex(prev => (prev - 1 + displayCars.length) % displayCars.length);
  }, [displayCars.length]);

  const goToSlide = useCallback((index: number) => {
    setCurrentIndex(index);
  }, []);

  // Auto-play
  useEffect(() => {
    if (displayCars.length <= 1) return;
    autoPlayRef.current = setInterval(nextSlide, 5000);
    return () => {
      if (autoPlayRef.current) clearInterval(autoPlayRef.current);
    };
  }, [nextSlide, displayCars.length]);

  const pauseAutoplay = () => {
    if (autoPlayRef.current) clearInterval(autoPlayRef.current);
  };

  const resumeAutoplay = () => {
    if (displayCars.length <= 1) return;
    autoPlayRef.current = setInterval(nextSlide, 5000);
  };

  // Touch handlers for swipe
  const handleTouchStart = (e: TouchEvent) => {
    setTouchStart(e.touches[0].clientX);
    pauseAutoplay();
  };

  const handleTouchEnd = (e: TouchEvent) => {
    if (touchStart === null) return;
    const touchEnd = e.changedTouches[0].clientX;
    const diff = touchStart - touchEnd;
    if (diff > 50) nextSlide();
    else if (diff < -50) prevSlide();
    setTouchStart(null);
    resumeAutoplay();
  };

  const currentCar = displayCars[currentIndex];
  if (!currentCar) return null;

  const firstImage = (car: FeaturedCar) => {
    const imgs = car.images || [];
    const img = imgs[0];
    if (typeof img === 'string') return img;
    return img?.url || '';
  };

  return (
    <div
      className="relative w-full overflow-hidden rounded-2xl"
      onMouseEnter={pauseAutoplay}
      onMouseLeave={resumeAutoplay}
      onTouchStart={handleTouchStart}
      onTouchEnd={handleTouchEnd}
    >
      {/* Slides Container */}
      <div
        className="flex transition-transform duration-500 ease-out"
        style={{ transform: `translateX(-${currentIndex * 100}%)` }}
      >
        {displayCars.map((car, idx) => (
          <div
            key={car._id || idx}
            className="w-full flex-shrink-0"
            onClick={() => onViewCar(car as any)}
          >
            <div className="relative aspect-[21/9] bg-[#12576D] overflow-hidden">
              <img
                src={firstImage(car)}
                alt={car.title}
                className="w-full h-full object-cover"
                loading={idx === 0 ? 'eager' : 'lazy'}
              />

              {/* Gradient Overlay */}
              <div className="absolute inset-0 bg-gradient-to-r from-[#0A3340]/90 via-[#0A3340]/50 to-transparent" />
              <div className="absolute inset-0 bg-gradient-to-t from-[#0A3340]/80 via-transparent to-transparent" />

              {/* Content */}
              <div className="absolute inset-0 flex items-center">
                <div className="max-w-7xl mx-auto w-full px-6 sm:px-8 lg:px-12">
                  <div className="max-w-xl">
                    {/* Badges */}
                    <div className="flex flex-wrap gap-2 mb-4">
                      {car.isPromoted && (
                        <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-[#13B8A6]/90 text-[#0A3340] text-xs font-bold rounded-full">
                          <Star size={12} /> FEATURED
                        </span>
                      )}
                      {car.escrowEnabled && (
                        <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-[#12576D]/80 text-white text-xs font-semibold rounded-full backdrop-blur-sm">
                          <Shield size={12} /> ESCROW
                        </span>
                      )}
                      {car.ntsaVerified && (
                        <span className="inline-flex items-center gap-1.5 px-3 py-1 bg-emerald-500/90 text-white text-xs font-semibold rounded-full">
                          ✓ NTSA OK
                        </span>
                      )}
                    </div>

                    {/* Title */}
                    <h2 className="font-serif text-2xl sm:text-3xl lg:text-4xl text-white font-bold mb-2 leading-tight">
                      {car.title}
                    </h2>

                    {/* Quick Specs */}
                    <div className="flex flex-wrap items-center gap-4 text-white/70 text-sm mb-4">
                      {car.year && <span>{car.year}</span>}
                      {car.mileage && <span>· {car.mileage}</span>}
                      {car.fuel && <span>· {car.fuel}</span>}
                      {car.location?.city && (
                        <span className="flex items-center gap-1">
                          <MapPin size={14} /> {car.location.city}
                        </span>
                      )}
                    </div>

                    {/* Price & Stats */}
                    <div className="flex items-end justify-between">
                      <div>
                        <p className="text-white/50 text-xs font-semibold uppercase tracking-wider mb-1">
                          {car.currentBid ? 'Current Bid' : 'Price'}
                        </p>
                        <p className="font-serif text-3xl sm:text-4xl text-[#13B8A6] font-bold">
                          {formatKES(car.currentBid || car.price)}
                        </p>
                      </div>

                      <div className="hidden sm:flex items-center gap-4 text-white/50 text-xs">
                        {car.views && (
                          <span className="flex items-center gap-1">
                            <Eye size={14} /> {car.views.toLocaleString()}
                          </span>
                        )}
                        {car.createdAt && (
                          <span className="flex items-center gap-1">
                            <Clock size={14} /> {timeAgo(car.createdAt)}
                          </span>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              </div>

              {/* Live Badge */}
              {car.auctionStatus === 'live' && (
                <div className="absolute top-4 left-4 flex items-center gap-2 px-3 py-1.5 bg-red-500/90 text-white text-xs font-bold rounded-full">
                  <span className="w-2 h-2 bg-white rounded-full animate-pulse" />
                  LIVE AUCTION
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Navigation Arrows */}
      {displayCars.length > 1 && (
        <>
          <button
            onClick={(e) => { e.stopPropagation(); prevSlide(); }}
            className="absolute left-4 top-1/2 -translate-y-1/2 w-10 h-10 bg-white/10 hover:bg-white/20 backdrop-blur-sm text-white rounded-full flex items-center justify-center transition-all z-10"
          >
            <ChevronLeft size={20} />
          </button>
          <button
            onClick={(e) => { e.stopPropagation(); nextSlide(); }}
            className="absolute right-4 top-1/2 -translate-y-1/2 w-10 h-10 bg-white/10 hover:bg-white/20 backdrop-blur-sm text-white rounded-full flex items-center justify-center transition-all z-10"
          >
            <ChevronRight size={20} />
          </button>
        </>
      )}

      {/* Pagination Dots */}
      {displayCars.length > 1 && (
        <div className="absolute bottom-4 left-1/2 -translate-x-1/2 flex gap-2 z-10">
          {displayCars.map((_, idx) => (
            <button
              key={idx}
              onClick={(e) => { e.stopPropagation(); goToSlide(idx); }}
              className={`w-2 h-2 rounded-full transition-all ${
                idx === currentIndex
                  ? 'w-6 bg-[#13B8A6]'
                  : 'bg-white/40 hover:bg-white/60'
              }`}
            />
          ))}
        </div>
      )}

      {/* Loading State */}
      {loading && (
        <div className="absolute inset-0 bg-[#12576D] animate-pulse flex items-center justify-center">
          <div className="text-[#13B8A6] font-serif text-xl">Loading featured vehicles...</div>
        </div>
      )}
    </div>
  );
}

import { useState, type FormEvent } from 'react';
import { MessageSquare, Send, Lock } from 'lucide-react';
import { useAuth } from '../../../context/AuthContext';

interface Note {
  id: string;
  content: string;
  author: string;
  createdAt: string;
  isPrivate: boolean;
}

interface InternalNotesProps {
  disputeId: string;
  initialNotes?: Note[];
  onAddNote?: (content: string, isPrivate: boolean) => void;
}

export default function InternalNotes({
  disputeId,
  initialNotes = [],
  onAddNote
}: InternalNotesProps) {
  const [notes, setNotes] = useState<Note[]>(initialNotes);
  const [newNote, setNewNote] = useState('');
  const [isPrivate, setIsPrivate] = useState(false);
  const { user } = useAuth();

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!newNote.trim() || !user) return;

    const note: Note = {
      id: Date.now().toString(),
      content: newNote,
      author: user.name || user.email || 'Unknown',
      createdAt: new Date().toISOString(),
      isPrivate
    };

    setNotes([note, ...notes]);
    onAddNote?.(newNote, isPrivate);
    setNewNote('');
  };

  return (
    <div className="space-y-4">
      <form onSubmit={handleSubmit} className="space-y-3">
        <div className="relative">
          <textarea
            value={newNote}
            onChange={(e) => setNewNote(e.target.value)}
            placeholder="Add an internal note..."
            rows={3}
            className="w-full px-3 py-2 border border-[#BDE5DE] rounded-lg focus:ring-2 focus:ring-[#5AAFA4] focus:border-transparent resize-none"
          />
          <MessageSquare className="absolute right-3 top-3 h-5 w-5 text-[#94A3B8]" />
        </div>

        <div className="flex items-center justify-between">
          <label className="flex items-center gap-2 text-sm text-[#64748B]">
            <input
              type="checkbox"
              checked={isPrivate}
              onChange={(e) => setIsPrivate(e.target.checked)}
              className="rounded border-[#BDE5DE] text-[#176B87] focus:ring-[#5AAFA4]"
            />
            <Lock className="h-4 w-4" />
            Private note
          </label>

          <button
            type="submit"
            disabled={!newNote.trim()}
            className="flex items-center gap-2 px-4 py-2 bg-[#176B87] text-white rounded-lg hover:bg-[#12576D] disabled:opacity-50 disabled:cursor-not-allowed"
          >
            <Send className="h-4 w-4" />
            Add Note
          </button>
        </div>
      </form>

      <div className="space-y-3">
        {notes.map((note) => (
          <div
            key={note.id}
            className={`p-3 rounded-lg ${
              note.isPrivate ? 'bg-[#F3FAF9] border border-[#BDE5DE]' : 'bg-[#F6FAF9]'
            }`}
          >
            <div className="flex items-center justify-between mb-2">
              <span className="font-medium text-sm">{note.author}</span>
              <div className="flex items-center gap-2 text-xs text-[#64748B]">
                {note.isPrivate && <Lock className="h-3 w-3" />}
                <span>{new Date(note.createdAt).toLocaleString()}</span>
              </div>
            </div>
            <p className="text-sm text-[#12576D]">{note.content}</p>
          </div>
        ))}

        {notes.length === 0 && (
          <p className="text-center text-sm text-[#64748B] py-4">
            No internal notes yet
          </p>
        )}
      </div>
    </div>
  );
}

