import { useState, useEffect } from 'react';
import { TrendingUp, TrendingDown, Minus, BarChart3, Clock, Target } from 'lucide-react';
import { marketAPI } from '../../../api/api';

const fmtKES = (n) => 'KES ' + Number(n || 0).toLocaleString('en-KE');

const TREND_CONFIG = {
  undervalued: { icon: TrendingUp, color: '#22c55e', label: 'Undervalued', desc: 'Priced below market — good buying opportunity' },
  stable: { icon: Minus, color: '#176B87', label: 'Fair Value', desc: 'Priced in line with market' },
  overvalued: { icon: TrendingDown, color: '#ef4444', label: 'Overvalued', desc: 'Priced above typical market range' },
};

function ScoreRing({ score, size = 56 }) {
  const r = (size - 8) / 2;
  const circ = 2 * Math.PI * r;
  const offset = circ - (score / 100) * circ;
  const color = score >= 75 ? '#22c55e' : score >= 50 ? 'var(--brand)' : '#ef4444';
  return (
    <svg width={size} height={size} style={{ flexShrink: 0 }}>
      <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="rgba(255,255,255,0.06)" strokeWidth={4} />
      <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke={color} strokeWidth={4}
        strokeDasharray={circ} strokeDashoffset={offset} strokeLinecap="round"
        transform={`rotate(-90 ${size / 2} ${size / 2})`}
        style={{ transition: 'stroke-dashoffset 1s ease' }} />
      <text x={size / 2} y={size / 2} textAnchor="middle" dominantBaseline="central"
        fill={color} fontSize={size * 0.28} fontWeight={900} fontFamily="var(--font-display)">
        {score}
      </text>
    </svg>
  );
}

export default function MarketPulse({ carId, carBrand, carYear }) {
  const [pulse, setPulse] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  useEffect(() => {
    if (!carId) { setLoading(false); return; }
    setLoading(true);
    setError(false);
    marketAPI.pulse(carId)
      .then(d => setPulse(d?.data || d))
      .catch(() => setError(true))
      .finally(() => setLoading(false));
  }, [carId]);

  if (loading) return (
    <div style={{ background: 'var(--card)', borderRadius: 'var(--radius-lg)', border: '1px solid var(--border)', padding: 16, marginBottom: 14 }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 12 }}>
        <BarChart3 size={14} style={{ color: 'var(--brand)' }} />
        <span style={{ fontSize: 11, fontWeight: 700, color: 'rgba(255,255,255,0.5)', textTransform: 'uppercase', letterSpacing: '0.06em' }}>Market Pulse</span>
      </div>
      <div style={{ height: 14, borderRadius: 4, background: 'rgba(255,255,255,0.05)', width: '60%', marginBottom: 8 }} />
      <div style={{ height: 14, borderRadius: 4, background: 'rgba(255,255,255,0.05)', width: '40%' }} />
    </div>
  );

  if (error || !pulse) return null;

  const trend = TREND_CONFIG[pulse.trend] || TREND_CONFIG.stable;
  const TrendIcon = trend.icon;

  return (
    <div style={{
      background: 'linear-gradient(135deg, var(--card) 0%, rgba(19, 184, 166, 0.04) 100%)',
      borderRadius: 'var(--radius-lg)', border: '1px solid rgba(19, 184, 166, 0.15)',
      padding: 16, marginBottom: 14,
    }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 14 }}>
        <BarChart3 size={14} style={{ color: 'var(--brand)' }} />
        <span style={{ fontSize: 11, fontWeight: 700, color: 'rgba(255,255,255,0.6)', textTransform: 'uppercase', letterSpacing: '0.06em' }}>Market Pulse</span>
        <span style={{ marginLeft: 'auto', fontSize: 10, color: 'rgba(255,255,255,0.25)' }}>{carBrand} · {carYear}</span>
      </div>

      <div style={{ display: 'flex', gap: 16, alignItems: 'center', marginBottom: 14 }}>
        <ScoreRing score={pulse.predictiveScore} />
        <div style={{ flex: 1, minWidth: 0 }}>
          <div style={{ fontSize: 13, fontWeight: 800, color: '#fff', marginBottom: 2 }}>
            {pulse.demandScore >= 80 ? 'High Demand' : pulse.demandScore >= 60 ? 'Moderate Demand' : 'Low Demand'}
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: 5, marginBottom: 4 }}>
            <TrendIcon size={12} style={{ color: trend.color }} />
            <span style={{ fontSize: 11, fontWeight: 700, color: trend.color }}>{trend.label}</span>
          </div>
          <div style={{ fontSize: 10, color: 'rgba(255,255,255,0.4)', lineHeight: 1.4 }}>{trend.desc}</div>
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 8, marginBottom: 12 }}>
        <div style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 8, padding: '10px 12px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 5, marginBottom: 4 }}>
            <Target size={11} style={{ color: 'var(--brand)' }} />
            <span style={{ fontSize: 9, color: 'rgba(255,255,255,0.4)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Fair Price</span>
          </div>
          <div style={{ fontSize: 12, fontWeight: 700, color: '#fff' }}>{fmtKES(pulse.fairPriceRange.avg)}</div>
          <div style={{ fontSize: 10, color: 'rgba(255,255,255,0.3)' }}>
            {fmtKES(pulse.fairPriceRange.min)} – {fmtKES(pulse.fairPriceRange.max)}
          </div>
        </div>
        <div style={{ background: 'rgba(255,255,255,0.03)', borderRadius: 8, padding: '10px 12px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 5, marginBottom: 4 }}>
            <Clock size={11} style={{ color: trend.color }} />
            <span style={{ fontSize: 9, color: 'rgba(255,255,255,0.4)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Est. Sell Time</span>
          </div>
          <div style={{ fontSize: 12, fontWeight: 700, color: '#fff' }}>{pulse.estDaysToSell} days</div>
          <div style={{ fontSize: 10, color: 'rgba(255,255,255,0.3)' }}>
            {pulse.daysOnMarket} days on market
          </div>
        </div>
      </div>

      <div style={{ height: 4, borderRadius: 9999, background: 'rgba(255,255,255,0.06)', overflow: 'hidden', marginBottom: 8 }}>
        <div style={{
          width: `${pulse.demandScore}%`, height: '100%', borderRadius: 9999,
          background: `linear-gradient(90deg, #176B87, ${pulse.demandScore >= 80 ? '#22c55e' : pulse.demandScore >= 50 ? 'var(--brand)' : '#ef4444'})`,
          transition: 'width 1s ease',
        }} />
      </div>
      <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 9, color: 'rgba(255,255,255,0.3)' }}>
        <span>Market Demand Score: {pulse.demandScore}/100</span>
        <span>{pulse.sampleSize} comparable listings</span>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { TrendingUp, TrendingDown, Minus, Info } from 'lucide-react';
import { formatKES } from '../../../utils/helpers';
import { getValuationMatrix, type ValuationMatrixRow } from '../../../services/valuationApi';

interface Props { vehicle?: { make?: string; model?: string; year?: number; price?: number } }

export default function MarketValuationMatrix({ vehicle }: Props) {
  const [rows, setRows] = useState<ValuationMatrixRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let active = true;
    setLoading(true);
    getValuationMatrix({ brand: vehicle?.make, model: vehicle?.model, limit: 20 })
      .then((response) => { if (active) setRows(response.data || []); })
      .catch((err) => { if (active) setError(err instanceof Error ? err.message : 'Unable to load valuation data'); })
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [vehicle?.make, vehicle?.model]);

  const current = useMemo(() => rows.find((row) => row.make.toLowerCase() === vehicle?.make?.toLowerCase() && row.model.toLowerCase() === vehicle?.model?.toLowerCase()), [rows, vehicle]);
  const trend = (row: ValuationMatrixRow) => vehicle?.price && row.avgPrice ? ((row.avgPrice - vehicle.price) / vehicle.price) * 100 : 0;

  return <div className="bg-white rounded-2xl border border-[#D7E7E4] overflow-hidden">
    <div className="p-5 border-b border-[#D7E7E4] flex items-center justify-between"><div><h3 className="font-serif text-lg text-[#0A3340] font-bold">Market Valuation</h3><p className="font-sans text-xs text-warm-400 mt-0.5">Calculated from KAYAD vehicle inventory</p></div><Info size={16} className="text-warm-400" /></div>
    {loading ? <div className="p-6 text-sm text-warm-500">Loading live market data…</div> : error ? <div className="p-6 text-sm text-red-600">{error}</div> : rows.length === 0 ? <div className="p-6 text-sm text-warm-500">No comparable KAYAD inventory is available yet.</div> : <div className="overflow-x-auto"><table className="w-full"><thead><tr className="bg-[#F6FAF9]">{['Vehicle','Avg. Price','Range','Trend','Listings'].map((h) => <th key={h} className="px-4 py-3 text-right first:text-left font-sans text-[10px] text-warm-400 font-bold uppercase tracking-wider">{h}</th>)}</tr></thead><tbody>{rows.map((row) => { const change = trend(row); const isMatch = current === row; return <tr key={`${row.make}-${row.model}-${row.year}`} className={`border-b border-[#D7E7E4] hover:bg-[#F6FAF9] ${isMatch ? 'bg-[#13B8A6]/5' : ''}`}><td className="px-4 py-3"><p className="font-sans text-sm font-semibold text-[#0A3340]">{row.make} {row.model}</p><p className="font-sans text-xs text-warm-400">{row.year}</p></td><td className="px-4 py-3 text-right font-sans text-sm font-semibold text-[#0A3340]">{formatKES(row.avgPrice)}</td><td className="px-4 py-3 text-right font-sans text-xs text-warm-500">{formatKES(row.minPrice)} - {formatKES(row.maxPrice)}</td><td className="px-4 py-3 text-right"><span className="inline-flex items-center gap-1 text-xs font-semibold">{change > 2 ? <TrendingUp size={14} /> : change < -2 ? <TrendingDown size={14} /> : <Minus size={14} />}{change > 0 ? '+' : ''}{change.toFixed(1)}%</span></td><td className="px-4 py-3 text-right font-sans text-xs text-warm-500">{row.listingsCount}</td></tr>; })}</tbody></table></div>}
    <div className="px-4 py-3 bg-[#F6FAF9] border-t border-[#D7E7E4]"><p className="font-sans text-[10px] text-warm-400 text-center">Live KAYAD inventory comparables · No hardcoded valuation figures</p></div>
  </div>;
}

import { useMemo } from 'react';
import { useNotifications } from '../../../context/NotificationContext';
import { Link } from 'react-router-dom';
import { Bell, Check, X, Clock, MessageCircle, Shield, DollarSign, Gavel } from 'lucide-react';
import { timeAgo } from '../../../utils/helpers';
import { notificationDestination } from '../../../utils/notificationDestination';

interface Notification {
  id: string;
  type: 'bid' | 'payment' | 'escrow' | 'chat' | 'auction' | 'system' | 'info' | 'referral';
  title: string;
  message?: string;
  read: boolean;
  createdAt: string;
  link?: string;
}

interface NotificationCenterProps {
  onClose?: () => void;
}

const TYPE_CONFIG = {
  bid: { icon: DollarSign, color: 'text-[#13B8A6]', bg: 'bg-[#13B8A6]/10' },
  payment: { icon: DollarSign, color: 'text-emerald-400', bg: 'bg-emerald-500/10' },
  escrow: { icon: Shield, color: 'text-[#5AAFA4]', bg: 'bg-[#13B8A6]/10' },
  chat: { icon: MessageCircle, color: 'text-[#5AAFA4]', bg: 'bg-[#13B8A6]/10' },
  auction: { icon: Gavel, color: 'text-red-400', bg: 'bg-red-500/10' },
  system: { icon: Bell, color: 'text-warm-400', bg: 'bg-warm-500/10' },
  info: { icon: Bell, color: 'text-warm-400', bg: 'bg-warm-500/10' },
  referral: { icon: Bell, color: 'text-[#13B8A6]', bg: 'bg-[#13B8A6]/10' },
};

export default function NotificationCenter({ onClose }: NotificationCenterProps) {
  const { notifications, unreadCount, markAsRead, markAllRead, deleteNotif } = useNotifications();
  const visibleNotifications = useMemo(() => notifications.slice(0, 20), [notifications]);

  const getNotifIcon = (type: string) => {
    const config = TYPE_CONFIG[type as keyof typeof TYPE_CONFIG] || TYPE_CONFIG.info;
    return config.icon;
  };

  return (
    <div className="absolute top-full right-0 mt-3 w-[min(370px,calc(100vw-1.5rem))] bg-[#0A3340] border border-white/10 rounded-2xl shadow-2xl overflow-hidden z-[200]">
      {/* Header */}
      <div className="px-5 py-4 flex items-center justify-between border-b border-white/5">
        <div className="flex items-center gap-2">
          <span className="font-sans font-bold text-white">
            Notifications
            {unreadCount > 0 && (
              <span className="ml-2 text-xs text-[#13B8A6] font-bold">({unreadCount})</span>
            )}
          </span>
        </div>
        {unreadCount > 0 && (
          <button
            onClick={markAllRead}
            className="bg-transparent border-none text-[#13B8A6] text-xs font-semibold cursor-pointer hover:text-[#5AAFA4] transition-colors"
          >
            Mark all read
          </button>
        )}
      </div>

      {/* Empty state */}
      {visibleNotifications.length === 0 && (
        <div className="px-5 py-12 text-center text-white/30 font-sans text-sm">
          No notifications yet
        </div>
      )}

      {/* List */}
      {notifications.length > 0 && (
        <div className="max-h-[380px] overflow-y-auto">
          {notifications.map((n) => {
            const Icon = getNotifIcon(n.type);
            const config = TYPE_CONFIG[n.type as keyof typeof TYPE_CONFIG] || TYPE_CONFIG.info;
            const content = (
              <div
                className={`px-5 py-3 border-b border-white/3 flex gap-3 items-start cursor-pointer transition-colors ${
                  n.read ? 'hover:bg-white/2' : 'bg-[#13B8A6]/3 hover:bg-[#13B8A6]/5'
                }`}
                onClick={() => void markAsRead(n._id)}
              >
                {/* Icon */}
                <div className={`w-8 h-8 rounded-lg ${config.bg} flex items-center justify-center flex-shrink-0`}>
                  <Icon size={16} className={config.color} />
                </div>

                {/* Content */}
                <div className="flex-1 min-w-0">
                  <div className="flex items-start gap-2">
                    <span className={`font-sans text-sm flex-1 ${n.read ? 'text-white/55 font-normal' : 'text-white font-semibold'}`}>
                      {n.title}
                    </span>
                    {!n.read && (
                      <button
                        onClick={(e) => { e.stopPropagation(); markAsRead(n._id); }}
                        className="bg-transparent border-none text-[#13B8A6]/40 text-xs cursor-pointer hover:text-[#13B8A6] flex-shrink-0"
                      >
                        <Check size={14} />
                      </button>
                    )}
                  </div>
                  {n.message && (
                    <p className="font-sans text-xs text-white/30 mt-0.5 line-clamp-2">{n.message}</p>
                  )}
                  <div className="flex items-center gap-2 mt-1.5">
                    <span className="font-sans text-[10px] text-white/20 flex items-center gap-1">
                      <Clock size={10} />
                      {timeAgo(n.createdAt)}
                    </span>
                    <button
                      onClick={(e) => { e.stopPropagation(); deleteNotif(n._id); }}
                      className="bg-transparent border-none text-red-400/30 text-xs cursor-pointer hover:text-red-400 ml-auto"
                    >
                      <X size={12} />
                    </button>
                  </div>
                </div>
              </div>
            );

            const destination = notificationDestination(n);
            if (destination) {
              return (
                <Link
                  key={n._id}
                  to={destination}
                  onClick={onClose}
                  className="block no-underline"
                >
                  {content}
                </Link>
              );
            }

            return <div key={n._id}>{content}</div>;
          })}
        </div>
      )}

      {/* Footer */}
      <Link
        to="/notifications"
        onClick={onClose}
        className="block px-5 py-3.5 text-center font-sans text-sm text-[#13B8A6] border-t border-white/5 hover:text-[#5AAFA4] no-underline font-semibold transition-colors"
      >
        View all →
      </Link>
    </div>
  );
}

import { useState, useRef, useEffect } from 'react';
import { Flag } from 'lucide-react';

const REPORT_REASONS = [
  { value: 'fake_listing', label: 'Fake Listing' },
  { value: 'scam', label: 'Scam / Fraud' },
  { value: 'misleading_photos', label: 'Misleading Photos' },
  { value: 'wrong_info', label: 'Wrong Information' },
  { value: 'duplicate', label: 'Duplicate Listing' },
  { value: 'spam', label: 'Spam' },
  { value: 'other', label: 'Other' },
];

interface ReportButtonProps {
  targetType: 'listing' | 'dealer' | 'review';
  targetId: string;
  onReported?: () => void;
}

export default function ReportButton({ targetType, targetId, onReported }: ReportButtonProps) {
  const [open, setOpen] = useState(false);
  const [reason, setReason] = useState('');
  const [description, setDescription] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [done, setDone] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Close on click outside
  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    if (open) {
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }
  }, [open]);

  const handleSubmit = async () => {
    if (!reason) return;

    setSubmitting(true);
    try {
      // API call would go here
      // await reportAPI.submit({ targetType, targetId, category: reason, description });

      // Simulate success
      await new Promise(resolve => setTimeout(resolve, 1000));
      setDone(true);
      onReported?.();
      setTimeout(() => {
        setOpen(false);
        setDone(false);
        setReason('');
        setDescription('');
      }, 2000);
    } catch (e) {
      setOpen(false);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="relative inline-block" ref={dropdownRef}>
      <button
        onClick={() => setOpen(!open)}
        className="flex items-center gap-1.5 text-xs text-warm-400 hover:text-warm-600 transition-colors"
        title="Report"
      >
        <Flag size={12} />
        <span>Report</span>
      </button>

      {open && (
        <div className="absolute right-0 top-full z-50 mt-2 w-72 bg-white border border-[#D7E7E4] rounded-xl shadow-xl overflow-hidden">
          {done ? (
            <div className="p-4 text-center">
              <div className="w-10 h-10 bg-emerald-100 rounded-full flex items-center justify-center mx-auto mb-2">
                <span className="text-emerald-500 text-xl">✓</span>
              </div>
              <p className="font-sans text-sm font-semibold text-[#0A3340]">Report submitted</p>
              <p className="font-sans text-xs text-warm-400 mt-1">We'll review and take action if needed.</p>
            </div>
          ) : (
            <>
              <div className="p-4 border-b border-[#D7E7E4]">
                <p className="font-sans text-sm font-semibold text-[#0A3340] mb-1">
                  Report this {targetType}
                </p>
                <p className="font-sans text-xs text-warm-400">
                  Help us keep KAYAD safe and trustworthy.
                </p>
              </div>

              <div className="p-4 space-y-3">
                <select
                  value={reason}
                  onChange={(e) => setReason(e.target.value)}
                  className="w-full px-3 py-2 bg-[#F6FAF9] border border-[#D7E7E4] rounded-lg font-sans text-sm text-[#0A3340] outline-none focus:border-[#5AAFA4]"
                >
                  <option value="">Select a reason...</option>
                  {REPORT_REASONS.map(r => (
                    <option key={r.value} value={r.value}>{r.label}</option>
                  ))}
                </select>

                <textarea
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                  placeholder="Additional details (optional)..."
                  rows={2}
                  className="w-full px-3 py-2 bg-[#F6FAF9] border border-[#D7E7E4] rounded-lg font-sans text-sm text-[#0A3340] placeholder-warm-300 outline-none focus:border-[#5AAFA4] resize-none"
                />

                <div className="flex gap-2">
                  <button
                    onClick={() => setOpen(false)}
                    className="flex-1 px-3 py-2 bg-[#EEF7F5] text-[#0A3340] font-sans text-xs font-semibold rounded-lg hover:bg-[#DDF4F0] transition-colors"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={handleSubmit}
                    disabled={!reason || submitting}
                    className={`flex-1 px-3 py-2 font-sans text-xs font-semibold rounded-lg transition-colors ${
                      !reason || submitting
                        ? 'bg-[#DDF4F0] text-warm-400 cursor-not-allowed'
                        : 'bg-red-500 text-white hover:bg-red-600'
                    }`}
                  >
                    {submitting ? 'Submitting...' : 'Submit Report'}
                  </button>
                </div>
              </div>
            </>
          )}
        </div>
      )}
    </div>
  );
}

// src/components/SEOHead.tsx - Production Hardened v7.0
// ─────────────────────────────────────────────────────────────
// SEO head component for React
// Renders meta tags, OpenGraph tags, Twitter cards, canonical URL, and structured data
// ─────────────────────────────────────────────────────────────

import { Helmet } from "react-helmet-async";

interface OpenGraph {
  title: string;
  description: string;
  type: string;
  url: string;
  image: string;
  siteName: string;
  locale: string;
  priceAmount?: string;
  priceCurrency?: string;
  availability?: string;
}

interface Twitter {
  card: string;
  title: string;
  description: string;
  image: string;
}

interface Metadata {
  title: string;
  description: string;
  openGraph: OpenGraph;
  twitter: Twitter;
  canonical: string;
  structuredData?: any;
}

interface SEOHeadProps {
  metadata?: Metadata;
  title?: string;
  description?: string;
}

const buildDefaultMetadata = (title: string, description: string): Metadata => ({
  title,
  description,
  openGraph: {
    title,
    description,
    type: 'website',
    url: typeof window !== 'undefined' ? window.location.href : '',
    image: '',
    siteName: 'KAYAD',
    locale: 'en_KE',
  },
  twitter: {
    card: 'summary_large_image',
    title,
    description,
    image: '',
  },
  canonical: typeof window !== 'undefined' ? window.location.href : '',
});

const SEOHead = ({ metadata, title, description }: SEOHeadProps) => {
  const resolvedMetadata = metadata || (title ? buildDefaultMetadata(title, description || '') : null);
  if (!resolvedMetadata) return null;

  return (
    <Helmet>
      <title>{resolvedMetadata.title}</title>
      <meta name="description" content={resolvedMetadata.description} />

      {/* OpenGraph */}
      <meta property="og:title" content={resolvedMetadata.openGraph.title} />
      <meta property="og:description" content={resolvedMetadata.openGraph.description} />
      <meta property="og:type" content={resolvedMetadata.openGraph.type} />
      <meta property="og:url" content={resolvedMetadata.openGraph.url} />
      <meta property="og:image" content={resolvedMetadata.openGraph.image} />
      <meta property="og:site_name" content={resolvedMetadata.openGraph.siteName} />
      <meta property="og:locale" content={resolvedMetadata.openGraph.locale} />
      {resolvedMetadata.openGraph.priceAmount && (
        <meta property="og:price:amount" content={resolvedMetadata.openGraph.priceAmount} />
      )}
      {resolvedMetadata.openGraph.priceCurrency && (
        <meta property="og:price:currency" content={resolvedMetadata.openGraph.priceCurrency} />
      )}
      {resolvedMetadata.openGraph.availability && (
        <meta property="og:availability" content={resolvedMetadata.openGraph.availability} />
      )}

      {/* Twitter Cards */}
      <meta name="twitter:card" content={resolvedMetadata.twitter.card} />
      <meta name="twitter:title" content={resolvedMetadata.twitter.title} />
      <meta name="twitter:description" content={resolvedMetadata.twitter.description} />
      <meta name="twitter:image" content={resolvedMetadata.twitter.image} />

      {/* Canonical URL */}
      <link rel="canonical" href={resolvedMetadata.canonical} />

      {/* Structured Data */}
      {resolvedMetadata.structuredData && (
        <script type="application/ld+json">
          {JSON.stringify(resolvedMetadata.structuredData)}
        </script>
      )}
    </Helmet>
  );
};

export default SEOHead;

