import { useRef, useState, useEffect } from 'react';
import { Search, X, Clock } from 'lucide-react';
import { useRecentSearches } from '../../../hooks/useRecentSearches';
import { autocompleteSearch } from '../../../services/searchApi';

const MAX_RECENT = 8;



interface SearchBarProps {
  value?: string;
  onChange?: (value: string) => void;
  onSubmit?: (value: string) => void;
  suggestions?: string[];
  placeholder?: string;
  autoFocus?: boolean;
  size?: 'sm' | 'md' | 'lg';
}

export default function SearchBar({
  value = '',
  onChange,
  onSubmit,
  suggestions = [],
  placeholder = 'Search by make, model, or keyword…',
  autoFocus = false,
  size = 'md',
}: SearchBarProps) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [focused, setFocused] = useState(false);
  const [remoteSuggestions, setRemoteSuggestions] = useState<string[]>([]);
  const { recentSearches, addRecentSearch, clearRecentSearches } = useRecentSearches();

  useEffect(() => {
    if (autoFocus && inputRef.current) inputRef.current.focus();
  }, [autoFocus]);

  useEffect(() => {
    let cancelled = false;
    const query = value.trim();
    if (query.length < 2) { setRemoteSuggestions([]); return undefined; }
    const timer = window.setTimeout(async () => {
      try {
        const results = await autocompleteSearch(query);
        if (!cancelled) setRemoteSuggestions(results.map(item => item.text));
      } catch {
        if (!cancelled) setRemoteSuggestions([]);
      }
    }, 180);
    return () => { cancelled = true; window.clearTimeout(timer); };
  }, [value]);

  const matched = value
    ? (remoteSuggestions.length ? remoteSuggestions : suggestions.filter(s => s.toLowerCase().includes(value.toLowerCase())))
    : suggestions;
  const showSuggestions = focused && matched.length > 0 && matched[0] !== value;
  const showRecent = focused && !value && recentSearches.length > 0;

  const handleSelect = (query) => {
    onChange?.(query);
    onSubmit?.(query);
    addRecentSearch(query);
    inputRef.current?.blur();
  };

  const clearRecent = (e) => {
    e.stopPropagation();
    void clearRecentSearches();
  };

  const padY = size === 'sm' ? 9 : size === 'lg' ? 15 : 12;
  const iconSize = size === 'sm' ? 15 : size === 'lg' ? 19 : 17;
  const fontSize = size === 'sm' ? 13 : size === 'lg' ? 16 : 14;

  return (
    <div style={{ position: 'relative', width: '100%' }}>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          width: '100%',
          background: focused ? 'rgba(255,255,255,0.045)' : 'rgba(255,255,255,0.02)',
          border: `1px solid ${focused ? 'var(--brand)' : 'rgba(255,255,255,0.08)'}`,
          borderRadius: 10,
          boxShadow: focused ? '0 0 0 3px rgba(23, 107, 135, 0.10)' : 'none',
          transition: 'all 0.2s ease',
        }}
      >
        <Search
          size={iconSize}
          style={{
            color: focused || value ? 'var(--brand)' : 'rgba(255,255,255,0.4)',
            marginLeft: 12,
            flexShrink: 0,
            transition: 'color 0.2s',
          }}
        />
        <input
          ref={inputRef}
          type="search"
          value={value}
          onChange={e => onChange?.(e.target.value)}
          onFocus={() => setFocused(true)}
          onBlur={() => setTimeout(() => setFocused(false), 200)}
          onKeyDown={e => {
            if (e.key === 'Enter') {
              if (value.trim()) {
                onSubmit?.(value);
                addRecentSearch(value);
                          }
              inputRef.current?.blur();
            }
          }}
          placeholder={placeholder}
          aria-label="Search cars"
          style={{
            flex: 1,
            background: 'transparent',
            border: 'none',
            outline: 'none',
            color: '#fff',
            fontSize,
            fontWeight: 500,
            padding: `${padY}px 12px`,
            fontFamily: 'var(--font-body)',
            minWidth: 0,
          }}
        />
        {value && (
          <button
            type="button"
            onClick={() => { onChange?.(''); inputRef.current?.focus(); }}
            aria-label="Clear search"
            style={{
              background: 'rgba(255,255,255,0.06)',
              border: 'none',
              borderRadius: '50%',
              width: 22, height: 22,
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              cursor: 'pointer',
              color: 'rgba(255,255,255,0.6)',
              marginRight: 8,
              flexShrink: 0,
            }}
          >
            <X size={12} />
          </button>
        )}
      </div>

      {(showSuggestions || showRecent) && (
        <div
          role="listbox"
          style={{
            position: 'absolute',
            top: 'calc(100% + 6px)',
            left: 0, right: 0,
            background: '#0a3340',
            border: '1px solid rgba(255,255,255,0.08)',
            borderRadius: 10,
            overflow: 'hidden',
            zIndex: 50,
            boxShadow: '0 8px 32px rgba(10, 51, 64, 0.5)',
            maxHeight: 320, overflowY: 'auto',
          }}
        >
          {showRecent && (
            <>
              <div style={{
                display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                padding: '8px 14px 4px',
              }}>
                <span style={{ fontSize: 10, color: 'rgba(255,255,255,0.35)', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.1em' }}>
                  Recent Searches
                </span>
                <button onClick={clearRecent} style={{
                  background: 'none', border: 'none', color: 'rgba(255,255,255,0.25)',
                  fontSize: 9, cursor: 'pointer', padding: 0,
                }}>
                  Clear
                </button>
              </div>
              {recentSearches.slice(0, MAX_RECENT).map(q => (
                <button
                  key={q}
                  type="button"
                  onMouseDown={() => handleSelect(q)}
                  style={{
                    display: 'flex', alignItems: 'center', gap: 10,
                    width: '100%', padding: '9px 14px',
                    background: 'transparent', border: 'none',
                    color: 'rgba(255,255,255,0.75)',
                    fontSize: 12.5, fontFamily: 'var(--font-body)',
                    cursor: 'pointer', textAlign: 'left',
                    transition: 'background 0.15s',
                  }}
                  onMouseEnter={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.04)'; }}
                  onMouseLeave={e => { e.currentTarget.style.background = 'transparent'; }}
                >
                  <Clock size={12} style={{ color: 'rgba(255,255,255,0.3)', flexShrink: 0 }} />
                  <span>{q}</span>
                </button>
              ))}
              <div style={{ height: 1, background: 'rgba(255,255,255,0.04)', margin: '4px 14px' }} />
            </>
          )}

          {showSuggestions && matched.slice(0, 8).map(brand => (
            <button
              key={brand}
              type="button"
              onMouseDown={() => handleSelect(brand)}
              style={{
                display: 'flex', alignItems: 'center', gap: 10,
                width: '100%', padding: '9px 14px',
                background: 'transparent', border: 'none',
                color: 'rgba(255,255,255,0.85)',
                fontSize: 12.5, fontFamily: 'var(--font-body)',
                cursor: 'pointer', textAlign: 'left',
                transition: 'background 0.15s',
              }}
              onMouseEnter={e => { e.currentTarget.style.background = 'rgba(255,255,255,0.04)'; }}
              onMouseLeave={e => { e.currentTarget.style.background = 'transparent'; }}
            >
              <Search size={12} style={{ color: 'var(--brand)', flexShrink: 0 }} />
              <span>{brand}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect } from 'react';

const BASE = import.meta.env.VITE_PUBLIC_URL || 'https://www.kayad.space';

function inject(json: any): () => void {
  const el = document.createElement('script');
  el.type = 'application/ld+json';
  el.textContent = JSON.stringify(json);
  document.head.appendChild(el);
  return () => el.remove();
}

interface VehicleStructuredDataProps {
  car: any;
}

export function VehicleStructuredData({ car }: VehicleStructuredDataProps) {
  useEffect(() => {
    if (!car?._id) return;
    const price = car.currentBid || car.price || 0;
    const img = car.images?.[0]?.url || car.images?.[0] || '';
    return inject({
      '@context': 'https://schema.org',
      '@type': 'Vehicle',
      '@id': `${BASE}/cars/${car._id}`,
      url: `${BASE}/cars/${car._id}`,
      name: car.title,
      description: car.description || `${car.year} ${car.brand} ${car.model} for sale in ${car.location?.city || 'Kenya'}`,
      image: img,
      brand: { '@type': 'Brand', name: car.brand },
      model: car.model,
      vehicleIdentificationNumber: car.vin,
      vehicleTransmission: car.transmission,
      fuelType: car.fuel,
      vehicleEngine: car.engine ? { '@type': 'EngineSpecification', name: car.engine } : undefined,
      mileageFromOdometer: car.mileage ? { '@type': 'QuantitativeValue', value: car.mileage, unitCode: 'KMT' } : undefined,
      bodyType: car.bodyType,
      color: car.color,
      vehicleConfiguration: car.drivetrain,
      productionDate: car.year ? `${car.year}` : undefined,
      condition: car.condition === 'new' ? 'https://schema.org/NewCondition' : car.condition === 'used' ? 'https://schema.org/UsedCondition' : undefined,
      offers: {
        '@type': 'Offer',
        price: price,
        priceCurrency: 'KES',
        availability: car.status === 'sold' ? 'https://schema.org/SoldOut' : 'https://schema.org/InStock',
        url: `${BASE}/cars/${car._id}`,
        seller: car.dealer ? {
          '@type': car.dealer.role === 'dealer' ? 'AutoDealer' : 'Person',
          name: car.dealer.businessName || car.dealer.name || 'Seller',
          telephone: car.dealer.phone,
          email: car.dealer.email,
        } : undefined,
      },
      ...(car.auctionStatus === 'live' ? {
        additionalProperty: {
          '@type': 'PropertyValue',
          name: 'Auction',
          value: 'Live',
        },
      } : {}),
    });
  }, [car]);
  return null;
}

export function WebSiteStructuredData() {
  useEffect(() => inject({
    '@context': 'https://schema.org',
    '@type': 'WebSite',
    url: BASE,
    name: 'Kayad',
    description: "Kenya's Premium Car Marketplace",
    potentialAction: {
      '@type': 'SearchAction',
      target: {
        '@type': 'EntryPoint',
        urlTemplate: `${BASE}/showroom?brand={search_term_string}`,
      },
      'query-input': 'required name=search_term_string',
    },
  }), []);
  return null;
}

interface ItemListStructuredDataProps {
  items: any[];
}

export function ItemListStructuredData({ items }: ItemListStructuredDataProps) {
  useEffect(() => {
    if (!items?.length) return;
    return inject({
      '@context': 'https://schema.org',
      '@type': 'ItemList',
      itemListElement: items.slice(0, 20).map((item, i) => ({
        '@type': 'ListItem',
        position: i + 1,
        url: `${BASE}/cars/${item._id}`,
        name: item.title || `${item.brand} ${item.model}`,
      })),
    });
  }, [items]);
  return null;
}

interface BreadcrumbStructuredDataProps {
  items: Array<{ name: string; url: string }>;
}

export function BreadcrumbStructuredData({ items }: BreadcrumbStructuredDataProps) {
  useEffect(() => {
    if (!items?.length) return;
    return inject({
      '@context': 'https://schema.org',
      '@type': 'BreadcrumbList',
      itemListElement: items.map((item, i) => ({
        '@type': 'ListItem',
        position: i + 1,
        name: item.name,
        item: item.url.startsWith('http') ? item.url : `${BASE}${item.url}`,
      })),
    });
  }, [items]);
  return null;
}

import { useState, useMemo } from 'react';
import { Calculator, ChevronDown, ChevronUp, Info } from 'lucide-react';
import { formatKES } from '../../../utils/helpers';

interface TcoCalculatorProps {
  vehicle?: {
    price?: number;
    engine?: string;
    dutyStatus?: string;
  };
}

export default function TcoCalculator({ vehicle }: TcoCalculatorProps) {
  const [open, setOpen] = useState(false);

  const defaultCc = vehicle?.engine
    ? parseInt(vehicle.engine.replace(/[^0-9]/g, ''), 10) || 1800
    : 1800;

  const [cc, setCc] = useState(defaultCc);
  const [downPct, setDownPct] = useState(20);
  const [loanYears, setLoanYears] = useState(3);
  const [estimateRate, setEstimateRate] = useState(0);

  const isUsed = vehicle?.dutyStatus === 'already_in_kenya' || !vehicle?.dutyStatus;
  const price = vehicle?.price || 5000000;

  const tco = useMemo(() => {
    // Import duties (if not already in Kenya)
    let importDuty = 0;
    if (!isUsed) {
      const customs = price * 0.25;
      const excise = price * 0.20;
      const vat = (price + customs + excise) * 0.16;
      const idf = price * 0.02;
      const rdl = price * 0.015;
      const portFees = 95000;
      importDuty = customs + excise + vat + idf + rdl + portFees;
    }

    // Insurance (4% of vehicle value annually)
    const annualInsurance = price * 0.04;

    // Financing
    const loanAmt = price * (1 - downPct / 100);
    const monthlyRate = (estimateRate / 100) / 12;
    const nMonths = loanYears * 12;
    const monthlyPmt = monthlyRate === 0
      ? loanAmt / nMonths
      : (loanAmt * monthlyRate * Math.pow(1 + monthlyRate, nMonths)) / (Math.pow(1 + monthlyRate, nMonths) - 1);
    const totalFinanced = monthlyPmt * nMonths;
    const totalInterest = totalFinanced - loanAmt;

    return { importDuty, annualInsurance, monthlyPmt, totalFinanced, totalInterest, loanAmt };
  }, [price, downPct, loanYears, estimateRate, isUsed]);

  return (
    <div className="bg-[#0A3340] border border-white/10 rounded-xl overflow-hidden mt-4">
      <button
        onClick={() => setOpen(!open)}
        className="w-full flex items-center justify-between px-4 py-3.5 bg-transparent border-none text-white font-sans text-sm font-bold cursor-pointer"
      >
        <span className="flex items-center gap-2">
          <Calculator size={14} className="text-[#13B8A6]" />
          Total Cost of Ownership
        </span>
        {open ? (
          <ChevronUp size={14} className="text-white/40" />
        ) : (
          <ChevronDown size={14} className="text-white/40" />
        )}
      </button>

      {open && (
        <div className="px-4 pb-4 space-y-4">
          {/* Price */}
          <div className="p-4 bg-white/5 rounded-xl">
            <div className="flex items-center justify-between">
              <span className="text-white/50 font-sans text-xs">Vehicle Price</span>
              <span className="text-white font-sans font-bold">{formatKES(price)}</span>
            </div>
            {tco.importDuty > 0 && (
              <div className="flex items-center justify-between mt-2">
                <span className="text-white/50 font-sans text-xs">Import Duty (est.)</span>
                <span className="text-white font-sans text-sm">+ {formatKES(tco.importDuty)}</span>
              </div>
            )}
            <div className="flex items-center justify-between mt-2 pt-2 border-t border-white/5">
              <span className="text-[#13B8A6] font-sans text-xs font-semibold">Total with Import</span>
              <span className="text-[#13B8A6] font-sans font-bold">{formatKES(price + tco.importDuty)}</span>
            </div>
          </div>

          {/* Financing */}
          <div className="space-y-3">
            <p className="text-white font-sans text-xs font-bold">Financing</p>

            <label className="block space-y-2">
              <span className="text-white/60 font-sans text-xs">Illustrative annual rate (optional)</span>
              <input
                type="number"
                min="0"
                max="100"
                step="0.1"
                value={estimateRate}
                onChange={(e) => setEstimateRate(Number(e.target.value) || 0)}
                className="w-full rounded-lg bg-white/5 border border-white/10 px-3 py-2 text-sm text-white outline-none"
              />
              <span className="text-white/40 font-sans text-[10px]">This is a calculator assumption, not a lender offer or quoted bank rate.</span>
            </label>

            {/* Down payment */}
            <div>
              <div className="flex items-center justify-between mb-1">
                <span className="text-white/50 font-sans text-xs">Down Payment</span>
                <span className="text-white font-sans text-xs">{downPct}%</span>
              </div>
              <input
                type="range"
                min={0}
                max={50}
                step={5}
                value={downPct}
                onChange={(e) => setDownPct(parseInt(e.target.value))}
                className="w-full accent-[#13B8A6]"
              />
            </div>

            {/* Loan years */}
            <div className="flex gap-2">
              {[2, 3, 4, 5].map(year => (
                <button
                  key={year}
                  onClick={() => setLoanYears(year)}
                  className={`flex-1 py-2 rounded-lg text-xs font-semibold transition-colors ${
                    loanYears === year
                      ? 'bg-[#13B8A6] text-[#0A3340]'
                      : 'bg-white/5 text-white/60 hover:bg-white/10'
                  }`}
                >
                  {year} yr
                </button>
              ))}
            </div>

            {/* Results */}
            <div className="p-4 bg-white/5 rounded-xl space-y-2">
              <div className="flex items-center justify-between">
                <span className="text-white/50 font-sans text-xs">Loan Amount</span>
                <span className="text-white font-sans text-xs">{formatKES(tco.loanAmt)}</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-white/50 font-sans text-xs">Total Interest</span>
                <span className="text-white font-sans text-xs">{formatKES(tco.totalInterest)}</span>
              </div>
              <div className="h-px bg-white/10 my-2" />
              <div className="flex items-center justify-between">
                <span className="text-white/50 font-sans text-xs">Monthly Payment</span>
                <span className="text-[#13B8A6] font-sans font-bold">{formatKES(tco.monthlyPmt)}/mo</span>
              </div>
            </div>
          </div>

          {/* Running costs */}
          <div className="space-y-2">
            <p className="text-white font-sans text-xs font-bold">Annual Running Costs</p>
            <div className="p-4 bg-white/5 rounded-xl">
              <div className="flex items-center justify-between">
                <span className="text-white/50 font-sans text-xs flex items-center gap-1">
                  Insurance <Info size={10} className="text-white/30" />
                </span>
                <span className="text-white font-sans text-xs">{formatKES(tco.annualInsurance)}/yr</span>
              </div>
            </div>
          </div>

          <p className="text-white/20 font-sans text-[10px] text-center">
            Estimates only. Actual rates may vary. Subject to approval.
          </p>
        </div>
      )}
    </div>
  );
}

import { useState, type FC } from 'react';
import { useTheme } from '../../../context/ThemeContext';
import { preferencesAPI } from '../../../api/api.exports';

interface ThemeSettingsProps {
  className?: string;
}

export const ThemeSettings: FC<ThemeSettingsProps> = ({ className = '' }) => {
  const { theme, setTheme } = useTheme();
  const [saving, setSaving] = useState(false);

  const themes = [
    { value: 'light', label: 'Light', icon: '☀️' },
    { value: 'dark', label: 'Dark', icon: '🌙' },
    { value: 'system', label: 'System', icon: '💻' },
  ] as const;

  const handleThemeChange = async (newTheme: 'light' | 'dark' | 'system') => {
    setSaving(true);
    try {
      await setTheme(newTheme);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className={`bg-white dark:bg-[#12576D] rounded-xl p-4 shadow-sm ${className}`}>
      <h3 className="text-lg font-semibold text-[#0A3340] dark:text-[#64748B] mb-4">
        Appearance
      </h3>

      <div className="grid grid-cols-3 gap-3">
        {themes.map(({ value, label, icon }) => (
          <button
            key={value}
            onClick={() => handleThemeChange(value)}
            disabled={saving}
            className={`
              flex flex-col items-center gap-2 p-4 rounded-xl border-2 transition-all
              ${
                theme === value
                  ? 'border-brand-500 bg-brand-50 dark:bg-brand-900/20'
                  : 'border-[#D7E7E4] dark:border-[#12576D] hover:border-brand-300'
              }
              ${saving ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer'}
            `}
          >
            <span className="text-2xl">{icon}</span>
            <span
              className={`text-sm font-medium ${
                theme === value
                  ? 'text-brand-600 dark:text-brand-400'
                  : 'text-[#176B87] dark:text-[#64748B]'
              }`}
            >
              {label}
            </span>
          </button>
        ))}
      </div>

      <p className="mt-4 text-sm text-[#64748B] dark:text-[#5AAFA4]">
        {theme === 'system'
          ? 'Theme follows your system settings'
          : theme === 'dark'
          ? 'Dark mode is active'
          : 'Light mode is active'}
      </p>
    </div>
  );
};

export default ThemeSettings;

