// High-performance virtualized list for rendering 100k+ items
// Uses windowing technique to only render visible items + buffer

import { useState, useEffect, useRef, useCallback, useMemo, memo, type CSSProperties, type ReactNode, type ComponentType, type UIEvent } from 'react';
import useIntersectionObserver from '../../../hooks/useIntersectionObserver';

interface VirtualListProps<T> {
  items: T[];
  renderItem: (item: T, index: number) => ReactNode;
  estimatedItemHeight?: number;
  overscan?: number;
  className?: string;
  style?: CSSProperties;
  onEndReached?: () => void;
  onEndReachedThreshold?: number;
  ListFooter?: ComponentType;
  ListEmpty?: ComponentType;
  keyExtractor?: (item: T, index: number) => string;
  horizontal?: boolean;
}

interface VirtualListState {
  scrollTop: number;
  containerHeight: number;
  visibleRange: { start: number; end: number };
}

export default function VirtualList<T>({
  items,
  renderItem,
  estimatedItemHeight = 300,
  overscan = 3,
  className,
  style,
  onEndReached,
  onEndReachedThreshold = 0.9,
  ListFooter,
  ListEmpty,
  keyExtractor = (item, index) => String(index),
  horizontal = false,
}: VirtualListProps<T>) {
  const containerRef = useRef<HTMLDivElement>(null);
  const [state, setState] = useState<VirtualListState>({
    scrollTop: 0,
    containerHeight: horizontal ? 0 : 400,
    visibleRange: { start: 0, end: 10 },
  });

  // Store item heights in a ref to handle dynamic heights
  const itemHeightsRef = useRef<Map<number, number>>(new Map());
  const measuredItemsRef = useRef<Set<number>>(new Set());

  // Calculate total height based on item heights
  const totalHeight = useMemo(() => {
    if (horizontal) return estimatedItemHeight;

    let total = 0;
    for (let i = 0; i < items.length; i++) {
      total += itemHeightsRef.current.get(i) || estimatedItemHeight;
    }
    return total || estimatedItemHeight * items.length;
  }, [items.length, estimatedItemHeight, horizontal]);

  // Calculate visible range
  const calculateVisibleRange = useCallback(() => {
    if (!containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const containerHeight = horizontal ? rect.width : rect.height;
    const scrollOffset = horizontal
      ? containerRef.current.scrollLeft
      : state.scrollTop;

    if (items.length === 0 || containerHeight === 0) {
      setState(prev => ({
        ...prev,
        containerHeight,
        visibleRange: { start: 0, end: 0 },
      }));
      return;
    }

    let startIndex = 0;
    let accumulatedHeight = 0;

    // Find start index
    for (let i = 0; i < items.length; i++) {
      const height = itemHeightsRef.current.get(i) || estimatedItemHeight;
      if (accumulatedHeight + height > scrollOffset) {
        startIndex = i;
        break;
      }
      accumulatedHeight += height;
      if (i === items.length - 1) startIndex = i;
    }

    // Find end index
    let endIndex = startIndex;
    accumulatedHeight = 0;
    for (let i = 0; i <= startIndex; i++) {
      accumulatedHeight += itemHeightsRef.current.get(i) || estimatedItemHeight;
    }

    const viewportBottom = scrollOffset + containerHeight;
    for (let i = startIndex; i < items.length; i++) {
      const height = itemHeightsRef.current.get(i) || estimatedItemHeight;
      accumulatedHeight += height;
      endIndex = i;
      if (accumulatedHeight >= viewportBottom) break;
    }

    // Apply overscan
    startIndex = Math.max(0, startIndex - overscan);
    endIndex = Math.min(items.length - 1, endIndex + overscan);

    setState(prev => ({
      ...prev,
      containerHeight,
      visibleRange: { start: startIndex, end: endIndex },
    }));
  }, [items.length, estimatedItemHeight, overscan, state.scrollTop, horizontal]);

  // Handle scroll
  const handleScroll = useCallback((e: UIEvent<HTMLDivElement>) => {
    const target = e.currentTarget;
    const scrollTop = horizontal ? target.scrollLeft : target.scrollTop;

    setState(prev => ({ ...prev, scrollTop }));
  }, [horizontal]);

  // Measure item after render
  const measureItemRef = useCallback((index: number, element: HTMLElement | null) => {
    if (!element) return;

    const height = horizontal ? element.offsetWidth : element.offsetHeight;

    if (itemHeightsRef.current.get(index) !== height) {
      itemHeightsRef.current.set(index, height);
      measuredItemsRef.current.add(index);
      calculateVisibleRange();
    }
  }, [calculateVisibleRange, horizontal]);

  // Re-calculate when items change
  useEffect(() => {
    calculateVisibleRange();
  }, [calculateVisibleRange, items.length]);

  // Handle resize
  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const resizeObserver = new ResizeObserver(() => {
      calculateVisibleRange();
    });

    resizeObserver.observe(container);
    return () => resizeObserver.disconnect();
  }, [calculateVisibleRange]);

  // Infinite scroll trigger
  useEffect(() => {
    if (!onEndReached) return;

    const container = containerRef.current;
    if (!container) return;

    const handleInfiniteScroll = () => {
      const scrollHeight = horizontal ? container.scrollWidth : container.scrollHeight;
      const scrollPosition = horizontal ? container.scrollLeft + container.clientWidth : container.scrollTop + container.clientHeight;
      const threshold = scrollHeight * onEndReachedThreshold;

      if (scrollPosition >= threshold) {
        onEndReached();
      }
    };

    container.addEventListener('scroll', handleInfiniteScroll, { passive: true });
    return () => container.removeEventListener('scroll', handleInfiniteScroll);
  }, [onEndReached, onEndReachedThreshold, horizontal]);

  // Get item offset
  const getItemOffset = useCallback((index: number) => {
    let offset = 0;
    for (let i = 0; i < index; i++) {
      offset += itemHeightsRef.current.get(i) || estimatedItemHeight;
    }
    return offset;
  }, [estimatedItemHeight]);

  // Empty state
  if (items.length === 0) {
    return ListEmpty ? <ListEmpty /> : null;
  }

  const { visibleRange } = state;
  const visibleItems: { item: T; index: number; offset: number }[] = [];

  for (let i = visibleRange.start; i <= visibleRange.end; i++) {
    if (items[i] !== undefined) {
      visibleItems.push({
        item: items[i],
        index: i,
        offset: getItemOffset(i),
      });
    }
  }

  const containerStyle: CSSProperties = {
    ...style,
    overflow: horizontal ? 'auto hidden' : 'hidden auto',
    position: 'relative',
  };

  const contentStyle: CSSProperties = horizontal
    ? {
        display: 'flex',
        flexDirection: 'row',
        width: totalHeight,
        height: '100%',
      }
    : {
        height: totalHeight,
        width: '100%',
        position: 'relative',
      };

  return (
    <div
      ref={containerRef}
      className={className}
      style={containerStyle}
      onScroll={handleScroll}
    >
      <div style={contentStyle}>
        {visibleItems.map(({ item, index, offset }) => (
          <div
            key={keyExtractor(item, index)}
            ref={(el) => measureItemRef(index, el)}
            style={{
              position: 'absolute',
              ...(horizontal
                ? { height: '100%', left: offset }
                : { width: '100%', top: offset }),
            }}
          >
            {renderItem(item, index)}
          </div>
        ))}
      </div>
      {ListFooter && <ListFooter />}
    </div>
  );
}

// Simplified version for simple row-based lists
interface SimpleVirtualListProps<T> {
  items: T[];
  renderRow: (item: T, index: number) => ReactNode;
  rowHeight: number;
  className?: string;
  style?: CSSProperties;
  onLoadMore?: () => void;
  hasMore?: boolean;
  loadingComponent?: ReactNode;
}

export function SimpleVirtualList<T>({
  items,
  renderRow,
  rowHeight,
  className,
  style,
  onLoadMore,
  hasMore = false,
  loadingComponent,
}: SimpleVirtualListProps<T>) {
  const [visibleCount, setVisibleCount] = useState(20);
  const sentinelRef = useRef<HTMLDivElement>(null);
  const [, sentinelEntry] = useIntersectionObserver({ threshold: 0.1 });

  // Show more items when sentinel is visible
  useEffect(() => {
    if (sentinelEntry?.isIntersecting && hasMore) {
      setVisibleCount(prev => prev + 20);
      onLoadMore?.();
    }
  }, [sentinelEntry, hasMore, onLoadMore]);

  const visibleItems = useMemo(() => items.slice(0, visibleCount), [items, visibleCount]);

  return (
    <div className={className} style={{ ...style, overflow: 'auto' }}>
      {visibleItems.map((item, index) => (
        <div key={index} style={{ height: rowHeight, flexShrink: 0 }}>
          {renderRow(item, index)}
        </div>
      ))}
      <div ref={sentinelRef} style={{ height: 1 }} />
      {loadingComponent && hasMore && (
        <div style={{ padding: 16, textAlign: 'center' }}>
          {loadingComponent}
        </div>
      )}
    </div>
  );
}

import { useState, useMemo, memo } from 'react';
import { Link, useLocation } from 'react-router-dom';
import {
  LayoutDashboard, Car, Users, MessageSquare, BarChart3,
  Settings, Bell, Plus, TrendingUp, ChevronDown, Menu, X,
  Package, ShoppingCart, DollarSign, Eye, Heart, Star, TrendingDown
} from 'lucide-react';
import { Vehicle } from '../../../types/index';

// Navigation items
const NAV_ITEMS = [
  { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard, to: '/dealer' },
  { id: 'inventory', label: 'Inventory', icon: Car, to: '/dealer/inventory' },
  { id: 'leads', label: 'Leads', icon: Users, to: '/dealer/leads', badge: 12 },
  { id: 'messages', label: 'Messages', icon: MessageSquare, to: '/chat', badge: 5 },
  { id: 'analytics', label: 'Analytics', icon: BarChart3, to: '/dealer/analytics' },
];

// Metric card component
interface DealerMetricProps {
  icon: React.ReactNode;
  label: string;
  value: string | number;
  trend?: number;
  trendLabel?: string;
  accent?: 'gold' | 'views' | 'leads' | 'sales' | 'revenue' | 'inventory' | 'rating';
  className?: string;
}

export const DealerMetric = memo(function DealerMetric({
  icon,
  label,
  value,
  trend,
  trendLabel,
  accent = 'gold',
  className = ''
}: DealerMetricProps) {
  const iconColors = {
    gold: { bg: 'rgba(19, 184, 166, 0.12)', color: '#176B87' },
    views: { bg: 'rgba(23, 107, 135, 0.15)', color: '#5AAFA4' },
    leads: { bg: 'rgba(168, 85, 247, 0.15)', color: '#91cec5' },
    sales: { bg: 'rgba(34, 197, 94, 0.15)', color: '#22C55E' },
    revenue: { bg: 'rgba(19, 184, 166, 0.12)', color: '#176B87' },
    inventory: { bg: 'rgba(251, 146, 60, 0.15)', color: '#13b8a6' },
    rating: { bg: 'rgba(19, 184, 166, 0.15)', color: '#13B8A6' },
  };

  const colorScheme = iconColors[accent] || iconColors.gold;

  return (
    <div className={`dealer-metric ${className}`}>
      <div className="dealer-metric__header">
        <div className="dealer-metric__icon" style={{ background: colorScheme.bg }}>
          <span style={{ fontSize: 20 }}>{icon}</span>
        </div>
        {trend !== undefined && (
          <div className={`dealer-metric__trend dealer-metric__trend--${trend >= 0 ? 'up' : 'down'}`}>
            {trend >= 0 ? <TrendingUp size={12} /> : <TrendingDown size={12} />}
            {Math.abs(trend)}%
          </div>
        )}
      </div>
      <div className="dealer-metric__value">{value}</div>
      <div className="dealer-metric__label">{label}</div>
      {trendLabel && (
        <div style={{ fontSize: 'var(--dealer-text-xs)', color: 'var(--dealer-text-dim)', marginTop: 4 }}>
          {trendLabel}
        </div>
      )}
    </div>
  );
});

// Quick action button
interface DealerActionProps {
  icon: React.ReactNode;
  label: string;
  description?: string;
  to?: string;
  onClick?: () => void;
  variant?: 'default' | 'gold';
  className?: string;
}

export const DealerAction = memo(function DealerAction({
  icon,
  label,
  description,
  to,
  onClick,
  variant = 'default',
  className = ''
}: DealerActionProps) {
  const content = (
    <>
      <div className="dealer-action__icon" style={variant === 'gold' ? {} : { background: 'var(--dealer-elevated)' }}>
        {icon}
      </div>
      <div className="dealer-action__label">{label}</div>
      {description && <div className="dealer-action__desc">{description}</div>}
    </>
  );

  if (to) {
    return (
      <Link to={to} className={`dealer-action ${className}`}>
        {content}
      </Link>
    );
  }

  return (
    <button className={`dealer-action ${className}`} onClick={onClick} type="button">
      {content}
    </button>
  );
});

// Lead funnel component
interface DealerFunnelStage {
  type: 'new' | 'contacted' | 'interested' | 'negotiating' | 'closed';
  label: string;
  count: number;
}

interface DealerFunnelProps {
  stages: DealerFunnelStage[];
}

export const DealerFunnel = memo(function DealerFunnel({ stages }: DealerFunnelProps) {
  return (
    <div className="dealer-funnel">
      {stages.map((stage, i) => (
        <div key={i} className={`dealer-funnel-stage dealer-funnel-stage--${stage.type}`}>
          <div className="dealer-funnel-stage__count">{stage.count}</div>
          <div className="dealer-funnel-stage__label">{stage.label}</div>
        </div>
      ))}
    </div>
  );
});

// Leads table
interface Lead {
  id: string;
  name: string;
  phone?: string;
  email?: string;
  vehicle: string;
  status: 'new' | 'contacted' | 'negotiating' | 'closed-won' | 'closed-lost';
  value: number;
  createdAt: string;
}

interface DealerLeadsTableProps {
  leads: Lead[];
  onView?: (id: string) => void;
  onContact?: (id: string) => void;
  onConvert?: (id: string) => void;
  className?: string;
}

export const DealerLeadsTable = memo(function DealerLeadsTable({
  leads,
  onView,
  onContact,
  onConvert,
  className = ''
}: DealerLeadsTableProps) {
  const statusColors = {
    new: 'dealer-leads__status--new',
    contacted: 'dealer-leads__status--contacted',
    negotiating: 'dealer-leads__status--negotiating',
    'closed-won': 'dealer-leads__status--closed-won',
    'closed-lost': 'dealer-leads__status--closed-lost',
  };

  return (
    <div className={`dealer-leads ${className}`}>
      <div className="dealer-leads__header">
        <div className="dealer-leads__title">
          Recent Leads
          <span className="dealer-leads__count">{leads.length}</span>
        </div>
        <div className="dealer-leads__filters">
          <button className="dealer-leads__filter dealer-leads__filter--active">All</button>
          <button className="dealer-leads__filter">New</button>
          <button className="dealer-leads__filter">Hot</button>
        </div>
      </div>
      <table className="dealer-leads__table">
        <thead>
          <tr>
            <th>Customer</th>
            <th>Vehicle</th>
            <th>Status</th>
            <th>Value</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {leads.map((lead) => (
            <tr key={lead.id} className="dealer-leads__row">
              <td className="dealer-leads__cell">
                <div className="dealer-leads__cell--customer">
                  <div className="dealer-leads__avatar">
                    {lead.name.split(' ').map(n => n[0]).join('').slice(0, 2)}
                  </div>
                  <div>
                    <div className="dealer-leads__name">{lead.name}</div>
                    <div className="dealer-leads__vehicle">{lead.phone}</div>
                  </div>
                </div>
              </td>
              <td className="dealer-leads__cell">{lead.vehicle}</td>
              <td className="dealer-leads__cell">
                <span className={`dealer-leads__status ${statusColors[lead.status] || ''}`}>
                  {lead.status.replace('-', ' ')}
                </span>
              </td>
              <td className="dealer-leads__cell" style={{ fontWeight: 700, color: 'var(--dealer-gold)' }}>
                {lead.value}
              </td>
              <td className="dealer-leads__cell">
                <div className="dealer-leads__actions">
                  <button className="dealer-leads__action" onClick={() => onView?.(lead.id)} title="View">
                    <Eye size={14} />
                  </button>
                  <button className="dealer-leads__action" onClick={() => onContact?.(lead.id)} title="Contact">
                    <MessageSquare size={14} />
                  </button>
                  <button className="dealer-leads__action" onClick={() => onConvert?.(lead.id)} title="Convert">
                    <DollarSign size={14} />
                  </button>
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
});

// Inventory card
interface DealerInventoryCardData {
  id: string;
  title: string;
  image?: string;
  price?: number;
  status?: string;
  featured?: boolean;
  views?: number;
  inquiries?: number;
  days?: number;
}

interface DealerInventoryCardProps {
  car: DealerInventoryCardData;
  onEdit?: () => void;
  onPromote?: () => void;
  onDelete?: () => void;
  className?: string;
}

export const DealerInventoryCard = memo(function DealerInventoryCard({
  car,
  onEdit,
  onPromote,
  onDelete,
  className = ''
}: DealerInventoryCardProps) {
  const statusMap = {
    active: 'active',
    pending: 'pending',
    sold: 'sold',
    draft: 'pending',
  };

  return (
    <div className={`dealer-inventory-card ${className}`}>
      <div className="dealer-inventory-card__image">
        <img src={car.image || 'https://images.pexels.com/photos/3593922/pexels-photo-3593922.jpeg?auto=compress&cs=tinysrgb&w=800'} alt={car.title} loading="lazy" decoding="async" />
        <div className="dealer-inventory-card__badges">
          <span className={`dealer-inventory-card__badge dealer-inventory-card__badge--${statusMap[car.status] || 'active'}`}>
            {car.status || 'Active'}
          </span>
          {car.featured && (
            <span className="dealer-inventory-card__badge dealer-inventory-card__badge--featured">
              ⭐ Featured
            </span>
          )}
        </div>
        <div className="dealer-inventory-card__menu">
          <button className="dealer-leads__action" onClick={() => onEdit?.()}>✏️</button>
        </div>
      </div>
      <div className="dealer-inventory-card__body">
        <div className="dealer-inventory-card__title">{car.title}</div>
        <div className="dealer-inventory-card__price">
          KES {car.price?.toLocaleString() || '0'}
        </div>
        <div className="dealer-inventory-card__stats">
          <div className="dealer-inventory-card__stat">
            <span className="dealer-inventory-card__stat-value">{car.views?.toLocaleString() || 0}</span>
            <span className="dealer-inventory-card__stat-label">Views</span>
          </div>
          <div className="dealer-inventory-card__stat">
            <span className="dealer-inventory-card__stat-value">{car.inquiries || 0}</span>
            <span className="dealer-inventory-card__stat-label">Inquiries</span>
          </div>
          <div className="dealer-inventory-card__stat">
            <span className="dealer-inventory-card__stat-value">{car.days || 0}</span>
            <span className="dealer-inventory-card__stat-label">Days</span>
          </div>
        </div>
      </div>
    </div>
  );
});

// Analytics chart placeholder
interface DealerChartProps {
  title: string;
  period?: string;
  children?: React.ReactNode;
  className?: string;
}

export const DealerChart = memo(function DealerChart({
  title,
  period,
  children,
  className = ''
}: DealerChartProps) {
  return (
    <div className={`dealer-chart ${className}`}>
      <div className="dealer-chart__header">
        <h3 className="dealer-chart__title">{title}</h3>
        {period && <span className="dealer-chart__period">{period}</span>}
      </div>
      <div className="dealer-chart__body">
        {children}
      </div>
    </div>
  );
});

// Insights panel
interface Insight {
  type: 'tip' | 'alert' | 'info';
  title: string;
  description: string;
}

interface DealerInsightsProps {
  insights: Insight[];
}

export const DealerInsights = memo(function DealerInsights({ insights }: DealerInsightsProps) {
  return (
    <div className="dealer-insights">
      <h3 className="dealer-insights__title">AI Insights</h3>
      {insights.map((insight, i) => (
        <div key={i} className="dealer-insight">
          <div className={`dealer-insight__icon dealer-insight__icon--${insight.type}`}>
