export interface InputProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, 'size'> {
  label?: string;
  hint?: string;
  error?: string;
  size?: 'sm' | 'md' | 'lg';
  icon?: React.ReactNode;
  iconPosition?: 'left' | 'right';
  leftIcon?: React.ReactNode;
  fullWidth?: boolean;
}

// Stitch: 48px height for mobile touch, teal focus glow
export const Input = forwardRef<HTMLInputElement, InputProps>(
  (
    {
      label,
      hint,
      error,
      size = 'md',
      icon,
      iconPosition = 'left',
      leftIcon,
      fullWidth = true,
      className = '',
      style,
      id,
      ...props
    },
    ref
  ) => {
    // STAGE 11 ACCESSIBILITY (Phase H): this shared Input had no id/htmlFor
    // association between its <label> and <input>, so a screen reader
    // could not announce the label for any field using this component
    // (found while writing the Stage 11 Phase F bid-form regression test,
    // where getByLabelText failed for exactly this reason). useId()
    // generates a stable id when the caller doesn't already pass one,
    // preserving any explicit id a call site already relies on.
    const generatedId = useId();
    const inputId = id ?? (label ? generatedId : undefined);
    // Stitch: Height based on size (48px mobile)
    const effectiveIcon = icon ?? leftIcon;
    const effectiveIconPosition = icon ? iconPosition : 'left';
    const inputHeights: Record<string, string> = {
      sm: '32px',
      md: '40px',
      lg: '48px', // Stitch: 48px for mobile touch
    };

    const inputPadding: Record<string, string> = {
      sm: 'var(--space-2) var(--space-3)',
      md: 'var(--space-3) var(--space-4)',
      lg: '12px var(--space-4)',
    };

    // Stitch: White background with surface-dim border
    const inputBaseStyle: React.CSSProperties = {
      display: 'block',
      width: fullWidth ? '100%' : 'auto',
      padding: inputPadding[size],
      minHeight: inputHeights[size],
      fontFamily: 'var(--font-sans)',
      fontSize: 'var(--text-base)',
      color: 'var(--on-surface)',
      background: 'var(--surface-container-lowest, #ffffff)',
      border: `1px solid ${error ? 'var(--color-error)' : 'var(--surface-dim)'}`,
      borderRadius: 'var(--radius-md)', // Stitch: 8px
      boxShadow: 'none',
      // Stitch: Teal focus ring
      transition: 'border-color 200ms ease, box-shadow 200ms ease',
      outline: 'none',
      boxSizing: 'border-box',
    };

    const containerStyle: React.CSSProperties = {
      display: 'flex',
      flexDirection: 'column',
      gap: 'var(--space-2)',
      width: fullWidth ? '100%' : 'auto',
    };

    // Stitch: Outfit font for labels
    const labelStyle: React.CSSProperties = {
      fontFamily: 'var(--font-sans)',
      fontSize: 'var(--text-sm)',
      fontWeight: 600,
      color: 'var(--on-surface)',
    };

    const hintStyle: React.CSSProperties = {
      fontSize: 'var(--text-sm)',
      color: 'var(--on-surface-variant)',
    };

    // Stitch: Error with red
    const errorStyle: React.CSSProperties = {
      fontSize: 'var(--text-sm)',
      color: 'var(--color-error)',
      fontWeight: 500,
    };

    const iconWrapperStyle: React.CSSProperties = {
      position: 'relative',
      display: 'flex',
      alignItems: 'center',
    };

    const inputWithIconStyle: React.CSSProperties = {
      ...inputBaseStyle,
      paddingLeft: effectiveIcon && effectiveIconPosition === 'left' ? 'calc(var(--space-4) + 24px)' : undefined,
      paddingRight: effectiveIcon && effectiveIconPosition === 'right' ? 'calc(var(--space-4) + 24px)' : undefined,
    };

    const iconWrapperInternalStyle: React.CSSProperties = {
      position: 'absolute',
      left: effectiveIconPosition === 'left' ? 'var(--space-3)' : undefined,
      right: effectiveIconPosition === 'right' ? 'var(--space-3)' : undefined,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      color: 'var(--on-surface-variant)',
      pointerEvents: 'none',
    };

    // Stitch: Focus state with teal glow
    const handleFocus = (e: React.FocusEvent<HTMLInputElement>) => {
      if (!error) {
        e.target.style.borderColor = 'var(--brand)';
        e.target.style.boxShadow = '0 0 0 3px rgba(19, 184, 166, 0.15)';
      }
    };

    const handleBlur = (e: React.FocusEvent<HTMLInputElement>) => {
      if (!error) {
        e.target.style.borderColor = 'var(--surface-dim)';
        e.target.style.boxShadow = 'none';
      }
    };

    return (
      <div style={containerStyle} className={className}>
        {label && <label htmlFor={inputId} style={labelStyle}>{label}</label>}
        <div style={iconWrapperStyle}>
          {effectiveIcon && <span style={iconWrapperInternalStyle}>{effectiveIcon}</span>}
          <input
            ref={ref}
            id={inputId}
            style={effectiveIcon ? inputWithIconStyle : inputBaseStyle}
            onFocus={handleFocus}
            onBlur={handleBlur}
            {...props}
          />
        </div>
        {hint && !error && <span style={hintStyle}>{hint}</span>}
        {error && <span style={errorStyle}>{error}</span>}
      </div>
    );
  }
);

Input.displayName = 'Input';

export default Input;

import { useEffect, useCallback, useRef } from 'react';
import { X } from 'lucide-react';
import { useFocusTrap } from '../../hooks/useAccessibility';

export interface ModalProps {
  isOpen: boolean;
  onClose: () => void;
  title?: string;
  subtitle?: string;
  description?: string;
  children?: React.ReactNode;
  size?: 'sm' | 'md' | 'lg' | 'xl';
  maxWidth?: string;
  closeOnBackdrop?: boolean;
  closeOnEscape?: boolean;
  showCloseButton?: boolean;
  footer?: React.ReactNode;
  className?: string;
}

export const Modal: React.FC<ModalProps> = ({
  isOpen,
  onClose,
  title,
  description,
  children,
  size = 'md',
  closeOnBackdrop = true,
  closeOnEscape = true,
  showCloseButton = true,
  footer,
  className = '',
}) => {
  const focusTrapRef = useFocusTrap(isOpen);
  const previousFocusRef = useRef<HTMLElement | null>(null);
  const closeButtonRef = useRef<HTMLButtonElement>(null);

  // Handle escape key
  const handleEscape = useCallback(
    (e: KeyboardEvent) => {
      if (closeOnEscape && e.key === 'Escape') {
        onClose();
      }
    },
    [closeOnEscape, onClose]
  );

  useEffect(() => {
    if (isOpen) {
      // Store current focus
      previousFocusRef.current = document.activeElement as HTMLElement;

      document.addEventListener('keydown', handleEscape);
      document.body.style.overflow = 'hidden';

      // Focus the close button after a brief delay
      setTimeout(() => {
        closeButtonRef.current?.focus();
      }, 50);
    }
    return () => {
      document.removeEventListener('keydown', handleEscape);
      document.body.style.overflow = '';
      // Restore focus
      if (previousFocusRef.current) {
        previousFocusRef.current.focus();
      }
    };
  }, [isOpen, handleEscape]);

  if (!isOpen) return null;

  const sizes: Record<string, React.CSSProperties> = {
    sm: { maxWidth: 400 },
    md: { maxWidth: 500 },
    lg: { maxWidth: 700 },
    xl: { maxWidth: 900 },
  };

  const backdropStyle: React.CSSProperties = {
    position: 'fixed',
    inset: 0,
    background: 'rgba(10, 51, 64, 0.7)',
    backdropFilter: 'blur(4px)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    zIndex: 'var(--z-modal-backdrop, 1000)',
    padding: 'var(--space-6)',
    animation: 'fadeIn var(--duration-normal) var(--ease-out)',
  };

  const modalStyle: React.CSSProperties = {
    position: 'relative',
    background: 'var(--color-bg-elevated, #ffffff)',
    borderRadius: 'var(--radius-xl)',
    boxShadow: 'var(--shadow-2xl)',
    width: '100%',
    maxHeight: '85vh',
    overflow: 'hidden',
    display: 'flex',
    flexDirection: 'column',
    zIndex: 'var(--z-modal, 1001)',
    animation: 'scaleIn var(--duration-normal) var(--ease-spring)',
    ...sizes[size],
  };

  const headerStyle: React.CSSProperties = {
    display: 'flex',
    alignItems: 'flex-start',
    justifyContent: 'space-between',
    padding: 'var(--space-6)',
    borderBottom: '1px solid var(--color-border-soft)',
  };

  const titleStyle: React.CSSProperties = {
    fontSize: 'var(--text-h3)',
    fontWeight: 600,
    color: 'var(--color-text-primary, #0A3340)',
    margin: 0,
  };

  const descriptionStyle: React.CSSProperties = {
    fontSize: 'var(--text-body-sm)',
    color: 'var(--color-text-muted, #64748B)',
    margin: 'var(--space-2) 0 0 0',
  };

  const closeButtonStyle: React.CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    width: 32,
    height: 32,
    padding: 0,
    background: 'var(--color-bg-secondary, #f4f8f8)',
    border: '1px solid var(--color-border)',
    borderRadius: 'var(--radius-md)',
    color: 'var(--color-text-muted, #64748B)',
    cursor: 'pointer',
    transition: 'all var(--transition-fast)',
  };

  const contentStyle: React.CSSProperties = {
    padding: 'var(--space-6)',
    overflowY: 'auto',
    flex: 1,
  };

  const footerStyle: React.CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'flex-end',
    gap: 'var(--space-3)',
    padding: 'var(--space-4) var(--space-6)',
    borderTop: '1px solid var(--color-border-soft)',
    background: 'var(--color-bg-secondary, #f4f8f8)',
  };

  return (
    <div
      style={backdropStyle}
      onClick={closeOnBackdrop ? onClose : undefined}
      role="presentation"
    >
      <div
        ref={focusTrapRef}
        role="dialog"
        aria-modal="true"
        aria-labelledby={title ? 'modal-title' : undefined}
        aria-describedby={description ? 'modal-description' : undefined}
        style={modalStyle}
        className={className}
        onClick={(e) => e.stopPropagation()}
      >
        {(title || showCloseButton) && (
          <div style={headerStyle}>
            <div>
              {title && <h2 id="modal-title" style={titleStyle}>{title}</h2>}
              {description && <p id="modal-description" style={descriptionStyle}>{description}</p>}
            </div>
            {showCloseButton && (
              <button
                ref={closeButtonRef}
                style={closeButtonStyle}
                onClick={onClose}
                aria-label="Close modal"
                className="hover:bg-[#EEF7F5] focus:outline-none focus:ring-2 focus:ring-[#5AAFA4]/30"
              >
                <X size={16} />
              </button>
            )}
          </div>
        )}
        <div style={contentStyle}>{children}</div>
        {footer && <div style={footerStyle}>{footer}</div>}
      </div>
    </div>
  );
};

export default Modal;

import { memo } from 'react';

// Design System Table Component
export interface TableColumn<T> {
  key: string;
  header: React.ReactNode;
  width?: string;
  align?: 'left' | 'center' | 'right';
  render?: (row: T, index: number) => React.ReactNode;
  sortable?: boolean;
}

interface TableProps<T> {
  columns: TableColumn<T>[];
  data: T[];
  keyField?: keyof T;
  loading?: boolean;
  empty?: React.ReactNode;
  striped?: boolean;
  hoverable?: boolean;
  compact?: boolean;
  className?: string;
  onRowClick?: (row: T, index: number) => void;
}

function TableComponent<T extends Record<string, any>>({
  columns,
  data,
  keyField = 'id' as keyof T,
  loading = false,
  empty,
  striped = false,
  hoverable = true,
  compact = false,
  className = '',
  onRowClick,
}: TableProps<T>) {
  const getValue = (row: T, key: string): any => {
    if (key.includes('.')) {
      return key.split('.').reduce((obj, k) => obj?.[k], row);
    }
    return row[key];
  };

  if (loading) {
    return (
      <div className={`overflow-hidden rounded-xl border border-[var(--border)] ${className}`}>
        <table className="w-full">
          <thead>
            <tr className="bg-[var(--surface)] border-b border-[var(--border)]">
              {columns.map((col) => (
                <th
                  key={col.key}
                  className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[var(--text-muted)]"
                >
                  {typeof col.header === 'string' ? col.header : '...'}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {Array.from({ length: 5 }).map((_, i) => (
              <tr key={i} className="border-b border-[var(--border)] last:border-0">
                {columns.map((col) => (
                  <td key={col.key} className="px-4 py-4">
                    <div className="h-4 bg-[var(--surface)] rounded animate-pulse" style={{ width: '80%' }} />
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  }

  if (data.length === 0) {
    return (
      <div className={`overflow-hidden rounded-xl border border-[var(--border)] ${className}`}>
        <table className="w-full">
          <thead>
            <tr className="bg-[var(--surface)] border-b border-[var(--border)]">
              {columns.map((col) => (
                <th
                  key={col.key}
                  className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[var(--text-muted)]"
                >
                  {col.header}
                </th>
              ))}
            </tr>
          </thead>
        </table>
        <div className="p-8 text-center text-[var(--text-muted)]">
          {empty || 'No data available'}
        </div>
      </div>
    );
  }

  return (
    <div className={`overflow-x-auto rounded-xl border border-[var(--border)] ${className}`}>
      <table className="w-full">
        <thead>
          <tr className="bg-[var(--surface)] border-b border-[var(--border)]">
            {columns.map((col) => (
              <th
                key={col.key}
                className={`
                  px-4 py-3 text-left text-xs font-semibold uppercase tracking-wider text-[var(--text-muted)]
                  ${col.align === 'center' ? 'text-center' : ''}
                  ${col.align === 'right' ? 'text-right' : ''}
                  ${col.sortable ? 'cursor-pointer hover:text-[var(--text-primary)]' : ''}
                `}
                style={{ width: col.width }}
              >
                {col.header}
              </th>
            ))}
          </tr>
        </thead>
        <tbody className="bg-white">
          {data.map((row, rowIndex) => {
            const key = String(getValue(row, String(keyField)) ?? rowIndex);
            return (
              <tr
                key={key}
                className={`
                  border-b border-[var(--border)] last:border-0
                  ${striped && rowIndex % 2 === 1 ? 'bg-[var(--surface)]/50' : ''}
                  ${hoverable ? 'hover:bg-[var(--surface)]/50' : ''}
                  ${onRowClick ? 'cursor-pointer' : ''}
                  transition-colors duration-150
                `}
                onClick={() => onRowClick?.(row, rowIndex)}
              >
                {columns.map((col) => {
                  const value = getValue(row, col.key);
                  return (
                    <td
                      key={col.key}
                      className={`
                        px-4 py-3 text-sm text-[var(--text-secondary)]
                        ${compact ? 'py-2' : 'py-4'}
                        ${col.align === 'center' ? 'text-center' : ''}
                        ${col.align === 'right' ? 'text-right' : ''}
                      `}
                    >
                      {col.render ? col.render(row, rowIndex) : value}
                    </td>
                  );
                })}
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

export const Table = memo(TableComponent) as typeof TableComponent;

