import { createContext, useContext, useEffect, useRef, useState, useCallback, ReactNode } from 'react';
import { useAuth } from './AuthContext';
import { request } from '../api/httpRequest';

type SocketHandler = (data: any) => void;
interface SocketClient { connected:boolean; on:(event:string,handler:SocketHandler)=>()=>void; off:(event:string,handler:SocketHandler)=>void; emit:(event:string,...args:any[])=>SocketClient|undefined; disconnect:()=>SocketClient|undefined; connect:()=>SocketClient|undefined; joinShowroom?:()=>void; leaveShowroom?:()=>void; }
interface SocketChannel { socket:SocketClient; room:string; events:Array<[string,SocketHandler]>; }
interface SocketContextValue { connected:boolean; socket: SocketClient | null; on:(event:string,handler:SocketHandler)=>()=>void; off:(event:string,handler:SocketHandler)=>void; emit:(event:string,...args:any[])=>SocketClient|undefined; disconnect:()=>SocketClient|undefined; connect:()=>SocketClient|undefined; joinAuction:(carId:string,handlers?:{onBid?:SocketHandler;onCarUpdate?:SocketHandler})=>SocketChannel|undefined; joinNotifications:(handlers?:{onNotification?:SocketHandler})=>SocketChannel|null; joinMessages:(conversationId:string,handlers?:{onMessage?:SocketHandler})=>SocketChannel|undefined; joinInspection:(inspectionId:string,handlers?:{onUpdate?:SocketHandler})=>SocketChannel|undefined; joinControlPlane:(handlers?:{onUpdate?:SocketHandler})=>SocketChannel|undefined; leaveChannel:(channel:SocketChannel)=>void; }
declare global { interface Window { io?: (url:string,options?:Record<string,any>)=>SocketClient; } }
const SocketCtx=createContext<SocketContextValue|null>(null);
const socketUrl=()=>import.meta.env.VITE_SOCKET_URL || (import.meta.env.PROD?'https://api.kayad.space':'http://localhost:5000');
let loaderPromise:Promise<void>|null=null;
function loadSocketIoClient(){
 if(window.io)return Promise.resolve(); if(loaderPromise)return loaderPromise;
 loaderPromise=new Promise((resolve,reject)=>{const existing=document.querySelector('script[data-kayad-socketio]') as HTMLScriptElement|null; if(existing){existing.addEventListener('load',()=>resolve(),{once:true});existing.addEventListener('error',()=>reject(new Error('Unable to load Socket.IO client')),{once:true});return;} const script=document.createElement('script'); script.src=`${socketUrl()}/socket.io/socket.io.js`;script.async=true;script.dataset.kayadSocketio='true';script.onload=()=>resolve();script.onerror=()=>reject(new Error(`Unable to load Socket.IO client from ${script.src}`));document.head.appendChild(script);}); return loaderPromise;
}
export function SocketProvider({children}:{children:ReactNode}){
 const {isAuth}=useAuth(); const [connected,setConnected]=useState(false); const socketRef=useRef<SocketClient|null>(null); const subscriptions=useRef<SocketChannel[]>([]);
 useEffect(()=>{let cancelled=false;
  // Public auction rooms are explicitly spectator-readable, so realtime must
  // also work for signed-out visitors. Private chat/notifications remain
  // server-authorized and cannot be joined without an authenticated socket.
  // RT-3: the socket host does not receive the app host's httpOnly session cookie, so a signed-in tab proves its
  // identity with a 60-second, single-use socket ticket fetched same-origin (cookie + CSRF) right before every
  // (re)connection. The ticket travels in the Socket.IO CONNECT packet (never a URL) and is not stored anywhere.
  let reauthTimer:ReturnType<typeof setTimeout>|null=null; let reauthDelay=15000;
  const fetchTicket=async():Promise<string|null>=>{try{const r=await request<{ticket?:unknown}>('/realtime/socket-ticket',{method:'POST',timeout:10000});return typeof r?.ticket==='string'?r.ticket:null;}catch{return null;}};
  const auth=isAuth?(cb:(data:Record<string,unknown>)=>void)=>{void fetchTicket().then((ticket)=>cb(ticket?{ticket}:{}));}:undefined;
  void loadSocketIoClient().then(()=>{if(cancelled||!window.io)return;const s=window.io(socketUrl(),{withCredentials:true,transports:['websocket','polling'],reconnection:true,reconnectionAttempts:Infinity,reconnectionDelay:1000,...(auth?{auth}:{})});socketRef.current=s;const c=()=>setConnected(true),d=()=>setConnected(false);s.on('connect',c);s.on('disconnect',d);s.on('sessionExpired',()=>{s.disconnect();s.connect();});
   // A signed-in tab whose handshake was judged anonymous (ticket unavailable, session refreshing) retries with backoff.
   s.on('authState',(state:{authenticated?:boolean})=>{if(!isAuth||cancelled)return;if(state?.authenticated){reauthDelay=15000;return;}if(reauthTimer)return;reauthTimer=setTimeout(()=>{reauthTimer=null;if(!cancelled){s.disconnect();s.connect();}},reauthDelay);reauthDelay=Math.min(reauthDelay*2,300000);});
   if(s.connected)setConnected(true);}).catch(e=>{if(!cancelled){console.warn('[KAYAD] Realtime unavailable:',e);setConnected(false);}});
  return()=>{cancelled=true;if(reauthTimer)clearTimeout(reauthTimer);subscriptions.current.forEach(ch=>ch.events.forEach(([ev,h])=>ch.socket.off(ev,h)));subscriptions.current=[];socketRef.current?.disconnect();socketRef.current=null;setConnected(false)};
 },[isAuth]);
 const on=useCallback((event:string,handler:SocketHandler)=>{socketRef.current?.on(event,handler);return()=>socketRef.current?.off(event,handler)},[]);
 const off=useCallback((event:string,handler:SocketHandler)=>{socketRef.current?.off(event,handler);return socketRef.current},[]);
 const emit=useCallback((event:string,...args:any[])=>{socketRef.current?.emit(event,...args);return socketRef.current},[]);
 const joinAuction=useCallback((carId:string,handlers:{onBid?:SocketHandler;onCarUpdate?:SocketHandler}={})=>{const s=socketRef.current;if(!s||!carId)return undefined;s.emit('joinAuction',carId);const events:Array<[string,SocketHandler]>=[];if(handlers.onBid){s.on('bidUpdate',handlers.onBid);events.push(['bidUpdate',handlers.onBid]);}if(handlers.onCarUpdate){['auctionResync','auctionPhase','auctionEnded','auctionExtended','auctionTimer','auctionUpdate'].forEach((event)=>{s.on(event,handlers.onCarUpdate!);events.push([event,handlers.onCarUpdate!]);});}const ch={socket:s,room:`car_${carId}`,events};subscriptions.current.push(ch);return ch;},[]);
 const joinNotifications=useCallback((handlers:{onNotification?:SocketHandler}={})=>{const s=socketRef.current;if(!s)return null;const events:Array<[string,SocketHandler]>=[];if(handlers.onNotification){s.on('notification',handlers.onNotification);events.push(['notification',handlers.onNotification]);}const ch={socket:s,room:'user_notifications',events};subscriptions.current.push(ch);return ch;},[]);
 const joinMessages=useCallback((conversationId:string,handlers:{onMessage?:SocketHandler}={})=>{const s=socketRef.current;if(!s||!conversationId)return undefined;s.emit('joinChat',conversationId);const events:Array<[string,SocketHandler]>=[];const rejoin:SocketHandler=()=>{s.emit('joinChat',conversationId)};s.on('connect',rejoin);events.push(['connect',rejoin]);if(handlers.onMessage){s.on('newMessage',handlers.onMessage);events.push(['newMessage',handlers.onMessage]);}const ch={socket:s,room:`chat_${conversationId}`,events};subscriptions.current.push(ch);return ch;},[]);
 const joinControlPlane=useCallback((handlers:{onUpdate?:SocketHandler}={})=>{const s=socketRef.current;if(!s)return undefined;s.emit('joinControlPlane');const events:Array<[string,SocketHandler]>=[];if(handlers.onUpdate){s.on('controlPlaneUpdated',handlers.onUpdate);events.push(['controlPlaneUpdated',handlers.onUpdate]);}const ch={socket:s,room:'admins',events};subscriptions.current.push(ch);return ch;},[]);
 const joinInspection=useCallback((inspectionId:string,handlers:{onUpdate?:SocketHandler}={})=>{const s=socketRef.current;if(!s||!inspectionId)return undefined;s.emit('joinInspection',inspectionId);const events:Array<[string,SocketHandler]>=[];if(handlers.onUpdate){s.on('inspectionUpdated',handlers.onUpdate);s.on('inspectionResync',handlers.onUpdate);events.push(['inspectionUpdated',handlers.onUpdate],['inspectionResync',handlers.onUpdate]);}const ch={socket:s,room:`inspection_${inspectionId}`,events};subscriptions.current.push(ch);return ch;},[]);
 const leaveChannel=useCallback((ch:SocketChannel)=>{if(!ch)return;ch.events.forEach(([ev,h])=>ch.socket.off(ev,h));if(ch.room.startsWith('chat_'))ch.socket.emit('leaveChat',ch.room.slice(5));if(ch.room.startsWith('car_'))ch.socket.emit('leaveAuction',ch.room.slice(4));subscriptions.current=subscriptions.current.filter(x=>x!==ch)},[]);
 const joinShowroom=useCallback(()=>socketRef.current?.emit('joinShowroom'),[]),leaveShowroom=useCallback(()=>socketRef.current?.emit('leaveShowroom'),[]);
 const value={connected,socket:socketRef.current,on,off,emit,disconnect:()=>socketRef.current?.disconnect(),connect:()=>socketRef.current?.connect(),joinShowroom,leaveShowroom,joinAuction,joinNotifications,joinMessages,joinInspection,joinControlPlane,leaveChannel} as SocketContextValue;
 return <SocketCtx.Provider value={value}>{children}</SocketCtx.Provider>;
}
export const useSocket=()=>{const c=useContext(SocketCtx);if(!c)throw new Error('useSocket must be used within a SocketProvider');return c};

import { createContext, useContext, useState, useCallback, ReactNode } from 'react';

// Local type definitions (types/index.ts has these)
type ToastType = 'success' | 'error' | 'warning' | 'info';

interface Toast {
  id: string;
  type: ToastType;
  message: string;
  duration?: number;
}

interface ToastContextValue {
  toasts: Toast[];
  addToast: (toast: Omit<Toast, 'id'>) => void;
  removeToast: (id: string) => void;
  success: (message: string, duration?: number) => void;
  error: (message: string, duration?: number) => void;
  warning: (message: string, duration?: number) => void;
  info: (message: string, duration?: number) => void;
  toast: (message: string, type?: ToastType) => void;
}

const ToastCtx = createContext<ToastContextValue | null>(null);

const DEFAULT_DURATION = 4000;

interface ToastProviderProps {
  children: ReactNode;
}

export function ToastProvider({ children }: ToastProviderProps) {
  const [toasts, setToasts] = useState<Toast[]>([]);

  const addToast = useCallback(({ type, message, duration = DEFAULT_DURATION }: Omit<Toast, 'id'>) => {
    const id = `${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    setToasts((prev) => [...prev, { id, type, message, duration }]);

    if (duration > 0) {
      setTimeout(() => {
        setToasts((prev) => prev.filter((t) => t.id !== id));
      }, duration);
    }
  }, []);

  const removeToast = useCallback((id: string) => {
    setToasts((prev) => prev.filter((t) => t.id !== id));
  }, []);

  const success = useCallback((message: string, duration?: number) => {
    addToast({ type: 'success', message, duration });
  }, [addToast]);

  const error = useCallback((message: string, duration?: number) => {
    addToast({ type: 'error', message, duration });
  }, [addToast]);

  const warning = useCallback((message: string, duration?: number) => {
    addToast({ type: 'warning', message, duration });
  }, [addToast]);

  const info = useCallback((message: string, duration?: number) => {
    addToast({ type: 'info', message, duration });
  }, [addToast]);

  const toast = useCallback((message: string, type: ToastType = 'info') => {
    addToast({ type, message });
  }, [addToast]);

  return (
    <ToastCtx.Provider value={{ toasts, addToast, removeToast, success, error, warning, info, toast }}>
      {children}
      <ToastContainer toasts={toasts} onRemove={removeToast} />
    </ToastCtx.Provider>
  );
}

// Toast Container Component
interface ToastContainerProps {
  toasts: Toast[];
  onRemove: (id: string) => void;
}

function ToastContainer({ toasts, onRemove }: ToastContainerProps) {
  if (toasts.length === 0) return null;

  return (
    <div
      style={{
        position: 'fixed',
        bottom: 24,
        right: 24,
        zIndex: 9999,
        display: 'flex',
        flexDirection: 'column',
        gap: 10
      }}
      role="region"
      aria-label="Notifications"
    >
      {toasts.map((t) => (
        <ToastItem key={t.id} toast={t} onRemove={onRemove} />
      ))}
    </div>
  );
}

// Individual Toast Item
interface ToastItemProps {
  toast: Toast;
  onRemove: (id: string) => void;
}

function ToastItem({ toast, onRemove }: ToastItemProps) {
  const icons: Record<ToastType, string> = {
    success: '✅',
    error: '❌',
    warning: '⚠️',
    info: 'ℹ️',
  };

  const borderColors: Record<ToastType, string> = {
    success: '#22C55E',
    error: '#EF4444',
    warning: '#176b87',
    info: '#176B87',
  };

  return (
    <div
      role="alert"
      className={`toast toast-${toast.type}`}
      style={{
        background: 'var(--card)',
        border: `1px solid ${borderColors[toast.type]}`,
        borderRadius: 'var(--radius)',
        padding: '14px 20px',
        fontSize: 14,
        display: 'flex',
        alignItems: 'center',
        gap: 10,
        boxShadow: '0 8px 32px rgba(10, 51, 64, 0.4)',
        animation: 'slideInRight 0.3s ease',
        maxWidth: 360,
        cursor: 'pointer',
      }}
      onClick={() => onRemove(toast.id)}
    >
      <span className="toast-icon" aria-hidden="true">
        {icons[toast.type]}
      </span>
      {toast.message}
    </div>
  );
}

const noop = () => {};
const NOOP_TOAST_CONTEXT: ToastContextValue = {
  toasts: [],
  addToast: noop,
  removeToast: noop,
  success: noop,
  error: noop,
  warning: noop,
  info: noop,
  toast: noop,
};

export const useToast = (): ToastContextValue => {
  const context = useContext(ToastCtx);
  if (!context) {
    // No provider is mounted (tests, and currently the app shell): return one shared no-op context. It must be a
    // module-level constant: a fresh object per render gave callers a new `toast` identity every render, and every
    // effect/useCallback that lists `toast` as a dependency re-ran forever (a request storm on admin pages).
    return NOOP_TOAST_CONTEXT;
  }
  return context;
};

export interface CardProps {
  children: React.ReactNode;
  className?: string;
  onClick?: () => void;
  hoverable?: boolean;
}

export const Card: React.FC<CardProps> = ({
  children,
  className = '',
  onClick,
  hoverable = false,
}) => {
  return (
    <div
      onClick={onClick}
      className={`bg-[#176B87]/90 border border-[#0A3340]/60 rounded-2xl p-5 backdrop-blur-md shadow-lg transition-all duration-300 ${
        hoverable ? 'hover:border-[#13B8A6]/50 hover:shadow-xl hover:-translate-y-1 cursor-pointer' : ''
      } ${className}`}
    >
      {children}
    </div>
  );
};

