                  )}

                  <div className="flex items-center gap-4 flex-wrap">
                    <label className="flex items-center gap-2 text-xs text-[#64748B]">
                      Background
                      <input
                        type="color"
                        value={slot.backgroundColor}
                        onChange={(e) => handleFieldChange(slot.id, 'backgroundColor', e.target.value)}
                        className="w-8 h-8 rounded border border-[#D7E7E4] cursor-pointer"
                      />
                    </label>
                    <label className="flex items-center gap-2 text-xs text-[#64748B]">
                      Text
                      <input
                        type="color"
                        value={slot.textColor}
                        onChange={(e) => handleFieldChange(slot.id, 'textColor', e.target.value)}
                        className="w-8 h-8 rounded border border-[#D7E7E4] cursor-pointer"
                      />
                    </label>
                    <label className="flex items-center gap-2 text-xs text-[#64748B] flex-1 min-w-[140px]">
                      Transparency
                      <input
                        type="range"
                        min={10}
                        max={100}
                        value={slot.opacity}
                        onChange={(e) => handleFieldChange(slot.id, 'opacity', Number(e.target.value))}
                        className="flex-1"
                      />
                      <span className="w-8 text-right">{slot.opacity}%</span>
                    </label>
                  </div>

                  {/* Live preview, using this slot's own real colors */}
                  <div
                    className="rounded-lg px-3 py-2 text-xs font-semibold"
                    style={{ backgroundColor: slot.backgroundColor, color: slot.textColor, opacity: slot.opacity / 100 }}
                  >
                    {slot.title || 'Preview'}{slot.tagline ? ` — ${slot.tagline}` : ''}
                  </div>

                  <button
                    onClick={() => handleSave(slot)}
                    disabled={savingId === slot.id}
                    className="bg-[#176B87] hover:bg-[#0A3340] text-white text-xs font-bold rounded-lg px-4 py-2 disabled:opacity-50"
                  >
                    {savingId === slot.id ? 'Saving…' : 'Save Changes'}
                  </button>
                </div>
              ))}

              {showAddForm ? (
                <form onSubmit={handleCreate} className="border-2 border-dashed border-[#176B87]/40 rounded-xl p-4 space-y-3">
                  <select
                    value={draft.placement}
                    onChange={(e) => setDraft((d) => ({ ...d, placement: e.target.value as AdPlacement }))}
                    className="text-xs font-bold text-[#176B87] border border-[#D7E7E4] rounded-lg px-2 py-1"
                  >
                    {Object.entries(PLACEMENT_LABELS).map(([val, label]) => (
                      <option key={val} value={val}>{label}</option>
                    ))}
                  </select>
                  <input
                    value={draft.title}
                    onChange={(e) => setDraft((d) => ({ ...d, title: e.target.value }))}
                    placeholder="Title"
                    required
                    className="w-full border border-[#D7E7E4] rounded-lg px-3 py-2 text-sm"
                  />
                  <input
                    value={draft.tagline}
                    onChange={(e) => setDraft((d) => ({ ...d, tagline: e.target.value }))}
                    placeholder="Tagline"
                    className="w-full border border-[#D7E7E4] rounded-lg px-3 py-2 text-xs"
                  />
                  <div className="flex gap-2">
                    <button type="submit" disabled={creating} className="bg-[#176B87] hover:bg-[#12576D] text-white text-xs font-bold rounded-lg px-4 py-2 disabled:opacity-50">
                      {creating ? 'Creating…' : 'Create Ad'}
                    </button>
                    <button type="button" onClick={() => setShowAddForm(false)} className="text-xs font-semibold text-[#64748B] px-4 py-2">
                      Cancel
                    </button>
                  </div>
                </form>
              ) : (
                <button
                  onClick={() => setShowAddForm(true)}
                  className="w-full border-2 border-dashed border-[#D7E7E4] hover:border-[#176B87] rounded-xl py-3 text-xs font-bold text-[#64748B] hover:text-[#176B87] flex items-center justify-center gap-1.5"
                >
                  <Plus className="w-4 h-4" /> Add New Ad
                </button>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
};

