import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Loader2, RefreshCw, Send, Lock } from 'lucide-react';
import { Badge, Button, Card } from '../components/ui';
import {
  getStaffCase, getStaffMetrics, getStaffQueue, getStaffTeam, staffReplyToCase, staffUpdateCase,
  SupportApiError, StaffCase, StaffCaseSummary, StaffPerson, SupportMetrics,
} from '../services/supportApi';

// Mirrors backend supportPolicy transitions; the server is authoritative and re-validates every change.
const NEXT: Record<string, string[]> = {
  open: ['in_progress', 'waiting_on_user', 'waiting_on_internal', 'escalated', 'resolved'],
  in_progress: ['waiting_on_user', 'waiting_on_internal', 'escalated', 'resolved'],
  waiting_on_user: ['in_progress', 'waiting_on_internal', 'escalated', 'resolved'],
  waiting_on_internal: ['in_progress', 'waiting_on_user', 'escalated', 'resolved'],
  escalated: ['in_progress', 'waiting_on_user', 'waiting_on_internal', 'resolved'],
  resolved: ['in_progress', 'closed'],
  closed: [],
};
const STATUS_LABEL: Record<string, string> = {
  open: 'Open', in_progress: 'In progress', waiting_on_user: 'Waiting on customer', waiting_on_internal: 'Waiting on internal',
  escalated: 'Escalated', resolved: 'Resolved', closed: 'Closed',
};
const PRIORITIES = ['low', 'medium', 'high', 'urgent'];
const when = (v?: string | null) => (v ? new Date(v).toLocaleString('en-KE', { dateStyle: 'medium', timeStyle: 'short' }) : '—');
const mins = (m: number | null | undefined) => (m == null ? 'No data' : m >= 120 ? `${(m / 60).toFixed(1)} h` : `${m} min`);

const errText = (e: unknown, fallback: string) => (e instanceof SupportApiError ? (e.kind === 'forbidden' ? 'You do not have access to support cases.' : e.message) : fallback);

export const AdminSupportWorkspace: React.FC = () => {
  const [metrics, setMetrics] = useState<SupportMetrics | null>(null);
  const [rows, setRows] = useState<StaffCaseSummary[]>([]);
  const [total, setTotal] = useState(0);
  const [team, setTeam] = useState<StaffPerson[]>([]);
  const [filters, setFilters] = useState({ status: 'active', priority: '', category: '', assignedTo: '', q: '' });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [forbidden, setForbidden] = useState(false);
  const [selected, setSelected] = useState<StaffCase | null>(null);
  const [detailBusy, setDetailBusy] = useState(false);
  const [detailError, setDetailError] = useState<string | null>(null);
  const [reply, setReply] = useState('');
  const [internal, setInternal] = useState(false);
  const [nextStatus, setNextStatus] = useState('');
  const [resolution, setResolution] = useState('');
  const [capability, setCapability] = useState<'agent' | 'oversight'>('agent');
  const [pendingId, setPendingId] = useState<string | null>(null);
  const [reason, setReason] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const [q, m] = await Promise.all([getStaffQueue({ ...filters, limit: 50 }), getStaffMetrics(30)]);
      setRows(Array.isArray(q.cases) ? q.cases : []); setTotal(Number.isFinite(q.total) ? q.total : 0); setCapability(q.capability === 'oversight' ? 'oversight' : 'agent'); setMetrics(m.metrics); setForbidden(false);
    } catch (e) {
      if (e instanceof SupportApiError && e.kind === 'forbidden') setForbidden(true);
      setError(errText(e, 'Unable to load the support queue.'));
    } finally {
      setLoading(false);
    }
  }, [filters]);

  useEffect(() => { void load(); }, [load]);
  useEffect(() => { getStaffTeam().then((r) => setTeam(Array.isArray(r.staff) ? r.staff : [])).catch(() => setTeam([])); }, []);

  const open = async (id: string, why?: string) => {
    setReply(''); setInternal(false); setNextStatus(''); setResolution(''); setDetailError(null);
    if (capability === 'oversight' && !why) { setSelected(null); setPendingId(id); setReason(''); return; }
    setDetailBusy(true); setPendingId(null);
    try { setSelected((await getStaffCase(id, why)).case); } catch (e) { setDetailError(errText(e, 'Unable to load this case.')); } finally { setDetailBusy(false); }
  };

  const apply = async (fn: () => Promise<{ case: StaffCase }>, ok?: () => void) => {
    setDetailBusy(true); setDetailError(null);
    try { setSelected((await fn()).case); ok?.(); void load(); } catch (e) { setDetailError(errText(e, 'The change could not be saved.')); } finally { setDetailBusy(false); }
  };

  const options = useMemo(() => (selected ? NEXT[selected.status] || [] : []), [selected]);

  if (forbidden) return <Card className="p-6 text-sm text-[#64748B]"><Lock className="w-4 h-4 inline mr-2" />Your role does not include customer support access.</Card>;

  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 lg:grid-cols-6 gap-3">
        {[
          ['Open backlog', metrics?.openBacklog],
          ['Unassigned', metrics?.unassignedOpen],
          ['Awaiting first reply', metrics?.awaitingFirstResponse],
          ['Median first reply', metrics ? mins(metrics.medianFirstResponseMinutes) : undefined],
          ['Median resolution', metrics ? mins(metrics.medianResolutionMinutes) : undefined],
          ['Avg rating', metrics ? (metrics.averageRating ?? 'No ratings') : undefined],
        ].map(([label, value]) => (
          <Card key={String(label)} className="p-3"><p className="text-[10px] font-bold uppercase tracking-wider text-[#94A3B8]">{label}</p><p className="mt-1 text-lg font-black text-[#0A3340]">{value ?? '…'}</p></Card>
        ))}
      </div>
      {metrics && <p className="text-[11px] text-[#64748B]">Last {metrics.windowDays} days · {metrics.total} cases · {metrics.slaConfigured ? `Within first-reply target: ${metrics.firstResponseWithinTarget ?? 'n/a'}` : 'No response targets are configured, so no target compliance is reported.'}</p>}

      <Card className="p-4">
        <div className="flex flex-wrap gap-2 items-end">
          <label className="text-xs font-bold text-[#64748B]">Status
            <select className="mt-1 block rounded-lg border border-[#D7E7E4] px-2 py-2 text-sm" value={filters.status} onChange={(e) => setFilters({ ...filters, status: e.target.value })}>
              <option value="active">Active</option><option value="">All</option>
              {Object.entries(STATUS_LABEL).map(([v, l]) => <option key={v} value={v}>{l}</option>)}
            </select></label>
          <label className="text-xs font-bold text-[#64748B]">Priority
            <select className="mt-1 block rounded-lg border border-[#D7E7E4] px-2 py-2 text-sm" value={filters.priority} onChange={(e) => setFilters({ ...filters, priority: e.target.value })}>
              <option value="">Any</option>{PRIORITIES.map((p) => <option key={p} value={p}>{p}</option>)}
            </select></label>
          <label className="text-xs font-bold text-[#64748B]">Assignee
            <select className="mt-1 block rounded-lg border border-[#D7E7E4] px-2 py-2 text-sm" value={filters.assignedTo} onChange={(e) => setFilters({ ...filters, assignedTo: e.target.value })}>
              <option value="">Anyone</option><option value="unassigned">Unassigned</option>
              {team.map((t) => <option key={t.id} value={t.id}>{t.name || t.id.slice(0, 8)}</option>)}
            </select></label>
          <label className="text-xs font-bold text-[#64748B]">Case number
            <input className="mt-1 block rounded-lg border border-[#D7E7E4] px-2 py-2 text-sm" value={filters.q} onChange={(e) => setFilters({ ...filters, q: e.target.value })} placeholder="SUP-2026…" /></label>
          <Button variant="outline" size="sm" onClick={() => void load()} disabled={loading}><RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} /> Refresh</Button>
        </div>
        {error && <p className="mt-3 text-xs font-semibold text-rose-700" role="alert">{error}</p>}
      </Card>

      <div className="grid grid-cols-1 xl:grid-cols-[1fr_1.1fr] gap-4">
        <Card className="p-0 overflow-hidden">
          <div className="px-4 py-3 border-b border-[#D7E7E4] text-xs font-bold text-[#64748B]">{total} case{total === 1 ? '' : 's'}</div>
          <ul>
            {rows.map((r) => (
              <li key={r.id}>
                <button type="button" onClick={() => void open(r.id)} className={`w-full text-left px-4 py-3 border-b border-[#D7E7E4] hover:bg-[#F6FAF9] ${selected?.id === r.id ? 'bg-[#F6FAF9]' : ''}`}>
                  <div className="flex items-center justify-between gap-2"><span className="text-[10px] font-extrabold tracking-wider text-[#176B87]">{r.ticketNumber}</span>
                    <span className="flex gap-1">{r.awaitingStaff && <Badge variant="warning">Needs reply</Badge>}<Badge variant="neutral">{STATUS_LABEL[r.status] || r.status}</Badge></span></div>
                  <p className="mt-1 text-sm font-bold text-[#0A3340] truncate">{r.subject}</p>
                  <p className="mt-0.5 text-[11px] text-[#64748B]">{r.customer?.name || 'Customer'} · {r.priority} · {r.assignedTo?.name || 'Unassigned'} · {when(r.createdAt)}</p>
                </button>
              </li>
            ))}
            {!rows.length && !loading && <li className="px-4 py-8 text-center text-xs text-[#64748B]">No cases match these filters.</li>}
            {loading && <li className="px-4 py-8 text-center text-xs text-[#64748B]"><Loader2 className="w-4 h-4 animate-spin inline" /> Loading…</li>}
          </ul>
        </Card>

        <Card className="p-4">
          {capability === 'oversight' && <p className="mb-3 rounded-lg border border-[#D7E7E4] bg-[#F6FAF9] p-2 text-[11px] text-[#64748B]"><Lock className="w-3 h-3 inline mr-1" />Oversight access is read-only. Internal notes are hidden, and each case you open is recorded with your stated reason.</p>}
          {pendingId && !selected && (
            <form className="space-y-2" onSubmit={(e) => { e.preventDefault(); void open(pendingId, reason.trim()); }}>
              <label htmlFor="support-oversight-reason" className="text-xs font-bold text-[#64748B]">Reason for opening this case (10–300 characters, recorded)</label>
              <textarea id="support-oversight-reason" rows={2} maxLength={300} value={reason} onChange={(e) => setReason(e.target.value)} className="w-full rounded-lg border border-[#D7E7E4] px-2 py-2 text-sm" />
              <Button size="sm" variant="primary" type="submit" disabled={detailBusy || reason.trim().length < 10}>Open case read-only</Button>
            </form>
          )}
          {!selected && !pendingId && !detailBusy && <p className="text-sm text-[#64748B]">Select a case to read the thread, reply, or change its status.</p>}
          {detailBusy && !selected && <p className="text-xs text-[#64748B]"><Loader2 className="w-4 h-4 animate-spin inline" /> Loading…</p>}
          {detailError && <p className="mb-3 text-xs font-semibold text-rose-700" role="alert">{detailError}</p>}
          {selected && (
            <div className="space-y-4">
              <div>
                <p className="text-[10px] font-extrabold tracking-wider text-[#176B87]">{selected.ticketNumber} · {selected.category}</p>
                <h3 className="text-base font-black text-[#0A3340]">{selected.subject}</h3>
                <p className="text-[11px] text-[#64748B]">Customer: {selected.customer?.name || 'Unknown'} · Opened {when(selected.createdAt)}{selected.reopenCount ? ` · reopened ${selected.reopenCount}×` : ''}</p>
                {(selected.references?.length ?? 0) > 0 && <p className="mt-1 text-[11px] text-[#64748B]">Linked: {(selected.references ?? []).map((r) => `${r.kind} ${r.id}`).join(', ')}</p>}
                <p className="mt-2 whitespace-pre-wrap rounded-xl bg-[#F6FAF9] border border-[#D7E7E4] p-3 text-sm text-[#12576D]">{selected.description}</p>
              </div>

              <ul className="space-y-2 max-h-72 overflow-auto">
                {(selected.messages ?? []).map((m, i) => (
                  <li key={m.id || i} className={`rounded-xl border p-3 text-sm ${m.internal ? 'border-[#BDE5DE] bg-[#F3FAF9]' : m.kind === 'staff' ? 'border-[#D7E7E4] bg-[#F6FAF9]' : 'border-[#D7E7E4]'}`}>
                    <div className="flex justify-between text-[10px] font-extrabold uppercase tracking-wider text-[#64748B]"><span>{m.internal ? 'Internal note' : m.kind === 'staff' ? `Staff${m.senderName ? ` · ${m.senderName}` : ''}` : 'Customer'}</span><span>{when(m.createdAt)}</span></div>
                    <p className="mt-1 whitespace-pre-wrap text-[#12576D]">{m.content}</p>
                  </li>
                ))}
              </ul>

              {selected.status !== 'closed' && !selected.readOnly && (
                <div>
                  <textarea aria-label="Reply" rows={3} value={reply} onChange={(e) => setReply(e.target.value)} placeholder={internal ? 'Internal note (never shown to the customer)…' : 'Reply to the customer…'} className={`w-full rounded-xl border px-3 py-2 text-sm ${internal ? 'border-[#BDE5DE] bg-[#F3FAF9]' : 'border-[#D7E7E4]'}`} />
                  <div className="mt-2 flex items-center justify-between">
                    <label className="text-xs font-bold text-[#64748B]"><input type="checkbox" checked={internal} onChange={(e) => setInternal(e.target.checked)} /> Internal note only</label>
                    <Button size="sm" variant="primary" disabled={detailBusy || !reply.trim()} onClick={() => void apply(() => staffReplyToCase(selected.id, reply.trim(), internal), () => setReply(''))}><Send className="w-3.5 h-3.5" /> {internal ? 'Add note' : 'Send reply'}</Button>
                  </div>
                </div>
              )}

              {!selected.readOnly && <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 border-t border-[#D7E7E4] pt-3">
                <label className="text-xs font-bold text-[#64748B]">Assign to
                  <select className="mt-1 block w-full rounded-lg border border-[#D7E7E4] px-2 py-2 text-sm" value={selected.assignedTo?.id || ''} disabled={detailBusy || selected.status === 'closed'}
                    onChange={(e) => void apply(() => staffUpdateCase(selected.id, { assignedTo: e.target.value || null, expectedVersion: selected.rowVersion }))}>
                    <option value="">Unassigned</option>{team.map((t) => <option key={t.id} value={t.id}>{t.name || t.id.slice(0, 8)} ({t.role})</option>)}
                  </select></label>
                <label className="text-xs font-bold text-[#64748B]">Priority
                  <select className="mt-1 block w-full rounded-lg border border-[#D7E7E4] px-2 py-2 text-sm" value={selected.priority} disabled={detailBusy || selected.status === 'closed'}
                    onChange={(e) => void apply(() => staffUpdateCase(selected.id, { priority: e.target.value, expectedVersion: selected.rowVersion }))}>
                    {PRIORITIES.map((p) => <option key={p} value={p}>{p}</option>)}</select></label>
                <label className="text-xs font-bold text-[#64748B]">Change status
                  <select className="mt-1 block w-full rounded-lg border border-[#D7E7E4] px-2 py-2 text-sm" value={nextStatus} disabled={detailBusy || !options.length} onChange={(e) => setNextStatus(e.target.value)}>
                    <option value="">{STATUS_LABEL[selected.status]} (current)</option>{options.map((o) => <option key={o} value={o}>{STATUS_LABEL[o]}</option>)}</select></label>
                {nextStatus === 'resolved' && (
                  <label className="text-xs font-bold text-[#64748B] sm:col-span-2">Resolution note (internal, required)
                    <textarea rows={2} value={resolution} onChange={(e) => setResolution(e.target.value)} className="mt-1 block w-full rounded-lg border border-[#D7E7E4] px-2 py-2 text-sm" /></label>
                )}
                {nextStatus && (
                  <div className="sm:col-span-2"><Button size="sm" variant="primary" disabled={detailBusy || (nextStatus === 'resolved' && !resolution.trim())}
                    onClick={() => void apply(() => staffUpdateCase(selected.id, { status: nextStatus, resolutionNote: resolution.trim() || undefined, expectedVersion: selected.rowVersion }), () => { setNextStatus(''); setResolution(''); })}>Apply status change</Button></div>
                )}
              </div>}
              {selected.rating != null && <p className="text-xs text-[#64748B]">Customer rating: <strong>{selected.rating}/5</strong>{selected.ratingComment ? ` — “${selected.ratingComment}”` : ''}</p>}
            </div>
          )}
        </Card>
      </div>
    </div>
  );
};

export default AdminSupportWorkspace;

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { ChevronRight } from 'lucide-react';
import { adminAPI } from '../api/api.exports';

type Status = 'healthy' | 'degraded' | 'down' | 'unavailable' | 'unknown';
type ServiceRow = { label: string; status: Status; latency: number | null };
type PanelState =
  | { status: 'loading' }
  | { status: 'ready'; services: ServiceRow[]; checkedAt: Date | null }
  | { status: 'unverifiable' }
  | { status: 'restricted' }
  | { status: 'error' };

const STATUS_LABEL: Record<Status, string> = {
  healthy: 'Healthy', degraded: 'Degraded', down: 'Down', unavailable: 'Check unavailable', unknown: 'Unknown',
};

const safeDate = (value: unknown): Date | null => {
  if (typeof value !== 'string' && typeof value !== 'number') return null;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
};

// Reads only the existing protected health contract (`/ecp/health`). A service is listed only if the
// response names it; a status is shown only if the response states one; latency and the check time
// appear only when they are genuinely measured. Nothing is inferred from configuration.
export default function AdminSystemHealthPanel() {
  const [state, setState] = useState<PanelState>({ status: 'loading' });

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const response: any = await (adminAPI as any).getInfrastructureHealth();
        if (cancelled) return;
        const health = response?.data?.health || response?.health || response?.data || response;
        const raw = Array.isArray(health?.services) ? health.services : [];
        const services: ServiceRow[] = raw
          .filter((s: any) => s && typeof s.name === 'string' && s.name.trim())
          .map((s: any) => {
            const rawStatus = typeof s.status === 'string' ? s.status.toLowerCase() : '';
            const status: Status = (['healthy', 'degraded', 'down', 'unavailable'] as const).includes(rawStatus as any) ? (rawStatus as Status) : 'unknown';
            const latency = s.latency != null && Number.isFinite(Number(s.latency)) && Number(s.latency) >= 0 ? Number(s.latency) : null;
            return { label: s.name.replace(/[-_]/g, ' ').replace(/\b\w/g, (c: string) => c.toUpperCase()), status, latency };
          });
        if (!services.length) { setState({ status: 'unverifiable' }); return; }
        setState({ status: 'ready', services: services.slice(0, 6), checkedAt: safeDate(health?.checkedAt || response?.timestamp) });
      } catch (err: any) {
        if (cancelled) return;
        setState(err?.response?.status === 403 ? { status: 'restricted' } : { status: 'error' });
      }
    })();
    return () => { cancelled = true; };
  }, []);

  return (
    <div aria-live="polite">
      {state.status === 'loading' && <p className="kayad-command-empty">Checking service health…</p>}
      {state.status === 'error' && <p className="kayad-command-empty">Service health could not be checked, so the current state is unknown. No status is assumed without a health check.</p>}
      {state.status === 'unverifiable' && <p className="kayad-command-empty">The health source returned no verifiable service checks, so the current state is unknown. No status is assumed without a health check.</p>}
      {state.status === 'restricted' && <p className="kayad-command-empty">Service health is not included in your role. This is an access boundary, not an outage.</p>}
      {state.status === 'ready' && (
        <>
          <ul className="kayad-command-health-list">
            {state.services.map((service) => (
              <li key={service.label} data-status={service.status}>
                <span className="kayad-command-health-dot" aria-hidden="true" />
                <strong>{service.label}</strong>
                <span>{STATUS_LABEL[service.status]}{service.latency !== null ? ` · ${Math.round(service.latency)} ms` : ''}</span>
              </li>
            ))}
          </ul>
          <p className="kayad-command-data-note">
            {state.checkedAt
              ? `Checked ${state.checkedAt.toLocaleString('en-KE', { timeZone: 'Africa/Nairobi', dateStyle: 'medium', timeStyle: 'short' })}.`
              : 'Check time not provided by the health source.'}
          </p>
        </>
      )}
      <Link className="kayad-command-inline-link" to="/admin/control-room">Open system monitoring <ChevronRight size={14} aria-hidden="true" /></Link>
    </div>
  );
}

import React, { useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import type { Vehicle } from '../types';
import { adminAPI } from '../api/api.exports';
import {
  AlertTriangle,
  Ban,
  Building2,
  ChevronRight,
  Car,
  CheckCircle2,
  Compass,
  FileCheck,
  History,
  LifeBuoy,
  Send,
  RefreshCw,
  Search,
  ShieldCheck,
  Users,
  Wrench as ProvidersIcon,
} from 'lucide-react';
import { Badge, Button, Card, Input, Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '../components/ui';
import AdminCommunications from '../pages/admin/AdminCommunications';
import AdminNavigationControl from './AdminNavigationControl';
import AdminSystemHealthPanel from './AdminSystemHealthPanel';
import AdminAlertsPanel from './AdminAlertsPanel';
import AdminProviderGovernance from './AdminProviderGovernance';
import AdminSupportWorkspace from './AdminSupportWorkspace';
// STAGE 5A (Gate D): the owner onboarding settings page was built in Stage 5 but never mounted anywhere reachable.
import AdminSettingsOnboarding from '../pages/admin/AdminSettingsOnboarding';
// STAGE 5B: owner membership management (owner-only on the server; the tab is shown only to owners).
import AdminOwnerManagement from '../pages/admin/AdminOwnerManagement';
import AdminAuctionVerification from './AdminAuctionVerification'; // STAGE 5F.10
import AdminDepartmentCapabilities from './AdminDepartmentCapabilities';
import './admin-command-centre.css';
import { useAuth } from '../context/AuthContext';
import { adminRoleLabel } from '../components/admin/adminRoleLabels';
import { getEffectivePermissions, PAGE_PERMISSIONS, SUPERADMIN_ONLY } from '../utils/permissions';

interface AdminViewProps {
  vehicles: Vehicle[];
  onQuickViewVehicle?: (vehicle: Vehicle) => void;
}

type AdminStats = Record<string, number | null>;
type QueueFilter = 'pendingDealers' | 'pendingVehicles' | null;
type AdminUser = {
  _id: string;
  name?: string;
  email?: string;
  role?: string;
  isBanned?: boolean;
  approved?: boolean;
  status?: string;
};
type AdminCar = {
  _id: string;
  title?: string;
  status?: string;
  auctionStatus?: string;
  auction_status?: string;
  currentBid?: number;
  current_bid?: number;
  price?: number;
  bidsCount?: number;
  bids_count?: number;
  auctionEnd?: string;
  auction_end?: string;
  year?: number | string;
  images?: Array<string | { url?: string; thumb?: string }>;
  image?: string;
  imageUrl?: string;
  dealer?: { name?: string; email?: string };
  seller?: { name?: string; email?: string };
};
type AuditRecord = {
  _id?: string;
  id?: string;
  action?: string;
  module?: string;
  actor?: { name?: string; email?: string };
  user?: { name?: string; email?: string };
  targetId?: string;
  createdAt?: string;
  timestamp?: string;
};

function unwrap<T = any>(value: any): T {
  if (value && typeof value === 'object' && 'data' in value) return value.data as T;
  return value as T;
}

export const AdminView: React.FC<AdminViewProps> = ({ vehicles, onQuickViewVehicle }) => {
  const { user: sessionUser } = useAuth();
  // Display convenience only: destinations the role cannot open are not offered as links. The route guard and the server still enforce access.
  const canOpen = (to: string): boolean => {
    if (sessionUser?.role === 'superadmin') return true;
    if (SUPERADMIN_ONLY.has(to)) return false;
    const required = PAGE_PERMISSIONS[to];
    return !required || getEffectivePermissions(sessionUser as any).includes(required);
  };
  const isOwner = (sessionUser as { isOwner?: boolean } | null)?.isOwner === true; // display only — the server enforces owner authority on every call
  const [stats, setStats] = useState<AdminStats>({});
  const [users, setUsers] = useState<AdminUser[]>([]);
  // A separate server-filtered preview prevents pending dealers beyond the first
  // general users page from disappearing from the command-centre queue.
  const [pendingDealerUsers, setPendingDealerUsers] = useState<AdminUser[]>([]);
  const [cars, setCars] = useState<AdminCar[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditRecord[]>([]);
  const [toolsOpen, setToolsOpen] = useState(false);
  // Minute-resolution clock so the Nairobi time does not freeze at first render.
  const [now, setNow] = useState(() => new Date());
  useEffect(() => {
    const timer = window.setInterval(() => setNow(new Date()), 30_000);
    return () => window.clearInterval(timer);
  }, []);
  const [module, setModule] = useState<'overview' | 'users' | 'cars' | 'audit' | 'communications' | 'navigation' | 'providers' | 'support' | 'onboarding' | 'auctions' | 'owners' | 'departments'>('overview');
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const [statsStatus, setStatsStatus] = useState<'loading' | 'ready' | 'stale' | 'error'>('loading');
  const [error, setError] = useState<string | null>(null);
  const [actionError, setActionError] = useState<string | null>(null);
  const [busyId, setBusyId] = useState<string | null>(null);
  // Queue tiles open their destination list already filtered to the rows the tile counts.
  const [queue, setQueue] = useState<QueueFilter>(null);
  // Sources the server refused for this role (403). That is an access boundary, not an outage, and is reported as such.
  const [restricted, setRestricted] = useState<string[]>([]);
  const [failedVehicleImages, setFailedVehicleImages] = useState<string[]>([]);
  // Only the latest dashboard request may publish results. This prevents a slow
  // refresh from overwriting newer queue-filter or post-action data.
  const loadSequence = useRef(0);

  const load = async (activeQueue: QueueFilter = queue) => {
    const sequence = ++loadSequence.current;
    setLoading(true);
    setError(null);
    setStatsStatus((current) => current === 'ready' || current === 'stale' ? 'stale' : 'loading');

    // Dashboard sources are independent. One failed source must not erase successful
    // results from the others or make the entire command centre look unavailable.
    const results = await Promise.allSettled([
      adminAPI.stats(),
      adminAPI.users({ page: 1, limit: 4, role: 'dealer', pendingApproval: true }),
      adminAPI.users({ page: 1, limit: 50, search: search || undefined, ...(activeQueue === 'pendingDealers' ? { role: 'dealer', pendingApproval: true } : {}) }),
      adminAPI.cars({ page: 1, limit: 50, search: search || undefined, ...(activeQueue === 'pendingVehicles' ? { status: 'pending' } : {}) }),
      adminAPI.getAuditLog({ page: 1, limit: 25 }),
    ] as const);

    if (sequence !== loadSequence.current) return;

    const failures: string[] = [];
    const denied: string[] = [];
    const [statsResult, pendingDealersResult, usersResult, carsResult, auditResult] = results;
    const isDenied = (r: PromiseSettledResult<unknown>) => r.status === 'rejected' && (r.reason as any)?.response?.status === 403;
    const note = (r: PromiseSettledResult<unknown>, label: string, failLabel: string) => {
      if (isDenied(r)) denied.push(label); else failures.push(failLabel);
    };

    if (statsResult.status === 'fulfilled') {
      const payload = unwrap<any>(statsResult.value);
      const nextStats = payload?.stats ?? payload;
      if (nextStats && typeof nextStats === 'object' && !Array.isArray(nextStats)) {
        setStats(nextStats);
        setStatsStatus('ready');
      } else {
        setStatsStatus((current) => current === 'stale' ? 'stale' : 'error');
        failures.push('dashboard statistics returned an invalid response');
      }
    } else {
      setStatsStatus((current) => current === 'stale' ? 'stale' : 'error');
      note(statsResult, 'dashboard statistics', 'dashboard statistics');
    }

    if (usersResult.status === 'fulfilled') {
      const payload = unwrap<any>(usersResult.value);
      if (Array.isArray(payload?.users)) {
        // The API returns `id` in some deployments rather than Mongo-style `_id`.
        setUsers(payload.users.map((u: any) => ({ ...u, _id: u._id ?? u.id })));
      } else {
        failures.push('user records (invalid response)');
      }
    } else {
      note(usersResult, 'user records', 'user records');
    }

    if (pendingDealersResult.status === 'fulfilled') {
      const payload = unwrap<any>(pendingDealersResult.value);
      if (Array.isArray(payload?.users)) {
        setPendingDealerUsers(payload.users
          .filter((u: any) => u && u.role === 'dealer' && u.status === 'pending')
          .map((u: any) => ({ ...u, _id: u._id ?? u.id })));
      } else {
        failures.push('pending dealer queue (invalid response)');
      }
    } else {
      note(pendingDealersResult, 'pending dealer queue', 'pending dealer queue');
    }

    if (carsResult.status === 'fulfilled') {
      const payload = unwrap<any>(carsResult.value);
      if (Array.isArray(payload?.cars)) {
        setCars(payload.cars.map((c: any) => ({ ...c, _id: c._id ?? c.id })));
      } else {
        failures.push('vehicle records (invalid response)');
      }
    } else {
      note(carsResult, 'vehicle records', 'vehicle records');
    }

    if (auditResult.status === 'fulfilled') {
      const payload = unwrap<any>(auditResult.value);
      const entries = payload?.entries ?? payload?.logs ?? payload?.auditLogs;
      if (Array.isArray(entries)) setAuditLogs(entries);
      else failures.push('audit log (invalid response)');
    } else {
      note(auditResult, 'audit log', 'audit log');
    }
    setRestricted(denied);

    setError(failures.length
      ? `Some operational data sources are unavailable: ${failures.join(', ')}. Other successful results remain available.`
      : null);
    setLoading(false);
  };

  useEffect(() => {
    void load();
    return () => { loadSequence.current += 1; };
    // The dashboard performs its initial load once; explicit refresh and action
    // handlers call load directly with the current queue when needed.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const filteredUsers = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return users;
    return users.filter((u) => `${u.name || ''} ${u.email || ''} ${u.role || ''}`.toLowerCase().includes(q));
  }, [users, search]);

  const filteredCars = useMemo(() => {
    const q = search.trim().toLowerCase();
    if (!q) return cars;
    return cars.filter((c) => `${c.title || ''} ${c._id} ${c.status || ''}`.toLowerCase().includes(q));
  }, [cars, search]);

  const toggleBan = async (user: AdminUser) => {
    setBusyId(user._id);
    setActionError(null);
    try {
      await adminAPI.toggleBan(user._id);
      await load();
    } catch (err: any) {
      setActionError(err?.message || 'The server rejected this account action.');
    } finally {
      setBusyId(null);
    }
  };

  // STAGE 5A (Gate F): the dealer/seller decision and listing moderation controls existed only on pages that are not mounted
  // anywhere reachable. The server remains the authority (owner_only / admins policy); these buttons only call it and show its answer.
  const decideSeller = async (user: AdminUser, action: 'approve' | 'reject') => {
    setBusyId(user._id);
    setActionError(null);
    try {
      if (action === 'approve') await adminAPI.approveDealer(user._id);
      else await adminAPI.verifyDealer(user._id, { action: 'reject', reason: 'Application not approved' });
      await load();
    } catch (err: any) {
      setActionError(err?.response?.data?.message || err?.message || 'The server rejected this application decision.');
    } finally {
      setBusyId(null);
    }
  };

  const moderateListing = async (car: AdminCar, action: 'approve' | 'hide') => {
    setBusyId(car._id);
    setActionError(null);
    try {
      await adminAPI.moderateCar(car._id, { action });
      await load();
    } catch (err: any) {
      setActionError(err?.response?.data?.message || err?.message || 'The server rejected this listing decision.');
    } finally {
      setBusyId(null);
    }
  };

  const verifyCar = async (car: AdminCar) => {
    setBusyId(car._id);
    setActionError(null);
    try {
      await adminAPI.verifyCar(car._id, { ntsaVerified: true, logbookVerified: true });
      await load();
    } catch (err: any) {
      setActionError(err?.message || 'The server rejected this vehicle verification action.');
    } finally {
      setBusyId(null);
    }
  };

  // Missing or malformed metrics must never masquerade as a healthy zero.
  // A numeric zero is shown only when the API actually returned zero.
  const stat = (key: string) => {
    const value = stats[key];
    if (typeof value !== 'number' || !Number.isSafeInteger(value) || value < 0) {
      return statsStatus === 'loading' || (loading && statsStatus !== 'stale') ? 'Loading…' : 'Unavailable';
    }
    return value.toLocaleString();
  };

  return (
    <div className="mx-auto w-full min-w-0 max-w-[1600px] space-y-5 sm:space-y-6" data-testid="admin-command-centre">
      <section aria-labelledby="admin-command-centre-title" className="kayad-command-hero">
        <div className="kayad-command-hero-content">
          <div className="kayad-command-eyebrow"><ShieldCheck size={15} aria-hidden="true" /> KAYAD BUSINESS COMMAND CENTRE</div>
          <h1 id="admin-command-centre-title">Welcome back, <span>{(typeof sessionUser?.name === 'string' ? sessionUser.name.trim() : '') || 'Administrator'}</span></h1>
          <p className="kayad-command-intro">Oversee your marketplace, team, operations and systems — all from one portal.</p>
          <div className="kayad-command-identity" aria-label="Authenticated administrator">
            <span className="kayad-command-identity-mark" aria-hidden="true">{(typeof sessionUser?.name === 'string' && sessionUser.name.trim() ? sessionUser.name.trim().split(/\s+/).slice(0, 2).map((part) => part.charAt(0)).join('').toUpperCase() : 'AD')}</span>
            <span className="kayad-command-identity-copy">
              <strong>{(typeof sessionUser?.name === 'string' && sessionUser.name.trim()) || 'Administrator'}</strong>
              <small>{adminRoleLabel(sessionUser?.role) ?? (isOwner ? 'Account Owner' : 'Authorized Administrator')}</small>
            </span>
          </div>
          <div className="kayad-command-meta">
            <span className="kayad-command-meta-item"><span className="kayad-command-meta-label">Nairobi time</span><time dateTime={now.toISOString()}>{new Intl.DateTimeFormat('en-KE', { dateStyle: 'full', timeStyle: 'short', timeZone: 'Africa/Nairobi' }).format(now)}</time></span>
            <span role="status" aria-live="polite" className={`kayad-command-data-state${error || restricted.length > 0 || statsStatus === 'error' ? ' is-limited' : loading ? ' is-loading' : ' is-ready'}`}><span aria-hidden="true" />{error || restricted.length > 0 || statsStatus === 'error' ? 'Some operational data unavailable or restricted' : loading ? 'Loading operational data' : 'Operational data loaded'}</span>
          </div>
        </div>
        <div className="kayad-command-actions" aria-label="Quick Actions">
          <div className="kayad-command-actions-heading"><strong>Quick Actions</strong><span>Common workspaces</span></div>
          <div className="kayad-command-actions-grid">
            {canOpen('/admin/staff') && <Link to="/admin/staff">Add Staff <ChevronRight size={14} aria-hidden="true" /></Link>}
            {canOpen('/admin/dealer-verifications') && <Link to="/admin/dealer-verifications">Approve Dealer <ChevronRight size={14} aria-hidden="true" /></Link>}
            {canOpen('/admin/cars') && <Link to="/admin/cars">View Vehicles <ChevronRight size={14} aria-hidden="true" /></Link>}
            {canOpen('/admin/reports') && <Link to="/admin/reports">View Reports <ChevronRight size={14} aria-hidden="true" /></Link>}
</div>
        </div>
      </section>
      <div className="kayad-command-toolbar"><span>{statsStatus === 'stale' ? 'Showing last successful statistics' : statsStatus === 'ready' ? 'Values reflect the latest API response' : 'Live data pending'}</span><Button variant="outline" size="sm" onClick={() => void load()} disabled={loading} aria-label="Refresh administration data"><RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} /> Refresh</Button></div>
      {(error || actionError) && (
        <Card role="alert" className="flex items-start gap-2 border-[#BDE5DE] bg-[#F3FAF9] p-4 text-sm text-[#0A3340]">
          <AlertTriangle className="w-5 h-5 shrink-0 mt-0.5" />
          <span>{actionError || error}</span>
        </Card>
      )}

      {restricted.length > 0 && (
        <p role="note" className="text-xs text-[#58717A]">Not included in your role: {restricted.join(', ')}. This is an access boundary, not an outage.</p>
      )}

      <div className="kayad-command-specialists">
        <button type="button" onClick={() => setToolsOpen(!toolsOpen)} aria-expanded={toolsOpen} aria-controls="kayad-specialist-tools">{toolsOpen ? 'Hide' : 'Show'} specialist tools <ChevronRight className="inline h-4 w-4" /></button>
        {toolsOpen && <nav id="kayad-specialist-tools" className="kayad-command-tool-links" aria-label="Administration modules">
          {([['overview', 'Dashboard'], ['users', 'User review'], ['cars', 'Vehicle review'], ['audit', 'Audit records'], ['communications', 'Communications'], ['navigation', 'Navigation settings'], ['providers', 'Providers'], ['support', 'Support'], ['onboarding', 'Onboarding'], ['auctions', 'Auction verification'], ...(isOwner ? [['owners', 'Owner management'], ['departments', 'Departments']] : [])] as [typeof module, string][]).map(([key, label]) => <button type="button" key={key} className={module === key ? 'selected' : ''} aria-label={`${label} module`} aria-current={module === key ? 'page' : undefined} onClick={() => { setModule(key); setToolsOpen(false); }}>{label}</button>)}
          {module !== 'overview' && <Input aria-label="Search administration records" placeholder="Search live records…" value={search} onChange={(e) => setSearch(e.target.value)} />}
        </nav>}
      </div>
      {module === 'overview' && (
        <div className="kayad-command-overview">
          <section aria-label="Marketplace metrics" className="kayad-command-kpis">
            {[
              { label: 'Total Users', value: stat('totalUsers'), icon: <Users size={22} />, to: '/admin/users' },
              { label: 'Active Staff', value: canOpen('/admin/staff') ? 'View staff' : 'Super Admin only', icon: <ShieldCheck size={22} />, to: '/admin/staff' },
              { label: 'Verified Dealers', value: stat('verifiedDealers'), icon: <Building2 size={22} />, to: '/admin/dealer-verifications' },
              { label: 'Vehicles', value: stat('totalCars'), icon: <Car size={22} />, to: '/admin/cars' },
              { label: 'Live Auctions', value: stat('activeAuctions'), icon: <FileCheck size={22} />, to: '/admin/auctions' },
              { label: 'Open Escrows', value: stat('openEscrows'), icon: <ShieldCheck size={22} />, to: '/admin/escrows' },
            ].map(item => canOpen(item.to)
              ? <Link to={item.to} className="kayad-command-kpi" key={item.label}><div className="kayad-command-kpi-icon">{item.icon}</div><div><small>{item.label}</small><strong className={typeof item.value === 'string' && !/^\d/.test(item.value) && item.value !== 'Unavailable' && item.value !== 'Loading…' ? 'is-link-label' : undefined}>{item.value}</strong></div></Link>
              : <div className="kayad-command-kpi is-restricted" key={item.label}><div className="kayad-command-kpi-icon">{item.icon}</div><div><small>{item.label}</small><strong className={typeof item.value === 'string' && !/^\d/.test(item.value) && item.value !== 'Unavailable' && item.value !== 'Loading…' ? 'is-link-label' : undefined}>{item.value}</strong></div></div>)}
          </section>
          <div className="kayad-command-main-grid">
            <section className="kayad-command-panel" aria-labelledby="approval-workflows-heading" data-testid="approval-workbench">
              <header><h2 id="approval-workflows-heading">Approval Workflows</h2><Link to="/admin/dealer-verifications">View All</Link></header>
              <div className="kayad-command-queue-tabs">
                {[
                  { label: 'Dealers', href: '/admin/dealer-verifications', count: stat('pendingDealers') },
                  { label: 'Sellers', href: '/admin/sellers' },
                  { label: 'Inspectors', href: '/admin/inspector-applications' },
                  { label: 'Vehicle Listings', href: '/admin/moderation', count: stat('pendingCars') },
                  { label: 'Document Verification', href: '/admin/ntsa-queue' },
                  { label: 'Inspections', href: '/admin/inspections' },
                ].map((item) => <Link key={item.href} to={item.href} aria-label={`Open ${item.label.toLowerCase()} approval workflow`}>{item.label}{item.count !== undefined && <b>{item.count}</b>}</Link>)}
              </div>
              <p className="kayad-command-empty">Each workflow retains its own domain rules and permissions; this panel only links to them.</p>
              <div className="kayad-command-approval-list" aria-live="polite">
                {pendingDealerUsers.map(u => <div key={u._id}><div><strong>{u.name || 'Dealer application'}</strong><small>{u.email || 'No email provided'}</small></div><span className="kayad-command-pending">Pending Review</span><button type="button" aria-label={`Review dealer application for ${u.name || u.email || 'dealer'}`} onClick={() => { setQueue('pendingDealers'); setModule('users'); void load('pendingDealers'); }}>Review</button></div>)}
                {!pendingDealerUsers.length && <p className="kayad-command-empty">{loading ? 'Loading approval records…' : restricted.includes('pending dealer queue') || restricted.includes('user records') ? 'Dealer records are restricted for this role. Use the authorized dealer verification workspace.' : error ? 'Approval records may be unavailable. Open the dealer verification queue for the authoritative list.' : 'No pending dealers returned by the server-filtered queue. View all to inspect the full queue.'}</p>}
              </div>
            </section>
            <section className="kayad-command-panel" aria-labelledby="system-health-heading">
              <header><h2 id="system-health-heading">System Health</h2><Link to="/admin/control-room">View All</Link></header>
              <AdminSystemHealthPanel />
            </section>
            <section className="kayad-command-panel" aria-labelledby="recent-submissions-heading">
              <header><h2 id="recent-submissions-heading">Recent Vehicle Submissions</h2><Link to="/admin/cars">View All</Link></header>
              <div className="kayad-command-vehicles">
                {cars.slice(0, 4).map(car => { const firstImage = car.images?.[0]; const imageUrl = (typeof firstImage === 'string' ? firstImage : firstImage?.thumb || firstImage?.url) || car.imageUrl || car.image; return <div key={car._id} className="kayad-command-vehicle"><div className="kayad-command-vehicle-art">{imageUrl && !failedVehicleImages.includes(`${car._id}:${imageUrl}`) ? <img src={imageUrl} alt={car.title || 'Vehicle submission'} loading="lazy" onError={() => setFailedVehicleImages((current) => current.includes(`${car._id}:${imageUrl}`) ? current : [...current, `${car._id}:${imageUrl}`])} /> : <Car size={32} aria-hidden="true" />}</div><strong>{car.title || 'Untitled vehicle'}</strong><small>{car.year ? `${car.year} · ` : ''}{typeof car.price === 'number' ? `KES ${car.price.toLocaleString()}` : 'Price not provided'}</small><span>{car.status || 'Status unavailable'}</span></div>; })}
                {!cars.length && <p className="kayad-command-empty">{loading ? 'Loading submissions…' : restricted.includes('vehicle records') ? 'Vehicle records are restricted for this role.' : error ? 'Vehicle records unavailable.' : 'No vehicle submissions in the loaded records.'}</p>}
              </div>
            </section>
            <section className="kayad-command-panel" aria-labelledby="customer-risk-heading">
              <header><h2 id="customer-risk-heading">Customer &amp; Risk Operations</h2><Link to="/admin/support" aria-label="Open support queue">View Support</Link></header>
              <p className="kayad-command-empty">Review customer support demand and route operational issues through the existing authorized workspaces.</p>
              <div className="kayad-command-risk-links">
                <Link to="/admin/support" aria-label="Open support tickets queue"><LifeBuoy size={16} /> Support queue <ChevronRight size={14} /></Link>
                <Link to="/admin/escrows" aria-label="Open escrow operations"><ShieldCheck size={16} /> Escrow operations <ChevronRight size={14} /></Link>
              </div>
            </section>
            <section className="kayad-command-panel" aria-labelledby="live-auctions-heading">
              <header><h2 id="live-auctions-heading">Live Auctions</h2><Link to="/admin/auctions">View All</Link></header>
              {cars.filter(car => (car.auctionStatus || car.auction_status || '').toLowerCase() === 'live').slice(0, 4).map(car => <div className="kayad-command-auction-row" key={car._id}><div className="kayad-command-auction-thumb"><Car size={20}/></div><div className="kayad-command-auction-info"><strong>{car.title || 'Live vehicle auction'}</strong><small>{typeof (car.currentBid ?? car.current_bid) === 'number' ? `KES ${(car.currentBid ?? car.current_bid as number).toLocaleString()}` : typeof car.price === 'number' ? `Starting price KES ${car.price.toLocaleString()}` : 'Current bid unavailable'}</small></div><span className="kayad-command-live">Live</span></div>)}
              {!cars.some(car => (car.auctionStatus || car.auction_status || '').toLowerCase() === 'live') && <p className="kayad-command-empty">{loading ? 'Loading auction records…' : restricted.includes('vehicle records') ? 'Auction details are restricted with the vehicle records for this role.' : error ? 'Auction records may be unavailable.' : 'No live auctions in the loaded vehicle records. Open the auction workspace for the authoritative list.'}</p>}
              <Link className="kayad-command-inline-link" to="/admin/auctions">Open live auction operations <ChevronRight size={14}/></Link>
            </section>
            <section className="kayad-command-panel" aria-labelledby="recent-activity-heading">
              <header><h2 id="recent-activity-heading">Recent Activity</h2><Link to="/admin/security-log">View All</Link></header>
              {auditLogs.length > 0 ? (
                <ul className="kayad-command-activity-list">
                  {auditLogs.slice(0, 4).map((log, i) => {
                    const when = log.createdAt || log.timestamp;
                    const valid = typeof when === 'string' && !Number.isNaN(Date.parse(when));
                    return (
                      <li key={log._id || log.id || i}>
                        <strong>{(log.action || 'Action not recorded').replace(/[._]/g, ' ')}</strong>
                        <small>{log.actor?.email || log.actor?.name || log.user?.email || log.user?.name || 'Actor not recorded'}{log.module ? ` · ${log.module}` : ''}{valid ? ` · ${new Date(when as string).toLocaleString('en-KE', { timeZone: 'Africa/Nairobi', dateStyle: 'medium', timeStyle: 'short' })}` : ''}</small>
                      </li>
                    );
                  })}
                </ul>
              ) : (
                <p className="kayad-command-empty">{loading ? 'Loading audit activity…' : restricted.includes('audit log') ? 'Audit activity is restricted for this role.' : error && /audit log/.test(error) ? 'Audit activity is unavailable right now. This is not a confirmation that nothing happened.' : 'No audit activity was returned.'}</p>
              )}
            </section>
            <section className="kayad-command-panel" aria-labelledby="team-heading"><header><h2 id="team-heading">Team Members</h2><Link to="/admin/staff">View All</Link></header>{users.filter(u => ['superadmin','admin','moderator','marketing','technical_support','hr','accounts','escrow_officer','ad_manager','ghost_checker'].includes((u.role || '').toLowerCase())).slice(0, 3).map(u => <div className="kayad-command-team-row" key={u._id}><span className="kayad-command-team-avatar">{(u.name || u.email || 'S').charAt(0).toUpperCase()}</span><div><strong>{u.name || 'Staff member'}</strong><small>{u.role || 'Staff role unavailable'}</small></div></div>)}{!users.some(u => ['superadmin','admin','moderator','marketing','technical_support','hr','accounts','escrow_officer','ad_manager','ghost_checker'].includes((u.role || '').toLowerCase())) && <p className="kayad-command-empty">{loading ? 'Loading team records…' : restricted.includes('user records') ? 'Team records are restricted for this role.' : error ? 'Team records may be unavailable. Open staff management for the authoritative list.' : 'No staff accounts found in the current user sample. Open staff management for the authoritative list.'}</p>}<Link className="kayad-command-inline-link" to="/admin/staff">Manage staff <ChevronRight size={14}/></Link></section>
            <section className="kayad-command-panel" aria-labelledby="rbac-heading"><header><h2 id="rbac-heading">Role-Based Access Control</h2><Link to="/admin/staff-permissions">Manage Roles</Link></header><div className="kayad-command-role-summary">{Array.from(new Set<string>(users.map(u => (u.role || '').trim()).filter((role): role is string => Boolean(role)))).slice(0, 4).map((role: string) => <div key={role}><span>{role.replace(/_/g, ' ')}</span><b>{users.filter(u => (u.role || '').trim() === role).length}</b></div>)}</div><p className="kayad-command-data-note">{restricted.includes('user records') ? 'Role membership is restricted for this role; no counts are available here.' : 'Counts reflect only the current loaded user sample, not total role membership.'}</p><Link className="kayad-command-inline-link" to="/admin/staff-permissions">Review permissions <ChevronRight size={14}/></Link></section>
          </div>
          <aside className="kayad-command-rail" aria-label="Account and system information" data-testid="admin-right-rail">
            <section className="kayad-command-panel kayad-command-rail-panel" aria-labelledby="right-rail-account-heading">
              <header><h2 id="right-rail-account-heading">My Account</h2></header>
              <div className="kayad-command-account">
                <div className="kayad-command-avatar" aria-hidden="true">{typeof sessionUser?.name === 'string' && sessionUser.name.trim() ? sessionUser.name.trim().charAt(0).toUpperCase() : '—'}</div>
                <div className="kayad-command-account-copy">
                  <strong>{typeof sessionUser?.name === 'string' && sessionUser.name.trim() ? sessionUser.name.trim() : 'Account name unavailable'}</strong>
                  <small>{adminRoleLabel(sessionUser?.role) ?? 'Role unavailable'}</small>
                </div>
              </div>
              <nav className="kayad-command-rail-links" aria-label="Account shortcuts">
                <Link to="/admin">Operations Dashboard <ChevronRight size={14} aria-hidden="true" /></Link>
                <Link to="/admin/settings">Account Settings <ChevronRight size={14} aria-hidden="true" /></Link>
                <Link to="/admin/security-log">Audit &amp; Logs <ChevronRight size={14} aria-hidden="true" /></Link>
              </nav>
            </section>
            <section className="kayad-command-panel kayad-command-rail-panel" aria-labelledby="right-rail-department-heading">
              <header><h2 id="right-rail-department-heading">Department Overview</h2><Link to="/admin/staff">View All</Link></header>
              <div className="kayad-command-rail-summary"><Building2 size={17} aria-hidden="true" /><p className="kayad-command-empty">Department information is managed in the existing staff and departmental workspace.</p></div>
              <Link className="kayad-command-rail-primary" to="/admin/staff">Staff &amp; Departments <ChevronRight size={14} aria-hidden="true" /></Link>
            </section>
            <AdminAlertsPanel />
            <section className="kayad-command-panel kayad-command-rail-panel" aria-labelledby="right-rail-provider-heading">
              <header><h2 id="right-rail-provider-heading">Provider Status</h2><Link to="/admin/provider-governance">View All</Link></header>
              <div className="kayad-command-rail-summary"><ProvidersIcon size={17} aria-hidden="true" /><p className="kayad-command-empty">Live connectivity is not verified in this summary. Review provider governance for the available records and verification state.</p></div>
              <Link className="kayad-command-rail-primary" to="/admin/provider-governance">Providers &amp; Integrations <ChevronRight size={14} aria-hidden="true" /></Link>
            </section>
          </aside>
        </div>
      )}

      {queue && (module === 'users' || module === 'cars') && ((queue === 'pendingDealers' && module === 'users') || (queue === 'pendingVehicles' && module === 'cars')) && (
        <div className="flex items-center gap-2 text-sm text-[#0B3440]" data-testid="queue-filter">
          <Badge variant="warning">{queue === 'pendingDealers' ? 'Showing pending dealers only' : 'Showing pending vehicles only'}</Badge>
          <Button size="sm" variant="outline" onClick={() => { setQueue(null); void load(null); }}>Show all</Button>
        </div>
      )}

      {module === 'users' && (
        <Card className="min-w-0 overflow-x-auto border-[#DCE8EB]">
          <Table>
            <TableHeader><TableRow><TableHead>User</TableHead><TableHead>Role</TableHead><TableHead>Status</TableHead><TableHead>Action</TableHead></TableRow></TableHeader>
            <TableBody>
              {filteredUsers.map((u) => <TableRow key={u._id}>
                <TableCell><div className="font-bold">{u.name || 'Unnamed user'}</div><div className="text-xs text-[#64748B]">{u.email || 'No email returned'}</div></TableCell>
                <TableCell><Badge variant="neutral">{u.role || 'unknown'}</Badge></TableCell>
                <TableCell>{u.isBanned ? <Badge variant="warning">Banned</Badge> : u.status === 'pending' ? <Badge variant="warning">Pending approval</Badge> : u.status === 'rejected' ? <Badge variant="warning">Not approved</Badge> : <Badge variant="success">Active</Badge>}</TableCell>
                <TableCell><div className="flex flex-wrap gap-2">
                  {(u.role === 'dealer' || u.role === 'individual_seller') && u.status !== 'approved' && <Button size="sm" variant="primary" disabled={busyId === u._id} onClick={() => void decideSeller(u, 'approve')}><CheckCircle2 className="w-3.5 h-3.5" /> Approve</Button>}
                  {u.role === 'dealer' && u.status === 'pending' && <Button size="sm" variant="outline" disabled={busyId === u._id} onClick={() => void decideSeller(u, 'reject')}>Reject</Button>}
                  <Button size="sm" variant="outline" disabled={busyId === u._id} onClick={() => void toggleBan(u)}><Ban className="w-3.5 h-3.5" /> {u.isBanned ? 'Unban' : 'Ban'}</Button>
                </div></TableCell>
              </TableRow>)}
              {!filteredUsers.length && <TableRow><TableCell colSpan={4} className="text-center py-8 text-[#64748B]">{restricted.includes('user records') ? 'User records are restricted for this role.' : error ? 'User records are unavailable. Refresh or use an authorized workspace.' : 'No users matched the current search.'}</TableCell></TableRow>}
            </TableBody>
          </Table>
        </Card>
      )}

      {module === 'cars' && (
        <Card className="min-w-0 overflow-x-auto border-[#DCE8EB]">
          <Table>
            <TableHeader><TableRow><TableHead>Vehicle</TableHead><TableHead>Status</TableHead><TableHead>Price</TableHead><TableHead>Action</TableHead></TableRow></TableHeader>
            <TableBody>
              {filteredCars.map((c) => <TableRow key={c._id}>
                <TableCell><div className="font-bold">{c.title || 'Untitled vehicle'}</div><div className="text-xs text-[#64748B]">{c._id}</div></TableCell>
                <TableCell><Badge variant="neutral">{c.status || 'unknown'}</Badge></TableCell>
                <TableCell>{typeof c.price === 'number' ? `Ksh ${c.price.toLocaleString()}` : 'Not provided'}</TableCell>
                <TableCell><div className="flex flex-wrap gap-2">{c.status === 'pending' && <Button size="sm" variant="primary" disabled={busyId === c._id} onClick={() => void moderateListing(c, 'approve')}>Approve</Button>}{(c.status === 'pending' || c.status === 'available') && <Button size="sm" variant="outline" disabled={busyId === c._id} onClick={() => void moderateListing(c, 'hide')}>Hide</Button>}<Button size="sm" variant="outline" disabled={busyId === c._id} onClick={() => void verifyCar(c)}><FileCheck className="w-3.5 h-3.5" /> Verify</Button>{onQuickViewVehicle && <Button size="sm" variant="outline" onClick={() => { const v = vehicles.find((x) => x.id === c._id); if (v) onQuickViewVehicle(v); }}>View</Button>}</div></TableCell>
              </TableRow>)}
              {!filteredCars.length && <TableRow><TableCell colSpan={4} className="text-center py-8 text-[#64748B]">{restricted.includes('vehicle records') ? 'Vehicle records are restricted for this role.' : error ? 'Vehicle records are unavailable. Refresh or use an authorized workspace.' : 'No vehicles matched the current search.'}</TableCell></TableRow>}
            </TableBody>
          </Table>
        </Card>
      )}

      {module === 'communications' && <AdminCommunications />}

      {module === 'navigation' && <AdminNavigationControl />}
      {module === 'providers' && <AdminProviderGovernance />}
      {module === 'support' && <AdminSupportWorkspace />}
      {module === 'auctions' && <AdminAuctionVerification />}
      {module === 'onboarding' && <AdminSettingsOnboarding />}
      {module === 'owners' && isOwner && <AdminOwnerManagement />}
      {module === 'departments' && isOwner && <AdminDepartmentCapabilities />}

      {module === 'audit' && (
        <Card className="min-w-0 overflow-x-auto border-[#DCE8EB]">
          <Table>
            <TableHeader><TableRow><TableHead>Time</TableHead><TableHead>Action</TableHead><TableHead>Module</TableHead><TableHead>Target</TableHead><TableHead>Actor</TableHead></TableRow></TableHeader>
            <TableBody>
              {auditLogs.map((log, i) => <TableRow key={log._id || log.id || i}>
                <TableCell className="text-xs">{log.createdAt || log.timestamp || 'Not provided'}</TableCell>
                <TableCell className="font-semibold">{log.action || 'Unknown action'}</TableCell>
                <TableCell>{log.module || '—'}</TableCell>
                <TableCell className="font-mono text-xs">{log.targetId || '—'}</TableCell>
                <TableCell>{log.actor?.email || log.user?.email || 'Server record'}</TableCell>
              </TableRow>)}
              {!auditLogs.length && <TableRow><TableCell colSpan={5} className="text-center py-8 text-[#64748B]">{restricted.includes('audit log') ? 'Audit records are restricted for this role.' : error ? 'Audit records are unavailable. Refresh or use an authorized workspace.' : 'No audit records returned by the server.'}</TableCell></TableRow>}
            </TableBody>
          </Table>
        </Card>
      )}
    </div>
  );
};

export default AdminView;

