                  <p className="text-[11px] text-[#64748B] leading-normal">
                    Use the available contact options and confirm the seller and transaction terms before proceeding. Do not send money until the payment method and deal terms are clear.
                  </p>
                </div>

                <div className="space-y-2.5">
                  <button
                    onClick={() => {
                      setShowContactModal(false);
                      if (dealerVehicles.length > 0 && onContactSeller) {
                        onContactSeller(dealerVehicles[0]);
                      } else {
                        setToastMessage('Open the existing KAYAD messaging workflow to contact the seller.');
                      }
                    }}
                    className="w-full p-3.5 bg-[#176B87] hover:bg-[#0A3340] text-white rounded-xl font-bold flex items-center justify-between transition-colors shadow-sm text-left"
                  >
                    <div className="flex items-center gap-3">
                      <MessageSquare className="w-5 h-5 text-[#5AAFA4]" />
                      <div>
                        <p className="font-extrabold">Message seller through KAYAD</p>
                        <p className="text-[11px] text-[#BDE5DE]">Response times and message security depend on the available service and account settings.</p>
                      </div>
                    </div>
                    <ChevronRight className="w-4 h-4 text-[#5AAFA4]" />
                  </button>

                  <button
                    onClick={() => {
                      setShowContactModal(false);
                      if (dealerVehicles.length > 0) {
                        onStartEscrow(dealerVehicles[0]);
                      } else {
                        setToastMessage('Escrow is arranged when you buy a listing that shows the Escrow badge.');
                      }
                    }}
                    className="w-full p-3.5 bg-[#176B87] hover:bg-[#12576d] text-white rounded-xl font-bold flex items-center justify-between transition-colors shadow-sm text-left"
                  >
                    <div className="flex items-center gap-3">
                      <Lock className="w-5 h-5 text-[#5AAFA4]" />
                      <div>
                        <p className="font-extrabold">Review escrow options</p>
                        <p className="text-[11px] text-[#91CEC5]">Check the current programme status and the terms for the specific eligible listing.</p>
                      </div>
                    </div>
                    <ChevronRight className="w-4 h-4 text-[#5AAFA4]" />
                  </button>

                  <button
                    onClick={() => {
                      setShowContactModal(false);
                      if (dealerVehicles.length > 0 && onQuickViewVehicle) {
                        onQuickViewVehicle(dealerVehicles[0]);
                      }
                    }}
                    className="w-full p-3.5 bg-emerald-50 hover:bg-emerald-100 border border-emerald-200 text-emerald-950 rounded-xl font-bold flex items-center justify-between transition-colors text-left"
                  >
                    <div className="flex items-center gap-3">
                      <FileCheck className="w-5 h-5 text-emerald-600" />
                      <div>
                        <p className="font-extrabold">Book an independent inspection</p>
                        <p className="text-[11px] text-emerald-800">Confirm provider status, scope and pricing before booking</p>
                      </div>
                    </div>
                    <ChevronRight className="w-4 h-4 text-emerald-600" />
                  </button>
                </div>
              </>
            ) : (
              <>
                <p className="text-[#64748B]">Contact the sales team at {dealer.name}:</p>

                <div className="space-y-2.5">
                  <a
                    href={`tel:${dealer.phone}`}
                    className="p-3.5 bg-emerald-50 hover:bg-emerald-100 border border-emerald-200 rounded-xl font-bold text-emerald-950 flex items-center justify-between transition-colors"
                  >
                    <div className="flex items-center gap-3">
                      <Phone className="w-5 h-5 text-emerald-600" />
                      <div>
                        <p className="font-extrabold">Official Telephone</p>
                        <p className="text-[11px] text-emerald-800">{dealer.phone}</p>
                      </div>
                    </div>
                    <ChevronRight className="w-4 h-4 text-emerald-600" />
                  </a>

                  <a
                    href={`https://wa.me/${dealer.phone.replace(/[^0-9]/g, '')}`}
                    target="_blank"
                    rel="noreferrer"
                    className="p-3.5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-xl font-bold flex items-center justify-between transition-colors shadow-sm"
                  >
                    <div className="flex items-center gap-3">
                      <MessageSquare className="w-5 h-5" />
                      <div>
                        <p className="font-extrabold">WhatsApp inquiry</p>
                        <p className="text-[11px] text-emerald-100">Response time depends on the seller.</p>
                      </div>
                    </div>
                    <ChevronRight className="w-4 h-4" />
                  </a>

                  <a
                    href={`mailto:${dealer.email}`}
                    className="p-3.5 bg-[#F6FAF9] hover:bg-[#EEF7F5] border border-[#D7E7E4] rounded-xl font-bold text-[#176B87] flex items-center justify-between transition-colors"
                  >
                    <div className="flex items-center gap-3">
                      <Mail className="w-5 h-5 text-[#64748B]" />
                      <div>
                        <p className="font-extrabold">Official Email Inquiry</p>
                        <p className="text-[11px] text-[#64748B]">{dealer.email}</p>
                      </div>
                    </div>
                    <ChevronRight className="w-4 h-4 text-[#94A3B8]" />
                  </a>
                </div>
              </>
            )}
          </div>
        </Modal>
      )}

      {/* ========================================================================= */}
      {/* SUB-MODAL 2: BOOK TEST DRIVE FORM */}
      {/* ========================================================================= */}
      {showTestDriveModal && (
        <Modal isOpen={true} onClose={() => setShowTestDriveModal(false)} title={`Book Test Drive with ${dealer.name}`} maxWidth="md">
          <div className="space-y-4 p-4 text-sm text-[#12576D]">
            <p className="rounded-xl border border-[#D7E7E4] bg-[#F6FAF9] p-4 leading-relaxed">
              Test-drive scheduling is not connected to a booking service here. No request has been sent and no appointment is reserved. Contact the seller to agree availability, location and terms directly.
            </p>
            <Button variant="primary" size="lg" fullWidth onClick={() => { setShowTestDriveModal(false); setShowContactModal(true); }} className="bg-[#176B87] text-white">
              Contact seller to arrange a test drive
            </Button>
          </div>
        </Modal>
      )}

      {/* ========================================================================= */}
      {/* SUB-MODAL 3: DIRECTIONS / MAP */}
      {/* ========================================================================= */}
      {showDirectionsModal && (
        <Modal isOpen={true} onClose={() => setShowDirectionsModal(false)} title={`Directions to ${dealer.name}`} maxWidth="md">
          <div className="space-y-4 p-2 text-xs">
            <div className="p-4 bg-[#176B87] text-white rounded-2xl space-y-2">
              <p className="font-extrabold text-sm flex items-center gap-1.5 text-[#5AAFA4]">
                <MapPin className="w-4 h-4" /> Yard Address:
              </p>
              <p className="text-[#EEF7F5] text-xs">{dealer.address || `${dealer.location} (${dealer.county})`}</p>
              {dealer.landmark && (
                <p className="text-[11px] text-[#5AAFA4] font-bold border-t border-white/20 pt-2">
                  Landmark: {dealer.landmark}
                </p>
              )}
            </div>

            <a
              href={`https://maps.google.com/?q=${encodeURIComponent(dealer.address || dealer.location)}`}
              target="_blank"
              rel="noreferrer"
              className="p-3.5 bg-emerald-600 text-white rounded-xl font-extrabold flex items-center justify-center gap-2 hover:bg-emerald-700 transition-colors"
            >
              <Navigation className="w-4 h-4" /> Open in Google Maps
            </a>
          </div>
        </Modal>
      )}

      {/* ========================================================================= */}
      {/* SUB-MODAL 4: FULLSCREEN GALLERY LIGHTBOX */}
      {/* ========================================================================= */}
      {activeGalleryImage && (
        <div className="fixed inset-0 z-50 bg-[#0A3340]/90 backdrop-blur-md flex items-center justify-center p-4">
          <button
            onClick={() => setActiveGalleryImage(null)}
            className="absolute top-4 right-4 text-white p-2 rounded-full bg-white/10 hover:bg-white/20"
          >
            <X className="w-6 h-6" />
          </button>
          <img src={activeGalleryImage} alt="Showroom Lightbox" className="max-w-full max-h-[85vh] rounded-2xl object-contain shadow-2xl" />
        </div>
      )}

    </Modal>
  );
};

export default DealerProfileModal;

import React, { useState, useMemo } from 'react';
import { Dealer, Vehicle } from '../../../types';
import { Building2, ShieldCheck, MapPin, Star, ExternalLink, Search, Phone, Mail, CheckCircle2, UserCheck, Sparkles, Filter, Crown } from 'lucide-react';
import { PageHeader, Card, Badge, Button, Input, LazyImage } from '../../../components/ui';
import DealerProfileModal from './DealerProfileModal';
import DealerBusinessView from './DealerBusinessView';

interface DealersViewProps {
  dealers: Dealer[];
  vehicles: Vehicle[];
  onSelectDealerVehicles: (dealerName: string) => void;
  onQuickViewVehicle?: (v: Vehicle) => void;
  onStartEscrow?: (v: Vehicle) => void;
  onAddVehicle?: (v: Vehicle) => void;
}

export const DealersView: React.FC<DealersViewProps> = ({
  dealers,
  vehicles,
  onSelectDealerVehicles,
  onQuickViewVehicle = () => {},
  onStartEscrow = () => {},
  onAddVehicle
}) => {
  const [viewMode, setViewMode] = useState<'platform' | 'directory'>('platform');
  const [dealerSearch, setDealerSearch] = useState<string>('');
  const [selectedCounty, setSelectedCounty] = useState<string>('All');
  const [sellerTypeFilter, setSellerTypeFilter] = useState<'All' | 'Enterprise Dealer' | 'Private Seller'>('All');
  const [activeProfileDealer, setActiveProfileDealer] = useState<Dealer | null>(null);

  const filteredDealers = useMemo(() => {
    return dealers.filter((d) => {
      // Filter seller type
      if (sellerTypeFilter !== 'All') {
        if (sellerTypeFilter === 'Enterprise Dealer' && d.type === 'Private Seller') return false;
        if (sellerTypeFilter === 'Private Seller' && d.type !== 'Private Seller') return false;
      }
      // Filter county
      if (selectedCounty !== 'All' && d.county !== selectedCounty) return false;
      // Filter search
      if (dealerSearch) {
        const q = dealerSearch.toLowerCase().trim();
        return (
          d.name.toLowerCase().includes(q) ||
          d.location.toLowerCase().includes(q) ||
          d.county.toLowerCase().includes(q)
        );
      }
      return true;
    });
  }, [dealers, dealerSearch, selectedCounty, sellerTypeFilter]);

  return (
    <div className="space-y-6">
      {/* Top View Toggle */}
      <div className="bg-white p-2 rounded-2xl shadow-card border border-[#D7E7E4] flex items-center justify-between gap-4 overflow-x-auto">
        <div className="flex items-center gap-2">
          <button
            onClick={() => setViewMode('platform')}
            className={`px-5 py-3 rounded-xl text-xs font-black flex items-center gap-2 transition-all cursor-pointer whitespace-nowrap ${
              viewMode === 'platform'
                ? 'bg-[#176B87] text-white shadow-md'
                : 'text-[#64748B] hover:bg-[#EEF7F5]'
            }`}
          >
            <Crown className="w-4 h-4 text-[#13B8A6]" />
            <span>Dealer Business Platform & Sales Suite</span>
            <Badge variant="accent" size="sm">MANAGEMENT CONSOLE</Badge>
          </button>

          <button
            onClick={() => setViewMode('directory')}
            className={`px-5 py-3 rounded-xl text-xs font-black flex items-center gap-2 transition-all cursor-pointer whitespace-nowrap ${
              viewMode === 'directory'
                ? 'bg-[#176B87] text-white shadow-md'
                : 'text-[#64748B] hover:bg-[#EEF7F5]'
            }`}
          >
            <Building2 className="w-4 h-4 text-emerald-500" />
            <span>Public Dealer Directory & Showrooms</span>
          </button>
        </div>
      </div>

      {viewMode === 'platform' ? (
        <DealerBusinessView
          vehicles={vehicles}
          onAddVehicle={onAddVehicle}
          onQuickViewVehicle={onQuickViewVehicle}
          onStartEscrow={onStartEscrow}
        />
      ) : (
        <div className="space-y-6">
          {/* Header Banner */}
          <PageHeader
            badgeIcon={<Building2 className="w-4 h-4 text-[#176B87]" />}
            badgeText="Verified Seller & Dealership Directory"
            title="Trusted Showrooms & Verified Private Sellers"
            description="Every enterprise dealership and private individual seller on KAYAD is verified by KAYAD, with escrow available on approved listings."
            rightElement={
              <Badge variant="success" size="md">
                <ShieldCheck className="w-4 h-4 text-emerald-600" /> 100% Audited Sellers
              </Badge>
            }
          />

      {/* Seller Type Tabs */}
      <div className="flex items-center gap-2 border-b border-[#D7E7E4] overflow-x-auto pb-2 scrollbar-none">
        {[
          { id: 'All', label: 'All Verified Sellers', icon: <Sparkles className="w-4 h-4 text-[#176B87]" /> },
          { id: 'Enterprise Dealer', label: 'Verified Enterprise Dealerships', icon: <Building2 className="w-4 h-4 text-[#176B87]" /> },
          { id: 'Private Seller', label: 'Verified Private Individual Owners', icon: <UserCheck className="w-4 h-4 text-emerald-600" /> }
        ].map((tab) => (
          <button
            key={tab.id}
            onClick={() => setSellerTypeFilter(tab.id as any)}
            className={`px-4 py-2.5 rounded-xl text-xs font-extrabold flex items-center gap-2 transition-all whitespace-nowrap ${
              sellerTypeFilter === tab.id
                ? 'bg-[#176B87] text-white shadow-md'
                : 'bg-white text-[#64748B] hover:bg-[#EEF7F5] border border-[#D7E7E4]'
            }`}
          >
            {tab.icon}
            {tab.label}
          </button>
        ))}
      </div>

      {/* Filter & Search Bar */}
      <div className="bg-white rounded-2xl p-4 shadow-card border border-[#D7E7E4] flex flex-col sm:flex-row items-center justify-between gap-3">
        <div className="flex-1 w-full">
          <Input
            placeholder="Search dealership, seller name, or yard location (e.g. Crown Motors, Westlands, Nyali)..."
            value={dealerSearch}
            onChange={(e) => setDealerSearch(e.target.value)}
            icon={<Search className="w-4 h-4" />}
          />
        </div>

        <div className="flex items-center gap-2 text-xs font-medium bg-[#F6FAF9] px-3.5 py-2.5 rounded-xl border border-[#D7E7E4] shrink-0">
          <Filter className="w-3.5 h-3.5 text-[#94A3B8]" />
          <span>County:</span>
          <select
            value={selectedCounty}
            onChange={(e) => setSelectedCounty(e.target.value)}
            className="bg-transparent font-bold text-[#176B87] focus:outline-none cursor-pointer"
          >
            <option value="All">All Counties</option>
            <option value="Nairobi">Nairobi</option>
            <option value="Mombasa">Mombasa</option>
            <option value="Nakuru">Nakuru</option>
            <option value="Kiambu">Kiambu</option>
          </select>
        </div>
      </div>

      {/* Seller Cards Grid */}
      {filteredDealers.length === 0 ? (
        <Card className="p-8 text-center space-y-3">
          <Building2 className="w-10 h-10 text-[#BDE5DE] mx-auto" />
          <p className="font-bold text-[#12576D]">No verified sellers match your selected criteria</p>
          <p className="text-xs text-[#64748B]">Try broadening your search or resetting county filters.</p>
          <Button
            variant="outline"
            size="sm"
            onClick={() => { setDealerSearch(''); setSelectedCounty('All'); setSellerTypeFilter('All'); }}
          >
            Reset All Filters
          </Button>
        </Card>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredDealers.map((d) => {
            const isPrivate = d.type === 'Private Seller';
            return (
              <Card
                key={d.id}
                className="p-6 flex flex-col justify-between space-y-4 hover:border-[#91CEC5] transition-all border border-[#D7E7E4]"
              >
                <div className="space-y-3">
                  {/* Logo / Avatar & Rating Badge */}
                  <div className="flex items-start justify-between gap-3">
                    <LazyImage
                      src={d.logo}
                      alt={d.name}
                      wrapperClassName={`w-14 h-14 rounded-2xl border-2 shadow-sm ${
                        isPrivate ? 'border-emerald-300' : 'border-[#BDE5DE]'
                      }`}
                      className="w-full h-full object-cover"
                    />
                    <Badge variant="warning" size="md">
                      <Star className="w-3.5 h-3.5 fill-current text-[#176B87]" /> {d.rating} ({d.reviewsCount} reviews)
                    </Badge>
                  </div>

                  {/* Dealer / Seller Title & Distinction */}
                  <div>
                    <div className="flex items-center gap-1.5 mb-1">
                      <Badge variant={isPrivate ? "neutral" : "verified"} size="sm">
                        {isPrivate ? (
                          <UserCheck className="w-3 h-3 text-emerald-600 shrink-0" />
                        ) : (
                          <Building2 className="w-3 h-3 text-[#13B8A6] shrink-0" />
                        )}
                        {d.type || (isPrivate ? 'Private Seller' : 'Enterprise Dealer')}
                      </Badge>
                    </div>

                    <h3 className="text-lg font-extrabold text-[#176B87] font-display">{d.name}</h3>
                    <p className="text-xs text-[#64748B] font-medium flex items-center gap-1 mt-1">
                      <MapPin className="w-3.5 h-3.5 text-[#176B87] shrink-0" /> {d.location} ({d.county})
                    </p>
                  </div>

                  {/* Badges */}
                  <div className="flex flex-wrap gap-1 pt-1">
                    {d.badges.map((b, i) => (
                      <Badge key={i} variant="neutral" size="sm">
                        ✓ {b}
                      </Badge>
                    ))}
                  </div>

                  {/* Seller Bio / Description */}
                  {d.description && (
                    <p className="text-xs text-[#64748B] line-clamp-2 bg-[#F6FAF9] p-2.5 rounded-xl border border-[#D7E7E4] italic">
                      "{d.description}"
                    </p>
                  )}

                  {/* Trust & Response Stats */}
                  <div className="space-y-1 text-xs text-[#64748B] pt-2 border-t border-[#D7E7E4]">
                    <p className="flex items-center gap-1.5 font-medium">
                      <Phone className="w-3.5 h-3.5 text-[#94A3B8]" /> {d.phone}
                    </p>
                    <p className="flex items-center gap-1.5 font-medium">
                      <Mail className="w-3.5 h-3.5 text-[#94A3B8]" /> {d.email}
                    </p>
                    <p className="flex items-center gap-1.5 font-bold text-[#12576D]">
                      <CheckCircle2 className="w-3.5 h-3.5 text-emerald-600" /> Avg Response Time: {d.responseTime || '< 15 mins'}
                    </p>
                  </div>
                </div>

                {/* Footer CTAs */}
                <div className="pt-3 border-t border-[#D7E7E4] space-y-3 text-xs">
                  <div className="flex justify-between items-center bg-[#F6FAF9] p-2.5 rounded-xl border border-[#D7E7E4]">
                    <span className="text-[#64748B] font-bold">Showroom Inventory:</span>
                    <span className="font-extrabold text-[#176B87] bg-[#DDF4F0] text-[#0A3340] px-2.5 py-0.5 rounded-md">
                      {d.activeListingsCount} Vehicles
                    </span>
                  </div>

                  <div className="grid grid-cols-2 gap-2">
                    <Button
                      variant="secondary"
                      size="md"
                      onClick={() => setActiveProfileDealer(d)}
                    >
                      <span>View Profile</span>
                    </Button>

                    <Button
                      variant="primary"
                      size="md"
                      onClick={() => onSelectDealerVehicles(d.name)}
                    >
                      <span>Show Stock</span>
                      <ExternalLink className="w-3.5 h-3.5 text-[#13B8A6]" />
                    </Button>
                  </div>
                </div>
              </Card>
            );
          })}
        </div>
      )}

      {/* Interactive Dealer Profile Modal */}
      <DealerProfileModal
        dealer={activeProfileDealer}
        allDealers={dealers}
        vehicles={vehicles}
        onClose={() => setActiveProfileDealer(null)}
        onQuickViewVehicle={onQuickViewVehicle}
        onStartEscrow={onStartEscrow}
      />
        </div>
      )}
    </div>
  );
};

export default DealersView;

