import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { AlertCircle, CheckCircle2, ChevronLeft, ChevronRight, Clock, CreditCard, RefreshCw, XCircle } from 'lucide-react';
import { getMyPayments, getPaymentStatus, BackendPayment } from '../services/paymentApi';
import { Button, Card, PageHeader } from '../components/ui';
import { AuctionExperienceRail } from '../components/auction/AuctionExperienceRail';
import { AuctionFulfilmentTimeline } from '../components/auction/AuctionPremiumSurface';

type PaymentStatus = 'pending' | 'success' | 'failed' | 'cancelled' | 'released' | 'refunded' | 'not_found';
type VehicleDetails = { title?: string; brand?: string; model?: string; year?: number };
const FILTERS: Array<{ label: string; value: PaymentStatus | '' }> = [{ label: 'All', value: '' }, { label: 'Completed', value: 'success' }, { label: 'Pending', value: 'pending' }, { label: 'Failed', value: 'failed' }, { label: 'Refunded', value: 'refunded' }];
const money = (amount?: number) => `KES ${Number(amount || 0).toLocaleString('en-KE', { maximumFractionDigits: 2 })}`;
const statusMeta = (status?: PaymentStatus) => status === 'success' || status === 'released' ? { label: status === 'released' ? 'Released' : 'Completed', Icon: CheckCircle2, className: 'text-emerald-700 bg-emerald-50' } : status === 'pending' ? { label: 'Pending', Icon: Clock, className: 'text-[#12576D] bg-[#F3FAF9]' } : status === 'cancelled' ? { label: 'Cancelled', Icon: XCircle, className: 'text-[#64748B] bg-[#EEF7F5]' } : status === 'refunded' ? { label: 'Refunded', Icon: RefreshCw, className: 'text-[#12576D] bg-[#F3FAF9]' } : { label: 'Failed', Icon: AlertCircle, className: 'text-rose-700 bg-rose-50' };

export default function PaymentHistoryView() {
  const [payments, setPayments] = useState<BackendPayment[]>([]);
  const [filter, setFilter] = useState<PaymentStatus | ''>('');
  const [page, setPage] = useState(1);
  const [pages, setPages] = useState(1);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const load = useCallback(async (nextPage = page, nextFilter = filter, background = false) => {
    if (background) setRefreshing(true); else setLoading(true);
    setError(null);
    try { const result = await getMyPayments({ page: nextPage, limit: 10, ...(nextFilter ? { status: nextFilter } : {}) }); setPayments(result.payments || []); setTotal(result.pagination?.total || 0); setPages(Math.max(1, result.pagination?.pages || 1)); }
    catch (err: any) { setError(err?.message || 'Could not load your payment history.'); }
    finally { setLoading(false); setRefreshing(false); }
  }, [filter, page]);
  useEffect(() => { void load(page, filter); }, [load, page, filter]);
  const pending = useMemo(() => payments.filter((p) => p.status === 'pending'), [payments]);
  const completed = useMemo(() => payments.filter((p) => p.status === 'success'), [payments]);
  const completedAmount = useMemo(() => completed.reduce((sum, p) => sum + Number(p.amount || 0), 0), [completed]);
  const refreshPending = async () => {
    await Promise.all(pending.filter((p) => p.checkoutRequestId).map(async (p) => { try { await getPaymentStatus(p.checkoutRequestId as string); } catch {} }));
    void load(page, filter, true);
  };
  return <div className="auction-payment-experience space-y-6">
    <AuctionExperienceRail current="payment" />
    <section className="auction-wallet-shell">
      <div className="auction-wallet-grid">
        <div><span className="auction-wallet-kicker">BIDDER WALLET & SETTLEMENT</span><h2 className="auction-wallet-title">Every payment, one calm place.</h2><p className="auction-wallet-copy">Track live payment status, receipts and settlement activity from the same journey that brought you into the auction room.</p></div>
        <div className="auction-wallet-metric"><span>Records loaded</span><strong>{total}</strong></div>
        <div className="auction-wallet-metric"><span>Pending</span><strong>{pending.length}</strong></div>
        <div className="auction-wallet-metric"><span>Completed</span><strong>{completed.length}</strong></div>
      </div>
      <div className="auction-wallet-links"><button type="button" onClick={() => window.location.href='/?nav=auctions'}>Return to auctions</button><button type="button" onClick={() => window.location.href='/?nav=profile'}>Open bidder profile</button></div>
    </section>
    <section className="auction-history-card">
      <div style={{ padding: '18px 18px 10px' }}><span className="auction-xp-overline">AFTER SETTLEMENT</span><h3 style={{ fontFamily: 'var(--font-display)', fontSize: 20, letterSpacing: '-.035em', color: '#0a3340', margin: '4px 0 2px' }}>The rest of the journey stays visible.</h3><p style={{ fontSize: 10, color: '#82949a', margin: 0 }}>Collection, ownership transfer and completion appear here as KAYAD records each stage.</p></div>
      <div className="auction-history-row auction-touch-card"><div className="auction-history-icon"><CheckCircle2 size={16} /></div><div><div className="auction-history-title">Settlement confirmed</div><div className="auction-history-meta">Payment receipt and settlement state</div></div><div className="auction-history-status">{completed.length ? 'Activity available' : 'Awaiting payment'}</div></div>
      <div className="auction-history-row auction-touch-card"><div className="auction-history-icon"><CreditCard size={16} /></div><div><div className="auction-history-title">Collection & transfer</div><div className="auction-history-meta">Dealer fulfilment milestones</div></div><div className="auction-history-status">Tracked in fulfilment</div></div>
      <div className="auction-history-row auction-touch-card"><div className="auction-history-icon"><Clock size={16} /></div><div><div className="auction-history-title">Auction history</div><div className="auction-history-meta">Your completed auction trail</div></div><div className="auction-history-status">Always available</div></div>
    </section>
    <AuctionFulfilmentTimeline steps={[{ label: 'Auction won', detail: 'Outcome recorded', state: 'complete' }, { label: 'Settlement', detail: completed.length ? 'Payment activity recorded' : 'Awaiting payment', state: completed.length ? 'complete' : 'current' }, { label: 'Collection', detail: 'Dealer fulfilment', state: 'pending' }, { label: 'Transfer', detail: 'Ownership completion', state: 'pending' }]} />
    <PageHeader badgeText="Payments" title="Payment History" description="Your real KAYAD payment records and M-Pesa transaction status." />
    <div className="grid grid-cols-1 sm:grid-cols-3 gap-4"><Card className="p-5"><p className="text-xs font-semibold text-[#64748B]">Successful on this page</p><p className="text-2xl font-black text-[#176B87] mt-1">{money(completedAmount)}</p></Card><Card className="p-5"><p className="text-xs font-semibold text-[#64748B]">Completed records</p><p className="text-2xl font-black text-[#176B87] mt-1">{completed.length}</p></Card><Card className="p-5"><p className="text-xs font-semibold text-[#64748B]">Pending records</p><p className="text-2xl font-black text-[#176B87] mt-1">{pending.length}</p></Card></div>
    <Card className="overflow-hidden"><div className="p-4 border-b border-[#D7E7E4] flex flex-wrap items-center justify-between gap-3"><div className="flex flex-wrap gap-2">{FILTERS.map((item) => <button key={item.value || 'all'} onClick={() => { setPage(1); setFilter(item.value); }} className={`px-3 py-1.5 rounded-lg text-xs font-bold ${filter === item.value ? 'bg-[#176B87] text-white' : 'bg-[#EEF7F5] text-[#64748B]'}`}>{item.label}</button>)}</div><Button variant="outline" onClick={refreshPending} disabled={refreshing || loading}><RefreshCw className={`w-4 h-4 mr-2 ${refreshing ? 'animate-spin' : ''}`} /> Refresh status</Button></div>
      {loading ? <div className="p-10 text-center text-sm text-[#64748B]">Loading your payment history…</div> : error ? <div className="p-10 text-center"><AlertCircle className="w-8 h-8 mx-auto text-rose-500 mb-2" /><p className="text-sm text-[#64748B]">{error}</p><Button className="mt-4" onClick={() => void load(page, filter)}>Try again</Button></div> : payments.length === 0 ? <div className="p-12 text-center"><CreditCard className="w-9 h-9 mx-auto text-[#BDE5DE] mb-3" /><p className="font-bold text-[#12576D]">No payment records found</p><p className="text-sm text-[#64748B] mt-1">Completed and pending payments will appear here after the backend records them.</p></div> : <div className="divide-y divide-[#D7E7E4]">{payments.map((payment) => { const meta = statusMeta(payment.status); const vehicleDetails = payment.carDetails as VehicleDetails | null | undefined; const vehicle = vehicleDetails?.title || [vehicleDetails?.brand, vehicleDetails?.model, vehicleDetails?.year].filter(Boolean).join(' ') || 'Vehicle payment'; return <div key={payment.id} className="p-4 flex flex-col md:flex-row md:items-center gap-4 justify-between"><div className="min-w-0"><p className="font-bold text-[#0A3340] truncate">{vehicle}</p><p className="text-xs text-[#64748B] mt-1">{payment.type || 'payment'} · {payment.createdAt ? new Date(payment.createdAt).toLocaleString() : 'Date unavailable'}</p>{payment.mpesaReceipt && <p className="text-xs text-[#64748B] mt-1">M-Pesa receipt: <span className="font-semibold">{payment.mpesaReceipt}</span></p>}</div><div className="text-right"><p className="font-black text-[#176B87]">{money(payment.amount)}</p><span className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-[10px] font-bold ${meta.className}`}><meta.Icon className="w-3 h-3" />{meta.label}</span></div></div>; })}</div>}
      {!loading && !error && payments.length > 0 && <div className="p-4 border-t border-[#D7E7E4] flex items-center justify-between text-xs text-[#64748B]"><span>{total} record{total === 1 ? '' : 's'}</span><div className="flex items-center gap-2"><button disabled={page <= 1} onClick={() => setPage((v) => v - 1)} className="p-2 rounded-lg border disabled:opacity-40"><ChevronLeft className="w-4 h-4" /></button><span>Page {page} of {pages}</span><button disabled={page >= pages} onClick={() => setPage((v) => v + 1)} className="p-2 rounded-lg border disabled:opacity-40"><ChevronRight className="w-4 h-4" /></button></div></div>}
    </Card>
  </div>;
}

