      <div className="grid md:grid-cols-3 gap-4">
        {['National ID', 'Email', 'NTSA TIMS Logbook'].map((label) => (
          <div key={label} className="p-4 rounded-xl bg-white border border-[#D7E7E4] flex items-center justify-between">
