interface AuctionDiscoveryNetworkProps {
  user?: UserProfile | null;
  onOpenAuth?: () => void;
}

const AuctionDiscoveryNetwork: React.FC<AuctionDiscoveryNetworkProps> = ({ user, onOpenAuth }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [liveAuctions, setLiveAuctions] = useState<Auction[]>([]);
  const [upcomingAuctions, setUpcomingAuctions] = useState<Auction[]>([]);
  const [completedAuctions, setCompletedAuctions] = useState<Auction[]>([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [watchingId, setWatchingId] = useState<string | null>(null);
  const [favoritePreferences, setFavoritePreferences] = useState<{ brands: string[]; locations: string[] }>({ brands: [], locations: [] });

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setLoadError(null);
    Promise.all([
      getCars({ limit: 50, auctionStatus: 'live' }),
      getCars({ limit: 50, auctionStatus: 'draft' }),
      getCars({ limit: 20, auctionStatus: 'ended' }),
    ])
      .then(([live, upcoming, ended]) => {
        if (cancelled) return;
        setLiveAuctions((live.data || []).map(mapCarToAuction));
        setUpcomingAuctions((upcoming.data || []).map(mapCarToAuction));
        setCompletedAuctions((ended.data || []).map(mapCarToAuction));
      })
      .catch(() => {
        if (!cancelled) setLoadError('Could not load auctions. Please try again.');
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => { cancelled = true; };
  }, []);

  useEffect(() => {
    let cancelled = false;
    if (!user) {
      setFavoritePreferences({ brands: [], locations: [] });
      return () => { cancelled = true; };
    }
    getFavorites({ page: 1, limit: 50 }).then((result) => {
      if (cancelled) return;
      const brands = new Set<string>();
      const locations = new Set<string>();
      (result.favorites || []).forEach((favorite) => {
        if (favorite.brand) brands.add(favorite.brand.toLowerCase());
        if (favorite.location) locations.add(favorite.location.toLowerCase());
      });
      setFavoritePreferences({ brands: [...brands], locations: [...locations] });
    }).catch(() => {
      if (!cancelled) setFavoritePreferences({ brands: [], locations: [] });
    });
    return () => { cancelled = true; };
  }, [user]);

  const searchLower = searchQuery.trim().toLowerCase();
  const filterBySearch = (a: Auction) => !searchLower || a.vehicle.title.toLowerCase().includes(searchLower) || a.vehicle.location.toLowerCase().includes(searchLower);

  const filteredLive = liveAuctions.filter(filterBySearch);
  const filteredUpcoming = upcomingAuctions.filter(filterBySearch);
  const filteredCompleted = completedAuctions.filter(filterBySearch);

  const nextAuctionTime = upcomingAuctions.length > 0 && upcomingAuctions[0].startsAt
    ? formatTimeRemaining(upcomingAuctions[0].startsAt)
    : 'N/A';
  const totalBids = liveAuctions.reduce((sum, a) => sum + a.bidsCount, 0);
  const personalizedAuctions = [...liveAuctions, ...upcomingAuctions]
    .map((auction) => {
      const brand = auction.vehicle.brand?.toLowerCase() || '';
      const location = auction.vehicle.location?.toLowerCase() || '';
      const score = (favoritePreferences.brands.some((value) => brand.includes(value) || value.includes(brand)) ? 3 : 0)
        + (favoritePreferences.locations.some((value) => location.includes(value) || value.includes(location)) ? 2 : 0)
        + (auction.status === 'live' ? 1 : 0);
      return { auction, score };
    })
    .sort((a, b) => b.score - a.score)
    .map(({ auction }) => ({ id: auction.id, title: auction.vehicle.title, image: auction.vehicle.image, currentBid: auction.currentBid || auction.startingBid, location: auction.vehicle.location }));

  return (
    <div className="min-h-screen bg-[#EEF7F5]">
      <HeroSummary
        liveCount={liveAuctions.length}
        scheduledCount={upcomingAuctions.length}
        totalBidsToday={totalBids}
        nextAuctionTime={nextAuctionTime}
      />

      <div className="sticky top-0 z-40 bg-white border-b border-[#D7E7E4] shadow-sm">
        <div className="max-w-7xl mx-auto px-4 py-3">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-5 h-5 text-[#94A3B8]" />
            <input
              type="text"
              placeholder="Search auctions by vehicle or location..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2.5 bg-[#F6FAF9] border border-[#D7E7E4] rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-[#176B87]/30"
            />
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto px-4 py-8 space-y-12">
        {loading ? (
          <div className="py-20 text-center text-[#94A3B8]">
            <Loader2 className="w-8 h-8 mx-auto mb-2 animate-spin" />
            <p className="text-sm">Loading auctions…</p>
          </div>
        ) : loadError ? (
          <div className="py-20 text-center text-rose-500">
            <AlertCircle className="w-8 h-8 mx-auto mb-2" />
            <p className="text-sm">{loadError}</p>
          </div>
        ) : (
          <>
            {/* Live Now */}
            <section>
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-2xl font-black text-[#176B87] flex items-center gap-2">
                  <Radio className="w-5 h-5 text-red-500" /> Live Now
                </h2>
                <span className="text-xs text-[#64748B]">{filteredLive.length} active auctions</span>
              </div>
              {filteredLive.length === 0 ? (
                <p className="text-sm text-[#94A3B8] py-6 text-center">No live auctions right now. Check back soon.</p>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {filteredLive.map((a) => (
                    <LiveAuctionCard key={a.id} auction={a} onWatch={() => setWatchingId(a.id)} />
                  ))}
                </div>
              )}
            </section>

            {/* Starting Soon */}
            <section>
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-2xl font-black text-[#176B87]">Starting Soon</h2>
                <span className="text-xs text-[#64748B]">Beginning soon</span>
              </div>
              {filteredUpcoming.length === 0 ? (
                <p className="text-sm text-[#94A3B8] py-6 text-center">No upcoming auctions scheduled right now.</p>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {filteredUpcoming.map((a) => <UpcomingAuctionCard key={a.id} auction={a} />)}
                </div>
              )}
            </section>

            {/* Recently Completed */}
            <section>
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-2xl font-black text-[#176B87]">Recently Completed</h2>
              </div>
              {filteredCompleted.length === 0 ? (
                <p className="text-sm text-[#94A3B8] py-6 text-center">No completed auctions to show yet.</p>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {filteredCompleted.map((a) => <CompletedAuctionCard key={a.id} auction={a} />)}
                </div>
              )}
            </section>

            <AuctionRecommendationStrip
              auctions={personalizedAuctions}
              title={favoritePreferences.brands.length || favoritePreferences.locations.length ? 'Picked from what you save' : 'Your next auction shortlist'}
            />

            {/* Auction Learning Center - static, informational content */}
            <section>
              <div className="flex items-center gap-2 mb-4">
                <BookOpen className="w-5 h-5 text-emerald-600" />
                <h2 className="text-2xl font-black text-[#176B87]">Auction Learning Center</h2>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {LEARNING_ARTICLES.map((a) => <LearningArticleCard key={a.id} article={a} />)}
              </div>
            </section>
          </>
        )}
      </div>

      <NewsletterSection />

      {watchingId && (
        <WatchLiveModal
          auctionId={watchingId}
          user={user}
          onClose={() => setWatchingId(null)}
          onOpenAuth={onOpenAuth}
        />
      )}
    </div>
  );
};

export default AuctionDiscoveryNetwork;

