                    </div>
                    {!editingField && (
                      <button onClick={() => handleEdit('phone', user.phone || '')} className="text-[#176B87] text-sm font-semibold hover:text-[#12576D]">Edit</button>
                    )}
                  </div>

                  <div className="flex items-center gap-4 p-4 bg-[#F6FAF9] rounded-xl">
