              </div>
              <button className="flex items-center gap-2 px-4 py-2 border border-[#BDE5DE] rounded-lg hover:bg-[#F6FAF9]">
                <Filter className="h-5 w-5" />
                Filters
              </button>
            </div>
            <div className="flex items-center gap-2">
              <button
