import { useState, useEffect } from 'react';
import { adsAPI } from '../../api/api';
import { Megaphone } from 'lucide-react';

const PLACEMENTS = [
  { value: 'navbar_banner', label: 'Navbar Banner' },
  { value: 'homepage_banner', label: 'Homepage Banner' },
  { value: 'auction_sidebar', label: 'Auction Sidebar' },
  { value: 'sneak_peek_top', label: 'Sneak Peek Top' },
  { value: 'bid_modal', label: 'Bid Modal' },
];

const emptyForm = () => ({
  clientName: '',
  imageUrl: '',
  targetLink: '',
  placement: 'navbar_banner',
  isActive: true,
});

export default function AdManager() {
  const [ads, setAds] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState(emptyForm());
  const [editing, setEditing] = useState(null);
  const [saving, setSaving] = useState(false);
  const [loadError, setLoadError] = useState(false);

  const load = () => {
    setLoading(true);
    setLoadError(false);
    adsAPI.adminList()
      .then((body) => {
        if (Array.isArray(body?.ads)) setAds(body.ads);
        else { setAds([]); setLoadError(true); }
      })
      .catch(() => { setAds([]); setLoadError(true); })
      .finally(() => setLoading(false));
  };

  useEffect(load, []);

  const handleSave = async () => {
    if (!form.clientName) return;
    setSaving(true);
    try {
      if (editing) {
        await adsAPI.update(editing, form);
      } else {
        await adsAPI.create(form);
      }
      setShowForm(false);
      setForm(emptyForm());
      setEditing(null);
      load();
    } catch (err) {
      console.error('Failed to save ad', err);
    } finally {
      setSaving(false);
    }
  };

  const handleEdit = (ad) => {
    setForm({
      clientName: ad.clientName,
      imageUrl: ad.imageUrl || '',
      targetLink: ad.targetLink || '',
      placement: ad.placement,
      isActive: ad.isActive,
    });
    setEditing(ad._id);
    setShowForm(true);
  };

  const handleDelete = async (id) => {
    if (!confirm('Delete this ad campaign?')) return;
    try {
      await adsAPI.remove(id);
      load();
    } catch (err) {
      console.error('Failed to delete ad', err);
    }
  };

  const handleToggleActive = async (ad) => {
    try {
      await adsAPI.update(ad._id, { isActive: !ad.isActive });
      load();
    } catch (err) {
      console.error('Failed to toggle ad', err);
    }
  };

  return (
    <div className="page" >
      <div className="container" style={{ paddingTop: 32, paddingBottom: 32 }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 40 }}>
          <div>
            <div className="section-eyebrow">Admin</div>
            <h2 style={{ fontStyle: 'italic' }}>AD <span style={{ color: 'var(--brand)' }}>TRAFFIC CONTROL</span></h2>
          </div>
          <button onClick={() => { setShowForm(!showForm); setForm(emptyForm()); setEditing(null); }}
            style={{ background: 'var(--admin-brand-dark)', color: 'var(--admin-surface)', padding: '12px 24px', borderRadius: 100, fontWeight: 700, fontSize: 12, border: 'none', cursor: 'pointer' }}>
            {showForm ? 'Cancel' : '+ New Campaign'}
          </button>
        </div>

        {showForm && (
          <div style={{ background: 'var(--admin-surface)', padding: 32, borderRadius: 'var(--admin-radius-lg)', border: '1px solid var(--admin-border)', boxShadow: 'var(--admin-shadow-card)', marginBottom: 40 }}>
            <h4 style={{ marginBottom: 24, color: 'var(--brand)' }}>{editing ? 'Edit Campaign' : 'New Campaign'}</h4>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 20 }}>
              <div>
                <label style={{ fontSize: 11, color: 'var(--text-muted)', display: 'block', marginBottom: 6 }}>Client Name *</label>
                <input value={form.clientName} onChange={e => setForm({ ...form, clientName: e.target.value })}
                  style={{ width: '100%', padding: '10px 14px', borderRadius: 10, border: '1px solid var(--border)', background: 'var(--surface)', color: 'var(--text)', outline: 'none', fontSize: 13 }} />
              </div>
              <div>
                <label style={{ fontSize: 11, color: 'var(--text-muted)', display: 'block', marginBottom: 6 }}>Target Link</label>
                <input value={form.targetLink} onChange={e => setForm({ ...form, targetLink: e.target.value })}
                  style={{ width: '100%', padding: '10px 14px', borderRadius: 10, border: '1px solid var(--border)', background: 'var(--surface)', color: 'var(--text)', outline: 'none', fontSize: 13 }} />
              </div>
              <div>
                <label style={{ fontSize: 11, color: 'var(--text-muted)', display: 'block', marginBottom: 6 }}>Image URL</label>
                <input value={form.imageUrl} onChange={e => setForm({ ...form, imageUrl: e.target.value })}
                  style={{ width: '100%', padding: '10px 14px', borderRadius: 10, border: '1px solid var(--border)', background: 'var(--surface)', color: 'var(--text)', outline: 'none', fontSize: 13 }} />
              </div>
              <div>
                <label style={{ fontSize: 11, color: 'var(--text-muted)', display: 'block', marginBottom: 6 }}>Placement</label>
                <select value={form.placement} onChange={e => setForm({ ...form, placement: e.target.value })}
                  style={{ width: '100%', padding: '10px 14px', borderRadius: 10, border: '1px solid var(--border)', background: 'var(--surface)', color: 'var(--text)', outline: 'none', fontSize: 13 }}>
                  {PLACEMENTS.map(p => <option key={p.value} value={p.value}>{p.label}</option>)}
                </select>
              </div>
              <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
                <label style={{ fontSize: 11, color: 'var(--text-muted)', cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 8 }}>
                  <input type="checkbox" checked={form.isActive} onChange={e => setForm({ ...form, isActive: e.target.checked })} />
                  Active
                </label>
              </div>
            </div>
            <button onClick={handleSave} disabled={saving || !form.clientName}
              style={{ marginTop: 24, background: 'var(--admin-brand-dark)', color: 'var(--admin-surface)', padding: '12px 32px', borderRadius: 100, fontWeight: 700, fontSize: 12, border: 'none', cursor: 'pointer', opacity: saving || !form.clientName ? 0.5 : 1 }}>
              {saving ? 'Saving...' : editing ? 'Update Campaign' : 'Create Campaign'}
            </button>
          </div>
        )}

        {loading ? (
          <div className="loading-center"><div className="spinner" /></div>
        ) : loadError ? (
          <div role="alert" style={{ textAlign: 'center', padding: 60, color: 'var(--admin-status-danger)' }}>
            <h3>Ad campaigns could not be loaded</h3>
            <p style={{ fontSize: 13, marginTop: 8 }}>This is a loading failure, not an empty list. <button type="button" className="btn btn-sm btn-outline" onClick={load}>Retry</button></p>
          </div>
        ) : ads.length === 0 ? (
          <div style={{ textAlign: 'center', padding: 80, color: 'var(--text-muted)' }}>
            <Megaphone size={40} aria-hidden="true" style={{ marginBottom: 16 }} />
            <h3>No ad campaigns yet</h3>
            <p style={{ fontSize: 13, marginTop: 8 }}>Create your first campaign to start monetizing placements.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {ads.map(ad => (
              <div key={ad._id} style={{ background: 'var(--admin-surface)', padding: 24, borderRadius: 'var(--admin-radius-lg)', border: '1px solid var(--admin-border)', boxShadow: 'var(--admin-shadow-card)' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 16 }}>
                  <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
                    <span style={{
                      background: ad.isActive ? 'var(--admin-status-success-bg)' : 'var(--admin-status-danger-bg)',
                      color: ad.isActive ? 'var(--admin-status-success)' : 'var(--admin-status-danger)',
                      fontSize: 10, padding: '4px 8px', borderRadius: 4, fontWeight: 700,
                    }}>
                      {ad.isActive ? 'ACTIVE' : 'PAUSED'}
                    </span>
                    <span style={{ background: 'var(--admin-brand-soft)', color: 'var(--admin-brand-dark)', fontSize: 10, padding: '4px 8px', borderRadius: 4, fontWeight: 500 }}>
                      {PLACEMENTS.find(p => p.value === ad.placement)?.label || ad.placement}
                    </span>
                  </div>
                  <div style={{ display: 'flex', gap: 4 }}>
                    <button onClick={() => handleToggleActive(ad)}
                      style={{ background: 'none', border: '1px solid var(--border)', borderRadius: 6, padding: '4px 8px', fontSize: 11, color: 'var(--text-muted)', cursor: 'pointer' }}>
                      {ad.isActive ? 'Pause' : 'Activate'}
                    </button>
                    <button onClick={() => handleEdit(ad)}
                      style={{ background: 'none', border: '1px solid var(--border)', borderRadius: 6, padding: '4px 8px', fontSize: 11, color: 'var(--brand)', cursor: 'pointer' }}>
                      Edit
                    </button>
                    <button onClick={() => handleDelete(ad._id)}
                      style={{ background: 'none', border: '1px solid var(--border)', borderRadius: 6, padding: '4px 8px', fontSize: 11, color: 'var(--admin-status-danger)', cursor: 'pointer' }}>
                      Delete
                    </button>
                  </div>
                </div>
                <h4 style={{ fontWeight: 700, color: 'var(--admin-ink)' }}>{ad.clientName}</h4>
                {ad.targetLink && (
                  <p style={{ fontSize: 12, color: 'var(--brand)', marginTop: 4, wordBreak: 'break-all' }}>{ad.targetLink}</p>
                )}
                <div style={{ marginTop: 16, display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 16 }}>
                  <div style={{ background: 'var(--admin-surface-muted)', padding: 12, borderRadius: 12, border: '1px solid var(--admin-border)', textAlign: 'center' }}>
                    <p style={{ fontSize: 10, color: 'var(--text-muted)', textTransform: 'uppercase' }}>Impressions</p>
                    <p style={{ fontSize: '1.125rem', fontFamily: 'monospace', color: 'var(--admin-ink)' }}>{Number.isFinite(ad.viewCount) ? ad.viewCount.toLocaleString() : '—'}</p>
                  </div>
                  <div style={{ background: 'var(--admin-surface-muted)', padding: 12, borderRadius: 12, border: '1px solid var(--admin-border)', textAlign: 'center' }}>
                    <p style={{ fontSize: 10, color: 'var(--text-muted)', textTransform: 'uppercase' }}>Clicks</p>
                    <p style={{ fontSize: '1.125rem', fontFamily: 'monospace', color: 'var(--admin-brand-dark)' }}>{Number.isFinite(ad.clickCount) ? ad.clickCount.toLocaleString() : '—'}</p>
                  </div>
                </div>
                {ad.budgetRemaining > 0 && (
                  <div style={{ marginTop: 16, fontSize: 11, color: 'var(--text-muted)' }}>
                    Budget remaining: KES {ad.budgetRemaining.toLocaleString()}
                  </div>
                )}
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';
import { carsAPI, auctionAdminAPI, bidsAPI, formatKES } from '../../api/api';
import { useToast } from '../../context/ToastContext';
import { CountdownDisplay } from '../../components/CountdownDisplay';

import { X, Radio, Pause, Flag, Zap, Car, Crown } from 'lucide-react';
export default function AdminAuctions() {
  const { toast } = useToast();
  const [cars, setCars]       = useState([]);
  const [loading, setLoading] = useState(true);
  const [tab, setTab]         = useState('live');
  const [actionId, setActionId] = useState(null);
  const [selected, setSelected] = useState(null); // car for start-auction modal
  const [bids, setBids]       = useState({}); // carId -> bids[]
  const [extendForm, setExtendForm] = useState({ hours: 2 });
  const [winnerModal, setWinnerModal] = useState(null); // { car, bids }

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const [live, draft, ended] = await Promise.all([
        carsAPI.list({ auctionStatus: 'live',  limit: 50 }),
        carsAPI.list({ auctionStatus: 'draft', limit: 50 }),
        carsAPI.list({ auctionStatus: 'ended', limit: 50 }),
      ]);
      const all = [
        ...(live.cars  || []).map(c => ({ ...c, _tab: 'live' })),
        ...(draft.cars || []).map(c => ({ ...c, _tab: 'draft' })),
        ...(ended.cars || []).map(c => ({ ...c, _tab: 'ended' })),
      ];
      setCars(all);
    } catch { toast('Failed to load auctions', 'error'); }
    finally { setLoading(false); }
  }, []);

  useEffect(() => { load(); }, [load]);

  const displayed = cars.filter(c => c._tab === tab);

  const loadBids = async (carId) => {
    if (bids[carId]) return bids[carId];
    try {
      const data = await auctionAdminAPI.bidHistory(carId);
      const b = (data.bids || data.data || []).filter((bid) => ['paid', 'won', 'lost'].includes(String(bid.status || '').toLowerCase()) || bid.mpesaPaid === true);
      setBids(prev => ({ ...prev, [carId]: b }));
      return b;
    } catch { return []; }
  };

  const handleStart = async () => {
    if (!selected) return;
    setActionId(selected._id);
    try {
      await auctionAdminAPI.start(selected._id, {});
      toast('Auction is now LIVE!', 'success');
      setSelected(null);
      load();
    } catch (err) {
      toast(err.response?.data?.message || 'Failed to start auction', 'error');
    } finally { setActionId(null); }
  };

  const handleEnd = async (carId) => {
    if (!window.confirm('End this auction now?')) return;
    setActionId(carId);
    try {
      await auctionAdminAPI.end(carId);
      toast('Auction ended.', 'success');
      load();
    } catch (err) {
      toast(err.response?.data?.message || 'Failed', 'error');
    } finally { setActionId(null); }
  };

  const handleExtend = async (carId) => {
    setActionId(carId + '-ext');
    try {
      const hours = Number(extendForm.hours);
      await auctionAdminAPI.extend(carId, { extraMs: hours * 3600000 });
      toast(`Auction extended by ${hours}h`, 'success');
      load();
    } catch (err) {
      toast(err.response?.data?.message || 'Failed', 'error');
    } finally { setActionId(null); }
  };

  const openWinnerModal = async (car) => {
    const b = await loadBids(car._id);
    setWinnerModal({ car, bids: b });
  };

  const handleSetWinner = async (bidId) => {
    if (!winnerModal) return;
    setActionId(bidId);
    try {
      await auctionAdminAPI.setWinner(winnerModal.car._id, bidId);
      toast('Winner recorded. Settlement follows the published auction mode.', 'success');
      setWinnerModal(null);
      load();
    } catch (err) {
      toast(err.response?.data?.message || 'Failed', 'error');
    } finally { setActionId(null); }
  };

  const liveCars  = cars.filter(c => c._tab === 'live');
  const draftCars = cars.filter(c => c._tab === 'draft');
  const endedCars = cars.filter(c => c._tab === 'ended');

  return (
    <div className="page">
      <div className="container" style={{ paddingTop: 32, paddingBottom: 32 }}>

        <div style={{ marginBottom: 28 }}>
          <div className="section-eyebrow">Admin</div>
          <h2>Auction Control</h2>
          <p style={{ color: 'var(--text-muted)', fontSize: 14, marginTop: 6 }}>
            Start, end, extend auctions and declare winners.
          </p>
        </div>

        {/* Stats bar */}
        <div className="grid-3" style={{ marginBottom: 28 }}>
          {[
            { label: 'Live Auctions', val: liveCars.length,  color: 'var(--green)', icon: Radio },
            { label: 'Ready to Launch', val: draftCars.length, color: 'var(--brand-light)', icon: Pause },
            { label: 'Completed', val: endedCars.length,     color: 'var(--text-muted)', icon: Flag },
          ].map(s => (
            <div key={s.label} className="stat-box">
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <div>
                  <div className="stat-label">{s.label}</div>
                  <div className="stat-value" style={{ color: s.color }}>{s.val}</div>
                </div>
                <s.icon size={28} aria-hidden="true" />
              </div>
            </div>
          ))}
        </div>

        {/* Tabs */}
        <div className="tabs">
          {[
            { key: 'live',  label: `Live (${liveCars.length})` },
            { key: 'draft', label: `Draft (${draftCars.length})` },
            { key: 'ended', label: `Ended (${endedCars.length})` },
          ].map(t => (
            <button key={t.key} className={`tab-btn ${tab === t.key ? 'active' : ''}`} onClick={() => setTab(t.key)}>
              {t.label}
            </button>
          ))}
        </div>

        {loading ? (
          <div className="loading-center"><div className="spinner" /></div>
        ) : displayed.length === 0 ? (
          <div className="empty-state">
            <div className="empty-icon"><Zap size={32} aria-hidden="true" /></div>
            <h3>No {tab} auctions</h3>
            {tab === 'draft' && <p>Dealers need to create listings with bidding enabled first.</p>}
          </div>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
            {displayed.map(car => (
              <div key={car._id} className="card" style={{
                padding: 20,
                border: car._tab === 'live' ? '1px solid rgba(34,197,94,0.2)' : '1px solid var(--border)',
              }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: 16, flexWrap: 'wrap' }}>

                  {/* Thumbnail */}
                  <div style={{ width: 80, height: 56, borderRadius: 6, overflow: 'hidden', background: 'var(--surface)', flexShrink: 0 }}>
                    {car.images?.[0]?.url
                      ? <img src={car.images[0].url} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                      : <div style={{ width: '100%', height: '100%', display: 'flex', alignItems: 'center', justifyContent: 'center' }}><Car size={28} aria-hidden="true" /></div>
                    }
                  </div>

                  {/* Info */}
                  <div style={{ flex: 1, minWidth: 200 }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4 }}>
                      {car._tab === 'live' && <span className="badge badge-green"><span className="live-dot" /> LIVE</span>}
                      {car._tab === 'draft' && <span className="badge badge-muted">Draft</span>}
                      {car._tab === 'ended' && <span className="badge badge-muted">Ended</span>}
                      <Link to={`/cars/${car._id}`} style={{ fontWeight: 600, fontSize: 15, color: 'var(--text)' }}>
                        {car.title}
                      </Link>
                    </div>
                    <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>
                      Dealer: {car.dealer?.name || '—'} · {car.bidsCount || 0} bids
                    </div>
                  </div>

                  {/* Price + timer */}
                  <div style={{ textAlign: 'center', minWidth: 120 }}>
                    <div style={{ fontSize: 11, color: 'var(--text-muted)' }}>
                      {car.currentBid > 0 ? 'Current Bid' : 'Start Price'}
                    </div>
                    <div className="price-tag">{formatKES(car.currentBid || car.price)}</div>
                  </div>

                  {car._tab === 'live' && car.auctionEnd && (
                    <div style={{ textAlign: 'center' }}>
                      <div style={{ fontSize: 11, color: 'var(--text-muted)', marginBottom: 4 }}>Ends In</div>
                      <CountdownDisplay endTime={car.auctionEnd} />
                    </div>
                  )}

                  {/* Actions */}
                  <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', flexShrink: 0 }}>
                    {car._tab === 'draft' && (
                      new Date(car.auctionStartTime || car.auction_start_time || 0).getTime() > Date.now() ? (
                        <span className="badge badge-muted">Scheduled · {new Date(car.auctionStartTime || car.auction_start_time).toLocaleString('en-KE')}</span>
                      ) : (
                        <button className="btn btn-gold btn-sm" onClick={() => setSelected(car)}>
                          ▶ Start Auction
                        </button>
                      )
                    )}

                    {car._tab === 'live' && (
                      <>
                        <button
                          className="btn btn-outline btn-sm"
                          onClick={() => handleExtend(car._id)}
                          disabled={actionId === car._id + '-ext'}
                        >
                          +2h Extend
                        </button>
                        <button
                          className="btn btn-danger btn-sm"
                          onClick={() => handleEnd(car._id)}
                          disabled={actionId === car._id}
                        >
                          {actionId === car._id ? '...' : '⏹ End Now'}
                        </button>
                        <button className="btn btn-outline btn-sm" onClick={() => openWinnerModal(car)}>
                          Set Winner
                        </button>
                      </>
                    )}

                    {car._tab === 'ended' && car.bidsCount > 0 && (
                      <button className="btn btn-gold btn-sm" onClick={() => openWinnerModal(car)}>
                        Declare Winner
                      </button>
                    )}

                    <Link to={`/cars/${car._id}`} className="btn btn-outline btn-sm">View</Link>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* ─── Start Auction Modal ─── */}
      {selected && (
        <div className="modal-overlay" onClick={e => e.target === e.currentTarget && setSelected(null)}>
          <div className="modal-box">
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 24 }}>
              <div>
                <div style={{ fontSize: 11, color: 'var(--green)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.08em' }}>Start Auction</div>
                <h3 style={{ marginTop: 4 }}>{selected.title}</h3>
              </div>
              <button onClick={() => setSelected(null)} style={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 6, width: 32, height: 32, cursor: 'pointer', color: 'var(--text-muted)' }} aria-label="Close" title="Close"><X size={16} aria-hidden="true" /></button>
            </div>

            <div style={{ background: 'var(--brand-glow)', border: '1px solid rgba(23, 107, 135, 0.15)', borderRadius: 'var(--radius)', padding: 16, marginBottom: 20 }}>
              <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>Starting Price</div>
              <div className="price-tag" style={{ fontSize: '1.6rem' }}>{formatKES(selected.price)}</div>
            </div>

            <div className="input-group" style={{ marginBottom: 20 }}>
              <label className="input-label">Published auction schedule</label>
              <input
                className="input"
                value={selected.auctionStartTime && selected.auctionEnd
                  ? `${new Date(selected.auctionStartTime).toLocaleString('en-KE')} → ${new Date(selected.auctionEnd).toLocaleString('en-KE')}`
                  : 'Published schedule'}
                readOnly
              />
              <div style={{ fontSize: 12, color: 'var(--text-muted)', marginTop: 6 }}>
                Admin can start only within the published schedule. Economics, timing and bidder rules remain bound to the published auction contract.
              </div>
            </div>

            <button className="btn btn-gold btn-full btn-lg" onClick={handleStart} disabled={actionId === selected._id}>
              {actionId === selected._id ? <><div className="spinner" style={{ width: 18, height: 18 }} /> Starting...</> : 'Go Live Now'}
            </button>
          </div>
        </div>
      )}

      {/* ─── Set Winner Modal ─── */}
      {winnerModal && (
        <div className="modal-overlay" onClick={e => e.target === e.currentTarget && setWinnerModal(null)}>
          <div className="modal-box" style={{ maxWidth: 540 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 20 }}>
              <div>
                <div style={{ fontSize: 11, color: 'var(--brand)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.08em' }}>Declare Winner</div>
                <h3 style={{ marginTop: 4 }}>{winnerModal.car.title}</h3>
              </div>
              <button onClick={() => setWinnerModal(null)} style={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 6, width: 32, height: 32, cursor: 'pointer', color: 'var(--text-muted)' }} aria-label="Close" title="Close"><X size={16} aria-hidden="true" /></button>
            </div>

            <p style={{ color: 'var(--text-muted)', fontSize: 14, marginBottom: 20 }}>
              Select the winning bid. The winner will be notified and settlement will follow the auction's published settlement mode.
            </p>

            {winnerModal.bids.length === 0 ? (
              <div className="empty-state" style={{ padding: 32 }}>
                <div className="empty-icon"><Zap size={32} aria-hidden="true" /></div>
                <h3>No bids placed</h3>
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: 10, maxHeight: 360, overflowY: 'auto' }}>
                {winnerModal.bids.sort((a, b) => b.amount - a.amount).map((bid, i) => {
                  const confirmed = ['paid', 'won', 'lost'].includes(String(bid.status || '').toLowerCase()) || bid.mpesaPaid === true;
                  return (
                    <div key={bid._id} style={{
                      background: i === 0 ? 'var(--brand-glow)' : 'var(--surface)',
                      border: `1px solid ${i === 0 ? 'rgba(23, 107, 135, 0.3)' : 'var(--border)'}`,
                      borderRadius: 'var(--radius)', padding: '14px 16px',
                      display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                    }}>
                      <div>
                        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                          {i === 0 && <Crown size={14} aria-label="Highest bid" />}
                          <span style={{ fontWeight: 600, fontSize: 14 }}>{bid.user?.name || 'Bidder'}</span>
                          {confirmed ? <span className="badge badge-green" style={{ fontSize: 9 }}>Confirmed</span> : <span className="badge badge-muted" style={{ fontSize: 9 }}>Pending payment</span>}
                        </div>
                        <div style={{ fontSize: 12, color: 'var(--text-muted)', marginTop: 2 }}>
                          {bid.phone} · {new Date(bid.createdAt).toLocaleString('en-KE')}
                        </div>
                      </div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                        <div className="price-tag">{formatKES(bid.amount)}</div>
                        <button
                          className={`btn btn-sm ${i === 0 ? 'btn-gold' : 'btn-outline'}`}
                          onClick={() => handleSetWinner(bid._id)}
                          disabled={actionId === bid._id || !confirmed}
                        >
                          {actionId === bid._id ? '...' : confirmed ? 'Select' : 'Awaiting payment'}
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

