import React, { useCallback, useEffect, useRef, useState } from 'react';
import { RefreshCw, RotateCcw, Activity, FileText, ShieldCheck, Send, Mail, MessageSquare, Smartphone, Power, CheckCircle2 } from 'lucide-react';
import { adminAPI } from '../../api/api.exports';

const unwrap = (x) => x?.data ?? x;
const pct = (n) => (n === null || n === undefined || n === '' || !Number.isFinite(Number(n)) ? 'Unavailable' : `${Number(n).toFixed(1)}%`);

const asList = (value) => (Array.isArray(value) ? value : []);

export default function AdminCommunications() {
  const [templates, setTemplates] = useState([]);
  const [analytics, setAnalytics] = useState([]);
  const [health, setHealth] = useState([]);
  const [history, setHistory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [busy, setBusy] = useState('');
  const [rollout, setRollout] = useState({ channels: [], events: [] });
  const [tab, setTab] = useState('email');
  const loadSequence = useRef(0);

  const load = useCallback(async () => {
    const sequence = ++loadSequence.current;
    setLoading(true); setError('');
    try {
      const [t, a, h, r, ro] = await Promise.all([
        adminAPI.communicationTemplates(),
        adminAPI.communicationAnalytics({ hours: 24 }),
        adminAPI.communicationProviderHealth(),
        adminAPI.communicationHistory({ limit: 50 }),
        adminAPI.communicationRollout(),
      ]);
      if (sequence !== loadSequence.current) return;
      setTemplates(asList(unwrap(t))); setAnalytics(asList(unwrap(a))); setHealth(asList(unwrap(h))); setHistory(asList(unwrap(r))); { const rollout = unwrap(ro) || {}; setRollout({ channels: Array.isArray(rollout.channels) ? rollout.channels : [], events: Array.isArray(rollout.events) ? rollout.events : [] }); }
    } catch (e) { if (sequence === loadSequence.current) setError(e?.response?.data?.message || e?.message || 'Communications control plane could not be loaded.'); }
    finally { if (sequence === loadSequence.current) setLoading(false); }
  }, []);
  useEffect(() => { void load(); }, [load]);

  const toggleChannel = async (channel, enabled) => {
    setBusy(`channel:${channel}`); setError('');
    try { await adminAPI.updateCommunicationChannelControl(channel, enabled); await load(); }
    catch (e) { setError(e?.message || 'Channel control update failed.'); }
    finally { setBusy(''); }
  };

  const toggleEvent = async (eventType, channel, enabled) => {
    setBusy(`event:${eventType}:${channel}`); setError('');
    try { await adminAPI.updateCommunicationEventControl(eventType, channel, enabled); await load(); }
    catch (e) { setError(e?.message || 'Event control update failed.'); }
    finally { setBusy(''); }
  };

  const retry = async (id) => {
    setBusy(id); setError('');
    try { await adminAPI.retryCommunication(id); await load(); }
    catch (e) { setError(e?.message || 'Retry rejected by the server.'); }
    finally { setBusy(''); }
  };

  return <div className="p-6 space-y-6">
    <div className="flex items-start justify-between gap-4">
      <div><div className="text-xs uppercase tracking-[.18em] text-[#64748B] font-bold">Communications Control Plane</div><h1 className="text-2xl font-black text-[#0A3340] mt-1">Messaging Operations</h1><p className="text-sm text-[#64748B] mt-1">Templates, consent, delivery health, retries and the authoritative communication ledger.</p></div>
      <button onClick={() => void load()} disabled={loading} className="inline-flex items-center gap-2 px-3 py-2 rounded-lg border bg-white text-sm font-bold"><RefreshCw size={15} className={loading ? 'animate-spin' : ''}/>Refresh</button>
    </div>
    {error && <div className="p-3 rounded-lg border border-[#BDE5DE] bg-[#F3FAF9] text-[#0A3340] text-sm">{error}</div>}
    <section className="bg-white border rounded-xl overflow-hidden">
      <div className="p-5 border-b"><div className="text-xs uppercase tracking-[.18em] text-[#64748B] font-bold">Launch Controls</div><h2 className="text-lg font-black mt-1">What KAYAD is allowed to send</h2><p className="text-sm text-[#64748B] mt-1">Roll communications out gradually. Email and SMS are launch channels; WhatsApp is built but remains off until you activate it.</p></div>
      <div className="p-4 flex flex-wrap gap-2 border-b">{[['email','Email',Mail],['sms','Kenya SMS',Smartphone],['whatsapp','WhatsApp',MessageSquare]].map(([key,label,Icon])=>{const c=rollout.channels.find(x=>x.channel===key); return <button key={key} onClick={()=>setTab(key)} className={`px-4 py-2 rounded-lg border text-sm font-black inline-flex items-center gap-2 ${tab===key?'bg-[#0A3340] text-white':'bg-white text-[#12576D]'}`}><Icon size={15}/>{label}<span className="text-xs opacity-70">{c?.canonicalProvider}</span></button>})}</div>
      <div className="p-5 space-y-4">
        {(() => { const c=rollout.channels.find(x=>x.channel===tab); const events=rollout.events.filter(x=>x.channel===tab); return <><div className="flex items-center justify-between p-4 rounded-xl border bg-[#F6FAF9]"><div><div className="font-black">{c?.canonicalProvider || tab}</div><div className="text-xs text-[#64748B]">Master switch for this channel</div></div><button onClick={()=>toggleChannel(tab,!c?.enabled)} disabled={busy===`channel:${tab}`} className={`px-3 py-2 rounded-lg text-xs font-black inline-flex items-center gap-2 ${c?.enabled?'bg-emerald-600 text-white':'bg-[#DDF4F0] text-[#12576D]'}`}><Power size={14}/>{c?.enabled?'Active':'Off'}</button></div>
        <div className="grid md:grid-cols-2 gap-2">{events.map(e=><div key={e.id} className="flex items-center justify-between gap-3 p-3 border rounded-lg"><div><div className="text-sm font-bold">{e.eventType}</div><div className="text-xs text-[#64748B]">{e.enabled?'Allowed to send':'Suppressed at launch'}</div></div><button onClick={()=>toggleEvent(e.eventType,tab,!e.enabled)} disabled={!c?.enabled || busy===`event:${e.eventType}:${tab}`} className={`px-3 py-1.5 rounded-lg text-xs font-black ${e.enabled?'bg-emerald-50 text-emerald-700 border border-emerald-200':'bg-[#EEF7F5] text-[#64748B] border'}`}>{e.enabled?'Enabled':'Disabled'}</button></div>)}</div></> })()}
      </div>
    </section>
    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
      <div className="p-4 rounded-xl bg-white border"><div className="text-xs text-[#64748B]">Templates</div><div className="text-2xl font-black">{templates.length}</div></div>
      <div className="p-4 rounded-xl bg-white border"><div className="text-xs text-[#64748B]">24h delivery groups</div><div className="text-2xl font-black">{analytics.reduce((n,x)=>n+Number(x.total||0),0)}</div></div>
      <div className="p-4 rounded-xl bg-white border"><div className="text-xs text-[#64748B]">Providers observed</div><div className="text-2xl font-black">{health.length}</div></div>
      <div className="p-4 rounded-xl bg-white border"><div className="text-xs text-[#64748B]">Failed messages</div><div className="text-2xl font-black">{history.filter(x=>x.status==='failed').length}</div></div>
    </div>
    <div className="grid lg:grid-cols-2 gap-5">
      <section className="bg-white border rounded-xl overflow-hidden"><div className="p-4 border-b flex items-center gap-2 font-black"><FileText size={17}/> Templates</div><div className="divide-y">{templates.map(t=><div key={t.id} className="p-4 flex items-center justify-between gap-3"><div><div className="font-bold text-sm">{t.name}</div><div className="text-xs text-[#64748B]">{t.code} · {t.channel} · {t.category}</div></div><span className={`text-xs font-bold ${t.enabled?'text-emerald-600':'text-[#94A3B8]'}`}>{t.enabled?'Enabled':'Disabled'}</span></div>)}{!templates.length&&<div className="p-6 text-sm text-[#64748B]">No templates returned.</div>}</div></section>
      <section className="bg-white border rounded-xl overflow-hidden"><div className="p-4 border-b flex items-center gap-2 font-black"><Activity size={17}/> Provider Health Evidence</div><p className="px-4 pt-3 text-xs text-[#64748B]">Configuration and delivery-ledger evidence only; this panel does not send test messages or prove live provider connectivity.</p><div className="divide-y">{health.map(p=><div key={p.provider} className="p-4 flex flex-wrap items-center justify-between gap-3"><div><div className="font-bold text-sm">{p.provider}</div><div className="text-xs text-[#64748B]">{p.total} recorded attempts · {p.failed} failed · {p.bounced || 0} bounced · {p.deadLetter || 0} dead-letter · {p.delivered} delivered</div><div className="text-xs text-[#64748B] mt-1">Configuration: {p.configured === true ? 'configured' : p.configured === false ? 'not configured' : 'unknown'} · Evidence: {p.evidence || 'unknown'} · Status: {p.status || 'unknown'}</div>{p.checkedAt && <div className="text-xs text-[#64748B] mt-1">Last checked: {new Date(p.checkedAt).toLocaleString()}</div>}{!p.total && <div className="text-xs text-warning mt-1">No delivery attempts recorded; provider connectivity is unknown.</div>}</div><div className="font-black text-sm">{p.successRate == null ? 'N/A' : pct(p.successRate)}</div></div>)}{!health.length&&<div className="p-6 text-sm text-[#64748B]">Provider health evidence unavailable or no records returned. Refresh to retry; an empty result is not proof of healthy delivery.</div>}</div></section>
    </div>
    <section className="bg-white border rounded-xl overflow-hidden"><div className="p-4 border-b flex items-center gap-2 font-black"><Send size={17}/> Delivery Analytics — last 24 hours</div><div className="overflow-auto" tabIndex={0} role="region" aria-label="Scrollable table"><table className="w-full text-sm"><thead><tr className="text-left text-xs text-[#64748B] border-b"><th className="p-3">Channel</th><th className="p-3">Category</th><th className="p-3">Total</th><th className="p-3">Delivered</th><th className="p-3">Failed</th><th className="p-3">Delivery</th></tr></thead><tbody>{analytics.map(x=><tr key={`${x.channel}-${x.category}`} className="border-b last:border-0"><td className="p-3 font-bold">{x.channel}</td><td className="p-3">{x.category}</td><td className="p-3">{x.total}</td><td className="p-3">{x.delivered}</td><td className="p-3">{x.failed}</td><td className="p-3 font-bold">{pct(x.deliveryRate)}</td></tr>)}</tbody></table></div></section>
    <section className="bg-white border rounded-xl overflow-hidden"><div className="p-4 border-b flex items-center gap-2 font-black"><ShieldCheck size={17}/> Recent Delivery Ledger</div><div className="overflow-auto" tabIndex={0} role="region" aria-label="Scrollable table"><table className="w-full text-sm"><thead><tr className="text-left text-xs text-[#64748B] border-b"><th className="p-3">Time</th><th className="p-3">Channel</th><th className="p-3">Event</th><th className="p-3">Provider</th><th className="p-3">Status</th><th className="p-3">Action</th></tr></thead><tbody>{history.map(x=><tr key={x.id} className="border-b last:border-0"><td className="p-3 text-xs">{x.createdAt ? new Date(x.createdAt).toLocaleString() : '—'}</td><td className="p-3">{x.channel}</td><td className="p-3">{x.eventType}</td><td className="p-3">{x.provider}</td><td className="p-3 font-bold">{x.status}</td><td className="p-3">{x.status==='failed'&&<button onClick={()=>void retry(x.id)} disabled={busy===x.id} className="inline-flex items-center gap-1 px-2 py-1 rounded border text-xs font-bold"><RotateCcw size={13}/>{busy===x.id?'Retrying':'Retry'}</button>}</td></tr>)}</tbody></table></div></section>
  </div>;
}

import { useState, useEffect, useCallback } from 'react';
import { adminVerificationAPI } from '../../api/api';
import { ShieldCheck, Search, CheckCircle, XCircle, Eye, FileText, X, AlertTriangle } from 'lucide-react';

const STATUS_COLORS = {
  pending: { bg: 'rgba(19, 184, 166, 0.1)', color: '#176b87', label: 'Pending' },
  under_review: { bg: 'rgba(23, 107, 135, 0.1)', color: '#176B87', label: 'Under Review' },
  approved: { bg: 'rgba(34,197,94,0.1)', color: 'var(--admin-status-success)', label: 'Approved' },
  rejected: { bg: 'rgba(239,68,68,0.1)', color: 'var(--admin-status-danger)', label: 'Rejected' },
  suspended: { bg: 'rgba(107,114,128,0.1)', color: 'var(--admin-status-neutral)', label: 'Suspended' },
};

function Modal({ title, children, onClose }) {
  return (
    <div style={{
      position: 'fixed', inset: 0, zIndex: 9999,
      display: 'flex', alignItems: 'center', justifyContent: 'center',
      background: 'rgba(10, 51, 64, 0.8)', backdropFilter: 'blur(8px)',
    }} onClick={onClose} role="presentation">
      <div onClick={e => e.stopPropagation()} role="presentation" style={{
        background: 'var(--admin-surface)', border: '1px solid var(--admin-border)',
        borderRadius: 16, padding: 28, width: 520, maxWidth: '90vw',
        position: 'relative', maxHeight: '80vh', overflow: 'auto',
      }}>
        <button onClick={onClose} style={{
          position: 'absolute', top: 12, right: 12,
          background: 'none', border: 'none', color: 'var(--admin-muted-content)',
          cursor: 'pointer', fontSize: 18,
        }} aria-label="Close"><X size={18} /></button>
        <h3 style={{ marginTop: 0, marginBottom: 18 }}>{title}</h3>
        {children}
      </div>
    </div>
  );
}

export default function AdminDealerVerifications() {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState('');
  const [actionError, setActionError] = useState('');
  const [filter, setFilter] = useState('');
  const [search, setSearch] = useState('');
  const [selected, setSelected] = useState(null);
  const [actionModal, setActionModal] = useState(null);
  const [actionNotes, setActionNotes] = useState('');
  const [processing, setProcessing] = useState(false);

  const load = useCallback(async () => {
    setLoading(true);
    setLoadError('');
    try {
      const params = filter ? { status: filter } : {};
      const data = await adminVerificationAPI.list(params);
      setItems(data.verifications || []);
    } catch { setLoadError('Dealer verification records could not be loaded. Check access or connectivity and retry.'); }
    finally { setLoading(false); }
  }, [filter]);

  useEffect(() => { load(); }, [load]);

  const filtered = items.filter(v =>
    !search ||
    v.user?.name?.toLowerCase().includes(search.toLowerCase()) ||
    v.user?.email?.toLowerCase().includes(search.toLowerCase()) ||
    v.dealer?.businessName?.toLowerCase().includes(search.toLowerCase())
  );

  const openAction = (id, action) => {
    setActionModal({ id, action });
    setActionNotes('');
    setActionError('');
  };

  const handleAction = async () => {
    if (!actionModal) return;
    if (actionModal.action === 'reject' && !actionNotes.trim()) {
      setActionError('A specific rejection reason is required.');
      return;
    }
    setActionError('');
    setProcessing(true);
    try {
      const { id, action } = actionModal;
      if (action === 'approve') {
        await adminVerificationAPI.approve(id, { adminNotes: actionNotes });
      } else if (action === 'reject') {
        await adminVerificationAPI.reject(id, { rejectionReason: actionNotes || 'Rejected by admin' });
      }
      setActionModal(null);
      setSelected(null);
      setActionError('');
      load();
    } catch (err) {
      setActionError(err?.response?.data?.message || 'The decision could not be saved. No approval change is confirmed; retry after checking the record.');
    } finally { setProcessing(false); }
  };

  const countByStatus = (status) => items.filter(v => v.verificationStatus === status).length;

  return (
    <div style={{ padding: '32px 32px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 28, flexWrap: 'wrap', gap: 12 }}>
        <div>
          <h1 style={{ fontSize: '1.4rem', fontWeight: 900, fontFamily: 'var(--font-display)', fontStyle: 'italic', margin: 0 }}>
            <ShieldCheck size={20} style={{ display: 'inline', marginRight: 8, verticalAlign: -3, color: 'var(--brand)' }} />
            Dealer Verifications
          </h1>
          <p style={{ color: 'var(--admin-muted-content)', fontSize: 13, margin: '4px 0 0' }}>
            Review and manage dealer verification applications
          </p>
        </div>
      </div>

      {loadError && (
        <div role="alert" style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 12, marginBottom: 18, padding: 14, borderRadius: 10, border: '1px solid rgba(239,68,68,.35)', background: 'rgba(239,68,68,.08)', color: 'var(--admin-status-danger)' }}>
          <span>{loadError}</span>
          <button onClick={load} style={{ padding: '7px 12px', borderRadius: 7, border: '1px solid var(--admin-border)', color: 'var(--admin-ink)' }}>Retry</button>
        </div>
      )}

      {/* Stats */}
      <div style={{ display: 'flex', gap: 12, marginBottom: 20, flexWrap: 'wrap' }}>
        {[
          { label: 'Pending', count: countByStatus('pending'), color: '#176b87' },
          { label: 'Under Review', count: countByStatus('under_review'), color: '#176B87' },
          { label: 'Approved', count: countByStatus('approved'), color: 'var(--admin-status-success)' },
          { label: 'Rejected', count: countByStatus('rejected'), color: 'var(--admin-status-danger)' },
          { label: 'Total', count: items.length, color: 'var(--admin-ink)' },
        ].map(stat => (
          <div key={stat.label} style={{
            background: 'var(--card)', border: '1px solid var(--border)',
            borderRadius: 10, padding: '12px 20px', minWidth: 100,
          }}>
            <div style={{ fontSize: 10, fontWeight: 700, color: `${stat.color}`, textTransform: 'uppercase', letterSpacing: '0.06em', marginBottom: 4 }}>{stat.label}</div>
            <div style={{ fontSize: 22, fontWeight: 900, color: 'var(--admin-ink)', fontFamily: 'var(--font-display)', fontStyle: 'italic' }}>{stat.count}</div>
          </div>
        ))}
      </div>

      {/* Filters */}
      <div style={{ display: 'flex', gap: 10, marginBottom: 16, flexWrap: 'wrap' }}>
        <div style={{ flex: 1, minWidth: 200, position: 'relative' }}>
          <Search size={14} style={{ position: 'absolute', left: 12, top: '50%', transform: 'translateY(-50%)', color: 'var(--admin-muted-content)' }} />
          <input
            placeholder="Search dealer name, email, or business..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            style={{
              width: '100%', padding: '9px 12px 9px 36px',
              background: 'var(--card)', border: '1px solid var(--border)',
              borderRadius: 8, color: 'var(--admin-ink)', fontSize: 13, outline: 'none',
            }}
          />
        </div>
        <select aria-label="Filter dealer verifications by status" value={filter} onChange={e => setFilter(e.target.value)} style={{
          padding: '9px 14px', background: 'var(--card)', border: '1px solid var(--border)',
          borderRadius: 8, color: 'var(--admin-ink)', fontSize: 13, outline: 'none',
        }}>
          <option value="">All Statuses</option>
          <option value="pending">Pending</option>
          <option value="under_review">Under Review</option>
          <option value="approved">Approved</option>
          <option value="rejected">Rejected</option>
          <option value="suspended">Suspended</option>
        </select>
      </div>

      {/* Table */}
      <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 12, overflow: 'hidden' }}>
        <div style={{ overflowX: 'auto' }} tabIndex={0} role="region" aria-label="Dealer verification table (scrollable)">
          <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 13 }}>
            <thead>
              <tr style={{ borderBottom: '1px solid var(--border)', background: 'var(--admin-surface-muted)' }}>
                {['Dealer', 'Business', 'Contact', 'Status', 'Submitted', 'Actions'].map(h => (
                  <th key={h} style={{ padding: '12px 16px', textAlign: 'left', color: 'var(--admin-muted-content)', fontWeight: 600, fontSize: 11, textTransform: 'uppercase', letterSpacing: '0.05em', whiteSpace: 'nowrap' }}>{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr><td colSpan={6} style={{ textAlign: 'center', padding: 40 }}><div className="spinner" /></td></tr>
              ) : filtered.length === 0 ? (
                <tr><td colSpan={6} style={{ textAlign: 'center', padding: 40, color: 'var(--admin-muted-content)' }}>No verification requests found</td></tr>
              ) : filtered.map(v => {
                const sc = STATUS_COLORS[v.verificationStatus] || STATUS_COLORS.pending;
                return (
                  <tr key={v._id} style={{ borderBottom: '1px solid var(--admin-border)' }}>
                    <td style={{ padding: '12px 16px' }}>
                      <span style={{ fontWeight: 600, color: 'var(--admin-ink)' }}>{v.user?.name || 'N/A'}</span>
                    </td>
                    <td style={{ padding: '12px 16px', color: 'var(--admin-body)' }}>{v.dealer?.businessName || '—'}</td>
                    <td style={{ padding: '12px 16px', color: 'var(--admin-body)' }}>
                      <div>{v.user?.email}</div>
                      <div style={{ fontSize: 11, color: 'var(--admin-muted-content)' }}>{v.user?.phone || ''}</div>
                    </td>
                    <td style={{ padding: '12px 16px' }}>
                      <span style={{
                        display: 'inline-block', padding: '3px 10px', borderRadius: 9999,
                        fontSize: 10, fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.05em',
                        background: sc.bg, color: sc.color,
                      }}>{sc.label}</span>
                    </td>
                    <td style={{ padding: '12px 16px', color: 'var(--admin-muted-content)', fontSize: 12, whiteSpace: 'nowrap' }}>
                      {v.submittedAt ? new Date(v.submittedAt).toLocaleDateString('en-KE', { day: 'numeric', month: 'short', year: 'numeric' }) : '—'}
                    </td>
                    <td style={{ padding: '12px 16px' }}>
                      <div style={{ display: 'flex', gap: 6 }}>
                        <button onClick={() => setSelected(v)} style={{
                          padding: '6px 10px', background: 'var(--admin-surface-muted)', border: '1px solid var(--admin-border)',
                          borderRadius: 6, color: 'var(--admin-ink)', fontSize: 11, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 4,
                        }}><Eye size={12} /> View</button>
                        {v.verificationStatus !== 'approved' && (
                          <button onClick={() => openAction(v._id, 'approve')} style={{
                            padding: '6px 10px', background: 'rgba(34,197,94,0.1)', border: '1px solid rgba(34,197,94,0.2)',
                            borderRadius: 6, color: 'var(--admin-status-success)', fontSize: 11, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 4,
                          }}><CheckCircle size={12} /> Approve</button>
                        )}
                        {v.verificationStatus !== 'rejected' && v.verificationStatus !== 'approved' && (
                          <button onClick={() => openAction(v._id, 'reject')} style={{
                            padding: '6px 10px', background: 'rgba(239,68,68,0.1)', border: '1px solid rgba(239,68,68,0.2)',
                            borderRadius: 6, color: 'var(--admin-status-danger)', fontSize: 11, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 4,
                          }}><XCircle size={12} /> Reject</button>
                        )}
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {/* Detail Modal */}
      {selected && (
        <Modal title="Verification Details" onClose={() => setSelected(null)}>
          <div style={{ display: 'grid', gap: 16 }}>
            <div>
              <label style={{ fontSize: 10, color: 'var(--admin-muted-content)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Dealer</label>
              <p style={{ margin: '4px 0', color: 'var(--admin-ink)' }}>{selected.user?.name}</p>
            </div>
            <div>
              <label style={{ fontSize: 10, color: 'var(--admin-muted-content)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Business</label>
              <p style={{ margin: '4px 0', color: 'var(--admin-ink)' }}>{selected.dealer?.businessName || '—'}</p>
            </div>
            <div>
              <label style={{ fontSize: 10, color: 'var(--admin-muted-content)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Contact</label>
              <p style={{ margin: '4px 0', color: 'var(--admin-ink)' }}>{selected.user?.email} {selected.user?.phone ? `· ${selected.user.phone}` : ''}</p>
            </div>
            <div>
              <label style={{ fontSize: 10, color: 'var(--admin-muted-content)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Status</label>
              <p style={{ margin: '4px 0' }}>
                <span style={{
                  display: 'inline-block', padding: '3px 10px', borderRadius: 9999,
                  fontSize: 10, fontWeight: 700, textTransform: 'uppercase',
                  background: STATUS_COLORS[selected.verificationStatus]?.bg || 'var(--admin-surface-muted)',
                  color: STATUS_COLORS[selected.verificationStatus]?.color || '#64748b',
                }}>{STATUS_COLORS[selected.verificationStatus]?.label || selected.verificationStatus}</span>
              </p>
            </div>
            {selected.documents?.length > 0 && (
              <div>
                <label style={{ fontSize: 10, color: 'var(--admin-muted-content)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: 8, display: 'block' }}>
                  <FileText size={12} style={{ display: 'inline', marginRight: 4, verticalAlign: -1 }} /> Documents ({selected.documents.length})
                </label>
                {selected.documents.map((doc, i) => (
                  <div key={i} style={{
                    background: 'var(--admin-surface-muted)', borderRadius: 8,
                    padding: '8px 12px', marginBottom: 6, fontSize: 12,
                    display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                  }}>
                    <span style={{ color: 'var(--admin-ink)' }}>{doc.type || doc.documentType || `Document ${i + 1}`}</span>
                    {doc.url && (
                      <a href={doc.url} target="_blank" rel="noopener noreferrer" style={{
                        color: 'var(--brand)', padding: '4px 10px', borderRadius: 6,
                        background: 'rgba(23, 107, 135, 0.1)', textDecoration: 'none', fontSize: 11, fontWeight: 600,
                      }}><Eye size={11} style={{ display: 'inline', marginRight: 4, verticalAlign: -1 }} /> View</a>
                    )}
                  </div>
                ))}
              </div>
            )}
            {selected.adminNotes && (
              <div>
                <label style={{ fontSize: 10, color: 'var(--admin-muted-content)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em' }}>Admin Notes</label>
                <p style={{ margin: '4px 0', color: 'var(--admin-body)', fontSize: 12 }}>{selected.adminNotes}</p>
              </div>
            )}
            {selected.rejectionReason && (
              <div style={{ background: 'rgba(239,68,68,0.06)', border: '1px solid rgba(239,68,68,0.15)', borderRadius: 8, padding: 12 }}>
                <label style={{ fontSize: 10, color: 'var(--admin-status-danger)', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.05em' }}>
                  <AlertTriangle size={12} style={{ display: 'inline', marginRight: 4, verticalAlign: -1 }} /> Rejection Reason
                </label>
                <p style={{ margin: '4px 0', color: 'var(--admin-body)', fontSize: 12 }}>{selected.rejectionReason}</p>
              </div>
            )}
          </div>
        </Modal>
      )}

      {/* Action Confirmation Modal */}
      {actionModal && (
        <Modal title={`${actionModal.action === 'approve' ? 'Approve' : 'Reject'} Verification`} onClose={() => setActionModal(null)}>
          <p style={{ color: 'var(--admin-body)', fontSize: 13, marginBottom: 16 }}>
            {actionModal.action === 'approve'
              ? 'This will approve the dealer, publish all their pending listings, and notify them.'
              : 'This will reject the dealer application and notify them.'}
          </p>
          <textarea
            placeholder={actionModal.action === 'approve' ? 'Optional admin notes...' : 'Reason for rejection (required)...'}
            value={actionNotes}
            onChange={e => setActionNotes(e.target.value)}
            rows={3}
            style={{
              width: '100%', padding: 10, marginBottom: 16,
              background: 'var(--admin-surface-muted)', border: '1px solid var(--border)',
              borderRadius: 8, color: 'var(--admin-ink)', fontSize: 13, outline: 'none', resize: 'vertical',
            }}
          />
          {actionError && <p role="alert" style={{ color: 'var(--admin-status-danger)', background: 'rgba(239,68,68,.08)', border: '1px solid rgba(239,68,68,.3)', borderRadius: 8, padding: 10, fontSize: 12, marginBottom: 12 }}>{actionError}</p>}
          <div style={{ display: 'flex', gap: 10, justifyContent: 'flex-end' }}>
            <button onClick={() => setActionModal(null)} style={{
              padding: '9px 18px', background: 'var(--admin-surface-muted)', border: '1px solid var(--border)',
              borderRadius: 8, color: 'var(--admin-ink)', fontSize: 12, fontWeight: 600, cursor: 'pointer',
            }}>Cancel</button>
            <button onClick={handleAction} disabled={processing} style={{
              padding: '9px 18px', borderRadius: 8, border: 'none',
              background: actionModal.action === 'approve' ? 'var(--admin-status-success)' : 'var(--admin-status-danger)',
              color: 'var(--admin-surface)', fontSize: 12, fontWeight: 700, cursor: processing ? 'not-allowed' : 'pointer',
              opacity: processing ? 0.6 : 1,
            }}>
              {processing ? 'Processing...' : actionModal.action === 'approve' ? 'Approve & Publish' : 'Reject'}
            </button>
          </div>
        </Modal>
      )}
    </div>
  );
}

