import { useState, useEffect, useCallback } from 'react';
import { adminAPI } from '../../api/api';
import { useToast } from '../../context/ToastContext';

import { Star } from 'lucide-react';
export default function AdminReviews() {
  const { toast } = useToast();
  const [reviews, setReviews] = useState([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [actionId, setActionId] = useState(null);
  const [selected, setSelected] = useState(null);
  const [search, setSearch] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const data = await adminAPI.reviews({ page, limit: 20 });
      const list = data.reviews || data.data || [];
      if (search) {
        const q = search.toLowerCase();
        setReviews(list.filter(r =>
          r.user?.name?.toLowerCase().includes(q) ||
          r.user?.email?.toLowerCase().includes(q) ||
          r.dealer?.name?.toLowerCase().includes(q) ||
          r.comment?.toLowerCase().includes(q)
        ));
      } else {
        setReviews(list);
      }
      setTotal(data.pagination?.total || list.length);
    } catch { toast('Failed to load reviews', 'error'); }
    finally { setLoading(false); }
  }, [page, search, toast]);

  useEffect(() => { load(); }, [load]);

  const handleStatus = async (id, status) => {
    setActionId(id);
    try { await adminAPI.reviewStatus(id, status); toast(`Review ${status}`, 'success'); load(); }
    catch (err) { toast(err.response?.data?.message || 'Moderation failed', 'error'); }
    finally { setActionId(null); }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Delete this review permanently? Cannot be undone.')) return;
    setActionId(id);
    try {
      await adminAPI.deleteReview(id);
      toast('Review deleted', 'success');
      load();
      if (selected?._id === id) setSelected(null);
    } catch (err) {
      toast(err.response?.data?.message || 'Delete failed', 'error');
    } finally { setActionId(null); }
  };

  const pages = Math.ceil(total / 20);

  return (
    <div style={{ padding: '32px', background: '#f6faf9', minHeight: '100vh' }}>
      <div style={{ maxWidth: 1400, margin: '0 auto' }}>
        <div style={{ marginBottom: 28 }}>
          <h2 style={{ fontFamily: 'var(--font-display)', fontSize: '1.8rem', fontWeight: 900, fontStyle: 'italic' }}>Review Moderation</h2>
          <p style={{ color: 'var(--admin-muted-content)', fontSize: 13, marginTop: 6 }}>Manage and moderate dealer reviews across the platform</p>
        </div>

        <input
          placeholder="Search reviews by user, dealer, or comment…"
          value={search}
          onChange={e => { setSearch(e.target.value); setPage(1); }}
          style={{
            width: '100%', maxWidth: 400, background: 'rgba(10, 51, 64, 0.04)', border: '1px solid rgba(10, 51, 64, 0.1)',
            borderRadius: 8, padding: '10px 14px', color: '#0a3340', fontSize: 13, outline: 'none', marginBottom: 24,
          }}
        />

        {loading ? (
          <div style={{ display: 'flex', justifyContent: 'center', padding: '60px 0' }}><div className="spinner" /></div>
        ) : reviews.length === 0 ? (
          <div className="empty-state" style={{ padding: 48 }}>
            <div className="empty-icon"><Star size={32} aria-hidden="true" /></div>
            <h3>No reviews found</h3>
            <p style={{ color: 'var(--text-muted)', fontSize: 14, marginTop: 8 }}>{search ? 'No reviews match your search' : 'No reviews have been submitted yet'}</p>
          </div>
        ) : (
          <>
            <div style={{ display: 'grid', gap: 12 }}>
              {reviews.map(r => (
                <div key={r._id} style={{ background: '#FFFFFF', border: '1px solid rgba(10, 51, 64, 0.07)', borderRadius: 14, padding: '18px 22px' }}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 10 }}>
                    <div>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 6 }}>
                        <span style={{ display: 'inline-flex', gap: 2, color: 'var(--admin-status-warning)' }} role="img" aria-label={`${Number.isFinite(r.rating) ? Math.min(Math.max(r.rating, 0), 5) : 0} out of 5 stars`}>{Array.from({ length: Math.min(Math.max(Number.isFinite(r.rating) ? r.rating : 0, 0), 5) }, (_, k) => <Star key={k} size={16} fill="currentColor" aria-hidden="true" />)}</span>
                        <span style={{ fontSize: 14, fontWeight: 700, color: '#0a3340' }}>{r.rating}/5</span>
                      </div>
                      <div style={{ fontSize: 12, color: 'var(--admin-muted-content)' }}>
                        <span style={{ color: 'var(--admin-muted-content)' }}>{r.user?.name || 'Anonymous'}</span>
                        {' · '}
                        <span style={{ color: 'var(--brand)' }}>{r.dealer?.name || 'Unknown Dealer'}</span>
                        {' · '}
                        {new Date(r.createdAt).toLocaleDateString()}
                      </div>
                    </div>
                    <div style={{ display: 'flex', gap: 6, alignItems: 'center' }}>
                      <span style={{ fontSize: 10, fontWeight: 700, textTransform: 'uppercase', color: r.status === 'approved' ? '#15803D' : r.status === 'rejected' ? '#B91C1C' : '#176B87' }}>{r.status || 'pending'}</span>
                      {r.status !== 'approved' && <button className="btn btn-outline btn-sm" disabled={actionId === r._id} onClick={() => handleStatus(r._id, 'approved')}>Approve</button>}
                      {r.status !== 'rejected' && <button className="btn btn-outline btn-sm" disabled={actionId === r._id} onClick={() => handleStatus(r._id, 'rejected')}>Reject</button>}
                      <button className="btn btn-outline btn-sm" style={{ fontSize: 11, color: 'var(--red)', borderColor: 'rgba(239,68,68,0.3)' }}
                        disabled={actionId === r._id} onClick={() => handleDelete(r._id)}>
                        {actionId === r._id ? '…' : 'Delete'}
                      </button>
                    </div>
                  </div>
                  {r.comment && (
                    <div style={{ fontSize: 13, color: 'rgba(10, 51, 64, 0.65)', lineHeight: 1.5, marginBottom: 8, maxWidth: 600 }}>
                      "{r.comment}"
                    </div>
                  )}
                  {r._id === selected?._id && (
                    <div style={{ marginTop: 10, paddingTop: 10, borderTop: '1px solid rgba(10, 51, 64, 0.06)', fontSize: 11, color: 'var(--admin-muted-content)', display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 6 }}>
                      <div>Review ID: {r._id}</div>
                      <div>User ID: {r.user?._id || '—'}</div>
                      <div>Dealer ID: {r.dealer?._id || '—'}</div>
                      <div>User Email: {r.user?.email || '—'}</div>
                    </div>
                  )}
                  <button className="btn btn-outline btn-sm" style={{ fontSize: 10, marginTop: 6 }} onClick={() => setSelected(selected?._id === r._id ? null : r)}>
                    {selected?._id === r._id ? 'Less info' : 'More info'}
                  </button>
                </div>
              ))}
            </div>

            {pages > 1 && (
              <div style={{ display: 'flex', justifyContent: 'center', gap: 8, marginTop: 24, flexWrap: 'wrap' }}>
                {Array.from({ length: Math.min(pages, 10) }, (_, i) => (
                  <button key={i} onClick={() => setPage(i + 1)}
                    className={`btn btn-sm ${page === i + 1 ? 'btn-gold' : 'btn-outline'}`}
                    style={{ fontSize: 11 }}>{i + 1}</button>
                ))}
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { adminAPI } from '../../api/api';

const SEVERITY_COLORS = {
  critical: { bg: 'rgba(239,68,68,0.1)', color: 'var(--red)' },
  warning: { bg: 'rgba(23, 107, 135, 0.1)', color: 'var(--brand)' },
  info: { bg: 'rgba(23, 107, 135, 0.08)', color: '#176B87' },
};

const ACTION_COLORS = {
  vehicle_created: 'var(--green)',
  vehicle_edited: 'var(--brand)',
  vehicle_deleted: 'var(--red)',
  auction_created: 'var(--blue)',
  auction_bid_placed: 'var(--purple)',
  auction_ended: 'var(--orange)',
  escrow_created: 'var(--teal)',
  escrow_released: 'var(--green)',
  escrow_refunded: 'var(--red)',
  dealer_verification_submitted: 'var(--blue)',
  dealer_verification_approved: 'var(--green)',
  user_created: 'var(--blue)',
  role_changed: 'var(--purple)',
  admin_login: 'var(--brand)',
  admin_logout: 'var(--gray)',
  dispute_created: 'var(--red)',
  dispute_resolved: 'var(--green)',
  payment_initiated: 'var(--blue)',
  payment_completed: 'var(--green)',
  payment_refunded: 'var(--red)',
};

export default function AdminSecurityLog() {
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState('');
  const [severityFilter, setSeverityFilter] = useState('');
  const [targetModelFilter, setTargetModelFilter] = useState('');
  const [page, setPage] = useState(1);
  const [pagination, setPagination] = useState(null);
  const [statistics, setStatistics] = useState(null);
  const [showStatistics, setShowStatistics] = useState(false);
  const [exporting, setExporting] = useState(false);

  const fetchLogs = useCallback(() => {
    setLoading(true);
    const params = { page, limit: 30 };
    if (filter) params.action = filter;
    if (severityFilter) params.severity = severityFilter;
    if (targetModelFilter) params.targetModel = targetModelFilter;
    adminAPI.getAuditLogs(params)
      .then(d => {
        setLogs(d.data || []);
        setPagination(d.pagination);
      })
      .catch(() => {})
      .finally(() => setLoading(false));
    // filter is applied manually (Enter key / Apply button), not auto-triggered on change
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [page, severityFilter, targetModelFilter]);

  const fetchStatistics = () => {
    adminAPI.getAuditLogStatistics({ days: 30 })
      .then(d => {
        setStatistics(d.statistics);
      })
      .catch(() => {});
  };

  const handleExport = async (format = 'json') => {
    setExporting(true);
    try {
      const params = { format };
      if (filter) params.action = filter;
      if (severityFilter) params.severity = severityFilter;
      if (targetModelFilter) params.targetModel = targetModelFilter;

      const response = await adminAPI.exportAuditLogs(params);

      if (format === 'csv') {
        const blob = new Blob([response], { type: 'text/csv' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `audit-logs-${Date.now()}.csv`;
        a.click();
        window.URL.revokeObjectURL(url);
      } else {
        const blob = new Blob([JSON.stringify(response, null, 2)], { type: 'application/json' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `audit-logs-${Date.now()}.json`;
        a.click();
        window.URL.revokeObjectURL(url);
      }
    } catch (err) {
      console.error('Export failed:', err);
    } finally {
      setExporting(false);
    }
  };

  useEffect(() => { fetchLogs(); }, [fetchLogs]);
  useEffect(() => { if (showStatistics) fetchStatistics(); }, [showStatistics]);

  return (
    <div className="page" style={{ background: 'var(--bg)' }}>
      <div className="container" style={{ paddingTop: 32, paddingBottom: 32, maxWidth: 1200 }}>
        <div style={{ marginBottom: 24, display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <h2>Immutable Audit Trail</h2>
            <p style={{ color: 'var(--text-muted)', fontSize: 13, marginTop: 4 }}>
              Enterprise-grade audit logging — records cannot be altered or deleted
            </p>
          </div>
          <div style={{ display: 'flex', gap: 8 }}>
            <button
              className="btn btn-sm btn-outline"
              onClick={() => setShowStatistics(!showStatistics)}
            >
              {showStatistics ? 'Hide Statistics' : 'Show Statistics'}
            </button>
            <button
              className="btn btn-sm btn-gold"
              onClick={() => handleExport('json')}
              disabled={exporting}
            >
              {exporting ? 'Exporting...' : 'Export JSON'}
            </button>
            <button
              className="btn btn-sm btn-outline"
              onClick={() => handleExport('csv')}
              disabled={exporting}
            >
              {exporting ? 'Exporting...' : 'Export CSV'}
            </button>
          </div>
        </div>

        {showStatistics && statistics && (
          <div className="card" style={{ marginBottom: 24, padding: 16 }}>
            <h3 style={{ fontSize: 14, marginBottom: 12 }}>Audit Statistics (Last 30 Days)</h3>
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 16 }}>
              <div>
                <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>Total Logs</div>
                <div style={{ fontSize: 24, fontWeight: 600, color: 'var(--brand)' }}>{statistics.totalLogs}</div>
              </div>
              <div>
                <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>Top Actions</div>
                <div style={{ fontSize: 12 }}>
                  {statistics.actionCounts?.slice(0, 3).map((a, i) => (
                    <div key={i} style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span>{a._id}</span>
                      <span style={{ fontWeight: 600 }}>{a.count}</span>
                    </div>
                  ))}
                </div>
              </div>
              <div>
                <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>Severity Distribution</div>
                <div style={{ fontSize: 12 }}>
                  {statistics.severityCounts?.map((s, i) => (
                    <div key={i} style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span style={{ color: SEVERITY_COLORS[s._id]?.color || 'var(--text-muted)' }}>{s._id}</span>
                      <span style={{ fontWeight: 600 }}>{s.count}</span>
                    </div>
                  ))}
                </div>
              </div>
              <div>
                <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>Target Models</div>
                <div style={{ fontSize: 12 }}>
                  {statistics.targetModelCounts?.slice(0, 3).map((t, i) => (
                    <div key={i} style={{ display: 'flex', justifyContent: 'space-between' }}>
                      <span>{t._id}</span>
                      <span style={{ fontWeight: 600 }}>{t.count}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}

        <div className="card" style={{ marginBottom: 24, padding: 16 }}>
          <div style={{ display: 'flex', gap: 12, flexWrap: 'wrap' }}>
            <select
              aria-label="Filter by severity"
              className="input"
              style={{ width: 140, fontSize: 12, padding: '6px 10px' }}
              value={severityFilter}
              onChange={e => { setSeverityFilter(e.target.value); setPage(1); }}
            >
              <option value="">All Severity</option>
              <option value="critical">Critical</option>
              <option value="warning">Warning</option>
              <option value="info">Info</option>
            </select>
            <select
              aria-label="Filter by target model"
              className="input"
              style={{ width: 140, fontSize: 12, padding: '6px 10px' }}
              value={targetModelFilter}
              onChange={e => { setTargetModelFilter(e.target.value); setPage(1); }}
            >
              <option value="">All Models</option>
              <option value="User">User</option>
              <option value="Car">Car</option>
              <option value="Auction">Auction</option>
              <option value="Escrow">Escrow</option>
              <option value="Payment">Payment</option>
              <option value="Bid">Bid</option>
            </select>
            <input
              className="input"
              style={{ width: 200, fontSize: 12, padding: '6px 10px' }}
              placeholder="Search by action..."
              value={filter}
              onChange={e => setFilter(e.target.value)}
              onKeyDown={e => { if (e.key === 'Enter') { setPage(1); fetchLogs(); } }}
            />
            <button className="btn btn-sm btn-gold" onClick={() => { setPage(1); fetchLogs(); }}>
              Search
            </button>
          </div>
        </div>

        {loading ? (
          <div className="loading-center"><div className="spinner" /></div>
        ) : (
          <>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              {logs.length === 0 ? (
                <div className="card" style={{ padding: 40, textAlign: 'center', color: 'var(--text-muted)' }}>
                  No audit logs found
                </div>
              ) : logs.map(log => {
                const sev = SEVERITY_COLORS[log.severity] || SEVERITY_COLORS.info;
                const actionColor = ACTION_COLORS[log.action] || 'var(--text-muted)';
                return (
                  <div key={log._id} className="card" style={{ padding: '12px 16px' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: 12, flexWrap: 'wrap' }}>
                      <span style={{
                        padding: '2px 8px', borderRadius: 4, fontSize: 10, fontWeight: 600,
                        background: sev.bg, color: sev.color, textTransform: 'uppercase',
                      }}>
                        {log.severity}
                      </span>
                      <code style={{ fontSize: 12, color: actionColor, fontFamily: 'monospace' }}>
                        {log.action}
                      </code>
                      <span style={{ fontSize: 12, color: 'var(--text-muted)' }}>
                        {log.actorName || log.actorEmail || 'System'} ({log.actorRole || '—'})
                      </span>
                      {log.targetModel && (
                        <span style={{ fontSize: 11, color: 'var(--text-dim)', background: 'rgba(255,255,255,0.05)', padding: '2px 6px', borderRadius: 4 }}>
                          {log.targetModel}
                        </span>
                      )}
                      {log.targetName && (
                        <span style={{ fontSize: 11, color: 'var(--text-dim)' }}>
                          → {log.targetName}
                        </span>
                      )}
                      <span style={{ marginLeft: 'auto', fontSize: 11, color: 'var(--text-dim)' }}>
                        {new Date(log.createdAt).toLocaleString('en-KE')}
                      </span>
                    </div>
                    {(log.oldValue || log.newValue || log.changes?.length > 0) && (
                      <div style={{ marginTop: 8, padding: '6px 10px', background: 'rgba(255,255,255,0.03)', borderRadius: 6 }}>
                        {log.changes?.length > 0 ? (
                          <div style={{ fontSize: 11 }}>
                            <div style={{ fontWeight: 600, marginBottom: 4, color: 'var(--text-muted)' }}>Changes:</div>
                            {log.changes.map((change, i) => (
                              <div key={i} style={{ marginBottom: 2 }}>
                                <span style={{ color: 'var(--brand)' }}>{change.field}:</span>
                                <span style={{ color: 'var(--red)', marginLeft: 4 }}>{JSON.stringify(change.oldValue)}</span>
                                <span style={{ color: 'var(--text-dim)', margin: '0 4px' }}>→</span>
                                <span style={{ color: 'var(--green)' }}>{JSON.stringify(change.newValue)}</span>
                              </div>
                            ))}
                          </div>
                        ) : (
                          <pre style={{ fontSize: 11, color: 'var(--text-dim)', margin: 0, whiteSpace: 'pre-wrap', wordBreak: 'break-all' }}>
                            {JSON.stringify({ oldValue: log.oldValue, newValue: log.newValue }, null, 1)}
                          </pre>
                        )}
                      </div>
                    )}
                    {log.ipAddress && (
                      <div style={{ marginTop: 4, fontSize: 10, color: 'var(--text-dim)' }}>
                        IP: {log.ipAddress} {log.userAgent && `• ${log.userAgent.substring(0, 50)}...`}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>

            {pagination && pagination.pages > 1 && (
              <div style={{ display: 'flex', justifyContent: 'center', gap: 8, marginTop: 20 }}>
                <button
                  className="btn btn-sm btn-outline"
                  disabled={page <= 1}
                  onClick={() => setPage(p => p - 1)}
                >
                  ← Prev
                </button>
                <span style={{ padding: '6px 12px', fontSize: 13, color: 'var(--text-muted)' }}>
                  Page {pagination.page} of {pagination.pages}
                </span>
                <button
                  className="btn btn-sm btn-outline"
                  disabled={page >= pagination.pages}
                  onClick={() => setPage(p => p + 1)}
                >
                  Next →
                </button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

