            <p className="text-lg opacity-90 mb-4">{block.props.subtitle}</p>
            <button className="px-6 py-2 bg-[#5aafa4] rounded-lg font-medium hover:bg-[#5aafa4] transition-colors">
              {block.props.buttonText}
