      case 'paragraph':
        return <p className="text-[#64748B] leading-relaxed">{block.props.text}</p>;
      case 'image':
        return (
          <div className="rounded-lg overflow-hidden">
            {block.props.src ? (
              <img src={block.props.src} alt={block.props.alt} className="w-full h-auto" />
