      <h2 className="text-2xl font-bold text-[#0A3340]">What-If Analysis</h2>
      <p className="text-[#64748B]">Ask questions in natural language and get AI-powered predictions</p>

      {/* Question Input */}
      <div className="bg-white rounded-xl p-6 shadow-sm border border-[#D7E7E4]">
