              <div className="flex items-center gap-2">
                <CheckCircle size={14} className="text-emerald-600" />
                <span>User Interface</span>
              </div>
              <div className="flex items-center gap-2">
                <CheckCircle size={14} className="text-emerald-600" />
                <span>Shared Services</span>
              </div>
              <div className="flex items-center gap-2">
                <CheckCircle size={14} className="text-emerald-600" />
                <span>AI Components</span>
