import '../../../styles/dashboard.css';
import { Link } from 'react-router-dom';
import { StatCard, QuickLink, BidStatusBadge, TimeRemaining } from './BuyerWidgets';
import { MiniBarChart, BreakdownBars } from '../../../components/features/admin/AdminWidgets';

export default function BuyerOverviewTab({
  favorites, escrows, payments, myBids, chats, watchlist, trending, trendingLoading, onSetTab,
}) {
  const activeEscrows = escrows.filter(e => ['pending','held','disputed'].includes(e.status));
  const unreadMessages = chats.reduce((sum, c) => sum + (c.unreadCount || 0), 0);

  const spendMonthly = (() => {
    const now = new Date();
    const buckets = [];
    for (let i = 5; i >= 0; i--) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      buckets.push({ key: `${d.getFullYear()}-${d.getMonth()}`, label: d.toLocaleDateString('en-KE', { month: 'short' }), value: 0 });
    }
    const map = Object.fromEntries(buckets.map(b => [b.key, b]));
    (payments || []).forEach(p => {
      const d = new Date(p.createdAt || p.date || Date.now());
      const key = `${d.getFullYear()}-${d.getMonth()}`;
      if (map[key]) map[key].value += Number(p.amount || p.total || 0);
    });
    return buckets;
  })();
  const totalSpent = (payments || []).reduce((sum, p) => sum + (Number(p.amount || p.total || 0)), 0);

  const savedByType = (() => {
    const m = {};
    (favorites || []).forEach(f => {
      const car = f.car || f;
      const t = car.bodyType || car.brand || 'Other';
      m[t] = (m[t] || 0) + 1;
    });
    const colors = ['var(--brand)', '#176B87', '#22c55e', '#5aafa4', '#176b87'];
    return Object.entries(m).sort((a, b) => b[1] - a[1]).slice(0, 5)
      .map(([name, count], i) => ({ name, count, color: colors[i % colors.length] }));
  })();

  const fmtK = (v) => (v >= 1e6 ? `${(v / 1e6).toFixed(1)}M` : v >= 1e3 ? `${Math.round(v / 1e3)}K` : `${v || 0}`);

  const statusBadge = (status) => {
    const valid = ['pending', 'held', 'released', 'refunded', 'disputed', 'paid', 'failed', 'accepted', 'outbid', 'won'];
    const cls = valid.includes(status) ? `status-badge-${status}` : 'status-badge-default';
    return (
      <span className={`status-badge ${cls}`}>
        {status.toUpperCase()}
      </span>
    );
  };

  return (
    <>
      <div className="overview-stats">
        <StatCard icon="♥" label="Saved Cars" value={favorites.length} sub={favorites.length ? 'in your wishlist' : 'no saved cars'} accent="#ef4444" to="/favorites" />
        <StatCard icon="⚡" label="Active Bids" value={myBids.filter(b => !b.status || ['pending','active'].includes(b.status)).length} sub={myBids.length ? 'across auctions' : 'place a bid to start'} accent="var(--brand)" to="/showroom?filter=auction" />
        <StatCard icon="⭐" label="Watchlist" value={watchlist.length || '-'} sub={watchlist.length ? 'saved searches' : 'track vehicles'} accent="#176B87" to="/showroom" />
        <StatCard icon="✉" label="Messages" value={unreadMessages || (chats.length || '-')} sub={unreadMessages > 0 ? `${unreadMessages} unread` : chats.length ? 'all read' : 'no messages'} accent="var(--purple)" to="/chat" />
      </div>

      <div className="overview-cols">
        <div className="ov-card">
          <div className="spending-header">
            <div>
              <div className="spending-header-title">Spending Overview</div>
              <div className="spending-header-sub">Payments · last 6 months</div>
            </div>
            <div className="spending-header-right">
              <div className="spending-total-label">Total</div>
              <div className="spending-total-value">KES {fmtK(totalSpent)}</div>
            </div>
          </div>
          <div className="spending-body">
            {totalSpent > 0
              ? <MiniBarChart data={spendMonthly} color="var(--brand)" height={160} format={(v) => `KES ${fmtK(v)}`} />
              : <div className="spending-empty">No payments yet — your purchases will appear here</div>}
          </div>
        </div>

        <div className="ov-card">
          <div className="saved-type-header">
            <span className="saved-type-title">Saved by Type</span>
          </div>
          <div className="saved-type-body">
            {savedByType.length
              ? <BreakdownBars data={savedByType} total={favorites.length} />
              : <div className="saved-type-empty">No saved cars yet</div>}
          </div>
        </div>
      </div>

      <div className="buyer-content-grid">
        <div className="left-column">
          <div>
            <div className="dash-section-title-sm">
              Quick Actions
            </div>
            <div className="quick-links-grid">
              <QuickLink to="/showroom" icon="🚗" label="Browse Gallery" desc="Discover all vehicles" />
              <QuickLink to="/showroom?filter=auction" icon="🔨" label="Live Auctions" desc="Bid in real-time" />
              <QuickLink to="/favorites" icon="♥" label="Saved Cars" desc={`${favorites.length} vehicles saved`} accent="rgba(239,68,68,0.1)" />
              <QuickLink to="/chat" icon="💬" label="Messages" desc="Chat with dealers" accent="rgba(23, 107, 135, 0.1)" />
            </div>
          </div>

          <div className="ov-card">
            <div className="ov-card-header-inner">
              <div className="flex-row">
                <span className="overview-icon">📋</span>
                <span className="activity-title">Recent Activity</span>
              </div>
              <Link to="/dashboard" className="dash-section-link">View All →</Link>
            </div>
            <div className="activity-body">
              {myBids.length === 0 && escrows.length === 0 && chats.length === 0 ? (
                <div className="activity-empty">
                  <span className="activity-empty-text">No activity yet. Start browsing the gallery!</span>
                </div>
              ) : (
                <div className="activity-list">
                  {myBids.slice(0, 3).map(bid => (
                    <div key={bid._id} className="activity-row">
                      <div className="activity-icon-box" style={{ background: 'rgba(23, 107, 135, 0.1)' }}>🔨</div>
                      <div className="activity-info">
                        <div className="activity-title">Bid placed on {bid.car?.title || 'a vehicle'}</div>
                        <div className="activity-meta">KES {Number(bid.amount || 0).toLocaleString()} · {bid.createdAt ? new Date(bid.createdAt).toLocaleDateString() : ''}</div>
                      </div>
                      <BidStatusBadge status={bid.status} />
                    </div>
                  ))}
                  {escrows.slice(0, 2).map(e => {
                    const isLast = escrows.slice(0, 2).indexOf(e) === escrows.slice(0, 2).length - 1 && myBids.length <= 3;
                    return (
                      <div key={e._id} className={`activity-row${isLast ? ' activity-row-last' : ''}`}>
                        <div className="activity-icon-box" style={{ background: 'rgba(34,197,94,0.1)' }}>🔒</div>
                        <div className="activity-info">
                          <div className="activity-title">Escrow for {e.car?.title || 'a vehicle'}</div>
                          <div className="activity-meta">KES {Number(e.amount || 0).toLocaleString()} · {new Date(e.createdAt).toLocaleDateString()}</div>
                        </div>
                        {statusBadge(e.status)}
                      </div>
                    );
                  })}
                  {chats.slice(0, 2).map(c => (
                    <div key={c._id} className="activity-row activity-row-last">
                      <div className="activity-icon-box" style={{ background: 'rgba(23, 107, 135, 0.1)' }}>💬</div>
                      <div className="activity-info">
                        <div className="activity-title">Message from {c.participants?.[0]?.name || 'dealer'}</div>
                        <div className="activity-meta">{c.lastMessage?.text?.slice(0, 50) || 'New conversation'}</div>
                      </div>
                      {c.unreadCount > 0 && (
                        <span className="activity-unread-badge">{c.unreadCount}</span>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>

          <div className="ov-card">
            <div className="ov-card-header-inner">
              <div className="flex-row">
                <span className="overview-icon">🔥</span>
                <span className="activity-title">Trending Now</span>
              </div>
              <Link to="/showroom?sort=views" className="dash-section-link">All →</Link>
            </div>
            <div>
              {trendingLoading ? (
                <div className="loading-centered"><div className="spinner" /></div>
              ) : trending.length === 0 ? (
                <div className="trending-empty-small">
                  <span className="trending-empty-text">No trending cars available</span>
                </div>
              ) : (
                trending.slice(0, 5).map(car => {
                  const img = car.images?.[0]?.url || car.images?.[0] || car.image;
                  return (
                    <Link key={car._id} to={`/cars/${car._id}`} className="link-unstyled">
                      <div className="trending-list-item">
                        {img ? (
                          <img src={img} alt={car.title} className="trending-list-img" loading="lazy" decoding="async" />
                        ) : (
                          <div className="trending-list-img-placeholder" />
                        )}
                        <div className="trending-list-info">
                          <div className="trending-list-name">{car.title || 'Vehicle'}</div>
                          <div className="trending-list-meta">
                            <span className="trending-list-price">KES {Number(car.price || 0).toLocaleString()}</span>
                            {car.views > 0 && <span>· {car.views} views</span>}
                          </div>
                        </div>
                        <svg className="trending-list-arrow" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,0.15)" strokeWidth="2"><path d="M9 18l6-6-6-6"/></svg>
                      </div>
                    </Link>
                  );
                })
              )}
            </div>
          </div>

          {activeEscrows.length > 0 && (
            <div className="ov-card">
              <div className="ov-card-header-inner">
                <div className="activity-title">Active Escrows</div>
                <button onClick={() => onSetTab('escrows')} className="btn-link-gold">View All →</button>
              </div>
              {activeEscrows.slice(0, 3).map(e => (
                <div key={e._id} className="escrow-item-simple">
                  <div>
                    <div className="activity-title activity-title-mb">{e.car?.title || 'Vehicle'}</div>
                    <div className="activity-meta">KES {Number(e.amount||0).toLocaleString()}</div>
                  </div>
                  {statusBadge(e.status)}
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="saved-sidebar">
          <div className="saved-sidebar-header">
            <div className="flex-row">
              <span className="heart-icon">♥</span>
              <span className="activity-title">Saved Cars</span>
            </div>
            <Link to="/favorites" className="dash-section-link">All →</Link>
          </div>
          {favorites.length === 0 ? (
            <div className="saved-sidebar-empty">
              <div className="saved-sidebar-icon">🚗</div>
              <div className="saved-sidebar-empty-text">No saved cars yet.<br />Browse the gallery to start.</div>
              <Link to="/showroom" className="saved-sidebar-cta">Browse Gallery</Link>
            </div>
          ) : favorites.slice(0, 6).map(f => {
            const car = f.car || f;
            const img = car.images?.[0]?.url || car.images?.[0] || car.image;
            return (
              <Link key={f._id} to={`/cars/${car._id}`} className="link-unstyled">
                <div className="saved-sidebar-item">
                  {img ? (
                    <img src={img} alt={car.title} className="saved-sidebar-thumb" loading="lazy" decoding="async" />
                  ) : (
                    <div className="saved-sidebar-thumb-placeholder" />
                  )}
                  <div className="saved-sidebar-info">
                    <div className="saved-sidebar-car-title">{car.title || 'Vehicle'}</div>
                    <div className="saved-sidebar-car-price">KES {Number(car.price||0).toLocaleString()}</div>
                  </div>
                </div>
              </Link>
            );
          })}
        </div>
      </div>
    </>
  );
}

import { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { carsAPI } from '../../api/api';
import { useToast } from '../../context/ToastContext';
import { calculateListingQualityScore, getQualityScoreColor, getQualityScoreGradient } from '../../utils/listingQualityScore';

const BRANDS  = ['Toyota','Mercedes-Benz','BMW','Land Rover','Subaru','Mazda','Nissan','Honda','Volkswagen','Lexus','Audi','Mitsubishi','Hyundai','Kia','Ford','Jeep','Peugeot','Isuzu'];
const FUELS   = ['Petrol','Diesel','Hybrid','Electric','LPG'];
const TRANS   = ['Automatic','Manual','CVT','Semi-Automatic'];
const BODIES  = ['SUV','Sedan','Hatchback','Pickup','Wagon','Van','Coupe','Convertible','Bus'];
const CITIES  = ['Nairobi','Mombasa','Kisumu','Nakuru','Eldoret','Thika','Nyeri','Machakos','Meru'];

export default function AddCarPage() {
  const { toast }  = useToast();
  const navigate   = useNavigate();
  const [loading, setLoading] = useState(false);
  const [images, setImages]   = useState([]);
  const [previews, setPreviews] = useState([]);
  const [step, setStep]       = useState(1);

  const [form, setForm] = useState({
    title: '', brand: '', model: '', year: '',
    price: '', fuel: '', transmission: '', bodyType: '', mileage: '',
    city: '', address: '', dealerPhone: '',
    allowBuy: true, allowBid: false,
    auctionStatus: 'draft', auctionEnd: '',
  });

  const set = (k, v) => setForm(p => ({ ...p, [k]: v }));

  // Calculate listing quality score based on form data
  const qualityScore = useMemo(() => {
    const factors = {
      hasTitle: Boolean(form.title),
      hasBrand: Boolean(form.brand),
      hasModel: Boolean(form.model),
      hasYear: Boolean(form.year),
      hasPrice: Boolean(form.price),
      hasMileage: Boolean(form.mileage),
      hasFuel: Boolean(form.fuel),
      hasTransmission: Boolean(form.transmission),
      hasBodyType: Boolean(form.bodyType),
      hasDescription: false,
      hasLocation: Boolean(form.city),
      hasImages: images.length > 0,
      imageCount: images.length,
      hasFeatures: false,
      featureCount: 0,
      hasVin: false,
      hasLogbook: false,
      descriptionLength: 0,
    };
    return calculateListingQualityScore(factors);
  }, [form, images.length]);

  // Quality Score Component
  const QualityIndicator = () => (
    <div style={{
      background: 'var(--surface)',
      border: '1px solid var(--border)',
      borderRadius: 12,
      padding: 16,
      marginBottom: 20,
    }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 }}>
        <span style={{ fontSize: 13, fontWeight: 600, color: 'var(--text-muted)' }}>Listing Quality Score</span>
        <span style={{
          fontSize: 24,
          fontWeight: 800,
          color: getQualityScoreColor(qualityScore.score),
        }}>
          {qualityScore.score}/100
        </span>
      </div>
      <div style={{
        height: 8,
        background: 'var(--border)',
        borderRadius: 4,
        overflow: 'hidden',
        marginBottom: 12,
      }}>
        <div style={{
          height: '100%',
          width: `${qualityScore.score}%`,
          background: getQualityScoreGradient(qualityScore.score),
          borderRadius: 4,
          transition: 'width 0.3s ease',
        }} />
      </div>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <span style={{
          fontSize: 12,
          fontWeight: 600,
          color: getQualityScoreColor(qualityScore.score),
          textTransform: 'uppercase',
          letterSpacing: '0.05em',
        }}>
          {qualityScore.level}
        </span>
        {qualityScore.suggestions.length > 0 && (
          <span style={{ fontSize: 11, color: 'var(--text-muted)' }}>
            💡 {qualityScore.suggestions[0]}
          </span>
        )}
      </div>
    </div>
  );

  const handleImages = (e) => {
    const files = Array.from(e.target.files).slice(0, 8);
    setImages(files);
    setPreviews(files.map(f => URL.createObjectURL(f)));
  };

  const handleSubmit = async () => {
    if (!form.title || !form.price || !form.brand) {
      toast('Fill in title, brand and price', 'error'); return;
    }
    setLoading(true);
    try {
      const fd = new FormData();
      Object.entries(form).forEach(([k, v]) => {
        if (v !== '' && v !== null) fd.append(k, v);
      });
      images.forEach(img => fd.append('images', img));

      const data = await carsAPI.create(fd);
      toast('🚗 Car listed successfully!', 'success');
      navigate('/dealer');
    } catch (err) {
      toast(err.response?.data?.message || 'Failed to create listing', 'error');
    } finally {
      setLoading(false);
    }
  };

  const Field = ({ label, children }) => (
    <div className="input-group">{label && <label className="input-label">{label}</label>}{children}</div>
  );

  const SelectField = ({ label, field, options }) => (
    <Field label={label}>
      <select className="input" value={form[field]} onChange={e => set(field, e.target.value)}>
        <option value="">Select {label}</option>
        {options.map(o => <option key={o} value={o}>{o}</option>)}
      </select>
    </Field>
  );

  return (
    <div className="page">
      <div className="container" style={{ paddingTop: 32, paddingBottom: 32, maxWidth: 800 }}>

        {/* Header */}
        <div style={{ marginBottom: 32 }}>
          <div className="section-eyebrow">Dealer Hub</div>
          <h2>List a Car</h2>
          <p style={{ color: 'var(--text-muted)', fontSize: 14, marginTop: 6 }}>
            Fill in the details below. Better info = more bids.
          </p>
        </div>

        {/* Step indicator */}
        <div style={{ display: 'flex', gap: 8, marginBottom: 32 }}>
          {['Basic Info', 'Specs', 'Pricing & Mode', 'Photos'].map((s, i) => (
            <div
              key={s}
              onClick={() => setStep(i + 1)}
              style={{
                flex: 1, textAlign: 'center', padding: '10px 8px', borderRadius: 8,
                background: step === i + 1 ? 'var(--brand-glow)' : 'var(--surface)',
                border: `1px solid ${step === i + 1 ? 'var(--brand)' : 'var(--border)'}`,
                cursor: 'pointer', fontSize: 13, fontWeight: step === i + 1 ? 600 : 400,
                color: step === i + 1 ? 'var(--brand)' : 'var(--text-muted)',
              }}
            >
              <div style={{ fontWeight: 700, fontSize: 16, marginBottom: 2 }}>{i + 1}</div>
              {s}
            </div>
          ))}
        </div>

        {/* Quality Score Indicator */}
        <QualityIndicator />

        <div className="card" style={{ padding: 28, marginBottom: 20 }}>

          {/* ─ Step 1: Basic Info ─ */}
          {step === 1 && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
              <h3 style={{ marginBottom: 4 }}>Basic Information</h3>
              <Field label="Listing Title *">
                <input className="input" placeholder="e.g. 2020 Toyota Land Cruiser V8 — Excellent Condition"
                  value={form.title} onChange={e => set('title', e.target.value)} />
              </Field>
              <div className="grid-2">
                <SelectField label="Brand *" field="brand" options={BRANDS} />
                <Field label="Model">
                  <input className="input" placeholder="e.g. Land Cruiser" value={form.model} onChange={e => set('model', e.target.value)} />
                </Field>
                <Field label="Year">
                  <input className="input" type="text" inputMode="numeric" pattern="[0-9]*"
                    value={form.year} onChange={e => set('year', e.target.value)} />
                </Field>
                <SelectField label="Body Type" field="bodyType" options={BODIES} />
              </div>
              <div className="grid-2">
                <SelectField label="City" field="city" options={CITIES} />
                <Field label="Dealer Phone">
                  <input className="input" placeholder="0712 345 678" value={form.dealerPhone} onChange={e => set('dealerPhone', e.target.value)} />
                </Field>
              </div>
              <Field label="Address (Optional)">
                <input className="input" placeholder="e.g. Ngong Road, Nairobi" value={form.address} onChange={e => set('address', e.target.value)} />
              </Field>
            </div>
          )}

          {/* ─ Step 2: Specs ─ */}
          {step === 2 && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
              <h3 style={{ marginBottom: 4 }}>Vehicle Specs</h3>
              <div className="grid-2">
                <SelectField label="Fuel Type" field="fuel" options={FUELS} />
                <SelectField label="Transmission" field="transmission" options={TRANS} />
                <Field label="Mileage (km)">
                  <input className="input" type="text" inputMode="numeric" pattern="[0-9]*" placeholder="e.g. 45000" value={form.mileage} onChange={e => set('mileage', e.target.value)} />
                </Field>
              </div>
            </div>
          )}

          {/* ─ Step 3: Pricing & Mode ─ */}
          {step === 3 && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
              <h3 style={{ marginBottom: 4 }}>Pricing & Listing Mode</h3>
              <Field label="Asking Price (KES) *">
                <input className="input" type="text" inputMode="numeric" pattern="[0-9]*" placeholder="e.g. 3500000" value={form.price} onChange={e => set('price', e.target.value)} />
              </Field>

              {/* Listing mode */}
              <div>
                <label className="input-label" style={{ marginBottom: 12, display: 'block' }}>How do you want to sell?</label>
                <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                  {[
                    { key: 'allowBuy', icon: '💳', title: 'Direct Buy',     desc: 'Buyers can purchase at your listed price via M-Pesa.' },
                    { key: 'allowBid', icon: '⚡', title: 'Allow Bidding',  desc: 'Buyers can place bids. You choose the winner.' },
                  ].map(opt => (
                    <div
                      key={opt.key}
                      onClick={() => set(opt.key, !form[opt.key])}
                      style={{
                        display: 'flex', alignItems: 'center', gap: 14,
                        background: form[opt.key] ? 'var(--brand-glow)' : 'var(--surface)',
                        border: `2px solid ${form[opt.key] ? 'var(--brand)' : 'var(--border)'}`,
                        borderRadius: 10, padding: '14px 16px', cursor: 'pointer',
                        transition: 'all 0.2s',
                      }}
                    >
                      <span style={{ fontSize: 28 }}>{opt.icon}</span>
                      <div style={{ flex: 1 }}>
                        <div style={{ fontWeight: 600, fontSize: 14 }}>{opt.title}</div>
                        <div style={{ fontSize: 12, color: 'var(--text-muted)' }}>{opt.desc}</div>
                      </div>
                      <div style={{
                        width: 22, height: 22, borderRadius: '50%',
                        background: form[opt.key] ? 'var(--brand)' : 'transparent',
                        border: `2px solid ${form[opt.key] ? 'var(--brand)' : 'var(--border)'}`,
                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                        color: '#0A3340', fontSize: 12, fontWeight: 700,
                      }}>
                        {form[opt.key] && '✓'}
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              {/* Auction settings */}
              {form.allowBid && (
                <div style={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: 10, padding: 18 }}>
                  <div style={{ fontWeight: 600, fontSize: 14, marginBottom: 12 }}>⚡ Auction Settings</div>
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
                    <Field label="Start Auction As">
                      <select className="input" value={form.auctionStatus} onChange={e => set('auctionStatus', e.target.value)}>
                        <option value="draft">Draft (start later)</option>
                        <option value="live">Live Immediately</option>
                      </select>
                    </Field>
                    {form.auctionStatus === 'live' && (
                      <Field label="Auction End Time">
                        <input className="input" type="datetime-local"
                          value={form.auctionEnd} onChange={e => set('auctionEnd', e.target.value)} />
                      </Field>
                    )}
                  </div>
                </div>
              )}
            </div>
          )}

          {/* ─ Step 4: Photos ─ */}
          {step === 4 && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
              <h3 style={{ marginBottom: 4 }}>Upload Photos</h3>
              <div
                style={{
                  border: '2px dashed var(--border-soft)', borderRadius: 'var(--radius-lg)',
                  padding: 40, textAlign: 'center', cursor: 'pointer',
                  transition: 'border-color 0.2s',
                }}
                onClick={() => document.getElementById('car-images').click()}
                onDragOver={e => e.preventDefault()}
                onDrop={e => {
                  e.preventDefault();
                  const files = Array.from(e.dataTransfer.files).filter(f => f.type.startsWith('image/')).slice(0, 8);
                  setImages(files); setPreviews(files.map(f => URL.createObjectURL(f)));
                }}
              >
                <div style={{ fontSize: 48, marginBottom: 12 }}>📷</div>
                <div style={{ fontWeight: 600, marginBottom: 6 }}>Drop photos here or click to browse</div>
                <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>Up to 8 images · JPG, PNG, WEBP</div>
                <input id="car-images" type="file" multiple accept="image/*" onChange={handleImages} style={{ display: 'none' }} />
              </div>

              {previews.length > 0 && (
                <div className="grid-4" style={{ gap: 8 }}>
                  {previews.map((src, i) => (
                    <div key={i} style={{ aspectRatio: '4/3', borderRadius: 8, overflow: 'hidden', position: 'relative' }}>
                      <img src={src} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                      {i === 0 && (
                        <div style={{
                          position: 'absolute', top: 4, left: 4, background: 'var(--brand)',
                          color: '#0A3340', fontSize: 9, fontWeight: 700, padding: '2px 6px', borderRadius: 4,
                        }}>MAIN</div>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>

        {/* Navigation Buttons */}
        <div style={{ display: 'flex', justifyContent: 'space-between', gap: 12 }}>
          {step > 1 ? (
            <button className="btn btn-outline" onClick={() => setStep(s => s - 1)}>← Back</button>
          ) : <div />}

          {step < 4 ? (
            <button className="btn btn-gold" onClick={() => setStep(s => s + 1)}>Continue →</button>
          ) : (
            <button className="btn btn-gold btn-lg" onClick={handleSubmit} disabled={loading}>
              {loading ? <><div className="spinner" style={{ width: 18, height: 18 }} /> Publishing...</> : '🚗 Publish Listing'}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { dealerAPI, formatKES } from '../../api/api';
import { useToast } from '../../context/ToastContext';
import { timeAgo, compactNumber } from '../../utils/helpers';

const BAR_COLORS = ['var(--brand)', 'var(--brand-muted)', 'var(--blue)', 'var(--green)', 'var(--orange)'];

function MiniBar({ value, max, color = 'var(--brand)', label, sub }) {
  const pct = max > 0 ? Math.round((value / max) * 100) : 0;
  return (
    <div style={{ marginBottom: 14 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 5 }}>
        <span style={{ fontSize: 13, fontWeight: 500 }}>{label}</span>
        <span style={{ fontSize: 13, color: 'var(--text-muted)' }}>{sub}</span>
      </div>
      <div style={{ height: 6, background: 'var(--surface)', borderRadius: 3, overflow: 'hidden' }}>
        <div style={{ width: `${pct}%`, height: '100%', background: color, borderRadius: 3, transition: 'width 0.6s ease' }} />
      </div>
    </div>
  );
}

export default function DealerAnalytics() {
  const { toast } = useToast();
  const [summary, setSummary]   = useState(null);
  const [earnings, setEarnings] = useState(null);
  const [analytics, setAnalytics] = useState(null);
  const [loading, setLoading]   = useState(true);
  const [period, setPeriod]     = useState('30');

  useEffect(() => {
    setLoading(true);
    Promise.all([
      dealerAPI.summary(),
      dealerAPI.earnings({ days: period }),
      dealerAPI.analytics({ days: period }),
    ]).then(([s, e, a]) => {
      setSummary(s.summary || s.data || s);
      setEarnings(e.earnings || e.data || e);
      setAnalytics(a.analytics || a.data || a);
    }).catch(() => toast('Failed to load analytics', 'error'))
    .finally(() => setLoading(false));
  }, [period]);

  if (loading) return <div className="page loading-center"><div className="spinner" /></div>;

  const topCars = analytics?.topCars || analytics?.cars || [];
  const maxViews = Math.max(...topCars.map(c => c.views || 0), 1);
  const maxBids  = Math.max(...topCars.map(c => c.bidsCount || 0), 1);

  const monthlyEarnings = earnings?.monthly || earnings?.byMonth || [];
  const maxMonthly = Math.max(...monthlyEarnings.map(m => m.amount || m.total || 0), 1);

  return (
    <div className="page">
      <div className="container" style={{ paddingTop: 32, paddingBottom: 32 }}>

        {/* Header */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: 32, flexWrap: 'wrap', gap: 16 }}>
          <div>
            <div className="section-eyebrow">Dealer Hub</div>
            <h2>Analytics & Earnings</h2>
          </div>
          <div style={{ display: 'flex', gap: 8 }}>
            {[
              { val: '7',   label: '7 Days' },
              { val: '30',  label: '30 Days' },
              { val: '90',  label: '3 Months' },
              { val: '365', label: '1 Year' },
            ].map(p => (
              <button key={p.val}
                className={`btn btn-sm ${period === p.val ? 'btn-gold' : 'btn-outline'}`}
                onClick={() => setPeriod(p.val)}>
                {p.label}
              </button>
            ))}
          </div>
        </div>

        {/* ─── Top KPIs ─── */}
        <div className="grid-4" style={{ marginBottom: 28 }}>
          {[
            { label: 'Total Listings',    val: summary?.totalCars || 0,                    icon: '🚗', color: 'var(--text)' },
            { label: 'Total Views',       val: compactNumber(analytics?.totalViews || 0),  icon: '👁', color: 'var(--blue)' },
            { label: 'Total Bids',        val: analytics?.totalBids || 0,                  icon: '⚡', color: 'var(--brand-light)' },
            { label: `Revenue (${period}d)`, val: formatKES(earnings?.total || 0),         icon: '💰', color: 'var(--green)' },
          ].map(s => (
            <div key={s.label} className="stat-box">
              <div style={{ display: 'flex', justifyContent: 'space-between' }}>
                <div>
                  <div className="stat-label">{s.label}</div>
                  <div className="stat-value" style={{ color: s.color }}>{s.val}</div>
                </div>
                <span style={{ fontSize: 26 }}>{s.icon}</span>
              </div>
            </div>
          ))}
        </div>

        <div className="grid-2" style={{ marginBottom: 20 }}>

          {/* ─── Monthly Revenue Chart ─── */}
          <div className="card" style={{ padding: 24 }}>
            <h3 style={{ fontSize: '1rem', marginBottom: 20 }}>📈 Revenue Over Time</h3>
            {monthlyEarnings.length === 0 ? (
              <div className="empty-state" style={{ padding: 32 }}>
                <div style={{ fontSize: 32, marginBottom: 8 }}>📊</div>
                <p style={{ fontSize: 13 }}>No earnings data yet</p>
              </div>
            ) : (
              <>
                <div style={{ display: 'flex', alignItems: 'flex-end', gap: 6, height: 140, marginBottom: 10 }}>
                  {monthlyEarnings.slice(-12).map((m, i) => {
                    const val = m.amount || m.total || 0;
                    const pct = maxMonthly > 0 ? (val / maxMonthly) * 100 : 0;
                    return (
                      <div key={i} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4 }}>
                        <div style={{ fontSize: 9, color: 'var(--text-dim)' }}>{formatKES(val).replace('KES ', '')}</div>
                        <div style={{
                          width: '100%', borderRadius: '3px 3px 0 0',
                          height: `${Math.max(4, pct)}%`,
                          background: i === monthlyEarnings.slice(-12).length - 1
                            ? 'var(--brand)' : 'var(--brand-muted)',
                          minHeight: 4, transition: 'height 0.4s ease',
                          cursor: 'default',
                        }} title={`${m.month || m.label || ''}: ${formatKES(val)}`} />
                      </div>
                    );
                  })}
                </div>
                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 10, color: 'var(--text-dim)' }}>
                  {monthlyEarnings.slice(-12).filter((_, i) => i % 3 === 0).map((m, i) => (
                    <span key={i}>{m.month || m.label || `M${i + 1}`}</span>
                  ))}
                </div>
                <div className="gold-line" style={{ margin: '16px 0' }} />
                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 13 }}>
                  <span style={{ color: 'var(--text-muted)' }}>Total period</span>
                  <span className="price-tag" style={{ fontSize: '1rem' }}>{formatKES(earnings?.total || 0)}</span>
                </div>
              </>
            )}
          </div>

          {/* ─── Listing Status Breakdown ─── */}
          <div className="card" style={{ padding: 24 }}>
            <h3 style={{ fontSize: '1rem', marginBottom: 20 }}>🗂 Listing Breakdown</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 0 }}>
              {[
                { label: 'Active Listings',  val: summary?.activeCars    || 0, color: 'var(--green)' },
                { label: 'Live Auctions',    val: summary?.liveAuctions  || 0, color: 'var(--red)' },
                { label: 'Sold',             val: summary?.soldCars      || 0, color: 'var(--brand)' },
                { label: 'Pending Bids',     val: summary?.pendingBids   || 0, color: 'var(--blue)' },
                { label: 'Draft',            val: summary?.draftCars     || 0, color: 'var(--text-muted)' },
              ].map((s, i) => {
                const total = summary?.totalCars || 1;
                return <MiniBar key={s.label} label={s.label} sub={s.val} value={s.val} max={total} color={BAR_COLORS[i]} />;
              })}
            </div>

            {/* Conversion rate */}
            {summary?.totalCars > 0 && (
              <div style={{ marginTop: 20, background: 'var(--surface)', borderRadius: 'var(--radius)', padding: 14 }}>
                <div style={{ fontSize: 11, color: 'var(--text-muted)', textTransform: 'uppercase', letterSpacing: '0.06em' }}>Sell-Through Rate</div>
                <div style={{ fontFamily: 'var(--font-display)', fontSize: '1.6rem', color: 'var(--brand-light)', marginTop: 4 }}>
                  {Math.round(((summary?.soldCars || 0) / summary.totalCars) * 100)}%
                </div>
              </div>
            )}
          </div>
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: 20 }}>

          {/* ─── Top Performing Cars ─── */}
          <div className="card" style={{ padding: 24 }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 }}>
              <h3 style={{ fontSize: '1rem' }}>🔥 Top Listings</h3>
              <Link to="/dealer" className="btn btn-ghost btn-sm" style={{ fontSize: 12 }}>View All →</Link>
            </div>
            {topCars.length === 0 ? (
              <div className="empty-state" style={{ padding: 24 }}>
                <div className="empty-icon">🚗</div>
                <h3>No listing data</h3>
                <Link to="/dealer/add-car" className="btn btn-gold btn-sm" style={{ marginTop: 12 }}>Add First Car</Link>
              </div>
            ) : topCars.slice(0, 5).map((car, i) => (
              <div key={car._id} style={{ display: 'flex', alignItems: 'center', gap: 12, padding: '12px 0', borderBottom: '1px solid var(--border)' }}>
                <div style={{
                  width: 28, height: 28, borderRadius: '50%', flexShrink: 0,
                  background: i === 0 ? 'var(--brand)' : 'var(--surface)',
                  border: `1px solid ${i === 0 ? 'var(--brand)' : 'var(--border)'}`,
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: 13, fontWeight: 700,
                  color: i === 0 ? '#0A3340' : 'var(--text-muted)',
                }}>
                  {i + 1}
                </div>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <Link to={`/cars/${car._id}`} style={{ fontWeight: 600, fontSize: 13, color: 'var(--text)' }}>
                    {car.title}
                  </Link>
                  <div style={{ fontSize: 11, color: 'var(--text-muted)', marginTop: 2 }}>
                    👁 {car.views || 0} · ⚡ {car.bidsCount || 0} bids · ❤️ {car.favoritesCount || 0}
                  </div>
                </div>
                <div style={{ textAlign: 'right', flexShrink: 0 }}>
                  <div className="price-tag" style={{ fontSize: '0.85rem' }}>{formatKES(car.currentBid || car.price)}</div>
                  <span className={`badge ${car.auctionStatus === 'live' ? 'badge-green' : car.status === 'sold' ? 'badge-gold' : 'badge-muted'}`} style={{ marginTop: 3, fontSize: 9 }}>
                    {car.auctionStatus === 'live' ? '🔴 LIVE' : car.status || 'Active'}
                  </span>
                </div>
              </div>
            ))}
          </div>

          {/* ─── Quick Tips ─── */}
          <div style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
            <div className="card" style={{ padding: 20 }}>
              <h3 style={{ fontSize: '0.95rem', marginBottom: 16 }}>💡 Boost Your Listings</h3>
              {[
                { icon: '📷', tip: 'Add 6+ high-quality photos. Listings with more images get 3× more views.' },
                { icon: '⚡', tip: 'Enable live auctions. They generate 5× more bids than fixed-price.' },
                { icon: '✅', tip: 'Keep your dealer profile complete and verified for trust badge.' },
                { icon: '📍', tip: 'Specify exact city location to appear in local searches.' },
              ].map(t => (
                <div key={t.icon} style={{ display: 'flex', gap: 10, marginBottom: 12 }}>
                  <span style={{ fontSize: 18, flexShrink: 0 }}>{t.icon}</span>
                  <p style={{ fontSize: 12, color: 'var(--text-muted)', lineHeight: 1.5 }}>{t.tip}</p>
                </div>
              ))}
            </div>

            <div className="card" style={{ padding: 20 }}>
              <h3 style={{ fontSize: '0.95rem', marginBottom: 14 }}>Quick Actions</h3>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                <Link to="/dealer/add-car"  className="btn btn-gold btn-sm" style={{ justifyContent: 'center' }}>+ New Listing</Link>
                <Link to="/dealer"          className="btn btn-outline btn-sm" style={{ justifyContent: 'center' }}>Dashboard</Link>
                <Link to="/admin/auctions"  className="btn btn-outline btn-sm" style={{ justifyContent: 'center' }}>Auction Control</Link>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { AlertTriangle, CheckCircle2, Clock3, Gavel, RefreshCw, Truck, Wallet } from 'lucide-react';
import { auctionOperationsAPI } from '../../api/api';
import { AuctionPremiumHeader, AuctionPremiumStats } from '../../components/auction/AuctionPremiumSurface';
import { useToast } from '../../context/ToastContext';

const money = (n) => `KES ${Number(n || 0).toLocaleString('en-KE')}`;

const statusMeta = {
  payment_due: ['Payment due', Clock3],
  escrow_pending_funding: ['Escrow funding', Wallet],
  payment_received: ['Payment received', CheckCircle2],
  reaward_pending: ['Re-award pending', AlertTriangle],
  disputed: ['Disputed', AlertTriangle],
  cancelled: ['Cancelled', AlertTriangle],
  defaulted: ['Defaulted', AlertTriangle],
  completed: ['Completed', CheckCircle2],
  no_sale: ['No sale', Gavel],
};

export default function DealerAuctionOperations() {
  const { toast } = useToast();
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(null);
  const [filter, setFilter] = useState('all');

  const load = useCallback(async () => {
    setLoading(true);
    try { const res = await auctionOperationsAPI.list(); setRows(res.data || res || []); }
    catch (err) { toast(err?.response?.data?.message || 'Failed to load auction operations', 'error'); }
    finally { setLoading(false); }
  }, [toast]);

  useEffect(() => { load(); }, [load]);

  const visible = useMemo(() => filter === 'all' ? rows : rows.filter((r) => r.status === filter), [rows, filter]);

  const act = async (id, action, body = {}) => {
    setBusy(`${id}:${action}`);
    try {
      if (action === 'collection') await auctionOperationsAPI.collection(id, body);
      if (action === 'transfer') await auctionOperationsAPI.transfer(id, body);
      if (action === 'release') await auctionOperationsAPI.release(id);
      if (action === 'reaward') await auctionOperationsAPI.reaward(id);
      toast('Auction operation updated', 'success');
      await load();
    } catch (err) { toast(err?.response?.data?.message || 'Operation failed', 'error'); }
    finally { setBusy(null); }
  };

  return (
    <div className="dealer-auction-premium" style={{ minHeight: '100vh' }}>
      <div className="dao-shell">
        <AuctionPremiumHeader kicker="DEALER OPERATIONS · AUCTION FULFILMENT" title="A premium command centre for every auction outcome." description="Move winners from payment through collection, transfer and completion while keeping exceptions visible and controlled." action={<button onClick={load} className="dao-btn secondary"><RefreshCw size={14} /> Refresh</button>} />
        <AuctionPremiumStats items={[{ label: 'Cases', value: rows.length }, { label: 'Payment due', value: rows.filter((r) => r.status === 'payment_due').length }, { label: 'In fulfilment', value: rows.filter((r) => ['payment_received','escrow_pending_funding'].includes(r.status)).length }, { label: 'Completed', value: rows.filter((r) => r.status === 'completed').length }]} />
        <section className="dao-hero dao-filter-panel">
          <div className="dao-toolbar">
            {['all', 'payment_due', 'escrow_pending_funding', 'payment_received', 'reaward_pending', 'disputed', 'completed'].map((key) => (
              <button key={key} onClick={() => setFilter(key)} className={`dao-filter ${filter === key ? 'active' : ''}`}>{key === 'all' ? 'All' : (statusMeta[key]?.[0] || key)}</button>
            ))}
          </div>
        </section>

        <div style={{ marginTop: 22 }}>
          {loading ? <div style={empty}>Loading auction operations…</div> : visible.length === 0 ? <div style={empty}>No fulfilment cases match this filter.</div> : <div style={{ display: 'grid', gap: 14 }}>{visible.map((row) => {
            const [label, Icon] = statusMeta[row.status] || [row.status, Gavel];
            const busyKey = (a) => busy === `${row.id}:${a}`;
            const canCollect = ['payment_received'].includes(row.status) && row.collection_status !== 'collected';
            const canRelease = row.settlement_mode === 'escrow' && row.escrow_id && row.collection_status === 'collected';
            const canTransfer = row.collection_status === 'collected' && row.payment_status === 'paid';
            const canReaward = row.status === 'reaward_pending';
            return <div key={row.id} className="dao-case auction-touch-card">
              <div className="dao-case-main">
                <div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 9 }}><Icon size={15} /><span style={pill}>{label}</span><span style={smallPill}>{row.settlement_mode === 'escrow' ? 'Escrow' : 'Direct'}</span></div>
                  <div style={{ fontWeight: 900, color: '#0a3340', fontSize: 17 }}>{row.car?.title || 'Auction vehicle'}</div>
                  <div style={{ marginTop: 6, color: '#71868C', fontSize: 12 }}>Winner: {row.winner_user_id || '—'} · Outcome {String(row.id).slice(0, 8)}</div>
                </div>
                <div><div className="dao-stat-label">Winning amount</div><div className="dao-stat-value">{money(row.winning_amount)}</div></div>
                <div><div className="dao-stat-label">Fulfilment</div><div style={{ fontSize: 12, fontWeight: 800 }}>Collection: {row.collection_status || '—'}</div><div style={{ fontSize: 12, fontWeight: 800, marginTop: 4 }}>Transfer: {row.transfer_status || '—'}</div></div>
              </div>
              <div className="dao-actions">
                {canCollect && <button disabled={!!busy} onClick={() => act(row.id, 'collection', { status: 'collected', notes: 'Dealer recorded vehicle collection.' })} className="dao-btn primary"><Truck size={14} /> {busyKey('collection') ? 'Saving…' : 'Mark collected'}</button>}
                {canRelease && <button disabled={!!busy} onClick={() => act(row.id, 'release')} className="dao-btn primary"><Wallet size={14} /> {busyKey('release') ? 'Releasing…' : 'Release escrow'}</button>}
                {canTransfer && <button disabled={!!busy} onClick={() => act(row.id, 'transfer', { status: 'completed', notes: 'Ownership transfer recorded by dealer/winner.' })} className="dao-btn primary"><CheckCircle2 size={14} /> {busyKey('transfer') ? 'Saving…' : 'Complete transfer'}</button>}
                {canReaward && <button disabled={!!busy} onClick={() => act(row.id, 'reaward')} className="dao-btn secondary"><Gavel size={14} /> {busyKey('reaward') ? 'Re-awarding…' : 'Re-award to next eligible bidder'}</button>}
                <Link to={`/dealer/auction-operations/${row.id}`} className="dao-btn secondary" style={{ textDecoration: 'none' }}>Open case</Link>
              </div>
            </div>;
          })}</div>}
        </div>
      </div>
    </div>
  );
}

const button = {
  primary: { padding: '10px 14px', border: 0, borderRadius: 8, background: 'var(--brand)', color: '#0a3340', fontWeight: 900, fontSize: 11, display: 'inline-flex', alignItems: 'center', gap: 7, cursor: 'pointer' },
  secondary: { padding: '9px 13px', border: '1px solid rgba(10, 51, 64, .1)', borderRadius: 8, background: '#fff', color: '#0a3340', fontWeight: 800, fontSize: 11, display: 'inline-flex', alignItems: 'center', gap: 7, cursor: 'pointer' },
  tab: { padding: '12px 13px', background: 'transparent', border: 0, color: '#0a3340', fontSize: 11, fontWeight: 850, cursor: 'pointer', whiteSpace: 'nowrap' },
};
const card = { background: '#fff', border: '1px solid rgba(10, 51, 64, .07)', borderRadius: 12, overflow: 'hidden', boxShadow: '0 12px 35px rgba(10, 51, 64, .05)' };
const empty = { padding: 70, textAlign: 'center', background: '#fff', border: '1px solid rgba(10, 51, 64, .07)', borderRadius: 12, color: 'rgba(10, 51, 64, .5)' };
const pill = { padding: '4px 8px', borderRadius: 999, background: 'rgba(23, 107, 135, .08)', color: '#176B87', fontSize: 10, fontWeight: 900 };
const smallPill = { padding: '4px 8px', borderRadius: 999, background: 'rgba(10, 51, 64, .05)', color: '#0a3340', fontSize: 10, fontWeight: 800 };
const labelStyle = { fontSize: 9, textTransform: 'uppercase', letterSpacing: '.1em', fontWeight: 800, color: 'rgba(10, 51, 64, .38)', marginBottom: 4 };
const valueStyle = { fontSize: 16, fontWeight: 900, fontFamily: 'var(--font-display)', fontStyle: 'italic', color: 'var(--brand)' };

