import { AlertTriangle, ChevronRight, FileText, Save, Keyboard } from 'lucide-react';
import { useEffect, useState } from 'react';
import { timeAgo } from '../../../utils/helpers';

export default function InspectorChecklistView({ activeTask, setActiveTask, checklist, setChecklist, notes, setNotes, condition, setCondition, collapsedCats, setCollapsedCats, searchQuery, setSearchQuery, handleSubmit, CATEGORIES }) {
  const total = checklist.length;
  const passed = checklist.filter(c => c.passed === true).length;
  const failed = checklist.filter(c => c.passed === false).length;
  const untested = total - passed - failed;
  const filtered = searchQuery
    ? checklist.filter(c => c.item.toLowerCase().includes(searchQuery.toLowerCase()) || c.category.toLowerCase().includes(searchQuery.toLowerCase()))
    : checklist;
  const [lastSaved, setLastSaved] = useState(null);
  const [_showKeyboardHint, setShowKeyboardHint] = useState(false);

  // Auto-save functionality
  useEffect(() => {
    const timer = setTimeout(() => {
      const data = { checklist, notes, condition };
      localStorage.setItem(`inspection_${activeTask._id}`, JSON.stringify(data));
      setLastSaved(new Date());
    }, 2000);
    return () => clearTimeout(timer);
  }, [checklist, notes, condition, activeTask._id]);

  // Load saved state on mount
  useEffect(() => {
    const saved = localStorage.getItem(`inspection_${activeTask._id}`);
    if (saved) {
      try {
        const data = JSON.parse(saved);
        if (data.checklist && data.checklist.length === checklist.length) {
          setChecklist(data.checklist);
        }
        if (data.notes) setNotes(data.notes);
        if (data.condition) setCondition(data.condition);
        setLastSaved(new Date(data.timestamp));
      } catch (e) {
        console.error('Failed to load saved state:', e);
      }
    }
    // Show keyboard hint on first visit
    const hintShown = sessionStorage.getItem('keyboard_hint_shown');
    if (!hintShown) {
      setShowKeyboardHint(true);
      setTimeout(() => {
        setShowKeyboardHint(false);
        sessionStorage.setItem('keyboard_hint_shown', 'true');
      }, 5000);
    }
    // checklist.length is intentionally excluded: this effect should only restore a
    // draft when switching tasks (activeTask._id), not whenever checklist mutates,
    // to avoid clobbering in-progress edits with a stale localStorage snapshot.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTask._id, setChecklist, setNotes, setCondition]);

  const toggleCheck = (idx) => {
    setChecklist(prev => prev.map((c, i) => i === idx ? { ...c, passed: c.passed === true ? false : c.passed === false ? null : true } : c));
  };

  const toggleCategory = (cat) => {
    setCollapsedCats(prev => prev.includes(cat) ? prev.filter(c => c !== cat) : [...prev, cat]);
  };

  // Keyboard navigation
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;

      if (e.key === 's' && (e.ctrlKey || e.metaKey)) {
        e.preventDefault();
        handleSubmit();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleSubmit]);

  return (
    <div style={{ background: 'var(--bg)', minHeight: '100vh' }}>
      <div style={{
        background: 'linear-gradient(180deg, rgba(23, 107, 135, 0.04) 0%, transparent 100%)',
        borderBottom: '1px solid var(--border)', padding: '24px 0 20px',
      }}>
        <div style={{ maxWidth: 1200, margin: '0 auto', padding: '0 32px' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 8, flexWrap: 'wrap', gap: 8 }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
              <span style={{ fontSize: 9, color: 'var(--brand)', fontWeight: 700, letterSpacing: '0.22em', textTransform: 'uppercase' }}>
                150-Point Inspection
              </span>
              <button onClick={() => setActiveTask(null)} style={{
                padding: '4px 12px', borderRadius: 6, background: 'rgba(10, 51, 64, 0.05)', border: '1px solid rgba(10, 51, 64, 0.1)',
                color: 'rgba(10, 51, 64, 0.5)', fontSize: 10, cursor: 'pointer', fontWeight: 600,
              }}>← Back to Tasks</button>
            </div>
            <div style={{ display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap' }}>
              <span style={{ fontSize: 11, color: 'rgba(10, 51, 64, 0.35)' }}>
                <span style={{ color: '#22c55e', fontWeight: 700 }}>{passed}</span> passed · <span style={{ color: failed > 0 ? '#ef4444' : 'rgba(10, 51, 64, 0.35)', fontWeight: 700 }}>{failed}</span> failed · <span style={{ color: 'rgba(10, 51, 64, 0.2)' }}>{untested}</span> pending
              </span>
              {lastSaved && (
                <span style={{ fontSize: 9, color: 'rgba(10, 51, 64, 0.25)', display: 'flex', alignItems: 'center', gap: 4 }}>
                  <Save size={10} /> Saved {timeAgo(lastSaved)}
                </span>
              )}
              <div style={{ width: 100, height: 6, borderRadius: 3, background: 'rgba(10, 51, 64, 0.06)', overflow: 'hidden', display: 'flex' }}>
                <div style={{ width: `${(passed / total) * 100}%`, height: '100%', background: '#22c55e', transition: 'width 0.3s' }} />
                <div style={{ width: `${(failed / total) * 100}%`, height: '100%', background: '#ef4444', transition: 'width 0.3s' }} />
              </div>
              <span style={{ fontSize: 15, fontWeight: 900, color: 'var(--brand)', fontFamily: 'var(--font-display)', fontStyle: 'italic' }}>
                {Math.round((passed / total) * 100)}%
              </span>
            </div>
          </div>
          <h1 style={{ fontFamily: 'var(--font-display)', fontWeight: 900, fontStyle: 'italic', fontSize: 'clamp(1.2rem,2vw,1.6rem)', color: '#0a3340', margin: 0 }}>
            {activeTask.car?.title || 'Vehicle Inspection'}
          </h1>
        </div>
      </div>

      <div style={{ maxWidth: 1200, margin: '0 auto', padding: '20px 32px 40px' }}>
        <div style={{ marginBottom: 16 }}>
          <input value={searchQuery} onChange={e => setSearchQuery(e.target.value)}
            placeholder="Search inspection items..."
            style={{
              width: '100%', padding: '10px 14px', borderRadius: 10,
              background: 'rgba(10, 51, 64, 0.03)', border: '1px solid rgba(10, 51, 64, 0.1)',
              color: '#0a3340', fontSize: 12, outline: 'none',
            }}
            onFocus={e => { e.currentTarget.style.borderColor = 'rgba(23, 107, 135, 0.3)'; }}
            onBlur={e => { e.currentTarget.style.borderColor = 'rgba(10, 51, 64, 0.1)'; }} />
        </div>

        <div style={{ display: 'flex', gap: 8, marginBottom: 20, flexWrap: 'wrap', alignItems: 'center' }}>
          <span style={{ fontSize: 11, fontWeight: 700, color: 'rgba(10, 51, 64, 0.35)', textTransform: 'uppercase', letterSpacing: '0.08em', marginRight: 4 }}>Condition:</span>
          {['excellent', 'good', 'fair', 'poor'].map(c => (
            <button key={c} onClick={() => setCondition(c)} style={{
              padding: '6px 16px', borderRadius: 8, border: '1px solid',
              background: condition === c ? 'rgba(23, 107, 135, 0.15)' : 'transparent',
              borderColor: condition === c ? 'rgba(23, 107, 135, 0.3)' : 'rgba(10, 51, 64, 0.1)',
              color: condition === c ? 'var(--brand)' : 'rgba(10, 51, 64, 0.4)',
              fontSize: 11, fontWeight: 700, cursor: 'pointer', textTransform: 'capitalize',
              transition: 'all 0.15s',
            }}>
              {condition === c ? '✓ ' : ''}{c}
            </button>
          ))}
        </div>

        <div style={{ display: 'flex', gap: 6, marginBottom: 16, flexWrap: 'wrap' }}>
          {CATEGORIES.map(cat => {
            const items = checklist.filter(c => c.category === cat);
            const catPassed = items.filter(c => c.passed === true).length;
            const catFailed = items.filter(c => c.passed === false).length;
            const allDone = catPassed + catFailed === items.length;
            return (
              <button key={cat} onClick={() => toggleCategory(cat)}
                style={{
                  padding: '4px 10px', borderRadius: 6, border: '1px solid',
                  background: allDone ? 'rgba(34,197,94,0.08)' : 'rgba(10, 51, 64, 0.03)',
                  borderColor: allDone ? 'rgba(34,197,94,0.15)' : 'rgba(10, 51, 64, 0.08)',
                  color: allDone ? 'rgba(10, 51, 64, 0.5)' : 'rgba(10, 51, 64, 0.35)',
                  fontSize: 9, fontWeight: 600, cursor: 'pointer',
                  display: 'flex', alignItems: 'center', gap: 4,
                }}>
                {cat} {allDone ? `✓` : `(${catPassed + catFailed}/${items.length})`}
              </button>
            );
          })}
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: 10, marginBottom: 20 }}>
          {CATEGORIES.map(cat => {
            const items = (searchQuery ? filtered : checklist).filter(c => c.category === cat);
            if (items.length === 0) return null;
            const catPassed = items.filter(c => c.passed === true).length;
            const catFailed = items.filter(c => c.passed === false).length;
            const isCollapsed = collapsedCats.includes(cat);
            return (
              <div role="presentation" key={cat} style={{
                background: 'var(--card)', border: '1px solid var(--border)',
                borderRadius: 12, overflow: 'hidden',
                transition: 'border-color 0.2s',
              }}
                onMouseEnter={e => { e.currentTarget.style.borderColor = 'rgba(23, 107, 135, 0.15)'; }}
                onMouseLeave={e => { e.currentTarget.style.borderColor = 'var(--border)'; }}
              >
                <div onClick={() => toggleCategory(cat)}
                  onKeyDown={e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggleCategory(cat); } }}
                  role="button" tabIndex={0} aria-expanded={!isCollapsed} aria-label={`${cat} category`}
                  style={{
                    padding: '12px 16px', display: 'flex', justifyContent: 'space-between',
                    alignItems: 'center', cursor: 'pointer', userSelect: 'none',
                    borderBottom: isCollapsed ? 'none' : '1px solid rgba(10, 51, 64, 0.04)',
                  }}
                >
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    <span style={{ fontSize: 12, fontWeight: 700, color: '#0a3340' }}>{cat}</span>
                    {catFailed > 0 && <AlertTriangle size={12} style={{ color: '#ef4444' }} />}
                  </div>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                    <span style={{ fontSize: 10, color: 'rgba(10, 51, 64, 0.35)', display: 'flex', gap: 6 }}>
                      <span style={{ color: '#22c55e' }}>{catPassed}✓</span>
                      {catFailed > 0 && <span style={{ color: '#ef4444' }}>{catFailed}✗</span>}
                    </span>
                    <ChevronRight size={12} style={{
                      color: 'rgba(10, 51, 64, 0.2)',
                      transform: isCollapsed ? 'rotate(0deg)' : 'rotate(90deg)',
                      transition: 'transform 0.2s',
                    }} />
                  </div>
                </div>
                {!isCollapsed && (
                  <div style={{ padding: '8px 16px 12px' }}>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(min(100%, 220px), 1fr))', gap: 2 }}>
                      {items.map((item, i) => {
                        const globalIdx = checklist.indexOf(item);
                        return (
                          <div key={i} style={{ display: 'flex', alignItems: 'center', gap: 6, padding: '4px 0' }}>
                            <button
                              onClick={() => toggleCheck(globalIdx)}
                              onKeyDown={(e) => {
                                if (e.key === 'Enter' || e.key === ' ') {
                                  e.preventDefault();
                                  toggleCheck(globalIdx);
                                }
                              }}
                              aria-label={`Toggle ${item.item}`}
                              role="checkbox"
                              aria-checked={item.passed === true ? 'true' : item.passed === false ? 'false' : 'mixed'}
                              tabIndex={0}
                              style={{
                                width: 16, height: 16, borderRadius: 4, border: '1px solid',
                                flexShrink: 0, cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center',
                                background: item.passed === true ? '#22c55e' : item.passed === false ? '#ef4444' : 'transparent',
                                borderColor: item.passed === true ? '#22c55e' : item.passed === false ? '#ef4444' : 'rgba(10, 51, 64, 0.15)',
                                color: item.passed !== null ? '#fff' : 'transparent',
                                fontSize: 9, fontWeight: 700,
                                transition: 'all 0.15s',
                              }}>
                              {item.passed === true ? '✓' : item.passed === false ? '✗' : ''}
                            </button>
                            <span style={{
                              fontSize: 10, flex: 1,
                              color: item.passed === true ? 'rgba(10, 51, 64, 0.4)' : item.passed === false ? 'rgba(239,68,68,0.6)' : 'rgba(10, 51, 64, 0.5)',
                              textDecoration: item.passed === false ? 'line-through' : 'none',
                            }}>{item.item}</span>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>

        <div style={{ marginBottom: 20 }}>
          <div style={{ fontSize: 11, fontWeight: 700, color: 'rgba(10, 51, 64, 0.35)', textTransform: 'uppercase', letterSpacing: '0.08em', marginBottom: 8 }}>Overall Notes</div>
          <textarea value={notes} onChange={e => setNotes(e.target.value)} rows={3}
            style={{
              width: '100%', background: '#FFFFFF', border: '1px solid var(--border)',
              borderRadius: 10, padding: 12, color: '#0a3340', fontSize: 12, resize: 'vertical',
              fontFamily: 'inherit', outline: 'none',
            }}
            placeholder="Summarize overall condition, notable findings..."
          />
        </div>

        <button onClick={handleSubmit} style={{
          width: '100%', padding: '14px', borderRadius: 10,
          background: 'var(--brand)', color: '#0a3340', border: 'none',
          fontSize: 13, fontWeight: 900, cursor: 'pointer',
          textTransform: 'uppercase', letterSpacing: '0.06em',
          display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 8,
          transition: 'opacity 0.15s',
        }}
          onMouseEnter={e => { e.currentTarget.style.opacity = '0.85'; }}
          onMouseLeave={e => { e.currentTarget.style.opacity = '1'; }}
        >
          <FileText size={16} /> Submit Inspection Report ({Math.round((passed / total) * 100)}%)
        </button>
        <div style={{ fontSize: 9, color: 'rgba(10, 51, 64, 0.25)', textAlign: 'center', marginTop: 8, display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 4 }}>
          <Keyboard size={10} /> Tip: Press Ctrl+S to submit quickly
        </div>
      </div>
    </div>
  );
}

import { Link } from 'react-router-dom';
import { Smartphone, ClipboardCheck, Play, CheckCircle, BarChart3, Clock, Car, MapPin, DollarSign } from 'lucide-react';
import InspectorStatusBadge from './InspectorStatusBadge';
import InspectorWorkflowProgress from './InspectorWorkflowProgress';
import { EnterpriseCard, EnterpriseKPI, EnterpriseTimeline, EnterpriseTaskSummary, EnterpriseTable, DashboardHeader } from '../../../components/enterprise/EnterpriseDashboard';

export default function InspectorTasksView({ tasks, loading, tab, setTab, totalPayment, totalAssigned, totalInProgress, totalCompleted, handleStart, handleBeginChecklist, loadTasks, user, logout }) {
  const hour = new Date().getHours();
  const greeting = hour < 12 ? 'Good morning' : hour < 18 ? 'Good afternoon' : 'Good evening';

  return (
    <div style={{ background: 'var(--bg)', minHeight: '100vh' }}>
      <DashboardHeader badge="Inspector Dashboard" greeting={greeting} name={user?.name?.split(' ')[0] || 'Inspector'}
        subtitle={`Inspection hub · ${new Date().toLocaleDateString('en-KE', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' })} · ${tasks.length} tasks`}
        actions={
          <div style={{ display: 'flex', gap: 8 }}>
            <button onClick={loadTasks} disabled={loading} style={{ padding: '8px 14px', borderRadius: 10, background: 'rgba(255,255,255,0.04)', border: '1px solid rgba(255,255,255,0.08)', color: 'rgba(255,255,255,0.5)', fontSize: 11, fontWeight: 600, cursor: loading ? 'wait' : 'pointer', display: 'flex', alignItems: 'center', gap: 5 }}>
              <Clock size={11} /> {loading ? '...' : 'Refresh'}
            </button>
            <button onClick={async () => { await logout(); window.location.href = '/'; }} style={{ padding: '8px 14px', borderRadius: 10, background: 'rgba(239,68,68,0.06)', border: '1px solid rgba(239,68,68,0.12)', color: 'rgba(239,68,68,0.7)', fontSize: 11, fontWeight: 600, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 5 }}>
              Sign Out
            </button>
          </div>
        }
      />

      <div style={{ maxWidth: 1400, margin: '0 auto', padding: '28px' }}>
        {/* KPI Row */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(160px, 1fr))', gap: 14, marginBottom: 28 }}>
          <EnterpriseKPI icon={<Smartphone size={18} />} label="Awaiting Payment" value={totalPayment} sub="pending confirmation" accent="#176b87" />
          <EnterpriseKPI icon={<ClipboardCheck size={18} />} label="Assigned" value={totalAssigned} sub="awaiting start" accent="#176B87" />
          <EnterpriseKPI icon={<Play size={18} />} label="In Progress" value={totalInProgress} sub="active inspections" accent="var(--brand)" />
          <EnterpriseKPI icon={<CheckCircle size={18} />} label="Completed" value={totalCompleted} sub="all time" accent="#22c55e" />
          <EnterpriseKPI icon={<BarChart3 size={18} />} label="Total Tasks" value={tasks.length} sub="assigned to you" accent="rgba(255,255,255,0.4)" />
        </div>

        {/* Task Summary */}
        <div style={{ marginBottom: 28 }}>
          <EnterpriseCard>
            <EnterpriseTaskSummary tasks={[
              { label: 'Assigned', count: totalAssigned, color: '#176B87' },
              { label: 'In Progress', count: totalInProgress, color: 'var(--brand)' },
              { label: 'Completed', count: totalCompleted, color: '#22c55e' },
              { label: 'Pending Pay', count: totalPayment, color: '#176b87' },
              { label: 'Total', count: tasks.length, color: 'rgba(255,255,255,0.4)' },
            ]} />
          </EnterpriseCard>
        </div>

        {/* Tab Bar */}
        <div style={{ display: 'flex', gap: 4, marginBottom: 20, borderBottom: '1px solid var(--border)', paddingBottom: 12 }}>
          {[
            { key: 'tasks', label: 'All Tasks', count: tasks.length },
            { key: 'payment', label: 'Payment Queue', count: totalPayment },
            { key: 'active', label: 'Active Only', count: totalAssigned + totalInProgress },
          ].map(t => (
            <button key={t.key} onClick={() => setTab(t.key)}
              style={{
                padding: '7px 16px', borderRadius: 8,
                background: tab === t.key ? 'rgba(23, 107, 135, 0.1)' : 'transparent',
                border: '1px solid',
                borderColor: tab === t.key ? 'rgba(23, 107, 135, 0.2)' : 'transparent',
                color: tab === t.key ? 'var(--brand)' : 'rgba(255,255,255,0.35)',
                fontSize: 11, fontWeight: 700, cursor: 'pointer', transition: 'all 0.15s',
              }}>
              {t.label}{t.count > 0 ? ` (${t.count})` : ''}
            </button>
          ))}
        </div>

        {loading ? (
          <div style={{ display: 'flex', justifyContent: 'center', padding: '60px 0' }}>
            <div className="spinner" />
          </div>
        ) : (() => {
          const filtered = tab === 'payment'
            ? tasks.filter(t => t.status === 'paid' || t.status === 'pending_payment')
            : tab === 'active'
            ? tasks.filter(t => t.status === 'assigned' || t.status === 'in_progress')
            : tasks;

          return filtered.length === 0 ? (
            <EnterpriseCard header={tab === 'payment' ? '💰 Payment Queue' : '📋 Tasks'}>
              <div style={{ textAlign: 'center', padding: '40px 0' }}>
                <div style={{ width: 56, height: 56, borderRadius: '50%', background: 'rgba(255,255,255,0.03)', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 16px' }}>
                  <ClipboardCheck size={28} style={{ color: 'rgba(255,255,255,0.15)' }} />
                </div>
                <div style={{ fontSize: 15, fontWeight: 700, color: 'rgba(255,255,255,0.6)', marginBottom: 6 }}>
                  {tab === 'payment' ? 'No payments pending' : 'No assignments yet'}
                </div>
                <div style={{ fontSize: 12, color: 'rgba(255,255,255,0.2)', maxWidth: 360, margin: '0 auto', lineHeight: 1.6 }}>
                  {tab === 'payment'
                    ? 'All paid inspections have been assigned or completed.'
                    : 'Awaiting inspection orders from dispatch. New tasks will appear here automatically.'}
                </div>
              </div>
            </EnterpriseCard>
          ) : (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
              {filtered.map(t => {
                const car = t.car || {};
                const img = car.images?.[0]?.url || car.images?.[0] || car.image;
                return (
                  <div key={t._id} style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 14, padding: '16px 20px', transition: 'border-color 0.2s' }}
                    onMouseEnter={e => { e.currentTarget.style.borderColor = 'rgba(23, 107, 135, 0.2)'; }}
                    onMouseLeave={e => { e.currentTarget.style.borderColor = 'var(--border)'; }}>
                    <InspectorWorkflowProgress status={t.status} />
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: 12 }}>
                      <div style={{ display: 'flex', alignItems: 'center', gap: 12, flex: 1, minWidth: 0 }}>
                        {img ? (
                          <img src={img} alt={car.title} loading="lazy" decoding="async" style={{ width: 48, height: 36, objectFit: 'cover', borderRadius: 8, flexShrink: 0 }} />
                        ) : (
                          <div style={{ width: 48, height: 36, borderRadius: 8, background: 'rgba(255,255,255,0.04)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                            <Car size={16} style={{ color: 'rgba(255,255,255,0.2)' }} />
                          </div>
                        )}
                        <div style={{ flex: 1, minWidth: 0 }}>
                          <div style={{ fontSize: 14, fontWeight: 700, color: '#fff', marginBottom: 2 }}>
                            {car.title || `Vehicle #${t._id?.slice(-6) || '—'}`}
                          </div>
                          <div style={{ fontSize: 11, color: 'rgba(255,255,255,0.35)', display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }}>
                            {t.location && <span style={{ display: 'flex', alignItems: 'center', gap: 3 }}><MapPin size={10} /> {t.location}</span>}
                            {car.year && <span>{car.year}</span>}
                            {car.brand && <span>{car.brand}</span>}
                            <span>·</span>
                            <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                              <DollarSign size={10} style={{ color: 'rgba(255,255,255,0.2)' }} />
                              Fee: <strong style={{ color: 'var(--brand)' }}>KES {Number(t.fee || 2500).toLocaleString()}</strong>
                            </span>
                          </div>
                        </div>
                        <InspectorStatusBadge status={t.status} />
                      </div>
                      <div style={{ display: 'flex', gap: 8, flexShrink: 0 }}>
                        {t.status === 'assigned' && (
                          <button onClick={() => handleStart(t._id)} style={{ padding: '8px 16px', borderRadius: 8, background: 'var(--brand)', color: '#0a3340', border: 'none', fontSize: 11, fontWeight: 800, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 6 }}>
                            <Play size={12} /> Start Inspection
                          </button>
                        )}
                        {t.status === 'in_progress' && (
                          <button onClick={() => handleBeginChecklist(t)} style={{ padding: '8px 16px', borderRadius: 8, background: '#22c55e', color: '#0a3340', border: 'none', fontSize: 11, fontWeight: 800, cursor: 'pointer', display: 'flex', alignItems: 'center', gap: 6 }}>
                            <ClipboardCheck size={12} /> Continue 150-Point Check
                          </button>
                        )}
                        {t.status === 'paid' && (
                          <div style={{ padding: '8px 16px', borderRadius: 8, background: 'rgba(23, 107, 135, 0.08)', border: '1px solid rgba(23, 107, 135, 0.15)', color: '#176B87', fontSize: 10, fontWeight: 600, display: 'flex', alignItems: 'center', gap: 5 }}>
                            <Clock size={11} /> Awaiting Admin Assignment
                          </div>
                        )}
                        {t.status === 'pending_payment' && (
                          <div style={{ padding: '8px 16px', borderRadius: 8, background: 'rgba(19, 184, 166, 0.08)', border: '1px solid rgba(19, 184, 166, 0.15)', color: '#176b87', fontSize: 10, fontWeight: 600, display: 'flex', alignItems: 'center', gap: 5 }}>
                            <Smartphone size={11} /> Buyer Payment Pending
                          </div>
                        )}
                        {t.status === 'completed' && (
                          <div style={{ padding: '8px 16px', borderRadius: 8, background: 'rgba(34,197,94,0.08)', border: '1px solid rgba(34,197,94,0.15)', color: '#22c55e', fontSize: 10, fontWeight: 600, display: 'flex', alignItems: 'center', gap: 5 }}>
                            <CheckCircle size={11} /> Score: {t.overallScore || '—'}/100
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          );
        })()}
      </div>
    </div>
  );
}

